hlxg_jieyue = gu_trigger("hlxg_jieyue", {sgs.EventPhaseStart, sgs.DamageInflicted}, function(self, event, room, p, data, owner)
    local key = "hlxg_jieyue_" .. owner:objectName() .. "-Clear"
