-- ==================== c1a_03
do
-- c1a_03: one active battlefield shared by these three battlefield skills.
local function hl_battle(room, name)
    room:setTag("hl_c1a03_battle", sgs.QVariant(name))
end
local function hl_inbattle(room, name)
    return room:getTag("hl_c1a03_battle"):toString() == name
end
local function hl_strike(room, owner, target)
    if owner:getPhase() == sgs.Player_Play then
        room:setPlayerMark(target, "hl_qiangxi_" .. owner:objectName() .. "-PlayClear", 1)
    end
    room:loseHp(owner, 1, true, owner, "hl_qiangxi")
    if owner:isAlive() then owner:drawCards(1, "hl_qiangxi") end
    if target:isAlive() then
        local d = sgs.DamageStruct(); d.from = owner; d.to = target; d.damage = 1; d.reason = "hl_qiangxi"
        room:damage(d)
    end
end
local function hl_raid(room, actor)
    if not actor or actor:isDead() then return end
    local selected = {}
    for i = 1, 2 do
        local candidates = sgs.SPlayerList()
        for _, q in sgs.qlist(room:getOtherPlayers(actor)) do
            if not q:isKongcheng() and not table.contains(selected, q:objectName()) then candidates:append(q) end
        end
        if candidates:isEmpty() then break end
        local q = room:askForPlayerChosen(actor, candidates, "hl_tuxi", "@hl_tuxi", true, true)
        if not q then break end
        table.insert(selected, q:objectName())
        local id = room:askForCardChosen(actor, q, "h", "hl_tuxi")
        room:obtainCard(actor, id, false)
        if actor:isDead() then break end
    end
end
local function hl_minhand(room, p)
    for _, q in sgs.qlist(room:getAlivePlayers()) do
        if q:getHandcardNum() < p:getHandcardNum() then return false end
    end
    return true
end

