hl_chuanglie = gu_trigger("hl_chuanglie", {sgs.TargetConfirming, sgs.CardFinished, sgs.EnterDying}, function(self, event, room, p, data, owner)
    if not hl_inbattle(room, "wancheng") then return end
    if event == sgs.EnterDying then
        if data:toDying().who ~= owner then return end
        local r = sgs.RecoverStruct(); r.who = owner; r.recover = 2; room:recover(owner, r)
        hl_battle(room, ""); return
    end
    local use = data:toCardUse()
    if not use.card or not use.card:isKindOf("Slash") then return end
    if event == sgs.TargetConfirming then
        if use.to:length() ~= 1 or not use.to:contains(p) or p == owner or use.from == owner then return end
        if gu_invoke(owner, self:objectName(), data) then
            use.to:clear(); use.to:append(owner); data:setValue(use)
        end
    elseif not use.card:hasFlag("hl_chuanglie_damage") and owner:isAlive() then
        local candidates = sgs.SPlayerList()
        local function eligible(q)
            return q and q ~= owner and q:isAlive() and owner:inMyAttackRange(q)
                and (owner:getPhase() ~= sgs.Player_Play or q:getMark("hl_qiangxi_" .. owner:objectName() .. "-PlayClear") == 0)
        end
        if eligible(use.from) then candidates:append(use.from) end
        for _, q in sgs.qlist(use.to) do
            if eligible(q) and not candidates:contains(q) then candidates:append(q) end
        end
        if not candidates:isEmpty() then
            local q = room:askForPlayerChosen(owner, candidates, "hl_chuanglie", "@hl_chuanglie-strike", true, true)
            if q then hl_strike(room, owner, q) end
        end
    end
end)
hl_kuangji = sgs.CreateViewAsSkillV2 {
    name = "hl_kuangji", response_or_use = true,
    can_activate = function(self, request)
        local p = request:getInitiator()
        return p:getMark("hl_kuangji-Clear") == 0 and
            (request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY or request:getPattern() == "jink")
    end,
    can_select_card = function(self, request, card)
        return request:getSelectedCardIds():isEmpty() and card:isKindOf("Weapon")
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        local weapon = sgs.Sanguosha:getCard(request:getSelectedCardIds():first())
        local name = request:getPattern() == "jink" and "jink" or "slash"
        local c = sgs.Sanguosha:cloneCard(name, weapon:getSuit(), weapon:getNumber())
        c:addSubcard(weapon); c:setSkillName("hl_kuangji"); return c
    end,
}
hl_kuangji_record = gu_record("#hl_kuangji_record", {sgs.GameStart, sgs.PreCardUsed, sgs.CardResponded}, function(self, event, room, p, data)
    if event == sgs.GameStart then
        if not p or not p:hasSkill("hl_kuangji") or p:getHandcardNum() < 2 then return end
        local c = room:askForExchange(p, "hl_kuangji", 2, 2, false, "@hl_kuangji-top", true)
        if not c then return end
        room:returnToTopDrawPile(c:getSubcards())
        local weapons = {}
        for _, id in sgs.qlist(room:getDrawPile()) do
            if sgs.Sanguosha:getCard(id):isKindOf("Weapon") then table.insert(weapons, id) end
        end
        local ids = sgs.IntList()
        for i = 1, math.min(2, #weapons) do local k = math.random(#weapons); ids:append(table.remove(weapons, k)) end
        gu_obtain(room, p, ids, "hl_kuangji"); return
    end
    local c = event == sgs.PreCardUsed and data:toCardUse().card or data:toCardResponse().m_card
    if not c or c:getSkillName() ~= "hl_kuangji" then return end
    room:setPlayerMark(p, "hl_kuangji-Clear", 1)
    local weapon = sgs.Sanguosha:getCard(c:getSubcards():first())
    local x = math.ceil(weapon:getRealCard():toWeapon():getRange() / 2)
    if c:isKindOf("Jink") then p:drawCards(x, "hl_kuangji")
    elseif event == sgs.PreCardUsed then
        local use = data:toCardUse(); use.extra_use = use.extra_use + x - 1; data:setValue(use)
    end
end)
hl_kuangji_mod = sgs.CreateTargetModSkillV2 {
    name = "#hl_kuangji_mod", pattern = "Slash", holder_selector = sgs.CorrectSkill_Primary,
    correct_func = function(self, ctx)
        local c = ctx:getCard()
        if ctx:getModType() == sgs.TargetModSkill_Residue and c and c:getSkillName() == "hl_kuangji" then return 1000 end
        return 0
    end,
}
