hl_pozhen = gu_trigger("hl_pozhen", {sgs.CardsMoveOneTime, sgs.DrawNCards}, function(self, event, room, p, data, owner)
    if event == sgs.DrawNCards then
        if p == owner then local n = owner:getMark("hl_pozhen_draw"); room:setPlayerMark(owner, "hl_pozhen_draw", 0); local draw = data:toDraw(); draw.num = draw.num + n; data:setValue(draw) end
        return
    end
    local move = data:toMoveOneTime()
    if not move.from or move.from:objectName() == owner:objectName() or not move.to or move.to:objectName() ~= owner:objectName() then return end
    local n = math.min(move.card_ids:length(), owner:getCardCount(true))
    if n == 0 then return end
    local c = room:askForExchange(owner, "hl_pozhen", n, 1, true, "@hl_pozhen", true)
    if not c then return end
    local basic, other = false, false
    for _, id in sgs.qlist(c:getSubcards()) do
        if sgs.Sanguosha:getCard(id):isKindOf("BasicCard") then basic = true else other = true end
    end
    local count = c:subcardsLength()
    local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_RECAST, owner:objectName(), "hl_pozhen", "")
    room:moveCardTo(c, owner, nil, sgs.Player_DiscardPile, reason, true)
    owner:drawCards(count, "hl_pozhen")
    if basic then room:addPlayerMark(owner, "hl_pozhen_slash-Clear") end
    if other then room:setPlayerMark(owner, "hl_pozhen_draw", math.min(5, owner:getMark("hl_pozhen_draw") + 1)) end
end)
