local function hl_xurui_pending_effect(event, room, data, owner)
    local key = "hl_xurui_" .. owner:objectName()
    if event == sgs.DamageCaused then
        local d = data:toDamage()
        if d.card and d.card:hasFlag(key .. "_damage") then d.damage = d.damage + 1; d.nature = sgs.DamageStruct_Fire; data:setValue(d) end
        return
    end
    local use = data:toCardUse()
    if not use.card then return end
    if event == sgs.CardFinished then
        if use.card:hasFlag(key .. "_adjacent") then
            room:setCardFlag(use.card, "-" .. key .. "_adjacent")
            local target = room:findPlayerByObjectName(use.card:getTag(key):toString(), true)
            if target then
                local candidates = sgs.SPlayerList()
                local seats = sgs.QList2Table(room:getAllPlayers(true))
                local seat
                for i, q in ipairs(seats) do if q == target then seat = i end end
                if seat then
                    for _, direction in ipairs({-1, 1}) do
                        for step = 1, #seats do
                            local q = seats[((seat - 1 + direction * step) % #seats) + 1]
                            if q:isAlive() then
                                if not candidates:contains(q) then candidates:append(q) end
                                break
                            end
                        end
                    end
                end
                local victim
                if not candidates:isEmpty() then victim = room:askForPlayerChosen(owner, candidates, "hl_xurui", "@hl_xurui-fire", false, true) end
                if victim then local d = sgs.DamageStruct(); d.from = owner; d.to = victim; d.damage = 1; d.nature = sgs.DamageStruct_Fire; d.reason = "hl_xurui"; room:damage(d) end
            end
        end
        room:setCardFlag(use.card, "-" .. key .. "_damage"); use.card:removeTag(key); return
    end
end
hl_xurui = gu_trigger("hl_xurui", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local key = "hl_xurui_" .. owner:objectName()
    local use = data:toCardUse()
    if not use.card then return end
    if not hl_inbattle(room, "yiling") or use.from ~= room:getCurrent() or use.to:length() ~= 1
        or use.to:first() == use.from or not hl_minhand(room, owner) or not gu_invoke(owner, "hl_xurui", data) then return end
    local choice = room:askForChoice(owner, "hl_xurui", "adjacent+damage", data)
    room:setCardFlag(use.card, key .. "_" .. choice)
    use.card:setTag(key, sgs.QVariant(use.to:first():objectName()))
    owner:drawCards(2, "hl_xurui")
    if owner:isAlive() and not owner:isKongcheng() and not room:getOtherPlayers(owner):isEmpty() then
        local c = room:askForExchange(owner, "hl_xurui", 1, 1, false, "@hl_xurui-give", true)
        if c then
            local q = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), "hl_xurui", "@hl_xurui-recipient", false, true)
            if q then room:obtainCard(q, c, false) end
        end
    end
end)
