-- Record battlefield entrance independently of optional owner effects.
hl_battle_record = gu_record("#hl_chuanglie_battle", {sgs.CardUsed, sgs.CardsMoveOneTime, sgs.Damage, sgs.EventPhaseChanging}, function(self, event, room, p, data)
    if event == sgs.CardUsed then
        local use = data:toCardUse()
        if not use.card or not use.from then return end
        room:setCardFlag(use.card, "-hl_chuanglie_damage")
        local entered = false
        for _, q in sgs.qlist(use.to) do
            local mark = "hl_chuanglie_target_" .. use.from:objectName() .. "-Clear"
            room:addPlayerMark(q, mark)
            if q:getMark(mark) == 3 then entered = true end
        end
        if entered and not room:findPlayersBySkillName("hl_chuanglie"):isEmpty() then hl_battle(room, "wancheng") end
    elseif event == sgs.CardsMoveOneTime then
        local move = data:toMoveOneTime()
        if not move.from then return end
        local from = room:findPlayerByObjectName(move.from:objectName())
        if not from then return end
        if from:getPhase() == sgs.Player_Play then
            local n = 0
            for _, id in sgs.qlist(move.card_ids) do if sgs.Sanguosha:getCard(id):isKindOf("BasicCard") then n = n + 1 end end
            local old = from:getMark("hl_biaoxi_basic-PlayClear")
            room:addPlayerMark(from, "hl_biaoxi_basic-PlayClear", n)
            if old < 2 and old + n >= 2 and not room:findPlayersBySkillName("hl_biaoxi"):isEmpty() then hl_battle(room, "hefei") end
        end
        if move.from_places:contains(sgs.Player_PlaceHand) and from:isKongcheng()
            and not room:findPlayersBySkillName("hl_xurui"):isEmpty() then hl_battle(room, "yiling") end
    elseif event == sgs.Damage then
        local d = data:toDamage()
        if d.card and d.damage > 0 then room:setCardFlag(d.card, "hl_chuanglie_damage") end
        if d.from and d.nature == sgs.DamageStruct_Fire then
            local n = room:getTag("hl_xurui_fireturn"):toInt() + d.damage
            room:setTag("hl_xurui_fireturn", sgs.QVariant(n))
            if n > 2 and hl_inbattle(room, "yiling") then hl_battle(room, "") end
        end
    elseif data:toPhaseChange().to == sgs.Player_NotActive then room:setTag("hl_xurui_fireturn", sgs.QVariant(0)) end
end)
extension_hl:addSkills(hl_battle_record)
extension_hl:insertRelatedSkills("hl_chuanglie", "#hl_chuanglie_battle")

