-- c1a_04: chapter 1 战; V2 definitions, helpers remain in assembler scope.
local function c104_nojink(owner, use, target)
    local key = "Jink_" .. use.card:toString()
    local old, ids = owner:getTag(key):toIntList(), sgs.IntList()
    for i = 0, use.to:length() - 1 do
        ids:append(use.to:at(i) == target and 0 or (i < old:length() and old:at(i) or 1))
    end
    local v = sgs.QVariant(); v:setValue(ids); owner:setTag(key, v)
end
local function c104_tieqi(room, owner, target, use)
    room:addPlayerMark(target, "hl_tieqi_invalid-Clear")
    local judge = sgs.JudgeStruct(); judge.who = owner; judge.reason = "hl_tieqi"
    judge.pattern = "."; room:judge(judge)
    if judge.card:isRed() then c104_nojink(owner, use, target)
    elseif judge.card:isBlack() then owner:drawCards(2, "hl_tieqi") end
end
hl_machao = sgs.General(extension_hl, "hl_machao", "qun", 4)
hl_dangfeng_record = gu_record("#hl_dangfeng_record", {sgs.CardUsed, sgs.Damage}, function(self, event, room, p, data)
    local current = room:getCurrent()
    if not current then return end
    if event == sgs.Damage then room:setPlayerMark(current, "hl_dangfeng_damage-Clear", 1)
    else
        local use = data:toCardUse()
        if use.card and use.card:isKindOf("Slash") then
            room:setPlayerMark(current, "hl_dangfeng_slash-Clear", 1)
            if use.from then room:addPlayerMark(use.from, "hl_haiji_slash-Clear") end
        end
    end
end)
hl_dangfeng = gu_trigger("hl_dangfeng", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p:getPhase() ~= sgs.Player_Finish then return end
    if p:getMark("hl_dangfeng_damage-Clear") == 0 then
        for _, id in sgs.qlist(room:getDrawPile()) do
            if sgs.Sanguosha:getCard(id):isKindOf("Slash") then room:obtainCard(owner, id, false); break end
        end
    end
    if p:getMark("hl_dangfeng_slash-Clear") == 0 then room:askForUseCard(owner, "slash", "@hl_dangfeng-slash", -1, sgs.Card_MethodUse, false) end
end)
hl_tieqi = gu_trigger("hl_tieqi", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if use.from ~= owner or not use.card or not use.card:isKindOf("Slash") then return end
    for _, to in sgs.qlist(use.to) do
        if to:isAlive() and room:askForSkillInvoke(owner, self:objectName(), sgs.QVariant(to)) then c104_tieqi(room, owner, to, use) end
    end
end)
hl_tieqi_invalid = sgs.CreateInvaliditySkill {
    name = "#hl_tieqi_invalid",
    skill_valid = function(self, p, skill)
        local f = skill:getFrequency(p)
        return p:getMark("hl_tieqi_invalid-Clear") == 0 or f == sgs.Skill_Compulsory or f == sgs.Skill_Wake
    end,
}
hl_haiji = gu_trigger("hl_haiji", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if use.from ~= owner or not use.card or not use.card:isKindOf("Slash") then return end
    for _, to in sgs.qlist(use.to) do
        room:addPlayerMark(owner, "&hl_haiji_lun")
        if owner:distanceTo(to) == 1 then owner:drawCards(1, self:objectName()) end
        local all = true
        for _, other in sgs.qlist(room:getOtherPlayers(owner)) do if owner:distanceTo(other) ~= 1 then all = false; break end end
        if all and to:isAlive() then c104_tieqi(room, owner, to, use) end
    end
end, true)
hl_haiji_distance = sgs.CreateDistanceSkillV2 {
    name = "#hl_haiji_distance", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local from = ctx:getPrimary()
        if from and from:hasSkill("hl_haiji") then return -from:getMark("&hl_haiji_lun") end
        return false
    end,
}
hl_haiji_target = sgs.CreateTargetModSkillV2 {
    name = "#hl_haiji_target", pattern = "Slash", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local from = ctx:getPrimary()
        if ctx:getModType() == sgs.TargetModSkill_ExtraTarget and from and from:hasSkill("hl_haiji") and from:getMark("hl_haiji_slash-Clear") == 0 then return 1 end
        return false
    end,
}
hl_machao:addSkill(hl_dangfeng); hl_machao:addSkill(hl_tieqi); hl_machao:addSkill(hl_haiji)
hl_machao:addSkill(hl_dangfeng_record); hl_machao:addSkill(hl_tieqi_invalid); hl_machao:addSkill(hl_haiji_distance); hl_machao:addSkill(hl_haiji_target)
extension_hl:insertRelatedSkills("hl_dangfeng", "#hl_dangfeng_record")
extension_hl:insertRelatedSkills("hl_tieqi", "#hl_tieqi_invalid")
extension_hl:insertRelatedSkills("hl_haiji", "#hl_haiji_distance")
extension_hl:insertRelatedSkills("hl_haiji", "#hl_haiji_target")

hl_huangzhong = sgs.General(extension_hl, "hl_huangzhong", "shu", 4)
hl_lizhan = sgs.CreateViewAsSkillV2 {
    name = "hl_lizhan",
    can_activate = function(self, request)
        if request:getReason() ~= sgs.CardUseStruct_CARD_USE_REASON_PLAY then return false end
        local c = sgs.Sanguosha:cloneCard("slash"); local ok = c:isAvailable(request:getInitiator()); c:deleteLater(); return ok
    end,
    can_select_card = function(self, request, card) return card:isKindOf("Slash") end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() >= 2 end,
    create_card = function(self, request)
        local c = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0)
        c:addSubcards(request:getSelectedCardIds()); c:setSkillName("hl_lizhan"); return c
    end,
}
hl_lizhan_effect = gu_record("#hl_lizhan_effect", {sgs.TargetSpecified, sgs.CardFinished}, function(self, event, room, p, data)
    local use = data:toCardUse()
    if not use.card or use.card:getSkillName() ~= "hl_lizhan" or use.card:subcardsLength() < 2 then return end
    if event == sgs.TargetSpecified then
        local key = "Jink_" .. use.card:toString(); local old = use.from:getTag(key):toIntList(); local ids = sgs.IntList()
        for i = 0, use.to:length() - 1 do
            local n = i < old:length() and old:at(i) or 1
            ids:append(n == 0 and 0 or math.min(5, use.card:subcardsLength()))
        end
        local v = sgs.QVariant(); v:setValue(ids); use.from:setTag(key, v)
    end
end)
hl_lizhan_jink = sgs.CreateRuleSkillV2 {
    name = "#hl_lizhan_jink", global = true, events = {sgs.SlashProceed}, priority = 5,
    can_trigger = function(self, event, room, p, data)
        local e = data:toSlashEffect()
        if e.slash and e.slash:getSkillName() == "hl_lizhan" and e.slash:subcardsLength() >= 2 and e.from and e.to then return self:objectName(), e.from end
        return false
    end,
    on_effect = function(self, event, room, p, ctx)
        local data = ctx.original_data; local e = data:toSlashEffect(); local y = 0
        for i = 1, e.jink_num do
            if not e.to:isAlive() then return true end
            local j = room:askForCard(e.to, "jink", "@hl_lizhan-jink::" .. e.from:objectName() .. ":" .. (e.jink_num - i + 1), data, sgs.Card_MethodUse, e.from, false, "hl_lizhan", false, e.slash)
            if j then y = y + 1 end
            if not room:isJinkEffected(e.to, j) then
                e.slash:setTag("hl_lizhan_bonus_" .. e.to:objectName(), sgs.QVariant(math.min(5, e.slash:subcardsLength()) - y + 1))
                room:slashResult(e, nil); return true
            end
        end
        -- A real Jink object lets slashResult dispatch the ordinary SlashMissed path.
        local j = sgs.Sanguosha:cloneCard("jink"); room:slashResult(e, j); j:deleteLater(); return true
    end,
}
local function c104_followup(room, owner, excluded)
    local names, seen = {}, {}
    for id = 0, sgs.Sanguosha:getCardCount() - 1 do
        local c = sgs.Sanguosha:getEngineCard(id)
        if c and c:isDamageCard() and not c:isKindOf("AOE") and not c:isKindOf("GlobalEffect") and not c:targetFixed() and not seen[c:objectName()] then
            seen[c:objectName()] = true; table.insert(names, c:objectName())
        end
    end
    local available = {}
    room:setPlayerFlag(owner, "hl_lizhan_followup")
    for _, name in ipairs(names) do
        local c = sgs.Sanguosha:cloneCard(name); c:setSkillName("hl_lizhan")
        for _, to in sgs.qlist(room:getAlivePlayers()) do
            local targets = sgs.PlayerList(); targets:append(to)
            if to ~= excluded and c:targetFilter(sgs.PlayerList(), to, owner) and c:targetsFeasible(targets, owner) and not owner:isProhibited(to, c) and not owner:isCardLimited(c, sgs.Card_MethodUse) then table.insert(available, name); break end
        end
        c:deleteLater()
    end
    if #available > 0 and room:askForSkillInvoke(owner, "hl_lizhan", sgs.QVariant(excluded)) then
        local name = room:askForChoice(owner, "hl_lizhan", table.concat(available, "+"))
        local c = sgs.Sanguosha:cloneCard(name); c:setSkillName("hl_lizhan")
        local choices = sgs.SPlayerList()
        for _, to in sgs.qlist(room:getAlivePlayers()) do
            local targets = sgs.PlayerList(); targets:append(to)
            if to ~= excluded and c:targetFilter(sgs.PlayerList(), to, owner) and c:targetsFeasible(targets, owner) and not owner:isProhibited(to, c) then choices:append(to) end
        end
        if not choices:isEmpty() then
            local to = room:askForPlayerChosen(owner, choices, "hl_lizhan", "@hl_lizhan-target", false, true)
            room:useCard(sgs.CardUseStruct(c, owner, to), false)
        else c:deleteLater() end
    end
    room:setPlayerFlag(owner, "-hl_lizhan_followup")
end
hl_lizhan_damage = gu_record("#hl_lizhan_damage", {sgs.DamageCaused, sgs.Damage}, function(self, event, room, p, data)
    local d = data:toDamage()
    if not d.card or not d.card:isKindOf("Slash") or d.card:getSkillName() ~= "hl_lizhan" or d.card:subcardsLength() < 2 then return end
    if event == sgs.DamageCaused and not d.chain and not d.transfer then
        local stored = d.card:getTag("hl_lizhan_bonus_" .. d.to:objectName()):toInt()
        local x = stored > 0 and stored - 2 or math.min(5, d.card:subcardsLength()) - 1
        -- No-response Slash skips SlashProceed: Y is zero.
        d.damage = d.damage + x; data:setValue(d)
    elseif event == sgs.Damage and d.from and d.from:isAlive() then c104_followup(room, d.from, d.to) end
end)
hl_lizhan_mod = sgs.CreateTargetModSkillV2 {
    name = "#hl_lizhan_mod", pattern = ".", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local from, card = ctx:getPrimary(), ctx:getCard()
        if from and card and from:hasFlag("hl_lizhan_followup") and card:getSkillName() == "hl_lizhan" and (ctx:getModType() == sgs.TargetModSkill_DistanceLimit or ctx:getModType() == sgs.TargetModSkill_Residue) then return 1000 end
        return false
    end,
}
hl_liegong = gu_trigger("hl_liegong", {sgs.TargetSpecified, sgs.DamageCaused}, function(self, event, room, p, data, owner)
    if event == sgs.TargetSpecified then
        local use = data:toCardUse()
        if use.from ~= owner or not use.card or not use.card:isKindOf("Slash") then return end
        for _, to in sgs.qlist(use.to) do
            if to:getHandcardNum() >= owner:getHandcardNum() then c104_nojink(owner, use, to) end
            if to:getHp() >= owner:getHp() then use.card:setTag("hl_liegong_" .. to:objectName(), sgs.QVariant(true)) end
        end
    else
        local d = data:toDamage()
        if d.from == owner and d.card and d.card:isKindOf("Slash") and not d.chain and not d.transfer and d.card:getTag("hl_liegong_" .. d.to:objectName()):toBool() then d.damage = d.damage + 1; data:setValue(d) end
    end
end, true)
local function c104_morale(room, owner, delta)
    room:setPlayerMark(owner, "&hl_dingjun", owner:getMark("&hl_dingjun") + delta)
end
local c104_dingjun_attachments = {}
hl_dingjun_record = gu_record("#hl_dingjun_record", {sgs.CardUsed, sgs.CardFinished}, function(self, event, room, p, data)
    local use = data:toCardUse(); if not use.card or not use.card:isKindOf("Slash") or not use.from then return end
    if event == sgs.CardUsed then room:addPlayerMark(use.from, "hl_dingjun_slash-Clear")
    elseif use.card:hasFlag("hl_dingjun_granted") then
        local key = use.from:objectName() .. ":" .. use.card:toString()
        local refs = c104_dingjun_attachments[key]
        if refs and #refs > 0 then
            room:detachAttachedSkill(table.remove(refs))
            if #refs == 0 then c104_dingjun_attachments[key] = nil end
        end
        room:setCardFlag(use.card, "-hl_dingjun_granted")
    end
end)
hl_dingjun = gu_trigger("hl_dingjun", {sgs.MarkChanged, sgs.Damage, sgs.CardUsed, sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if event == sgs.MarkChanged then
        local mark = data:toMark()
        if p == owner and mark.name == "&hl_dingjun" and mark.gain ~= 0 then owner:drawCards(1, self:objectName()) end
    elseif event == sgs.Damage then
        local d = data:toDamage()
        if not d.card or not d.card:isKindOf("Slash") then return end
        c104_morale(room, owner, 1)
        if owner:getMark("&hl_dingjun") == room:getPlayers():length() then room:setPlayerMark(owner, "&hl_dingjun_battlefield", 1) end
    elseif event == sgs.CardUsed then
        local use = data:toCardUse()
        if owner:getMark("&hl_dingjun_battlefield") == 0 or owner:getMark("&hl_dingjun") < 2 or not use.card or not use.card:isKindOf("Slash") or not use.from or use.from:getMark("hl_dingjun_slash-Clear") ~= 1 then return end
        if not room:askForSkillInvoke(owner, self:objectName(), sgs.QVariant(use.from)) then return end
        c104_morale(room, owner, -2)
        if not use.from:hasSkill("hl_liegong", true) then
            local parent = sgs.SkillInstanceRef(owner:objectName(), sgs.SkillInstanceKey("hl_dingjun", owner:getValidSkillInstanceIds("hl_dingjun"):first()))
            local ref = room:attachSkillToPlayer(use.from, "hl_liegong", parent, false)
            local key = use.from:objectName() .. ":" .. use.card:toString()
            c104_dingjun_attachments[key] = c104_dingjun_attachments[key] or {}
            table.insert(c104_dingjun_attachments[key], ref)
            room:setCardFlag(use.card, "hl_dingjun_granted")
        end
    elseif p:getPhase() == sgs.Player_Finish and owner:getMark("&hl_dingjun") == 0 then room:setPlayerMark(owner, "&hl_dingjun_battlefield", 0) end
end)
hl_huangzhong:addSkill(hl_lizhan); hl_huangzhong:addSkill(hl_dingjun); hl_huangzhong:addSkill(hl_liegong)
for _, helper in ipairs({hl_lizhan_effect, hl_lizhan_jink, hl_lizhan_damage, hl_lizhan_mod}) do hl_huangzhong:addSkill(helper); extension_hl:insertRelatedSkills("hl_lizhan", helper:objectName()) end
hl_huangzhong:addSkill(hl_dingjun_record); extension_hl:insertRelatedSkills("hl_dingjun", "#hl_dingjun_record")

hl_jiangwei = sgs.General(extension_hl, "hl_jiangwei", "shu", 4)
local function c104_tiaoxin(room, actor, victim)
    if not actor:isAlive() or not victim:isAlive() or victim:isKongcheng() then return false end
    local ids = room:askForCardsChosen(actor, victim, "h", "hl_tiaoxin", 0, math.min(2, victim:getHandcardNum()), false, sgs.Card_MethodDiscard, sgs.IntList(), true)
    local slash = false
    for _, id in sgs.qlist(ids) do if sgs.Sanguosha:getCard(id):isKindOf("Slash") then slash = true end end
    if not ids:isEmpty() then
        local c = gu_dummy(ids); room:throwCard(c, "hl_tiaoxin", victim, actor); c:deleteLater()
    end
    if slash and actor:isAlive() then room:askForDiscard(actor, "hl_tiaoxin", 1, 1, false, true, "@hl_tiaoxin-discard") end
    return slash
end
hl_tiaoxin = gu_trigger("hl_tiaoxin", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Play then return end
    local candidates = sgs.SPlayerList()
    for _, to in sgs.qlist(room:getOtherPlayers(owner)) do if not to:isKongcheng() then candidates:append(to) end end
    if candidates:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, candidates, "hl_tiaoxin", "@hl_tiaoxin-target", true, true)
    if to then c104_tiaoxin(room, owner, to) end
end)
hl_yilve = gu_active("hl_yilve", nil, 0, 0,
    function(self, targets, to, from) return #targets < 5 end,
    function(self, targets) return #targets <= 5 end,
    function(self, room, source, targets)
        room:addPlayerMark(source, "hl_yilve_used-PlayClear")
        local choice = #targets == 2 and room:askForChoice(source, "hl_yilve", "provoke+reveal") or "reveal"
        local acted = false
        if choice == "provoke" then acted = c104_tiaoxin(room, targets[1], targets[2])
        else
            local ids = room:getNCards(5); local slashes = {}; room:fillAG(ids)
            for _, id in sgs.qlist(ids) do room:moveCardTo(sgs.Sanguosha:getCard(id), nil, sgs.Player_PlaceTable, true) end
            for _, to in ipairs(targets) do
                if to:isAlive() and not ids:isEmpty() then
                    local id = room:askForAG(to, ids, false, "hl_yilve"); ids:removeOne(id); room:takeAG(to, id, false)
                    room:obtainCard(to, id, true)
                    if sgs.Sanguosha:getCard(id):isKindOf("Slash") then table.insert(slashes, {to, id}) end
                end
            end
            room:clearAG()
            for _, grant in ipairs(slashes) do
                if grant[1]:isAlive() and room:getCardOwner(grant[2]) == grant[1] and room:askForUseCard(grant[1], tostring(grant[2]), "@hl_yilve-slash", -1, sgs.Card_MethodUse, false) then acted = true end
            end
            if not ids:isEmpty() then local c = gu_dummy(ids); room:throwCard(c, "hl_yilve", nil); c:deleteLater() end
        end
        if acted and source:isAlive() then room:loseHp(source, 1, true, source, "hl_yilve") end
    end, nil,
    function(p) return p:getMark("hl_yilve_used-PlayClear") < 1 + p:getMark("hl_yilve_extra-PlayClear") end)
hl_qiezhi = gu_trigger("hl_qiezhi", {sgs.GameStart, sgs.HpChanged, sgs.HpRecover}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.GameStart then room:setPlayerMark(owner, "hl_qiezhi_hp", owner:getHp()); return end
    if event == sgs.HpChanged then
        local old = owner:getMark("hl_qiezhi_hp"); room:setPlayerMark(owner, "hl_qiezhi_hp", owner:getHp())
        if owner:getHp() < old and owner:getLostHp() > 0 then owner:drawCards(owner:getLostHp(), self:objectName()) end
    elseif owner:getPhase() == sgs.Player_Play and owner:getMark("hl_qiezhi_paid-PlayClear") < 5 then
        local c = room:askForCard(owner, ".", "@hl_qiezhi-discard", data, sgs.Card_MethodDiscard, nil, false, self:objectName())
        if c then room:addPlayerMark(owner, "hl_qiezhi_paid-PlayClear"); room:addPlayerMark(owner, "hl_yilve_extra-PlayClear") end
    end
end, true)
hl_jiangwei:addSkill(hl_tiaoxin); hl_jiangwei:addSkill(hl_yilve); hl_jiangwei:addSkill(hl_qiezhi)

sgs.LoadTranslationTable {
    ["hl_machao"] = "马超[欢乐2025]", ["&hl_machao"] = "马超",
    ["hl_dangfeng"] = "荡锋", [":hl_dangfeng"] = "一名角色的结束阶段，若本回合没有角色：受到过伤害，你获得一张【杀】；使用过【杀】，你可以使用一张【杀】。",
    ["hl_tieqi"] = "铁骑", [":hl_tieqi"] = "当你使用【杀】指定一名角色为目标后，你可以令其本回合所有非锁定技失效，然后你进行判定，若结果为：红色，其不能使用【闪】响应此【杀】；黑色，你摸两张牌。",
    ["hl_haiji"] = "骇击", [":hl_haiji"] = "锁定技，当你使用【杀】指定一名角色为目标后，你本轮计算与其他角色的距离-1，然后若你与此【杀】目标角色/所有其他角色的距离均为1，你摸一张牌/发动〖铁骑〗。你每回合使用的首张【杀】可以多指定一个目标。",
