-- ==================== c1a_05
do
-- c1a_05: chapter-one 2026 battlefield generals.
local function hl_c1a05_card(name, skill)
    local c = sgs.Sanguosha:cloneCard(name, sgs.Card_NoSuit, 0)
    c:setSkillName(skill)
    c:deleteLater()
    return c
end
local function hl_c1a05_field(room, name)
    room:setTag("hl_c1a05_battlefield", sgs.QVariant(name))
    for _, q in sgs.qlist(room:getAllPlayers()) do
        room:setPlayerMark(q, "&hl_andu_jiangling", name == "jiangling" and 1 or 0)
        room:setPlayerMark(q, "&hl_pozhan_jieqiao", name == "jieqiao" and 1 or 0)
    end
end
local function hl_c1a05_infield(room, name)
    return room:getTag("hl_c1a05_battlefield"):toString() == name
end
local function hl_c1a05_number(room, owner)
    local n = tonumber(room:askForChoice(owner, "hl_pozhan", "2+3+4+5")) or 2
    room:setPlayerMark(owner, "&hl_pozhan_number", n)
    room:setPlayerMark(owner, "hl_pozhan_lost", 0)
    room:setPlayerMark(owner, "hl_pozhan_slashes", 0)
end

hl_lvmeng = sgs.General(extension_hl, "hl_lvmeng", "wu", 4)
hl_mingtan = gu_trigger("hl_mingtan", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Start or not gu_invoke(owner, "hl_mingtan", data) then return end
    local x = 0
    for _, q in sgs.qlist(room:getAlivePlayers()) do if q:hasSkill("keji") then x = x + 1 end end
    x = math.max(1, math.min(5, x))
    local others = room:getOtherPlayers(owner)
    if others:isEmpty() then return end
    local target = room:askForPlayerChosen(owner, others, "hl_mingtan", "@hl_mingtan-target", false, true)
    for i = 1, x do
        if not owner:isAlive() or not target:isAlive() then break end
        local c = hl_c1a05_card("dismantlement", "hl_mingtan")
        if owner:isCardLimited(c, sgs.Card_MethodUse) or not c:targetFilter(sgs.PlayerList(), target, owner)
            or owner:isProhibited(target, c) then break end
        if room:askForChoice(owner, "hl_mingtan", "hl_mingtan_use+hl_mingtan_stop", sgs.QVariant(target)) ~= "hl_mingtan_use" then break end
        room:useCard(sgs.CardUseStruct(c, owner, target), false)
    end
    if owner:isAlive() then owner:drawCards(x, "hl_mingtan") end
    -- The holders are determined after the draw, not before the dismantlements.
    local holders = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getAlivePlayers()) do if q:hasSkill("keji") then holders:append(q) end end
    for _, q in sgs.qlist(holders) do
        if q:isAlive() and q:hasSkill("keji") then
            local slash = hl_c1a05_card("slash", "hl_mingtan")
            local choices = "hl_mingtan_lose"
            if target:isAlive() and q:canSlash(target, slash, true) and not q:isCardLimited(slash, sgs.Card_MethodUse)
                and slash:isAvailable(q) then choices = "hl_mingtan_slash+" .. choices end
            local choice = room:askForChoice(q, "hl_mingtan", choices, sgs.QVariant(target))
            local used = choice == "hl_mingtan_slash" and room:askForUseSlashTo(q, target, "@hl_mingtan-slash:" .. target:objectName(), true, true, true)
            if not used then room:detachSkillFromPlayer(q, "keji") end
        end
    end
end)

hl_andu = gu_trigger("hl_andu", {sgs.EventPhaseStart, sgs.EventPhaseEnd, sgs.EventLoseSkill}, function(self, event, room, p, data, owner)
    if not p then return end
    if event == sgs.EventLoseSkill then
        if data:toSkillChange().skillName ~= "keji" or not hl_c1a05_infield(room, "jiangling") then return end
        owner:drawCards(1, "hl_andu")
        local any = false
        for _, q in sgs.qlist(room:getAlivePlayers()) do if q:hasSkill("keji") then any = true end end
        if not any and hl_c1a05_infield(room, "jiangling") then hl_c1a05_field(room, "") end
        return
    end
    local enter = (event == sgs.EventPhaseStart and p == owner and p:getPhase() == sgs.Player_RoundStart)
        or (event == sgs.EventPhaseEnd and p:getPhase() == sgs.Player_Discard and p:getMark("hl_andu_discarded") == 0)
    if enter then
        hl_c1a05_field(room, "jiangling")
        for _, q in sgs.qlist(room:getAlivePlayers()) do
            local old = q:getTag("hl_andu_grants"):toString():match("^(%d+),")
            local id = old and tonumber(old) or 0
            if id > 0 and not q:getSkillInstanceIds("keji"):contains(id) then id = 0 end
            -- Re-entering refreshes this temporary grant; an existing independent
            -- copy is neither duplicated nor detached at the temporary expiry.
            if id == 0 and not q:hasSkill("keji", true) then id = room:acquireSkill(q, "keji") end
            if id and id > 0 then
                q:setTag("hl_andu_grants", sgs.QVariant(id .. "," .. (q:getMark("hl_andu_turns") + 1)))
            else q:removeTag("hl_andu_grants") end
        end
    elseif event == sgs.EventPhaseStart and p ~= owner and p:getPhase() == sgs.Player_Finish
        and hl_c1a05_infield(room, "jiangling") and gu_invoke(owner, "hl_andu", sgs.QVariant(p)) then
        if p:getMark("hl_andu_keji-Clear") > 0 then
            local ids = sgs.IntList()
            for _, c in sgs.qlist(p:getCards("he")) do if c:isKindOf("Slash") then ids:append(c:getEffectiveId()) end end
            gu_obtain(room, owner, ids, "hl_andu")
        else
            if not p:isNude() then
                local id = room:askForCardChosen(owner, p, "he", "hl_andu")
                room:obtainCard(owner, id, false)
            end
            if owner:isAlive() and p:isAlive() then
                local c = hl_c1a05_card("slash", "hl_andu")
                if not owner:isCardLimited(c, sgs.Card_MethodUse) and owner:canSlash(p, c, true) then
                    room:useCard(sgs.CardUseStruct(c, owner, p), false)
                end
            end
        end
    end
end)
hl_lvmeng:addSkill(hl_mingtan)
hl_lvmeng:addSkill(hl_andu)

-- The expiry rule survives loss/death of the grantor. Every acquisition has its own ID.
hl_andu_record = gu_record("#hl_andu_record", {sgs.EventPhaseStart, sgs.ChoiceMade, sgs.CardsMoveOneTime}, function(self, event, room, p, data)
    if event == sgs.CardsMoveOneTime then
        local move = data:toMoveOneTime()
        if move.from and p and p:objectName() == move.from:objectName() and move.from:getPhase() == sgs.Player_Discard
            and (move.reason.m_reason % 16) == sgs.CardMoveReason_S_REASON_DISCARD then
            local from = room:findPlayerByObjectName(move.from:objectName())
            if from then room:addPlayerMark(from, "hl_andu_discarded", move.card_ids:length()) end
        end
    elseif event == sgs.ChoiceMade then
        if p and data:toString():match("^skillInvoke:keji[#:]?.*:yes$") then room:setPlayerMark(p, "hl_andu_keji-Clear", 1) end
    elseif p then
        if p:getPhase() == sgs.Player_RoundStart then room:addPlayerMark(p, "hl_andu_turns", 1) end
        if p:getPhase() == sgs.Player_Discard then room:setPlayerMark(p, "hl_andu_discarded", 0) end
    end
end)
hl_andu_record.priority = 20
extension_hl:addSkills(hl_andu_record)
extension_hl:insertRelatedSkills("hl_andu", "#hl_andu_record")
hl_andu_expire = sgs.CreateRuleSkillV2 {
    name = "#hl_andu_expire", global = true, priority = -10,
    events = {sgs.EventPhaseStart},
    can_trigger = function(self, event, room, p, data)
        return p and p:getPhase() == sgs.Player_Finish and p:getTag("hl_andu_grants"):toString() ~= "" and self:objectName() or false
    end,
    on_effect = function(self, event, room, p, ctx)
        local keep, expire = {}, {}
        for entry in p:getTag("hl_andu_grants"):toString():gmatch("[^+]+") do
            local id, turn = entry:match("^(%d+),(%d+)$")
            if id and tonumber(turn) <= p:getMark("hl_andu_turns") then table.insert(expire, tonumber(id))
            else table.insert(keep, entry) end
        end
        p:setTag("hl_andu_grants", sgs.QVariant(table.concat(keep, "+")))
        for _, id in ipairs(expire) do room:detachSkillFromPlayer(p, "keji#" .. id) end
        return false
    end,
}
extension_hl:addSkills(hl_andu_expire)
extension_hl:insertRelatedSkills("hl_andu", "#hl_andu_expire")

hl_yuanshao = sgs.General(extension_hl, "hl_yuanshao", "qun", 4)
hl_hedou = gu_trigger("hl_hedou", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if not use.card or not use.card:isKindOf("TrickCard") or use.to:length() < 2 then return end
    local choices = {}
    if owner:getMark("hl_hedou_double-Clear") == 0 then table.insert(choices, "hl_hedou_double") end
    if owner:getMark("hl_hedou_gain-Clear") == 0 then table.insert(choices, "hl_hedou_gain") end
    if #choices == 0 or not gu_invoke(owner, "hl_hedou", data) then return end
    owner:setTag("hl_hedou_use", data)
    local to = room:askForPlayerChosen(owner, use.to, "hl_hedou", "@hl_hedou-target", false, true)
    owner:setTag("hl_hedou_target", sgs.QVariant(to))
    local choice = room:askForChoice(owner, "hl_hedou", table.concat(choices, "+"), data)
    owner:removeTag("hl_hedou_use")
    owner:removeTag("hl_hedou_target")
    room:setPlayerMark(owner, choice .. "-Clear", 1)
    local nullified = use.nullified_list
    if choice == "hl_hedou_double" then
        for _, q in sgs.qlist(use.to) do
            if q ~= to and not table.contains(nullified, q:objectName()) then table.insert(nullified, q:objectName()) end
        end
        local key = "hl_hedou_double_" .. to:objectName()
        use.card:setTag(key, sgs.QVariant(use.card:getTag(key):toInt() + 1))
    else
        if not table.contains(nullified, to:objectName()) then table.insert(nullified, to:objectName()) end
        local ids = use.card:isVirtualCard() and use.card:getSubcards() or sgs.IntList()
        if not use.card:isVirtualCard() then ids:append(use.card:getEffectiveId()) end
        -- Room tags survive CardFinished (including delayed tricks in the judging area).
        for _, id in sgs.qlist(ids) do
            local key = "hl_hedou_gain_" .. id
            local pending = room:getTag(key):toString()
            room:setTag(key, sgs.QVariant(pending .. (pending == "" and "" or "+") .. owner:objectName()))
        end
    end
    use.nullified_list = nullified
    data:setValue(use)
end)
hl_yuanshao:addSkill(hl_hedou)
hl_hedou_record = sgs.CreateRuleSkillV2 {
    name = "#hl_hedou_record", global = true, priority = 10,
    events = {sgs.CardEffected, sgs.CardsMoveOneTime, sgs.CardFinished},
    can_trigger = function(self, event, room, p, data)
        if event == sgs.CardEffected then
            local e = data:toCardEffect()
            return e.card and e.to and e.card:getTag("hl_hedou_double_" .. e.to:objectName()):toInt() > 0 and self:objectName() or false
        end
        return self:objectName()
    end,
    on_effect = function(self, event, room, p, ctx)
        local data = ctx.original_data
        if event == sgs.CardEffected then
            local e = data:toCardEffect()
            e.extra_effect = e.extra_effect + e.card:getTag("hl_hedou_double_" .. e.to:objectName()):toInt()
            data:setValue(e)
        elseif event == sgs.CardFinished then
            local use = data:toCardUse()
            if use.card then
                for _, q in sgs.qlist(room:getAllPlayers(true)) do use.card:removeTag("hl_hedou_double_" .. q:objectName()) end
            end
        else
            local move = data:toMoveOneTime()
            if move.to_place ~= sgs.Player_DiscardPile then return false end
            for _, id in sgs.qlist(move.card_ids) do
                local key = "hl_hedou_gain_" .. id
                local pending = room:getTag(key):toString()
                room:removeTag(key)
                for name in pending:gmatch("[^+]+") do
                    local q = room:findPlayerByObjectName(name)
                    if q and q:isAlive() and room:getCardPlace(id) == sgs.Player_DiscardPile then
                        room:obtainCard(q, id, true)
                    end
                end
            end
        end
        return false
    end,
}
extension_hl:addSkills(hl_hedou_record)
extension_hl:insertRelatedSkills("hl_hedou", "#hl_hedou_record")

hl_pozhan = gu_trigger("hl_pozhan", {sgs.GameStart, sgs.CardsMoveOneTime, sgs.CardUsed, sgs.CardResponded}, function(self, event, room, p, data, owner)
    if event == sgs.GameStart then
        if p == owner then hl_c1a05_number(room, owner) end
        return
    end
    local x = owner:getMark("&hl_pozhan_number")
    if x < 2 then return end
    if event == sgs.CardsMoveOneTime then
        local move = data:toMoveOneTime()
        if p == owner and move.from and move.from:objectName() == owner:objectName()
            and (not move.to or move.to:objectName() ~= owner:objectName()) then
            room:addPlayerMark(owner, "hl_pozhan_lost", move.card_ids:length())
            if not hl_c1a05_infield(room, "jieqiao") and owner:getMark("hl_pozhan_lost") >= 6 - x then
                room:setPlayerMark(owner, "hl_pozhan_slashes", 0)
                hl_c1a05_field(room, "jieqiao")
            end
        end
        return
    end
    if not hl_c1a05_infield(room, "jieqiao") or owner:getMark("hl_pozhan_resolving") > 0 then return end
    local card
    if event == sgs.CardUsed then card = data:toCardUse().card else card = data:toCardResponse().m_card end
    if not card or not card:isKindOf("Slash") then return end
    room:addPlayerMark(owner, "hl_pozhan_slashes", 1)
    if owner:getMark("hl_pozhan_slashes") < x or not gu_invoke(owner, "hl_pozhan", data) then return end
    room:setPlayerMark(owner, "hl_pozhan_resolving", 1)
    owner:drawCards(4, "hl_pozhan")
    local current = room:getCurrent()
    if current and current:isAlive() then
        if current:getHandcardNum() < x then current:drawCards(x - current:getHandcardNum(), "hl_pozhan") end
        if current:isAlive() and current:getHandcardNum() >= x then
            local selected = room:askForExchange(current, "hl_pozhan", x, x, false, "@hl_pozhan-cards")
            if selected then
                local c = hl_c1a05_card("archery_attack", "hl_pozhan")
                c:addSubcards(selected:getSubcards())
                if not current:isCardLimited(c, sgs.Card_MethodUse, true) then room:useCard(sgs.CardUseStruct(c, current), false) end
                selected:deleteLater()
            end
        end
    end
    hl_c1a05_field(room, "")
    if owner:isAlive() then hl_c1a05_number(room, owner) end
    room:setPlayerMark(owner, "hl_pozhan_resolving", 0)
end)
hl_yuanshao:addSkill(hl_pozhan)

