-- ==================== c1b_01
do
-- c1b_01: 徐庶 / 于吉 are skipped as documented in report.md.
-- Rival status follows the skill owner's current gender, including after switching.
local function hl_c1b_rival(owner, other)
    return owner and other and owner:getGender() == other:getGender()
end

local function hl_c1b_switch(room, owner)
    if owner:getMark("hl_qingchan_form") == 3 then return end
    room:setPlayerMark(owner, "hl_qingchan_form", 3)
    -- The excerpt specifies HP/gender only for the two initial forms.
    -- Switching therefore preserves both and restores the two printed skills.
    room:handleAcquireDetachSkills(owner, "hl_qingzhan|hl_qingyuan")
end

hl_lvbudiaochan = sgs.General(extension_hl, "hl_lvbudiaochan", "qun", 5)

hl_qingzhan = gu_active("hl_qingzhan", 1, 0, 0, gu_one, gu_one_feasible,
    function(self, room, source, targets)
        local opponent = targets[1]
        if not opponent or source:isDead() or opponent:isDead() then return end
        local repeated = hl_c1b_rival(source, opponent)
        room:addPlayerMark(source, "hl_qingzhan_active")
        room:addPlayerMark(opponent, "hl_qingzhan_active")
        local source_dying = source:getMark("hl_qingzhan_dying")
        local opponent_dying = opponent:getMark("hl_qingzhan_dying")
        local function stopped()
            return source:isDead() or opponent:isDead()
                or source:getMark("hl_qingzhan_dying") ~= source_dying
                or opponent:getMark("hl_qingzhan_dying") ~= opponent_dying
        end
        repeat
            for _, pair in ipairs({{source, opponent}, {opponent, source}}) do
                if stopped() then break end
                local actor, target = pair[1], pair[2]
                local choice = room:askForChoice(actor, "hl_qingzhan", "slash+losehp", sgs.QVariant(target))
                -- A cancelled Slash request is the HP-loss choice; no free pass.
                if choice ~= "slash" or not room:askForUseSlashTo(actor, target,
                    "@hl_qingzhan-slash:" .. target:objectName(), false, true, false) then
                    room:loseHp(actor, 1, true, source, "hl_qingzhan")
                end
            end
        until not repeated or stopped()
        room:removePlayerMark(source, "hl_qingzhan_active")
        room:removePlayerMark(opponent, "hl_qingzhan_active")
    end)

-- Record entry, rather than HP after rescue: entering dying ends the duel even
-- if a Peach immediately saves that participant. Counters also survive nesting.
hl_qingzhan_dying = gu_record("#hl_qingzhan_dying", {sgs.EnterDying},
    function(self, event, room, player, data)
        if player and player:getMark("hl_qingzhan_active") > 0 then
            room:addPlayerMark(player, "hl_qingzhan_dying")
        end
    end)

local function hl_c1b_beneficiary(room, owner)
    local name = owner:getTag("hl_qingyuan_recipient"):toString()
    if name == "" then return owner end
    for _, p in sgs.qlist(room:getAlivePlayers()) do
        if p:objectName() == name then return p end
    end
    -- A dead recipient does not return the effect before the round ends.
    return nil
end

local function hl_c1b_random_discard(room, owner, target)
    if not hl_c1b_rival(owner, target) or target:isKongcheng() then return end
    local ids = target:handCards()
    room:throwCard(ids:at(math.random(0, ids:length() - 1)), "hl_qingyuan", target)
end

hl_qingyuan = gu_trigger("hl_qingyuan",
    {sgs.Damage, sgs.TargetConfirmed, sgs.RoundStart, sgs.RoundEnd},
    function(self, event, room, player, data, owner)
        if event == sgs.RoundEnd then
            owner:removeTag("hl_qingyuan_recipient")
            return
        end
        if event == sgs.RoundStart then
            owner:removeTag("hl_qingyuan_recipient")
            local choices = sgs.SPlayerList()
            for _, p in sgs.qlist(room:getOtherPlayers(owner)) do
                if not hl_c1b_rival(owner, p) then choices:append(p) end
            end
            if not choices:isEmpty() then
                local target = room:askForPlayerChosen(owner, choices, "hl_qingyuan",
                    "@hl_qingyuan-transfer", true, true)
                if target then owner:setTag("hl_qingyuan_recipient", sgs.QVariant(target:objectName())) end
            end
            return
        end
        local beneficiary = hl_c1b_beneficiary(room, owner)
        if not beneficiary or player ~= beneficiary then return end
        local other
        if event == sgs.Damage then
            local damage = data:toDamage()
            if damage.from ~= beneficiary then return end
            other = damage.to
        else
            local use = data:toCardUse()
            if not use.card or not use.card:isDamageCard() or not use.to:contains(beneficiary) then return end
            other = use.from
        end
        room:sendCompulsoryTriggerLog(owner, "hl_qingyuan", true)
        beneficiary:drawCards(1, "hl_qingyuan")
        -- After transfer, "you" refers to the recipient of the effect.
        hl_c1b_random_discard(room, beneficiary, other)
    end, true)

hl_qingchan = gu_trigger("hl_qingchan", {sgs.GameStart, sgs.EnterDying, sgs.Death},
    function(self, event, room, player, data, owner)
        if event == sgs.GameStart then
            if player ~= owner or owner:getMark("hl_qingchan_form") > 0 then return end
            local choice = room:askForChoice(owner, "hl_qingchan", "lvbu+diaochan")
            local male = choice == "lvbu"
            room:setPlayerMark(owner, "hl_qingchan_form", male and 1 or 2)
            room:setPlayerProperty(owner, "gender", sgs.QVariant(male and sgs.General_Male or sgs.General_Female))
            room:setPlayerProperty(owner, "maxhp", sgs.QVariant(male and 5 or 3))
            room:setPlayerProperty(owner, "hp", sgs.QVariant(male and 5 or 3))
            room:detachSkillFromPlayer(owner, male and "hl_qingyuan" or "hl_qingzhan")
        elseif event == sgs.EnterDying then
            if player == owner and owner:getMark("hl_qingchan_first_dying") == 0 then
                room:setPlayerMark(owner, "hl_qingchan_first_dying", 1)
                hl_c1b_switch(room, owner)
            end
        else
            local death = data:toDeath()
            if hl_c1b_rival(owner, death.who) then hl_c1b_switch(room, owner) end
        end
    end, true)

hl_lvbudiaochan:addSkill(hl_qingzhan)
hl_lvbudiaochan:addSkill(hl_qingyuan)
