hl_jibian = gu_trigger("hl_jibian", {sgs.EventPhaseStart}, function(self, event, room, player, data, owner)
    if player:getPhase() ~= sgs.Player_Finish or not gu_invoke(owner, self:objectName(), data) then return end
    if owner:getMark("hl_langgu-Clear") > 0 then
        room:askForGuanxing(owner, room:getNCards(5, false, false), sgs.Room_GuanxingDownOnly)
    else
        local targets = sgs.SPlayerList()
        targets:append(owner)
        if player ~= owner and player:isAlive() then targets:append(player) end
        local target = room:askForPlayerChosen(owner, targets, self:objectName(), "@hl_jibian-damage", false)
        if target then
            local damage = sgs.DamageStruct()
            damage.from = owner; damage.to = target; damage.damage = 1; damage.reason = self:objectName()
            room:damage(damage)
        end
    end
end)

hl_langgu = gu_trigger("hl_langgu", {sgs.EventPhaseStart, sgs.Damaged}, function(self, event, room, player, data, owner)
    if player ~= owner or (event == sgs.EventPhaseStart and player:getPhase() ~= sgs.Player_Play)
        or not gu_invoke(owner, self:objectName(), data) then return end
    room:setPlayerMark(owner, "hl_langgu-Clear", 1)
    local choices = {"0", "1", "2", "3", "4", "5"}
    local n = tonumber(room:askForChoice(owner, "hl_langgu_count", table.concat(choices, "+"))) or 0
    local bottom = room:getNCards(n, false, false)
    n = bottom:length()
    local current = room:getCurrent()
    local selected = sgs.IntList()
    local available = sgs.IntList()
    for _, id in sgs.qlist(bottom) do available:append(id) end
    if current and current:isAlive() and not current:isKongcheng() and not available:isEmpty() then
        local viewers = sgs.SPlayerList(); viewers:append(owner)
        room:fillAG(available, owner)
        while selected:length() < current:getHandcardNum() and not available:isEmpty() do
            local id = room:askForAG(owner, available, true, self:objectName(), "@hl_langgu-bottom")
            if id < 0 then break end
            selected:append(id); available:removeOne(id)
            room:takeAG(owner, id, false, viewers)
        end
        room:clearAG(owner)
    elseif not bottom:isEmpty() then
        room:fillAG(bottom, owner)
        room:askForAG(owner, bottom, true, self:objectName(), "@hl_langgu-view")
        room:clearAG(owner)
    end
    if not selected:isEmpty() and current and current:isAlive() then
        local hand = sgs.IntList()
        for i = 1, selected:length() do
            local id = room:askForCardChosen(owner, current, "h", self:objectName(), false, sgs.Card_MethodNone, hand)
            hand:append(id)
        end
        local replacement = sgs.IntList()
        local index = 0
        for _, id in sgs.qlist(bottom) do
            if selected:contains(id) then replacement:append(hand:at(index)); index = index + 1
            else replacement:append(id) end
        end
        local moves = sgs.CardsMoveList()
        local incoming = sgs.CardsMoveStruct()
        incoming.card_ids = selected; incoming.to = current; incoming.to_place = sgs.Player_Hand
        incoming.reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_SWAP, owner:objectName(), self:objectName(), "")
        moves:append(incoming)
        local outgoing = sgs.CardsMoveStruct()
        outgoing.card_ids = hand; outgoing.from = current; outgoing.to_place = sgs.Player_PlaceTable
        outgoing.reason = incoming.reason; moves:append(outgoing)
        room:moveCardsAtomic(moves, false)
        bottom = replacement
    end
    room:returnToEndDrawPile(bottom)
    if not owner:isAlive() or not room:askForSkillInvoke(owner, "hl_langgu_reveal", data) then return end
    -- Re-read after exchange triggers, so these really are the current bottom cards.
    local revealed = room:getNCards(n, false, false)
    if revealed:isEmpty() then return end
    room:showCard(owner, revealed)
    local suit = sgs.Sanguosha:getCard(revealed:first()):getSuit()
    local same = true
    for _, id in sgs.qlist(revealed) do
        if sgs.Sanguosha:getCard(id):getSuit() ~= suit then same = false end
    end
    if same then gu_obtain(room, owner, revealed, self:objectName())
    else
        room:returnToEndDrawPile(revealed)
        room:moveField(owner, self:objectName(), true, "ej")
    end
end)
