hl_quanxue = gu_trigger("hl_quanxue", {sgs.EventPhaseStart}, function(self, event, room, player, data, owner)
    if player ~= owner or player:getPhase() ~= sgs.Player_Play then return end
    local targets = room:askForPlayersChosen(owner, room:getOtherPlayers(owner), self:objectName(), 0, 2, "@hl_quanxue")
    for _, target in sgs.qlist(targets) do room:addPlayerMark(target, "&hl_quanxue") end
end)
-- Removal and its consequences must run even if the granting general dies/loses the skill.
hl_quanxue_clear = gu_record("#hl_quanxue_clear", {sgs.TurnStart}, function(self, event, room, player, data)
    if not player or player:getMark("&hl_quanxue") == 0 then return end
    room:setPlayerMark(player, "&hl_quanxue", 0)
    for _, owner in sgs.qlist(room:getAlivePlayers()) do
        if owner ~= player and owner:hasSkill("hl_dingli") and owner:getMark("hl_dingli_lun") == 0 then
            local difference = owner:getHp() - player:getHp()
            if gu_invoke(owner, "hl_dingli", sgs.QVariant(player)) then
                room:setPlayerMark(owner, "hl_dingli_lun", 1)
                if difference <= 0 then
                    local recover = sgs.RecoverStruct(); recover.who = owner; recover.recover = 1
                    room:recover(owner, recover)
                else owner:drawCards(math.min(2, difference), "hl_dingli") end
            end
        end
    end
    if not player:isAlive() then return end
    if room:askForChoice(player, "hl_quanxue", "hl_quanxue_restrict+hl_quanxue_losehp") == "hl_quanxue_losehp" then
        room:loseHp(player, 1)
    else room:setPlayerMark(player, "hl_quanxue_restrict-Clear", 1) end
end)
