do
-- c1b_03: literal SP variants, SkillV2.
local function hl03_convert(name, cardname, match)
    return sgs.CreateViewAsSkillV2 {
        name = name, n = 1, response_or_use = true,
        can_activate = function(self, request)
            if request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY then
                if cardname ~= "peach" then return false end
                return request:getInitiator():isWounded()
                    and request:getInitiator():getMark("Global_PreventPeach") == 0
            end
            return string.find(request:getPattern(), cardname, 1, true) ~= nil
                and (cardname ~= "peach" or request:getInitiator():getMark("Global_PreventPeach") == 0)
        end,
        can_select_card = function(self, request, card)
            return request:getSelectedCardIds():isEmpty() and match(card)
        end,
        card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
        create_card = function(self, request)
            local id = request:getSelectedCardIds():first()
            local original = sgs.Sanguosha:getCard(id)
            local card = sgs.Sanguosha:cloneCard(cardname, original:getSuit(), original:getNumber())
            card:addSubcard(id); card:setSkillName(name)
            return card
        end,
    }
end
local function hl03_recover(room, who, amount, healer)
    if amount <= 0 or not who:isAlive() then return end
    local recover = sgs.RecoverStruct(); recover.who = healer; recover.recover = amount
    room:recover(who, recover)
end
local function hl03_huimou(room, owner)
    if not owner:isAlive() or not owner:hasSkill("hl_huimou") then return end
    local targets = room:getAlivePlayers()
    local target = room:askForPlayerChosen(owner, targets, "hl_huimou", "@hl_huimou", true, true)
    if target and not target:faceUp() then target:turnOver() end
end

