hl_taoxian = hl03_convert("hl_taoxian", "peach", function(c) return c:getSuit() == sgs.Card_Heart end)
hl_taoxian_draw = gu_trigger("#hl_taoxian_draw", {sgs.CardUsed}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner and use.card and use.card:isKindOf("Peach") then owner:drawCards(1, "hl_taoxian") end
end, true)
-- gu_trigger normally checks the helper's name; attach it along with the main skill.
hl_jishi = gu_trigger("hl_jishi", {sgs.GameStart, sgs.Dying, sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    if event == sgs.GameStart then
        room:setPlayerMark(owner, "&hl_jishi", 3)
    elseif event == sgs.Dying then
        local dying = data:toDying().who
        if dying and dying:getHp() < 1 and owner:getMark("&hl_jishi") > 0 and gu_invoke(owner, "hl_jishi", data) then
            room:removePlayerMark(owner, "&hl_jishi")
            hl03_recover(room, dying, 1 - dying:getHp(), owner)
        end
    elseif owner:getPhase() == sgs.Player_NotActive then
        local move = data:toMoveOneTime()
        if not move.from or move.from:objectName() ~= owner:objectName() then return end
        local n = 0
        for i, id in sgs.qlist(move.card_ids) do
            if move.from_places:at(i) == sgs.Player_PlaceHand and sgs.Sanguosha:getCard(id):isRed() then n = n + 1 end
        end
        if n > 0 then room:setPlayerMark(owner, "&hl_jishi", math.min(3, owner:getMark("&hl_jishi") + n)) end
    end
end)
hl_jishi_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hl_jishi_max", correct_func = function(self, ctx)
        local p = ctx:getPrimary(); return p and p:hasSkill("hl_jishi") and 3 or 0
    end,
}
hl_shenzhen = gu_trigger("hl_shenzhen", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_RoundStart or not gu_invoke(owner, "hl_shenzhen") then return end
    local choices = {"0"}
    for i = 1, math.min(owner:getMark("&hl_jishi"), room:alivePlayerCount()) do table.insert(choices, tostring(i)) end
    local n = tonumber(room:askForChoice(owner, "hl_shenzhen", table.concat(choices, "+"))) or 0
    room:removePlayerMark(owner, "&hl_jishi", n)
    local mode = room:askForChoice(owner, "hl_shenzhen", "recover+losehp")
    if n == 0 then return end
    local chosen = room:askForPlayersChosen(owner, room:getAlivePlayers(), "hl_shenzhen", n, n, "@hl_shenzhen")
    for _, target in sgs.qlist(chosen) do
        if target:isAlive() then
            if mode == "recover" then hl03_recover(room, target, 1, owner) else room:loseHp(target, 1) end
        end
    end
end)
