-- ==================== c1b_04
do
-- c1b_04: strategy state is private (tags, never public marks).
local function hl_plan_key(owner, target)
    return "hl_lunce_plan_" .. owner:objectName() .. "_" .. target:objectName()
end
local function hl_plan_assign(room, owner)
    if not owner:isAlive() or not gu_invoke(owner, "hl_lunce") then return end
    local to = room:askForPlayerChosen(owner, room:getAlivePlayers(), "hl_lunce", "@hl_lunce-target", false, false)
    if not to then return end
    local choice = room:askForChoice(owner, "hl_lunce", "upper+middle+lower")
    local key = hl_plan_key(owner, to)
    -- Each activation grants a strategy; repeat grants coexist rather than overwrite.
    local plans = owner:getTag(key):toString()
    owner:setTag(key, sgs.QVariant(plans == "" and choice or plans .. "+" .. choice))
end
local function hl_plan_success(room, owner)
    local n = owner:getTag("hl_lunce_success"):toInt()
    owner:setTag("hl_lunce_success", sgs.QVariant(n + 1))
end
local function hl_plan_recover(room, owner, to)
    local rec = sgs.RecoverStruct()
    rec.who = owner
    room:recover(to, rec)
end

hl_sp_pangtong = sgs.General(extension_hl, "hl_sp_pangtong", "god", 3, true)

-- Track the whole turn, including actions before a strategy is granted.
extension_hl:addSkills(gu_record("#hl_lunce_record", {sgs.TurnStart, sgs.CardUsed, sgs.Damage, sgs.RoundStart},
    function(self, event, room, player, data)
        if event == sgs.RoundStart then
            for _, q in sgs.qlist(room:getAllPlayers()) do q:removeTag("hl_lunce_success") end
        elseif event == sgs.TurnStart then
            if player then
                player:removeTag("hl_lunce_slashes")
                player:removeTag("hl_lunce_slash_damage")
            end
        elseif event == sgs.CardUsed then
            local use = data:toCardUse()
            if use.from and use.from:getPhase() ~= sgs.Player_NotActive and use.card and use.card:isKindOf("Slash") then
                use.from:setTag("hl_lunce_slashes", sgs.QVariant(use.from:getTag("hl_lunce_slashes"):toInt() + 1))
            end
        else
            local damage = data:toDamage()
            if damage.from and damage.from:getPhase() ~= sgs.Player_NotActive and damage.card and damage.card:isKindOf("Slash") then
                damage.from:setTag("hl_lunce_slash_damage", sgs.QVariant(true))
            end
        end
    end))

hl_lunce = gu_trigger("hl_lunce", {sgs.RoundStart, sgs.EventPhaseStart, sgs.CardUsed},
    function(self, event, room, player, data, owner)
        if event == sgs.RoundStart then hl_plan_assign(room, owner); return end
        if not player or player:getPhase() == sgs.Player_NotActive then return end
        local key = hl_plan_key(owner, player)
        local text = owner:getTag(key):toString()
        if text == "" then return end
        local plans = text:split("+")
        if event == sgs.CardUsed then
            local use = data:toCardUse()
            if not use.card or not use.card:isKindOf("Slash") or use.from ~= player
                or player:getTag("hl_lunce_slashes"):toInt() ~= 1 then return end
            for i, plan in ipairs(plans) do
                if plan == "middle" then
                    plans[i] = "middle_done"
                    hl_plan_success(room, owner)
                    if not player:isNude() and owner:isAlive() then
                        local id = room:askForCardChosen(owner, player, "he", "hl_lunce")
                        room:obtainCard(owner, id, false)
                    end
                end
            end
            owner:setTag(key, sgs.QVariant(table.concat(plans, "+")))
        elseif player:getPhase() == sgs.Player_Play then
            -- Persist state before the nested Slash event so middle strategies can also finish.
            for i, plan in ipairs(plans) do
                if plan == "upper" then
                    local slash = room:askForUseSlashTo(player, room:getOtherPlayers(player), "@hl_lunce-slash", false, false, false)
                    local latest = owner:getTag(key):toString():split("+")
                    if slash then latest[i] = "upper_done"; hl_plan_success(room, owner) end
                    owner:setTag(key, sgs.QVariant(table.concat(latest, "+")))
                end
            end
        elseif player:getPhase() == sgs.Player_Finish and not player:getTag("hl_lunce_slash_damage"):toBool() then
            for _, plan in ipairs(plans) do
                if plan == "lower" and owner:isAlive() and player:isAlive() and gu_invoke(owner, "hl_lunce", sgs.QVariant(player)) then
                    local cards = room:askForExchange(owner, "hl_lunce", 3, 0, true, "@hl_lunce-give:" .. player:objectName(), true)
                    if cards then
                        if cards:subcardsLength() > 0 then room:obtainCard(player, cards, false) end
                        cards:deleteLater()
                    end
                    if player:isAlive() then hl_plan_recover(room, owner, player) end
                end
            end
        end
    end)

hl_lanhai = gu_trigger("hl_lanhai", {sgs.EventPhaseChanging},
    function(self, event, room, player, data, owner)
        if not player or data:toPhaseChange().to ~= sgs.Player_NotActive then return end
        local key = hl_plan_key(owner, player)
        local text = owner:getTag(key):toString()
        if text == "" then return end
        -- Expire before the optional new grant, including when the same target is selected.
        owner:removeTag(key)
        local outcomes = {}
        for _, plan in ipairs(text:split("+")) do
            local success = plan == "upper_done" or plan == "middle_done"
            if plan == "lower" and not player:getTag("hl_lunce_slash_damage"):toBool() then
                success = true
                hl_plan_success(room, owner)
            end
            table.insert(outcomes, success)
        end
        for _, success in ipairs(outcomes) do
            if owner:isDead() then break end
            room:sendCompulsoryTriggerLog(owner, "hl_lanhai", true)
            if success then
                owner:drawCards(math.min(3, owner:getTag("hl_lunce_success"):toInt()), "hl_lanhai")
                hl_plan_assign(room, owner)
            else
                local gained = owner:getTag("hl_lanhai_maxhp"):toInt()
                if gained < 3 then
                    owner:setTag("hl_lanhai_maxhp", sgs.QVariant(gained + 1))
                    room:setPlayerProperty(owner, "maxhp", sgs.QVariant(owner:getMaxHp() + 1))
                end
                hl_plan_recover(room, owner, owner)
            end
        end
    end, true)

hl_sp_pangtong:addSkill(hl_lanhai)
hl_sp_pangtong:addSkill(hl_lunce)
extension_hl:insertRelatedSkills("hl_lunce", "#hl_lunce_record")
