-- ==================== c1c_01
do
-- c1c_01; assembled in the GU helper scope.
local function c1c_recover(room, p, n, skill)
    if p:isAlive() and n > 0 then
        local r = sgs.RecoverStruct(); r.who = p; r.recover = n; r.reason = skill
        room:recover(p, r)
    end
end
local function c1c_hand(request, card)
    local p = request:getInitiator()
    return p and p:handCards():contains(card:getEffectiveId()) and not p:isJilei(card)
end
local function c1c_no_target(self, targets) return #targets == 0 end

hl_dalanmao = sgs.General(extension_hl, "hl_dalanmao", "god", 4)
hl_moyu = gu_trigger("hl_moyu", {sgs.EventPhaseStart, sgs.DrawNCards, sgs.EventPhaseChanging, sgs.TurnStart}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.TurnStart then
        room:setPlayerMark(owner, "hl_moyu_draw", owner:getMark("hl_moyu_nextdraw"))
        room:setPlayerMark(owner, "hl_moyu_nextdraw", 0)
    elseif event == sgs.DrawNCards then
        local n = owner:getMark("hl_moyu_draw")
        if n > 0 then local draw = data:toDraw(); draw.num = draw.num + n; data:setValue(draw); room:setPlayerMark(owner, "hl_moyu_draw", 0) end
    elseif event == sgs.EventPhaseChanging then
        if data:toPhaseChange().to == sgs.Player_NotActive then
            room:setPlayerMark(owner, "hl_moyu_draw", 0)
            if owner:getMark("hl_moyu-Clear") > 0 then c1c_recover(room, owner, 1, "hl_moyu") end
        end
    elseif owner:getPhase() == sgs.Player_Play and gu_invoke(owner, "hl_moyu") then
        room:setPlayerMark(owner, "hl_moyu-Clear", 1)
        room:addPlayerMark(owner, "hl_moyu_nextdraw", 2)
    end
end)
hl_moyu_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hl_moyu_max", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary(); return p and p:getMark("hl_moyu-Clear") > 0 and 2 or false
    end,
}
hl_moyu_prohibit = sgs.CreateProhibitSkillV2 {
    name = "#hl_moyu_prohibit", holder_selector = sgs.CorrectSkill_System,
    is_prohibited = function(self, ctx)
        local from, to = ctx:getFrom(), ctx:getTo()
        return from and to and from ~= to and from:getMark("hl_moyu-Clear") > 0
    end,
}
hl_sanlian = gu_active("hl_sanlian", nil, 3, 3, function() return false end, c1c_no_target,
    function(self, room, source)
        local ids = self:getSubcards(); local name, same = nil, true
        for _, id in sgs.qlist(ids) do
            local n = sgs.Sanguosha:getCard(id):objectName()
            if name and name ~= n then same = false end; name = n
        end
        gu_throw(room, source, ids, "hl_sanlian")
        if not source:isAlive() then return end
        source:drawCards(source:getLostHp(), "hl_sanlian")
        local hit = {}
        for _, q in sgs.qlist(room:getAlivePlayers()) do
            local before = q:getMark("hl_sanlian_damage_count")
            local d = sgs.DamageStruct(); d.from = source; d.to = q; d.damage = 1; d.reason = "hl_sanlian"
            room:damage(d)
            if q ~= source and q:getMark("hl_sanlian_damage_count") > before then table.insert(hit, q) end
        end
        if same and source:isAlive() then
            for _, q in ipairs(hit) do
                if q:isAlive() and source:canDiscard(q, "he") then
                    local id = room:askForCardChosen(source, q, "he", "hl_sanlian", false, sgs.Card_MethodDiscard)
                    room:throwCard(id, "hl_sanlian", q, source)
                end
            end
        end
    end,
    function(request, card)
        if not c1c_hand(request, card) then return false end
        local ids = request:getSelectedCardIds()
        return ids:isEmpty() or sgs.Sanguosha:getCard(ids:first()):getTypeId() == card:getTypeId()
    end)
hl_sanlian_record = gu_record("#hl_sanlian_record", {sgs.DamageDone}, function(self, event, room, p, data)
    local d = data:toDamage()
    if d.to and d.reason == "hl_sanlian" then room:addPlayerMark(d.to, "hl_sanlian_damage_count") end
end)
extension_hl:addSkills(hl_sanlian_record)
hl_zuzhou_filter = sgs.CreateFilterSkill {
    name = "#hl_zuzhou_filter",
    view_filter = function(self, card)
        local room = sgs.Sanguosha:currentRoom(); local p = room and room:getCardOwner(card:getId())
        if not p or room:getCardPlace(card:getId()) ~= sgs.Player_PlaceHand then return false end
        local base = sgs.Sanguosha:getEngineCard(card:getId())
        return (p:getMark("hl_zuzhou_slash") > 0 and base:isKindOf("Slash")) or (p:getMark("hl_zuzhou_jink") > 0 and base:isKindOf("Jink"))
    end,
    view_as = function(self, card)
        local name = sgs.Sanguosha:getEngineCard(card:getId()):isKindOf("Slash") and "jink" or "slash"
        local c = sgs.Sanguosha:cloneCard(name, card:getSuit(), card:getNumber()); c:setSkillName("hl_zuzhou")
        local wrapped = sgs.Sanguosha:getWrappedCard(card:getId()); wrapped:takeOver(c); c:deleteLater(); return wrapped
    end,
}
extension_hl:addSkills(hl_zuzhou_filter)
hl_zuzhou = gu_trigger("hl_zuzhou", {sgs.TurnStart}, function(self, event, room, p, data, owner)
    if not p or not p:isAlive() or not gu_invoke(owner, "hl_zuzhou", sgs.QVariant(p)) then return end
    room:loseHp(owner, 1, true, owner, "hl_zuzhou")
    local choice = room:askForChoice(owner, "hl_zuzhou", "slash_to_jink+jink_to_slash", sgs.QVariant(p))
    room:setPlayerMark(p, choice == "slash_to_jink" and "hl_zuzhou_slash" or "hl_zuzhou_jink", 1)
    if not p:hasSkill("#hl_zuzhou_filter") then room:acquireSkill(p, "#hl_zuzhou_filter") end
    room:filterCards(p, p:getHandcards(), true)
end)
hl_zuzhou_clear = gu_record("#hl_zuzhou_clear", {sgs.EventPhaseChanging, sgs.Death}, function(self, event, room, p, data)
    if event == sgs.Death then p = data:toDeath().who
    elseif data:toPhaseChange().to ~= sgs.Player_NotActive then return end
    if p and (p:getMark("hl_zuzhou_slash") > 0 or p:getMark("hl_zuzhou_jink") > 0) then
        room:setPlayerMark(p, "hl_zuzhou_slash", 0); room:setPlayerMark(p, "hl_zuzhou_jink", 0)
        room:detachSkillFromPlayer(p, "#hl_zuzhou_filter", true)
        room:filterCards(p, p:getHandcards(), true)
    end
end)
