hl_tuantu = gu_active("hl_tuantu", 1, 0, 0, function() return false end, c1c_no_target,
    function(self, room, source)
        local wanted, found, ids = {}, {}, sgs.IntList()
        for _, c in sgs.qlist(source:getHandcards()) do wanted[c:objectName()] = true end
        for _, id in sgs.qlist(room:getDiscardPile()) do
            local name = sgs.Sanguosha:getCard(id):objectName()
