hl_lianshi_last = gu_record("#hl_lianshi_last", {sgs.CardsMoveOneTime}, function(self, event, room, p, data)
    local move = data:toMoveOneTime()
    if move.to_place == sgs.Player_DiscardPile and not move.card_ids:isEmpty() then
        room:setTag("hl_lianshi_last_number", sgs.QVariant(sgs.Sanguosha:getCard(move.card_ids:last()):getNumber()))
    end
end)
extension_hl:addSkills(hl_lianshi_last)
local function c1c_suit(room, owner, suit)
    if suit and suit >= sgs.Card_Spade and suit <= sgs.Card_Diamond then
        room:setPlayerMark(owner, "hl_lianshi_suit_" .. suit, 1)
    end
    local n = 0
    for s = sgs.Card_Spade, sgs.Card_Diamond do n = n + owner:getMark("hl_lianshi_suit_" .. s) end
    if n == 4 then
        local y = room:getTag("hl_lianshi_last_number"):toInt()
        owner:drawCards(1, "hl_lianshi"); c1c_recover(room, owner, y, "hl_lianshi")
        for s = sgs.Card_Spade, sgs.Card_Diamond do room:setPlayerMark(owner, "hl_lianshi_suit_" .. s, 0) end
    end
end
hl_lianshi = gu_trigger("hl_lianshi", {sgs.CardUsed, sgs.CardResponded, sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    if event == sgs.CardsMoveOneTime then
        local move = data:toMoveOneTime()
        if move.to_place == sgs.Player_DiscardPile and not move.card_ids:isEmpty() and move.from and move.from:objectName() == owner:objectName()
            and (move.reason.m_reason & sgs.CardMoveReason_S_MASK_BASIC_REASON) == sgs.CardMoveReason_S_REASON_DISCARD then
            -- Record all suits in the discard, then resolve once, as one discard action.
            for _, id in sgs.qlist(move.card_ids) do
                local suit = sgs.Sanguosha:getCard(id):getSuit()
                if suit >= sgs.Card_Spade and suit <= sgs.Card_Diamond then room:setPlayerMark(owner, "hl_lianshi_suit_" .. suit, 1) end
            end
            c1c_suit(room, owner, nil)
        end
    elseif p == owner then
        local c = event == sgs.CardUsed and data:toCardUse().card or data:toCardResponse().m_card
        if c and c:getTypeId() ~= sgs.Card_TypeSkill then c1c_suit(room, owner, c:getSuit()) end
    end
end, true)
hl_lianshi_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hl_lianshi_max", holder_selector = sgs.CorrectSkill_System,
    correct_func = function() return false end,
    fixed_func = function(self, ctx)
        local p = ctx:getPrimary(); return p and p:hasSkill("hl_lianshi") and 5 or false
    end,
}
hl_butian = gu_trigger("hl_butian", {sgs.Damage, sgs.Damaged, sgs.RoundEnd}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.Damage and data:toDamage().to == owner then return end
    local x = math.floor(owner:getLostHp() / 5)
    if event == sgs.Damage then c1c_recover(room, owner, x, "hl_butian")
    elseif x > 0 then room:loseHp(owner, x, true, owner, "hl_butian") end
    if owner:isAlive() and not owner:isWounded() then
        for _, q in sgs.qlist(room:getOtherPlayers(owner)) do if q:isAlive() then room:killPlayer(q) end end
    end
end, true)
hl_nvwa:addSkill(hl_tuantu); hl_nvwa:addSkill(hl_lianshi); hl_nvwa:addSkill(hl_lianshi_max); hl_nvwa:addSkill(hl_butian)
extension_hl:insertRelatedSkills("hl_lianshi", "#hl_lianshi_max")

hl_change = sgs.General(extension_hl, "hl_change", "god", 3, false)
hl_guanghan = gu_trigger("hl_guanghan", {sgs.Damaged}, function(self, event, room, p, data, owner)
    local d = data:toDamage(); local victim = d.to
    if not victim then return end
    local adjacent = {}
    for _, q in sgs.qlist(room:getAlivePlayers()) do
        if q ~= victim and (q:getNextAlive() == victim or victim:getNextAlive() == q) then table.insert(adjacent, q) end
    end
    for _, q in ipairs(adjacent) do
        if q:isAlive() then
            local choices = q:canDiscard(q, "h") and "discard+losehp" or "losehp"
            if room:askForChoice(q, "hl_guanghan", choices, data) == "discard" then
                room:askForDiscard(q, "hl_guanghan", 1, 1, false, false, "@hl_guanghan-discard")
            else room:loseHp(q, d.damage, true, owner, "hl_guanghan") end
        end
    end
end, true)
extension_hl:addSkills(hl_guanghan)
hl_benyue = gu_trigger("hl_benyue", {sgs.GameStart, sgs.CardsMoveOneTime, sgs.HpRecover}, function(self, event, room, p, data, owner)
    if owner:getMark("hl_benyue") > 0 then return end
    if event == sgs.HpRecover and p == owner then
        local r = data:toRecover()
        local stack = gu_names(owner, "hl_benyue_recover_stack")
        local capacity = tonumber(table.remove(stack)) or 0
        gu_setnames(owner, "hl_benyue_recover_stack", stack)
        room:addPlayerMark(owner, "hl_benyue_recovered", math.max(0, math.min(r.recover, capacity)))
    end
    local peaches = 0
    for _, c in sgs.qlist(owner:getHandcards()) do if c:isKindOf("Peach") then peaches = peaches + 1 end end
    if peaches >= 3 or owner:getMark("hl_benyue_recovered") >= 3 then
        room:setPlayerMark(owner, "hl_benyue", 1)
        if owner:getMaxHp() < 15 then room:setPlayerProperty(owner, "maxhp", sgs.QVariant(15)) end
        room:acquireSkill(owner, "hl_guanghan")
    end
end, true, sgs.Skill_Wake)
hl_benyue_record = gu_record("#hl_benyue_record", {sgs.PreHpRecover}, function(self, event, room, p, data)
    if p and p:hasSkill("hl_benyue") and p:getMark("hl_benyue") == 0 then
        local stack = gu_names(p, "hl_benyue_recover_stack")
        table.insert(stack, tostring(p:getLostHp())); gu_setnames(p, "hl_benyue_recover_stack", stack)
    end
end)
extension_hl:addSkills(hl_benyue_record)
hl_daoyao = gu_active("hl_daoyao", 1, 1, 1, function() return false end, c1c_no_target,
    function(self, room, source)
        gu_throw(room, source, self:getSubcards(), "hl_daoyao")
        if not source:isAlive() then return end
        local ids = sgs.IntList()
        for _, id in sgs.qlist(room:getDrawPile()) do
            if sgs.Sanguosha:getCard(id):isKindOf("Peach") then ids:append(id); break end
        end
