        gu_obtain(room, source, ids, "hl_daoyao"); if source:isAlive() then source:drawCards(n, "hl_daoyao") end
    end, c1c_hand)
hl_change:addSkill(hl_benyue); hl_change:addSkill(hl_daoyao)
