-- ==================== c1c_02
do
-- c1c_02: Sun Wukong is skipped; the excerpt does not define his weapon.
hl_libai = sgs.General(extension_hl, "hl_libai", "qun", 3)
hl_xiaoshan = sgs.General(extension_hl, "hl_xiaoshan", "god", 3)

local function hl_c1c_put(room, p, ids, skill)
    if ids:isEmpty() then return end
    local c = gu_dummy(ids)
    room:moveCardTo(c, p, nil, sgs.Player_DiscardPile,
        sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_PUT, p:objectName(), skill, ""), true)
    c:deleteLater()
end

hl_xiakexing = gu_trigger("hl_xiakexing", {sgs.CardUsed, sgs.Damage}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.CardUsed then
        local use = data:toCardUse()
        if not use.card or not use.card:isKindOf("Weapon") or not string.find(sgs.Sanguosha:translate(use.card:objectName()), "剑", 1, true) then return end
        local c = sgs.Sanguosha:cloneCard("archery_attack", sgs.Card_NoSuit, 0)
        c:setSkillName(self:objectName())
        local u = sgs.CardUseStruct(); u.card = c; u.from = owner
        room:useCard(u); c:deleteLater()
    else
        local d = data:toDamage()
        if d.chain or d.transfer or not d.card or not d.card:isKindOf("Slash") or not d.to or d.to:isDead() or not owner:getWeapon() or not owner:canPindian(d.to) then return end
        if not gu_invoke(owner, self:objectName(), data) then return end
        if owner:pindian(d.to, self:objectName()) then room:loseMaxHp(d.to, 1, self:objectName())
        elseif owner:getWeapon() then room:throwCard(owner:getWeapon(), owner, owner) end
    end
end)

hl_qiangjinjiu = gu_trigger("hl_qiangjinjiu", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if not p or p == owner or p:getPhase() ~= sgs.Player_RoundStart then return end
    if not room:askForCard(owner, ".|.|.|hand", "@hl_qiangjinjiu:" .. p:objectName(), data, sgs.Card_MethodDiscard, p, false, self:objectName()) then return end
    if room:askForChoice(owner, self:objectName(), "equipment+wine", data) == "equipment" then
        gu_throw(room, p, gu_ids(sgs.QList2Table(p:getEquips())), self:objectName())
        for _, id in sgs.qlist(room:getDrawPile()) do
            if sgs.Sanguosha:getCard(id):isKindOf("Analeptic") then room:obtainCard(p, id, false); break end
        end
    else
        local ids = sgs.IntList()
        for _, c in sgs.qlist(p:getHandcards()) do if c:isKindOf("Analeptic") then ids:append(c:getEffectiveId()) end end
        if not ids:isEmpty() then gu_obtain(room, owner, ids, self:objectName())
        elseif not p:isAllNude() then room:obtainCard(owner, room:askForCardChosen(owner, p, "hej", self:objectName()), false) end
    end
end)

hl_xinglunan = gu_trigger("hl_xinglunan", {sgs.CardFinished}, function(self, event, room, p, data, owner)
    local u = data:toCardUse()
    if owner:getPhase() == sgs.Player_NotActive and u.from and u.from ~= owner and u.card and u.card:isKindOf("Slash") and u.to:contains(owner) then
        room:addPlayerMark(owner, "hl_xinglunan_distance")
    end
end)
hl_xinglunan_distance = sgs.CreateDistanceSkillV2 {
    name = "#hl_xinglunan_distance", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local from, to = ctx:getPrimary(), ctx:getSecondary()
        if from and to and from ~= to then return to:getMark("hl_xinglunan_distance") end
        return 0
    end,
}
hl_xinglunan_reset = gu_record("#hl_xinglunan_reset", {sgs.EventPhaseStart}, function(self, event, room, p, data)
    if p and p:getPhase() == sgs.Player_RoundStart then room:setPlayerMark(p, "hl_xinglunan_distance", 0) end
end)

hl_jingyesi_use = sgs.CreateViewAsSkillV2 {
    name = "#hl_jingyesi_use",
    can_activate = function(self, request) return request:getPattern() == "@@hl_jingyesi" and request:getInitiator():getTag("hl_jingyesi_id"):toInt() > 0 end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function(self, request)
        local id = request:getInitiator():getTag("hl_jingyesi_id"):toInt() - 1
        if id >= 0 then
            local o = sgs.Sanguosha:getCard(id)
            local c = sgs.Sanguosha:cloneCard(o:objectName(), o:getSuit(), o:getNumber())
            c:addSubcard(id); c:setSkillName("hl_jingyesi"); return c
        end
    end,
}
hl_jingyesi = gu_trigger("hl_jingyesi", {sgs.EventPhaseEnd}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if p:getPhase() == sgs.Player_Discard then gu_obtain(room, owner, room:getNCards(1, true, false), self:objectName())
    elseif p:getPhase() == sgs.Player_Play and gu_invoke(owner, self:objectName()) then
        local ids = room:getNCards(1)
        if ids:isEmpty() then return end
        room:returnToTopDrawPile(ids)
        room:fillAG(ids, owner); room:askForAG(owner, ids, false, self:objectName()); room:clearAG(owner)
        owner:setTag("hl_jingyesi_id", sgs.QVariant(ids:first() + 1))
        room:askForUseCard(owner, "@@hl_jingyesi", "@hl_jingyesi-use")
        owner:removeTag("hl_jingyesi_id")
    end
end)

hl_shixian = gu_trigger("hl_shixian", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_RoundStart then return end
    for _, name in ipairs(gu_names(owner, "hl_shixian_skills")) do room:detachSkillFromPlayer(owner, name) end
    gu_setnames(owner, "hl_shixian_skills", {})
    local ids = room:getNCards(4)
    if ids:isEmpty() then return end
    local dummy = gu_dummy(ids)
    room:moveCardTo(dummy, nil, sgs.Player_PlaceTable, true); dummy:deleteLater()
    local counts, gained = {}, {}
    local skills = {[sgs.Card_Heart] = "hl_jingyesi", [sgs.Card_Diamond] = "hl_xinglunan", [sgs.Card_Spade] = "hl_xiakexing", [sgs.Card_Club] = "hl_qiangjinjiu"}
    for _, id in sgs.qlist(ids) do local suit = sgs.Sanguosha:getCard(id):getSuit(); counts[suit] = (counts[suit] or 0) + 1 end
    for _, suit in ipairs({sgs.Card_Heart, sgs.Card_Diamond, sgs.Card_Spade, sgs.Card_Club}) do
        local name = skills[suit]
        if counts[suit] and not owner:hasSkill(name) then table.insert(gained, name); room:acquireSkill(owner, name) end
    end
    gu_setnames(owner, "hl_shixian_skills", gained)
    local repeats, rest = sgs.IntList(), sgs.IntList()
    for _, id in sgs.qlist(ids) do
        if room:getCardPlace(id) == sgs.Player_PlaceTable then
            if counts[sgs.Sanguosha:getCard(id):getSuit()] > 1 then repeats:append(id) else rest:append(id) end
        end
    end
    if not repeats:isEmpty() then
        if gu_invoke(owner, self:objectName()) then gu_obtain(room, owner, repeats, self:objectName())
        else for _, id in sgs.qlist(repeats) do rest:append(id) end end
    end
    hl_c1c_put(room, owner, rest, self:objectName())
end, true)

hl_shanshan_vs = sgs.CreateViewAsSkillV2 {
    name = "hl_shanshan", n = 1, response_or_use = true,
    can_activate = function(self, request) return string.find(request:getPattern(), "jink", 1, true) ~= nil end,
    can_select_card = function(self, request, c) return request:getSelectedCardIds():isEmpty() and c:isKindOf("EquipCard") end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        local ids = request:getSelectedCardIds(); if ids:length() ~= 1 then return nil end
        local original = sgs.Sanguosha:getCard(ids:first())
        local c = sgs.Sanguosha:cloneCard("jink", original:getSuit(), original:getNumber())
        c:addSubcard(ids:first()); c:setSkillName("hl_shanshan"); return c
    end,
}
hl_shanshan = gu_trigger("hl_shanshan", {sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    local u = data:toCardUse()
    if p ~= owner or not u.from or u.from == owner or not u.card or not u.to:contains(owner) or not (u.card:isKindOf("Slash") or u.card:isNDTrick()) then return end
    if room:askForCard(owner, "jink", "@hl_shanshan", data, sgs.Card_MethodResponse, u.from, false, self:objectName()) then
        local names = u.nullified_list; table.insert(names, owner:objectName()); u.nullified_list = names; data:setValue(u)
        owner:drawCards(1, self:objectName())
    end
end)
hl_shanshan:setViewAsSkill(hl_shanshan_vs)

-- The random rule is a server-side tag; only its owner receives its log.
hl_anshi = gu_trigger("hl_anshi", {sgs.RoundStart, sgs.RoundEnd, sgs.CardUsed, sgs.CardResponded, sgs.CardsMoveOneTime, sgs.CardFinished, sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local key = "hl_anshi_" .. owner:objectName()
    local mode = owner:getTag(key):toInt()
    if event == sgs.RoundStart then
        if p ~= owner then return end
        mode = math.random(1, 5); owner:setTag(key, sgs.QVariant(mode))
        for _, q in sgs.qlist(room:getAlivePlayers()) do
            q:removeTag(key .. "_jink")
            q:setTag(key .. "_equips", sgs.QVariant(q:getEquips():length()))
        end
        local log = sgs.LogMessage(); log.type = "#hl_anshi_rule"; log.from = owner; log.arg = "hl_anshi_rule" .. mode
        room:sendLog(log, owner)
    elseif event == sgs.RoundEnd and mode == 2 then
        if p ~= owner then return end
        for _, q in sgs.qlist(room:getAlivePlayers()) do
            if not q:getTag(key .. "_jink"):toBool() then
                local d = sgs.DamageStruct(); d.to = q; d.damage = 1; d.nature = sgs.DamageStruct_Thunder; d.reason = self:objectName(); room:damage(d)
            end
        end
    elseif (event == sgs.CardUsed or event == sgs.CardResponded) and p then
        local c = event == sgs.CardUsed and data:toCardUse().card or data:toCardResponse().m_card
        if c and c:isKindOf("Jink") then p:setTag(key .. "_jink", sgs.QVariant(true)) end
        if mode == 1 and c and c:isKindOf("Slash") then hl_c1c_put(room, p, p:handCards(), self:objectName()) end
    elseif event == sgs.CardsMoveOneTime then
        local m = data:toMoveOneTime()
        if mode == 2 and m.from and (m.reason.m_reason % 16) == sgs.CardMoveReason_S_REASON_DISCARD then
            for _, id in sgs.qlist(m.card_ids) do if sgs.Sanguosha:getCard(id):isKindOf("Jink") then m.from:setTag(key .. "_jink", sgs.QVariant(true)) end end
        elseif mode == 3 then
            -- Compare the completed atomic move with the previous count.
            for _, q in sgs.qlist(room:getAlivePlayers()) do
                local count = q:getEquips():length()
                local previous = q:getTag(key .. "_equips"):toInt()
                q:setTag(key .. "_equips", sgs.QVariant(count))
                if count ~= previous and count > 0 then
                    hl_c1c_put(room, q, gu_ids(sgs.QList2Table(q:getEquips())), self:objectName())
                end
            end
        end
    elseif mode == 4 and event == sgs.CardFinished and p then
        local u = data:toCardUse()
        if u.card and (u.card:isKindOf("Peach") or u.card:isKindOf("Analeptic")) then room:setPlayerCardLimitation(p, "use,response", ".|.|.|hand", true, self:objectName()) end
    elseif mode == 5 and event == sgs.TargetSpecified then
        local u = data:toCardUse()
        if u.card and u.card:isKindOf("SingleTargetTrick") and not u.to:isEmpty() then owner:drawCards(1, self:objectName()) end
    end
end, true)

