-- ==================== c203_04
do
-- c203_04; assembled inside the GU helper scope.
local function c304_youlong_card(p, name)
    local c = sgs.Sanguosha:cloneCard(name, sgs.Card_NoSuit, 0)
    if not c then return end
    c:deleteLater()
    local yang = p:getChangeSkillState("hlxg_youlong") <= 1
    if not (yang and c:isNDTrick() or not yang and c:isKindOf("BasicCard")) then return end
    if p:getMark("hlxg_youlong_name_" .. name) > 0 then return end
    if p:getMark("hlxg_youlong_unlimited") == 0
        and p:getMark(yang and "hlxg_youlong_yang-Clear" or "hlxg_youlong_yin-Clear") > 0 then return end
    if yang and not p:hasEquipArea() then return end
    if not yang then
        local possible = false
        for _, x in sgs.qlist(p:getCards("he")) do
            if not x:isKindOf("BasicCard") and p:canDiscard(p, x:getEffectiveId()) then possible = true end
        end
        if not possible then return end
    end
    c:setSkillName("hlxg_youlong")
    return c
end
local function c304_youlong_pay(p, name, ids)
    local room = p:getRoom()
    if not c304_youlong_card(p, name) then return false end
    local yang = p:getChangeSkillState("hlxg_youlong") <= 1
    if yang then
        local slots = {}
        for i = 0, 4 do if p:hasEquipArea(i) then table.insert(slots, tostring(i)) end end
        local slot = room:askForChoice(p, "hlxg_youlong", table.concat(slots, "+"))
        room:setPlayerMark(p, "hlxg_youlong_yang-Clear", 1)
        room:setChangeSkillState(p, "hlxg_youlong", 2)
        room:setPlayerMark(p, "hlxg_youlong_name_" .. name, 1)
        p:throwEquipArea(tonumber(slot))
    else
        if ids:length() ~= 1 then return false end
        local id = ids:first()
        local c = sgs.Sanguosha:getCard(id)
        if c:isKindOf("BasicCard") or not p:getCards("he"):contains(c) or not p:canDiscard(p, id) then return false end
        room:setPlayerMark(p, "hlxg_youlong_yin-Clear", 1)
        room:setChangeSkillState(p, "hlxg_youlong", 1)
        room:setPlayerMark(p, "hlxg_youlong_name_" .. name, 1)
        gu_throw(room, p, ids, "hlxg_youlong")
    end
    return true
end
local function c304_response_names(p, pattern)
    local names = {}
    for _, name in ipairs(sgs.Sanguosha:getCardNames()) do
        local c = c304_youlong_card(p, name)
        if c and sgs.Sanguosha:matchExpPattern(pattern, p, c)
            and not p:isCardLimited(c, sgs.Card_MethodUse)
            and not (c:isKindOf("Peach") and p:getMark("Global_PreventPeach") > 0) then table.insert(names, name) end
    end
    return names
end
hlxg_youlongCard = sgs.CreateSkillCard {
    name = "hlxg_youlongCard", will_throw = false,
    filter = function(self, targets, to, from)
        if self:getUserString() == "" then return false end
        local names = c304_response_names(from, self:getUserString())
        local c = names[1] and c304_youlong_card(from, names[1])
        local list = sgs.PlayerList(); for _, p in ipairs(targets) do list:append(p) end
        return c and c:targetFilter(list, to, from) and not from:isProhibited(to, c, list)
    end,
    feasible = function(self, targets, from)
        if self:getUserString() == "" or sgs.Sanguosha:getCurrentCardUseReason() == sgs.CardUseStruct_CARD_USE_REASON_RESPONSE then return #targets == 0 end
        local names = c304_response_names(from, self:getUserString())
        local c = names[1] and c304_youlong_card(from, names[1])
        local list = sgs.PlayerList(); for _, p in ipairs(targets) do list:append(p) end
        return c and c:targetsFeasible(list, from)
    end,
    on_use = function(self, room, p)
        local names = {}
        for _, name in ipairs(sgs.Sanguosha:getCardNames()) do
            local c = c304_youlong_card(p, name)
            if c and c:isAvailable(p) then table.insert(names, name) end
        end
        if #names == 0 then return end
        local name = room:askForChoice(p, "hlxg_youlong", table.concat(names, "+") .. "+cancel")
        if name == "cancel" then return end
        p:setTag("hlxg_youlong_declare", sgs.QVariant(name))
        room:askForUseCard(p, "@@hlxg_youlong_imitate", "@hlxg_youlong-use:" .. name)
        p:removeTag("hlxg_youlong_declare")
    end,
    on_validate = function(self, use)
        if self:getUserString() == "" then return self end
        local p = use.from
        local names = c304_response_names(p, self:getUserString())
        if #names == 0 then return nil end
        local name = p:getRoom():askForChoice(p, "hlxg_youlong", table.concat(names, "+"))
        local c = c304_youlong_card(p, name)
        if c and c304_youlong_pay(p, name, self:getSubcards()) then return c end
    end,
    on_validate_in_response = function(self, p)
        local names = c304_response_names(p, self:getUserString())
        if #names == 0 then return nil end
        local name = p:getRoom():askForChoice(p, "hlxg_youlong", table.concat(names, "+"))
        local c = c304_youlong_card(p, name)
        if c and c304_youlong_pay(p, name, self:getSubcards()) then return c end
    end,
}
local function c304_select(self, request, c)
    local p = request:getInitiator()
    return p:getChangeSkillState("hlxg_youlong") == 2 and request:getSelectedCardIds():isEmpty()
        and p:getCards("he"):contains(c) and not c:isKindOf("BasicCard") and p:canDiscard(p, c:getEffectiveId())
end
local function c304_feasible(self, request)
    return request:getSelectedCardIds():length() == (request:getInitiator():getChangeSkillState("hlxg_youlong") <= 1 and 0 or 1)
end
hlxg_youlong_imitate = sgs.CreateViewAsSkillV2 {
    name = "#hlxg_youlong_imitate", n = 1,
    can_activate = function(self, r) return r:getPattern() == "@@hlxg_youlong_imitate" end,
    can_select_card = c304_select, card_selection_feasible = c304_feasible,
    create_card = function(self, r)
        local c = hlxg_youlongCard:clone(); c:setSkillName("hlxg_youlong")
        c:setUserString(r:getInitiator():getTag("hlxg_youlong_declare"):toString())
        c:addSubcards(r:getSelectedCardIds()); return c
    end,
}
hlxg_youlong = sgs.CreateViewAsSkillV2 {
    name = "hlxg_youlong", n = 1, response_or_use = true,
    can_activate = function(self, r)
        local p = r:getInitiator()
        if r:getReason() == sgs.CardUseStruct_CARD_USE_REASON_RESPONSE then return false end -- text permits use, not pure responses
        if r:getReason() ~= sgs.CardUseStruct_CARD_USE_REASON_PLAY then return #c304_response_names(p, r:getPattern()) > 0 end
        for _, name in ipairs(sgs.Sanguosha:getCardNames()) do local c = c304_youlong_card(p, name); if c and c:isAvailable(p) then return true end end
        return false
    end,
    can_select_card = function(self, r, c) return r:getReason() ~= sgs.CardUseStruct_CARD_USE_REASON_PLAY and c304_select(self, r, c) end,
    card_selection_feasible = function(self, r)
        return r:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY and r:getSelectedCardIds():isEmpty() or c304_feasible(self, r)
    end,
    create_card = function(self, r)
        local c = hlxg_youlongCard:clone(); c:setSkillName("hlxg_youlong")
        if r:getReason() ~= sgs.CardUseStruct_CARD_USE_REASON_PLAY then c:setUserString(r:getPattern()); c:addSubcards(r:getSelectedCardIds()) end
        return c
    end,
}
local c304_youlong_name = "hlxg_youlong"
hlxg_youlong = sgs.CreateTriggerSkillV2 {
    name = c304_youlong_name, view_as_skill = hlxg_youlong, change_skill = true,
    events = {sgs.GameStart}, can_trigger = function() return false end,
}
hlxg_luanfeng = gu_trigger("hlxg_luanfeng", {sgs.Dying}, function(self, event, room, p, data, owner)
    local to = data:toDying().who
