hlxg_fuhai = gu_active("hlxg_fuhai", 1, 0, 0, function() return false end, function(self, targets) return #targets == 0 end,
    function(self, room, p)
        local players, shows = {}, {}
        local to = p
        repeat
            table.insert(players, to)
            if not to:isKongcheng() then
                local c = room:askForExchange(to, "hlxg_fuhai", 1, 1, false, "@hlxg_fuhai-show")
                if c then shows[to:objectName()] = c:getSubcards():first(); c:deleteLater() end
            end
            to = to:getNextAlive()
        until to == p
        for _, q in ipairs(players) do local id = shows[q:objectName()]; if id then room:showCard(q, id) end end
        local direction = room:askForChoice(p, "hlxg_fuhai", "clockwise+counterclockwise")
        local sequence = {}
        for i = 1, #players do
            local q = players[direction == "clockwise" and i or (i == 1 and 1 or #players - i + 2)]
            if shows[q:objectName()] then table.insert(sequence, sgs.Sanguosha:getCard(shows[q:objectName()]):getNumber()) end
        end
        local n, sign = #sequence > 0 and 1 or 0, 0
        for i = 2, #sequence do
            local diff = sequence[i] - sequence[i-1]
            if diff == 0 or sign ~= 0 and diff * sign <= 0 then break end
            sign = diff > 0 and 1 or -1; n = n + 1
        end
        p:drawCards(math.max(2, n), "hlxg_fuhai")
    end)
