-- Signets use batch-specific marks so base Jianjie never grants different skills.
local function c304_sync(room, p)
    local dragon = p:getMark("&hlxg_jianjie_dragon") > 0
    local phoenix = p:getMark("&hlxg_jianjie_phoenix") > 0
    for _, pair in ipairs({{"hlxg_huoji_simahui", dragon}, {"hlxg_lianhuan_simahui", phoenix}, {"hlxg_yeyan_simahui", dragon and phoenix}}) do
        local name, wanted = pair[1], pair[2]
        if wanted and not p:hasSkill(name) then room:acquireSkill(p, name)
        elseif not wanted and p:hasSkill(name) then room:detachSkillFromPlayer(p, name, false, true) end
    end
end
local function c304_transfer(room, from, to, mark)
    room:removePlayerMark(from, mark); c304_sync(room, from)
    room:addPlayerMark(to, mark); c304_sync(room, to)
end
local function c304_convert(name, target, predicate)
    return sgs.CreateViewAsSkillV2 {
        name = name, n = 1, response_or_use = true,
        can_activate = function(self, r)
            if r:getInitiator():getMark(name .. "-Clear") >= 3 then return false end
            if r:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY then return true end
            if r:getReason() ~= sgs.CardUseStruct_CARD_USE_REASON_RESPONSE_USE then return false end
            local c = sgs.Sanguosha:cloneCard(target, sgs.Card_NoSuit, 0); c:deleteLater()
            return sgs.Sanguosha:matchExpPattern(r:getPattern(), r:getInitiator(), c)
        end,
        can_select_card = function(self, r, c)
            return r:getSelectedCardIds():isEmpty() and r:getInitiator():getHandcards():contains(c) and predicate(c)
        end,
        card_selection_feasible = function(self, r) return r:getSelectedCardIds():length() == 1 end,
        create_card = function(self, r)
            local old = sgs.Sanguosha:getCard(r:getSelectedCardIds():first())
            local c = sgs.Sanguosha:cloneCard(target, old:getSuit(), old:getNumber()); c:addSubcard(old); c:setSkillName(name); return c
        end,
        pay = function(self, room, ctx, r) room:addPlayerMark(r:getInitiator(), name .. "-Clear"); return true end,
    }
end
hlxg_huoji_simahui = c304_convert("hlxg_huoji_simahui", "fire_attack", function(c) return c:isRed() end)
hlxg_lianhuan_simahui = c304_convert("hlxg_lianhuan_simahui", "iron_chain", function(c) return c:getSuit() == sgs.Card_Club end)
-- Replace only the resolved Fire Attack effect; nullification/target checks remain native.
hlxg_huoji_simahui_effect = sgs.CreateRuleSkillV2 {
    name = "#hlxg_huoji_simahui_effect", global = true, events = {sgs.CardEffected}, priority = 0,
    can_trigger = function(self, event, room, p, data)
        local e = data:toCardEffect()
        return e.from and e.from:hasSkill("hlxg_huoji_simahui") and e.card:isKindOf("FireAttack") and self:objectName() or false
    end,
    on_effect = function(self, event, room, p, ctx)
        local e = ctx.original_data:toCardEffect()
        if e.nullified then return true end
        if not e.offset_card then e.offset_card = room:isCanceled(e); ctx.original_data:setValue(e) end
        if e.offset_card and not room:getThread():trigger(sgs.CardOffset, room, e.from, ctx.original_data) then return true end
        room:getThread():trigger(sgs.CardOnEffect, room, e.to, ctx.original_data)
        e = ctx.original_data:toCardEffect()
        for iteration = 0, e.extra_effect do
        if not e.to:isAlive() or e.to:isKongcheng() then break end
        local shown = room:askForCardShow(e.to, e.from, "fire_attack"); room:showCard(e.to, shown:getEffectiveId())
        local paid = false
        if e.from:isAlive() and gu_invoke(e.from, "hlxg_huoji_simahui", ctx.original_data) then
            local ids = room:getNCards(4, false)
            local disabled = sgs.IntList()
            for _, id in sgs.qlist(ids) do if sgs.Sanguosha:getCard(id):getSuit() ~= shown:getSuit() then disabled:append(id) end end
            e.from:setTag("hlxg_huoji_suit", sgs.QVariant(shown:getSuit()))
            room:fillAG(ids, e.from, disabled)
            local id = room:askForAG(e.from, ids, true, "hlxg_huoji_simahui")
            room:clearAG(e.from)
            e.from:removeTag("hlxg_huoji_suit")
            if id >= 0 and ids:contains(id) and not disabled:contains(id) then
                ids:removeOne(id); local cost = sgs.IntList(); cost:append(id); gu_throw(room, e.from, cost, "hlxg_huoji_simahui"); paid = true
            end
            room:returnToTopDrawPile(ids)
        end
        if not paid and e.from:isAlive() then
            paid = room:askForCard(e.from, ".|" .. shown:getSuitString() .. "|.|hand", "@hlxg_huoji-discard:" .. e.to:objectName(), ctx.original_data) ~= nil
        end
        if paid and e.from:isAlive() then
            local d = sgs.DamageStruct(); d.card = e.card; d.from = e.from; d.to = e.to; d.damage = 1; d.nature = sgs.DamageStruct_Fire; room:damage(d)
        end
        end
        return true
    end,
}
extension_hl:addSkills(hlxg_huoji_simahui_effect)
-- Snapshot the chain before GameRule unchains the victim; distribute only after damage.
hlxg_chenghao_snapshot = gu_record("#hlxg_chenghao_snapshot", {sgs.DamageDone}, function(self, event, room, p, data)
    local d = data:toDamage()
    if d.nature == sgs.DamageStruct_Normal or d.chain or not d.to:isChained() then return end
    local n = 1
    for _, q in sgs.qlist(room:getAlivePlayers()) do if q:isChained() then n = n + 1 end end
    local tips = d.tips; tips:append("hlxg_chenghao:" .. n); d.tips = tips; data:setValue(d)
end)
hlxg_chenghao_snapshot.priority = 10
extension_hl:addSkills(hlxg_chenghao_snapshot)
hlxg_chenghao = gu_trigger("hlxg_chenghao", {sgs.Damaged}, function(self, event, room, p, data, owner)
    local n
    for _, tip in sgs.qlist(data:toDamage().tips) do n = tonumber(tip:match("^hlxg_chenghao:(%d+)$")) or n end
    if not n or not gu_invoke(owner, "hlxg_chenghao", data) then return end
    local ids = room:getNCards(n, false)
    while not ids:isEmpty() and owner:isAlive() do
        room:fillAG(ids, owner); local id = room:askForAG(owner, ids, false, "hlxg_chenghao"); room:clearAG(owner)
        if id < 0 or not ids:contains(id) then id = ids:first() end
        local to = room:askForPlayerChosen(owner, room:getAlivePlayers(), "hlxg_chenghao", "@hlxg_chenghao-give", false, true)
        ids:removeOne(id); room:obtainCard(to, id, false)
    end
    if not ids:isEmpty() then room:returnToTopDrawPile(ids) end
end)
hlxg_yinshi = gu_trigger("hlxg_yinshi", {sgs.DamageInflicted}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:getArmor() or owner:getMark("&hlxg_jianjie_dragon") > 0 and owner:getMark("&hlxg_jianjie_phoenix") > 0 then return end
    local d = data:toDamage()
    return d.nature ~= sgs.DamageStruct_Normal or d.card and d.card:isKindOf("TrickCard")
end, true)
hlxg_jianjie = gu_active("hlxg_jianjie", 1, 0, 0,
    function(self, targets, to, from)
        if #targets == 0 then return to:getMark("&hlxg_jianjie_dragon") > 0 or to:getMark("&hlxg_jianjie_phoenix") > 0 end
        return #targets == 1 and to ~= targets[1]
    end, function(self, targets) return #targets == 2 end,
    function(self, room, p, targets)
        local from, to = targets[1], targets[2]
        local choices = {}
        if from:getMark("&hlxg_jianjie_dragon") > 0 then table.insert(choices, "dragon") end
        if from:getMark("&hlxg_jianjie_phoenix") > 0 then table.insert(choices, "phoenix") end
        if #choices == 0 then return end
        local choice = room:askForChoice(p, "hlxg_jianjie", table.concat(choices, "+"))
        c304_transfer(room, from, to, "&hlxg_jianjie_" .. choice)
    end, nil, function(p) return p:getMark("hlxg_jianjie_turns") > 1 end)
hlxg_jianjie_trigger = gu_trigger("#hlxg_jianjie_trigger", {sgs.TurnStart, sgs.Death}, function(self, event, room, p, data, owner)
    if event == sgs.TurnStart then
        if p ~= owner then return end
        room:addPlayerMark(owner, "hlxg_jianjie_turns")
        if owner:getMark("hlxg_jianjie_turns") ~= 1 then return end
        local candidates = room:getOtherPlayers(owner)
        if candidates:length() < 2 then return end
        local dragon = room:askForPlayerChosen(owner, candidates, "hlxg_jianjie", "@hlxg_jianjie-dragon", false, true)
        candidates:removeOne(dragon)
        local phoenix = room:askForPlayerChosen(owner, candidates, "hlxg_jianjie", "@hlxg_jianjie-phoenix", false, true)
        room:addPlayerMark(dragon, "&hlxg_jianjie_dragon"); c304_sync(room, dragon)
        room:addPlayerMark(phoenix, "&hlxg_jianjie_phoenix"); c304_sync(room, phoenix)
    else
        local dead = data:toDeath().who
        for _, kind in ipairs({"dragon", "phoenix"}) do
            local mark = "&hlxg_jianjie_" .. kind
            if dead:getMark(mark) > 0 then
                local to = room:askForPlayerChosen(owner, room:getAlivePlayers(), "hlxg_jianjie", "@hlxg_jianjie-" .. kind, true, true)
                if to then c304_transfer(room, dead, to, mark) end
            end
        end
    end
end)
-- Choose distinct targets, then allocate the damage before paying the cost.
hlxg_yeyan_simahui = gu_active("hlxg_yeyan_simahui", nil, 0, 4,
    function(self, targets, to, from)
        return #targets < (self:subcardsLength() == 4 and 2 or 3)
    end,
    function(self, targets)
        return #targets >= 1 and #targets <= (self:subcardsLength() == 4 and 2 or 3)
    end,
    function(self, room, p, targets)
        room:setPlayerMark(p, "hlxg_yeyan_simahui_used", 1)
        local counts, order = {}, targets
        local heavy = self:subcardsLength() == 4
        for _, to in ipairs(targets) do counts[to:objectName()] = 1 end
        if heavy then
            if #targets == 1 then
                counts[targets[1]:objectName()] = room:askForChoice(p, "hlxg_yeyan_simahui", "two+three") == "three" and 3 or 2
            else
                local choices = sgs.SPlayerList(); for _, to in ipairs(targets) do choices:append(to) end
                local to = room:askForPlayerChosen(p, choices, "hlxg_yeyan_simahui", "@hlxg_yeyan-double", false, true)
                counts[to:objectName()] = 2
            end
        end
        if heavy then
            gu_throw(room, p, self:getSubcards(), "hlxg_yeyan_simahui")
            room:setPlayerMark(p, "&hlxg_jianjie_dragon", 0); room:setPlayerMark(p, "&hlxg_jianjie_phoenix", 0); c304_sync(room, p)
        end
        for _, to in ipairs(order) do
            if to:isAlive() then local d = sgs.DamageStruct(); d.from = p; d.to = to; d.damage = counts[to:objectName()]; d.nature = sgs.DamageStruct_Fire; d.reason = "hlxg_yeyan_simahui"; room:damage(d) end
        end
    end,
    function(r, c)
        local p = r:getInitiator()
        if not p:getHandcards():contains(c) or not p:canDiscard(p, c:getEffectiveId()) then return false end
        for _, id in sgs.qlist(r:getSelectedCardIds()) do if sgs.Sanguosha:getCard(id):getSuit() == c:getSuit() then return false end end
        return true
    end, function(p) return p:getMark("hlxg_yeyan_simahui_used") == 0 end)
-- gu_active accepts 1..3 selected costs too; explicitly require zero or four.
hlxg_yeyan_simahui.card_selection_feasible = function(self, r) local n = r:getSelectedCardIds():length(); return n == 0 or n == 4 end
