-- ==================== c203_05
do
-- c203_05: literal skill text; all definitions use the shared GU V2 helpers.
local function c203_recover(room, p, who, skill)
    local r = sgs.RecoverStruct(); r.who = who; r.recover = 1
    room:recover(p, r)
end
local function c203_jilve(room, p, data)
    if not p:hasSkill("hlxg_jilve") or p:getMark("@hlxg_renjie") == 0
        or not gu_invoke(p, "hlxg_jilve", data) then return false end
    room:removePlayerMark(p, "@hlxg_renjie")
    local first = p:getMark("hlxg_jilve-Clear") == 0
    room:addPlayerMark(p, "hlxg_jilve-Clear")
    return true, first
end
local function c203_jilve_done(p, first, data)
    if p:isAlive() and first and gu_invoke(p, "hlxg_jilve_draw", data) then p:drawCards(1, "hlxg_jilve") end
end
local function c203_fangzhu(room, p, name)
    local to = room:askForPlayerChosen(p, room:getOtherPlayers(p), name, "@" .. name, true, true)
    if not to then return false end
    to:turnOver(); if to:isAlive() then to:drawCards(1, name) end
    return true
end
hljx_simayi = sgs.General(extension_hl, "hljx_simayi", "wei", 3)
hljx_fankui = gu_trigger("hljx_fankui", {sgs.Damaged}, function(self, event, room, player, data, p)
    if player ~= p then return end
    local damage = data:toDamage()
    for i = 1, damage.damage do
        if p:isDead() or not gu_invoke(p, self:objectName(), data) then break end
        local j = sgs.JudgeStruct(); j.who = p; j.reason = self:objectName(); j.pattern = ".|heart"; j.good = true
        room:judge(j)
        local to = damage.from
        if j.card:getSuit() == sgs.Card_Heart then
            local list = sgs.SPlayerList()
            for _, other in sgs.qlist(room:getOtherPlayers(p)) do if not other:isNude() then list:append(other) end end
            if not list:isEmpty() then to = room:askForPlayerChosen(p, list, self:objectName(), "@hljx_fankui") else to = nil end
        end
        if p:isAlive() and to and to:isAlive() and not to:isNude() then
            room:obtainCard(p, room:askForCardChosen(p, to, "he", self:objectName()), false)
        end
    end
end)
hljx_guicai = gu_trigger("hljx_guicai", {sgs.AskForRetrial}, function(self, event, room, player, data, p)
    local card = room:askForCard(p, ".", "@hljx_guicai", data, sgs.Card_MethodResponse, player, true, self:objectName())
    if not card then return end
    local suit = card:getSuit()
    room:retrial(card, p, data:toJudge(), self:objectName())
    if p:isAlive() then
        if suit == sgs.Card_Heart then c203_recover(room, p, p, self:objectName())
        elseif suit == sgs.Card_Club then p:drawCards(2, self:objectName()) end
    end
end)
hljx_simayi:addSkill(hljx_fankui); hljx_simayi:addSkill(hljx_guicai)

hlxg_simayi = sgs.General(extension_hl, "hlxg_simayi", "god", 4)
hlxg_wansha_simayi_limit = sgs.CreateCardLimitSkill {
    name = "#hlxg_wansha_simayi_limit",
    limit_list = function() return "use" end,
    limit_pattern = function(self, p)
        local room = sgs.Sanguosha:currentRoom()
        local current = room and room:getCurrent()
        if current and current ~= p and current:isAlive() and current:getPhase() ~= sgs.Player_NotActive
            and current:getMark("hlxg_jilve_wansha-Clear") > 0 and room:getCurrentDyingPlayer() then return "Peach" end
        return ""
    end,
}
hlxg_renjie = gu_trigger("hlxg_renjie", {sgs.GameStart, sgs.Damaged, sgs.CardsMoveOneTime}, function(self, event, room, player, data, p)
    local n = 0
    if event == sgs.GameStart and player == p then n = 1
    elseif event == sgs.Damaged and player == p then n = data:toDamage().damage
    elseif event == sgs.CardsMoveOneTime then
        local m = data:toMoveOneTime()
        if m.from and m.from:objectName() == p:objectName() and p:getPhase() == sgs.Player_Discard
            and m.reason.m_reason % 16 == sgs.CardMoveReason_S_REASON_DISCARD then
            for i = 0, m.card_ids:length() - 1 do if m.from_places:at(i) == sgs.Player_PlaceHand then n = n + 1 end end
        end
    end
    if n > 0 then room:addPlayerMark(p, "@hlxg_renjie", n) end
end, true)
-- 完杀/放逐/集智/鬼才 are not owned skills: they are only obtained/used by discarding a 忍 via 极略.
hlxg_jilve_react = sgs.CreateRuleSkillV2 {
    name = "#hlxg_jilve_react", events = {sgs.Damaged, sgs.CardUsed, sgs.AskForRetrial}, global = true,
    can_trigger = function(self, event, room, player, data)
        for _, p in sgs.qlist(room:getAlivePlayers()) do
            if p:hasSkill("hlxg_jilve") and p:getMark("@hlxg_renjie") > 0 then return self:objectName(), p end
        end
        return false
    end,
    on_effect = function(self, event, room, player, ctx)
        local data = ctx.original_data
        for _, p in sgs.qlist(room:getAlivePlayers()) do
            if p:hasSkill("hlxg_jilve") and p:getMark("@hlxg_renjie") > 0 then
                if event == sgs.Damaged and player == p then
                    local paid, first = c203_jilve(room, p, data)
                    if paid then c203_fangzhu(room, p, "hlxg_fangzhu_simayi"); c203_jilve_done(p, first, data) end
                elseif event == sgs.CardUsed and player == p then
                    local c = data:toCardUse().card
                    if c and c:isNDTrick() and not c:isVirtualCard() and c:getSkillName() == "" then
                        local paid, first = c203_jilve(room, p, data)
                        if paid then p:drawCards(1, "hlxg_jizhi_simayi"); c203_jilve_done(p, first, data) end
                    end
                elseif event == sgs.AskForRetrial and not p:isKongcheng() then
                    local paid, first = c203_jilve(room, p, data)
                    if paid then
                        local c = room:askForCard(p, ".|.|.|hand", "@hlxg_guicai", data, sgs.Card_MethodResponse, player, true, "hlxg_guicai")
                        if c then room:retrial(c, p, data:toJudge(), "hlxg_guicai") end
                        c203_jilve_done(p, first, data)
                    end
                end
            end
        end
        return false
    end,
}
hlxg_jilve = gu_active("hlxg_jilve", nil, 0, 0, function() return false end,
    function(self, targets) return #targets == 0 end,
    function(self, room, p, targets)
        -- 完杀 option: usable until end of this turn (放逐/集智/鬼才 are offered at their own timings).
        local data = sgs.QVariant("hlxg_wansha_simayi")
        local paid, first = c203_jilve(room, p, data)
        if paid then room:setPlayerMark(p, "hlxg_jilve_wansha-Clear", 1); c203_jilve_done(p, first, data) end
    end, nil, function(p) return p:getMark("@hlxg_renjie") > 0 end)
hlxg_lianpo = gu_trigger("hlxg_lianpo", {sgs.Death, sgs.EventPhaseChanging}, function(self, event, room, player, data, p)
    if event == sgs.Death then
        local d = data:toDeath()
        if d.damage and d.damage.from == p then room:setPlayerMark(p, "hlxg_lianpo-Clear", 1) end
    elseif data:toPhaseChange().to == sgs.Player_NotActive and p:getMark("hlxg_lianpo-Clear") > 0
        and gu_invoke(p, self:objectName(), data) then p:gainAnExtraTurn() end
end)
for _, skill in ipairs({hlxg_renjie, hlxg_jilve, hlxg_lianpo, hlxg_jilve_react, hlxg_wansha_simayi_limit}) do hlxg_simayi:addSkill(skill) end
extension_hl:insertRelatedSkills("hlxg_jilve", "#hlxg_jilve_react")
extension_hl:insertRelatedSkills("hlxg_jilve", "#hlxg_wansha_simayi_limit")

hlxg_simalang = sgs.General(extension_hl, "hlxg_simalang", "wei", 3)
hlxg_qujiCard = sgs.CreateSkillCard {
    name = "hlxg_qujiCard", will_throw = false,
    filter = function(self, targets, to, p) return to:isWounded() and #targets < self:subcardsLength() end,
    feasible = function(self, targets) return #targets <= self:subcardsLength() end,
    on_use = function(self, room, p, targets)
        local n = self:subcardsLength()
        local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_RECAST, p:objectName(), "hlxg_quji", "")
        room:moveCardTo(self, p, nil, sgs.Player_DiscardPile, reason, true)
        p:drawCards(n, "hlxg_quji")
        for _, to in ipairs(targets) do if to:isAlive() then c203_recover(room, to, p, "hlxg_quji") end end
        for _, to in ipairs(targets) do if to:isAlive() and to:isWounded() then to:drawCards(1, "hlxg_quji") end end
    end,
}
