hlxg_junbing = gu_trigger("hlxg_junbing", {sgs.EventPhaseStart}, function(self, event, room, player, data, p)
    if not player or player:getPhase() ~= sgs.Player_Finish or player:getHandcardNum() >= player:getHp()
        or not gu_invoke(player, self:objectName(), sgs.QVariant(p)) then return end
    player:drawCards(1, self:objectName())
    if player:isDead() or p:isDead() then return end
    local n = player:getHandcardNum()
    gu_obtain(room, p, player:handCards(), self:objectName())
    if n > 0 and p:isAlive() and player:isAlive() and p:getCardCount(true) >= n then
        local cards = room:askForExchange(p, self:objectName(), n, n, true, "@hlxg_junbing", true)
        if cards then room:obtainCard(player, cards, false); cards:deleteLater() end
    end
end)
