-- c203_06: literal Huanle variants.
hlxg_xianglang = sgs.General(extension_hl, "hlxg_xianglang", "shu", 3)
hlxg_lvkai = sgs.General(extension_hl, "hlxg_lvkai", "shu", 3)
hlxg_lvdai = sgs.General(extension_hl, "hlxg_lvdai", "wu", 4)
local function hl06_suits(p)
    local seen, n = {}, 0
    for _, c in sgs.qlist(p:getHandcards()) do
        local suit = c:getSuit()
        if not seen[suit] then seen[suit] = true; n = n + 1 end
    end
    return n
end
local function hl06_recast(room, p, ids, skill)
    if ids:isEmpty() then return end
    local c = gu_dummy(ids)
    local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_RECAST, p:objectName(), skill, "")
    room:throwCard(c, reason, p)
    c:deleteLater()
    if p:isAlive() then room:drawCards(p, ids:length(), skill) end
end
hlxg_kanji = gu_active("hlxg_kanji", 2, 0, 0,
    function() return false end, function(self, targets) return #targets == 0 end,
    function(self, room, source)
        room:showAllCards(source)
        local n = hl06_suits(source)
        if n == source:getHandcardNum() then
            room:drawCards(source, 2, "hlxg_kanji")
            if source:isAlive() and n < 4 and hl06_suits(source) == 4 then
                room:showAllCards(source)
                source:skip(sgs.Player_Discard)
            end
        end
    end)
hlxg_qianzheng = gu_trigger("hlxg_qianzheng", {sgs.CardUsed, sgs.TargetConfirming, sgs.CardFinished},
    function(self, event, room, actor, data, p)
        local use = data:toCardUse()
        local card = use.card
        if not card then return end
        local flag = "hlxg_qianzheng_" .. p:objectName()
        if event == sgs.CardFinished then
            if card:hasFlag(flag) then
                room:setCardFlag(card, "-" .. flag)
                local ids = card:isVirtualCard() and card:getSubcards() or sgs.IntList()
                if not card:isVirtualCard() and card:getEffectiveId() >= 0 then ids:append(card:getEffectiveId()) end
                local obtainable = not ids:isEmpty()
                for _, id in sgs.qlist(ids) do
                    local place = room:getCardPlace(id)
                    if place ~= sgs.Player_DiscardPile and place ~= sgs.Player_PlaceTable then obtainable = false end
                end
                if obtainable and gu_invoke(p, "hlxg_qianzheng_obtain", data) then gu_obtain(room, p, ids, self:objectName()) end
            end
            return
        end
        local eligible = event == sgs.CardUsed and use.from == p and card:isKindOf("Slash")
            or event == sgs.TargetConfirming and actor == p and use.from and use.from ~= p
                and (card:isKindOf("Slash") or card:isNDTrick())
        if not eligible or p:getMark("hlxg_qianzheng-Clear") >= 2 or p:getCardCount(true) < 2 then return end
        local cost = room:askForExchange(p, self:objectName(), 2, 2, true, "@hlxg_qianzheng", true)
        if not cost then return end
        room:addPlayerMark(p, "hlxg_qianzheng-Clear")
        local different = true
        for _, id in sgs.qlist(cost:getSubcards()) do
            if sgs.Sanguosha:getCard(id):getTypeId() == card:getTypeId() then different = false end
        end
        if different then room:setCardFlag(card, flag) end
        hl06_recast(room, p, cost:getSubcards(), self:objectName())
        cost:deleteLater()
    end)
-- Response-only borrowed view-as: the inspected card stays on top until used.
local function hl06_tunan_card(p)
    local id = p:getMark("hlxg_tunan_id") - 1
    if id < 0 then return nil end
    local material = sgs.Sanguosha:getCard(id)
    local slash = p:getMark("hlxg_tunan_slash") > 0
    local c = sgs.Sanguosha:cloneCard(slash and "slash" or material:objectName(), material:getSuit(), material:getNumber())
    c:addSubcard(id); c:setSkillName("hlxg_tunan")
    if not slash then c:setFlags("hlxg_tunan_distance") end
    return c
end
hlxg_tunan_use = sgs.CreateViewAsSkillV2 {
    name = "#hlxg_tunan_use",
    can_activate = function(self, request) return request:getPattern() == "@@#hlxg_tunan_use" and request:getInitiator():getMark("hlxg_tunan_id") > 0 end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function(self, request) return hl06_tunan_card(request:getInitiator()) end,
}
hlxg_tunan_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_tunan_mod", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local c = ctx:getCard()
        if c and c:hasFlag("hlxg_tunan_distance") and ctx:getModType() == sgs.TargetModSkill_DistanceLimit then return 1000 end
        return false
    end,
}
local function hl06_forced_targets(room, p, c, selected)
    if c:targetsFeasible(selected, p) then
        local targets = sgs.SPlayerList()
        for _, target in sgs.qlist(selected) do targets:append(room:findPlayerByObjectName(target:objectName())) end
        room:useCard(sgs.CardUseStruct(c, p, targets)); return true
    end
    for _, target in sgs.qlist(room:getAlivePlayers()) do
        if not selected:contains(target) and c:targetFilter(selected, target, p) and not p:isProhibited(target, c, selected) then
            selected:append(target)
            if hl06_forced_targets(room, p, c, selected) then return true end
            selected:removeOne(target)
        end
    end
    return false
end
hlxg_tunan = gu_active("hlxg_tunan", 1, 0, 0,
    function(self, targets, to, from) return #targets < 2 end,
    function(self, targets) return #targets <= 2 end,
    function(self, room, source, targets)
        for _, p in ipairs(targets) do
            if p:isAlive() then
                local ids = room:getNCards(1)
                if not ids:isEmpty() then
                    room:returnToTopDrawPile(ids)
                    room:fillAG(ids, p); room:askForAG(p, ids, true, "hlxg_tunan"); room:clearAG(p)
                    room:setPlayerMark(p, "hlxg_tunan_id", ids:first() + 1)
                    local choices = {}
                    for _, choice in ipairs({"use", "slash"}) do
                        room:setPlayerMark(p, "hlxg_tunan_slash", choice == "slash" and 1 or 0)
                        local c = hl06_tunan_card(p)
                        if p:canUse(c) then table.insert(choices, choice) end
                        c:deleteLater()
                    end
                    if #choices > 0 then
                        local choice = room:askForChoice(p, "hlxg_tunan", table.concat(choices, "+"))
                        room:setPlayerMark(p, "hlxg_tunan_slash", choice == "slash" and 1 or 0)
                        local c = hl06_tunan_card(p)
                        local parent = sgs.SkillInstanceRef(source:objectName(), sgs.SkillInstanceKey("hlxg_tunan", source:getValidSkillInstanceIds("hlxg_tunan"):first()))
                        local borrowed = room:attachSkillToPlayer(p, "#hlxg_tunan_use", parent, false)
                        if c:targetFixed() then room:useCard(sgs.CardUseStruct(c, p))
                        elseif not room:askForUseCard(p, "@@#hlxg_tunan_use", "@hlxg_tunan")
                            and p:isAlive() and room:getCardPlace(ids:first()) == sgs.Player_DrawPile then
                            hl06_forced_targets(room, p, c, sgs.PlayerList())
                        end
                        room:detachAttachedSkill(borrowed)
                        c:deleteLater()
                    end
                    room:setPlayerMark(p, "hlxg_tunan_id", 0); room:setPlayerMark(p, "hlxg_tunan_slash", 0)
                end
            end
        end
    end)
hlxg_bijing = gu_trigger("hlxg_bijing", {sgs.EventPhaseStart, sgs.CardsMoveOneTime},
    function(self, event, room, actor, data, p)
        if event == sgs.CardsMoveOneTime then
            local move = data:toMoveOneTime()
            if not move.from or move.from:objectName() ~= p:objectName() then return end
            for i, id in sgs.qlist(move.card_ids) do
                if move.from_places:at(i) == sgs.Player_PlaceHand and p:getMark("hlxg_bijing_" .. id) > 0 then
                    room:setPlayerMark(p, "hlxg_bijing_" .. id, 0)
                    room:setPlayerMark(p, "hlxg_bijing_lost-Clear", 1)
                end
            end
            return
        end
        if actor == p and p:getPhase() == sgs.Player_Finish then
            local cards = room:askForExchange(p, self:objectName(), 2, 1, false, "@hlxg_bijing", true)
            if cards then
                for _, id in sgs.qlist(cards:getSubcards()) do room:setPlayerMark(p, "hlxg_bijing_" .. id, 1) end
                cards:deleteLater()
            end
        elseif actor == p and p:getPhase() == sgs.Player_Start then
            local ids = sgs.IntList()
            for _, c in sgs.qlist(p:getHandcards()) do
                if p:getMark("hlxg_bijing_" .. c:getEffectiveId()) > 0 then
                    ids:append(c:getEffectiveId()); room:setPlayerMark(p, "hlxg_bijing_" .. c:getEffectiveId(), 0)
                end
            end
            hl06_recast(room, p, ids, self:objectName())
        elseif actor and actor ~= p and actor:getPhase() == sgs.Player_Discard and p:getMark("hlxg_bijing_lost-Clear") > 0 then
            room:askForDiscard(actor, self:objectName(), 2, 2, false, true)
        end
    end)
