hlxg_qinguo = gu_trigger("hlxg_qinguo", {sgs.CardFinished, sgs.Damage, sgs.CardsMoveOneTime},
    function(self, event, room, actor, data, p)
        if event == sgs.CardFinished then
            local use = data:toCardUse()
            if use.from == p and p:getPhase() ~= sgs.Player_NotActive and use.card:isKindOf("EquipCard") then
                room:askForUseCardWithBorrowedSkill(p, "#hlxg_qinguo_use", "hlxg_qinguo", "@hlxg_qinguo", -1, sgs.Card_MethodUse, false)
            end
        elseif event == sgs.Damage then
            local d = data:toDamage()
            if d.from == p and d.card and d.card:isKindOf("Slash") and d.card:getSkillName() == self:objectName() then room:drawCards(p, 1, self:objectName()) end
        else
            local move = data:toMoveOneTime()
            local delta = 0
            if move.from and move.from:objectName() == p:objectName() then
                for _, place in sgs.qlist(move.from_places) do if place == sgs.Player_PlaceEquip then delta = delta - 1 end end
            end
            if move.to and move.to:objectName() == p:objectName() and move.to_place == sgs.Player_PlaceEquip then delta = delta + move.card_ids:length() end
            if delta ~= 0 and p:getEquips():length() >= p:getHp() then room:recover(p, sgs.RecoverStruct(p)) end
        end
    end)
