-- ==================== c203_07
do
-- c203_07: response receipts are attached to the actual card, not a turn-wide mark.
local function c203_07_wushuang(self, event, room, player, data, owner)
    if event == sgs.CardResponded then
        local response = data:toCardResponse()
        local card = response.m_toCard
        local key = self:objectName() .. "_double_" .. (player and player:objectName() or "") .. "_" .. owner:objectName()
        if not card or not card:isKindOf("Duel") or not response.m_card or not response.m_card:isKindOf("Slash")
            or not card:hasFlag(key) or card:hasFlag("c203_07_extra_response") then return end
        room:setCardFlag(card, "c203_07_extra_response")
        local extra = room:askForCard(player, "slash", "@" .. self:objectName() .. "-slash", data,
            sgs.Card_MethodResponse, response.m_who, false, self:objectName(), false, card)
        room:setCardFlag(card, "-c203_07_extra_response")
        if not extra then response.nullified = true; data:setValue(response) end
        return
    end
    local use = data:toCardUse()
    if not use.card or not use.from then return end
    if use.card:isKindOf("Slash") and use.from == owner then
        local key = "Jink_" .. use.card:toString()
        local required = use.from:getTag(key):toIntList()
        local values = sgs.QList2Table(required)
        for i = 1, #values do if values[i] > 0 then values[i] = math.max(values[i], 2) end end
        local result = sgs.IntList()
        for _, n in ipairs(values) do result:append(n) end
        local value = sgs.QVariant(); value:setValue(result); use.from:setTag(key, value)
    elseif use.card:isKindOf("Duel") then
        if use.from == owner then
            for _, to in sgs.qlist(use.to) do room:setCardFlag(use.card, self:objectName() .. "_double_" .. to:objectName() .. "_" .. owner:objectName()) end
        elseif use.to:contains(owner) then
            room:setCardFlag(use.card, self:objectName() .. "_double_" .. use.from:objectName() .. "_" .. owner:objectName())
        end
    end
end
