hljx_wuchang_record = gu_record("#hljx_wuchang_record", {sgs.TargetSpecified, sgs.CardResponded, sgs.CardFinished},
    function(self, event, room, player, data)
        if event == sgs.TargetSpecified then
            local use = data:toCardUse()
            if use.card then
                for _, to in sgs.qlist(use.to) do room:setCardFlag(use.card, "hljx_wuchang_target_" .. to:objectName()) end
            end
        elseif event == sgs.CardResponded then
            local response = data:toCardResponse()
            if player and response.m_toCard then room:setCardFlag(response.m_toCard, "hljx_wuchang_responded_" .. player:objectName()) end
        else
            local use = data:toCardUse()
            if not use.card then return end
            room:setCardFlag(use.card, "-hlxg_wuqian_first")
            for _, p in sgs.qlist(room:getAllPlayers()) do
                room:setCardFlag(use.card, "-hljx_wuchang_responded_" .. p:objectName())
                room:setCardFlag(use.card, "-hljx_wuchang_target_" .. p:objectName())
                for _, owner in sgs.qlist(room:getAllPlayers()) do
                    room:setCardFlag(use.card, "-hljx_wushuang_double_" .. p:objectName() .. "_" .. owner:objectName())
                    room:setCardFlag(use.card, "-hlxg_wushuang_double_" .. p:objectName() .. "_" .. owner:objectName())
                end
            end
        end
    end)
hljx_wuchang_damage = gu_trigger("#hljx_wuchang_damage", {sgs.DamageCaused},
    function(self, event, room, player, data, owner)
        local damage = data:toDamage()
        if damage.from ~= owner or not damage.to or not damage.card
            or not damage.card:hasFlag("hljx_wuchang_target_" .. damage.to:objectName())
            or not (damage.card:isKindOf("Slash") or damage.card:isKindOf("Duel"))
            or damage.to:getKingdom() ~= owner:getKingdom()
            or damage.card:hasFlag("hljx_wuchang_responded_" .. damage.to:objectName())
            or not gu_invoke(owner, "hljx_wuchang", data) then return end
        damage.damage = damage.damage + 1; data:setValue(damage)
        local choices = {}
        for _, kingdom in ipairs(sgs.Sanguosha:getKingdoms()) do
            if kingdom ~= owner:getKingdom() then table.insert(choices, kingdom) end
        end
        if #choices > 0 then room:changeKingdom(owner, room:askForChoice(owner, "hljx_wuchang", table.concat(choices, "+"))) end
    end)
