        for _, to in ipairs(others) do
            if to:isAlive() then
                local damage = sgs.DamageStruct(); damage.from = source; damage.to = to
                damage.damage = 1; damage.reason = "hlxg_shenfen"; room:damage(damage)
            end
        end
        for _, to in ipairs(others) do if to:isAlive() then to:throwAllEquips("hlxg_shenfen") end end
        for _, to in ipairs(others) do
            if to:isAlive() then room:askForDiscard(to, "hlxg_shenfen", 4, 4, false, false) end
        end
    end,
}
