-- ==================== c205_01
do
-- c205_01: literal Daqiao variants.
local function batch_active(name, quota, nmin, nmax, target_filter, target_feasible, effect, select_card)
    local card = sgs.CreateSkillCard {
        name = name .. "Card", will_throw = false,
        filter = target_filter, feasible = target_feasible, on_use = effect,
    }
    _G[name .. "Card"] = card
    local spec = {
        name = name,
        can_activate = function(self, request)
            return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
        end,
        can_select_card = function(self, request, c)
            return request:getSelectedCardIds():length() < nmax and select_card(request, c)
        end,
        card_selection_feasible = function(self, request)
            local n = request:getSelectedCardIds():length(); return n >= nmin and n <= nmax
        end,
        create_card = function(self, request)
            local c = card:clone(); c:addSubcards(request:getSelectedCardIds()); c:setSkillName(name); return c
        end,
    }
    if quota then spec.limit_scope = sgs.Skill_Limit_Phase; spec.phase_name = "Play"; spec.max_usage_limit = quota end
    return sgs.CreateViewAsSkillV2(spec)
end
local function diamond_loss(name)
    return gu_trigger(name, {sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
        local move = data:toMoveOneTime()
        if not move.from or move.from:objectName() ~= owner:objectName() then return end
        if move.to and move.to:objectName() == owner:objectName() then return end
        for _, id in sgs.qlist(move.card_ids) do
            if sgs.Sanguosha:getCard(id):getSuit() == sgs.Card_Diamond then
                owner:drawCards(1, self:objectName()); break
            end
        end
    end, true)
end
local function redirect(name)
    return gu_trigger(name, {sgs.TargetConfirming}, function(self, event, room, p, data, owner)
        local use = data:toCardUse()
        if p ~= owner or not use.from or use.from == owner or not use.card
            or not use.card:isKindOf("Slash") or not use.to:contains(owner) or owner:isNude() then return end
        local candidates = sgs.SPlayerList()
        for _, to in sgs.qlist(room:getOtherPlayers(owner)) do
            if to ~= use.from and not use.to:contains(to) and owner:inMyAttackRange(to) then candidates:append(to) end
        end
        if candidates:isEmpty() then return end
        local to = room:askForPlayerChosen(owner, candidates, name, "@" .. name, true, true)
        if not to then return end
        local c = room:askForCard(owner, "..", "@" .. name .. "-discard", data, sgs.Card_MethodDiscard, nil, false, name)
        if not c or not to:isAlive() then return end
        use.to:removeOne(owner); use.to:append(to); room:sortByActionOrder(use.to); data:setValue(use)
        room:getThread():trigger(sgs.TargetConfirming, room, to, data)
    end)
end
hlxg_guose_daqiao = diamond_loss("hlxg_guose_daqiao")
hljx_guose = diamond_loss("hljx_guose")
hlxg_guose_daqiao2 = diamond_loss("hlxg_guose_daqiao2")
hlxg_liuli = redirect("hlxg_liuli")
hljx_liuli = redirect("hljx_liuli")

local function wanrong_use(from, to, id)
    local base = sgs.Sanguosha:getCard(id)
    local c = sgs.Sanguosha:cloneCard("indulgence", base:getSuit(), base:getNumber())
    c:addSubcard(id); c:setSkillName("hljx_wanrong")
    local targets = sgs.PlayerList()
    local legal = c:isAvailable(from) and not from:isProhibited(to, c) and c:targetFilter(targets, to, from)
    return c, legal
end
hljx_wanrong = batch_active("hljx_wanrong", 1, 1, 1,
    function(self, targets, to, from)
        if #targets ~= 0 then return false end
        local c, legal = wanrong_use(from, to, self:getSubcards():first()); c:deleteLater()
        if legal then return true end
        local cost = sgs.Sanguosha:getCard(self:getSubcards():first())
        if from:isJilei(cost) then return false end
        for _, trick in sgs.qlist(to:getJudgingArea()) do
            if trick:isKindOf("Indulgence") and from:canDiscard(to, trick:getEffectiveId()) then return true end
        end
        return false
    end, gu_one_feasible,
    function(self, room, source, targets)
        local to, id = targets[1], self:getSubcards():first()
        local c, legal = wanrong_use(source, to, id)
        local remove = sgs.IntList()
        if not source:isJilei(sgs.Sanguosha:getCard(id)) then
            for _, trick in sgs.qlist(to:getJudgingArea()) do
                if trick:isKindOf("Indulgence") and source:canDiscard(to, trick:getEffectiveId()) then remove:append(trick:getEffectiveId()) end
            end
        end
        local choices = {}
        if legal then table.insert(choices, "use") end
        if not remove:isEmpty() then table.insert(choices, "remove") end
        if #choices == 0 then c:deleteLater(); return end
        local choice = #choices == 1 and choices[1] or room:askForChoice(source, "hljx_wanrong", table.concat(choices, "+"))
        if choice == "use" then
            local use = sgs.CardUseStruct(); use.card = c; use.from = source; use.to:append(to); room:useCard(use)
        else
            c:deleteLater()
            gu_throw(room, source, self:getSubcards(), "hljx_wanrong")
            if source:isAlive() and to:isAlive() then
                room:fillAG(remove, source)
                local chosen = room:askForAG(source, remove, false, "hljx_wanrong"); room:clearAG(source)
                if chosen >= 0 and room:getCardOwner(chosen) == to and room:getCardPlace(chosen) == sgs.Player_PlaceDelayedTrick then
                    room:throwCard(chosen, to, source)
                end
            end
        end
    end,
    function(self, c) return c:getSuit() == sgs.Card_Diamond and self:getInitiator():getCards("he"):contains(c) end)

hlxg_anxian = gu_trigger("hlxg_anxian", {sgs.TargetSpecified, sgs.TargetConfirming}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if not use.card or not use.card:isKindOf("Slash") then return end
    if event == sgs.TargetSpecified then
        if use.from ~= owner or use.card:getSkillName() == "hlxg_anxian" then return end
        for _, to in sgs.qlist(use.to) do
            if to ~= owner and to:isAlive() and not to:isKongcheng()
                and gu_invoke(owner, "hlxg_anxian", sgs.QVariant(to)) then
                room:askForDiscard(to, "hlxg_anxian", 1, 1, false, false)
            end
        end
    elseif p == owner and use.to:contains(owner) then
        local c = room:askForCard(owner, ".|.|.|hand", "@hlxg_anxian-discard", data, sgs.Card_MethodDiscard, nil, false, "hlxg_anxian")
        if not c then return end
        local nullified = use.nullified_list
        local already = false
        for _, name in ipairs(nullified) do if name == owner:objectName() then already = true end end
        if not already then table.insert(nullified, owner:objectName()) end
        use.nullified_list = nullified; data:setValue(use)
        if use.from and use.from:isAlive() then
            use.from:drawCards(1, "hlxg_anxian")
            if c:getSuit() == sgs.Card_Diamond and owner:isAlive() and use.from:isAlive() then
                local slash = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0); slash:setSkillName("hlxg_anxian")
                local counter = sgs.CardUseStruct(); counter.card = slash; counter.from = owner; counter.to:append(use.from)
                room:useCard(counter, false); slash:deleteLater()
            end
        end
    end
end)

hlxg_yanxiao = batch_active("hlxg_yanxiao", nil, 1, 1,
    function(self, targets, to, from) return #targets == 0 end, gu_one_feasible,
    function(self, room, source, targets)
        local id = self:getSubcards():first()
        room:setCardFlag(id, "hlxg_yanxiao_card")
        room:moveCardTo(sgs.Sanguosha:getCard(id), source, targets[1], sgs.Player_PlaceDelayedTrick,
            sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_PUT, source:objectName(), "hlxg_yanxiao", ""), true)
    end,
    function(self, c) return c:getSuit() == sgs.Card_Diamond and self:getInitiator():getCards("he"):contains(c) end)
hlxg_yanxiao_judge = gu_record("#hlxg_yanxiao_judge", {sgs.EventPhaseStart, sgs.CardsMoveOneTime}, function(self, event, room, p, data)
    if event == sgs.CardsMoveOneTime then
        local move = data:toMoveOneTime()
        for i, id in sgs.qlist(move.card_ids) do
            if move.from_places:at(i) == sgs.Player_PlaceDelayedTrick and move.to_place ~= sgs.Player_PlaceDelayedTrick then
                room:setCardFlag(id, "-hlxg_yanxiao_card")
            end
        end
        return
    end
    if not p or not p:isAlive() or p:getPhase() ~= sgs.Player_Judge then return end
    local found = false
    local ids = sgs.IntList()
    for _, c in sgs.qlist(p:getJudgingArea()) do
        ids:append(c:getEffectiveId())
        if c:hasFlag("hlxg_yanxiao_card") then found = true end
    end
    if not found then return end
    gu_obtain(room, p, ids, "hlxg_yanxiao")
    if not p:isAlive() then return end
    local judge = sgs.JudgeStruct(); judge.who = p; judge.reason = "hlxg_yanxiao"; judge.pattern = ".|red"; judge.good = true
    room:judge(judge)
    if not p:isAlive() or not judge.card then return end
    if judge.card:isRed() then p:drawCards(1, "hlxg_yanxiao")
    elseif judge.card:isBlack() then room:addPlayerMark(p, "hlxg_yanxiao_slash-Clear") end
end)
hlxg_yanxiao_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_yanxiao_mod", pattern = "Slash", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        if ctx:getModType() == sgs.TargetModSkill_Residue and ctx:getPrimary() then
            return ctx:getPrimary():getMark("hlxg_yanxiao_slash-Clear")
        end
        return 0
    end,
}
