-- ==================== c205_02
do
-- c205_02: all three literal variants.
hlxg_taishici = sgs.General(extension_hl, "hlxg_taishici", "wu", 4)
hljx_taishici = sgs.General(extension_hl, "hljx_taishici", "wu", 4)
hlxg_taishici2 = sgs.General(extension_hl, "hlxg_taishici2", "qun", 4)

local function c205_02_option(room, owner, skill, choice)
    if choice == "draw" then owner:drawCards(1, skill)
    else room:addPlayerMark(owner, skill .. "_" .. choice .. "-Clear") end
end
local function c205_02_recover(room, owner)
    local recover = sgs.RecoverStruct(); recover.who = owner; recover.recover = 1
    room:recover(owner, recover)
end
hlxg_tianyi_taishici = gu_trigger("hlxg_tianyi_taishici", {sgs.EventPhaseStart, sgs.Damage, sgs.TargetSpecified},
    function(self, event, room, p, data, owner)
        if p ~= owner then return end
        local name = self:objectName()
        if event == sgs.EventPhaseStart then
            if owner:getPhase() ~= sgs.Player_Play or not gu_invoke(owner, name, data) then return end
            local choice = room:askForChoice(owner, name, "assault+reach")
            if choice == "assault" then
                c205_02_option(room, owner, name, "residue")
                c205_02_option(room, owner, name, "recover")
            else
                c205_02_option(room, owner, name, "draw")
                c205_02_option(room, owner, name, "reach")
            end
        elseif event == sgs.Damage then
            local d = data:toDamage()
            if d.from == owner and d.card and d.card:isKindOf("Slash") and owner:getMark(name .. "_recover-Clear") > 0 then
                c205_02_recover(room, owner)
            end
        else
            local use = data:toCardUse()
            if use.card and use.card:isKindOf("Slash") and owner:getMark(name .. "_reach-Clear") > 0 then
                for _, to in sgs.qlist(use.to) do to:addQinggangTag(use.card) end
            end
        end
    end)

hljx_tianyi = gu_trigger("hljx_tianyi", {sgs.EventPhaseStart, sgs.Damage, sgs.TargetSpecified},
    function(self, event, room, p, data, owner)
        if p ~= owner then return end
        local name = self:objectName()
        if event == sgs.EventPhaseStart then
            if owner:getPhase() ~= sgs.Player_Play or not gu_invoke(owner, name, data) then return end
            local choices = {"residue", "recover", "draw", "reach"}
            for i = 1, 2 do
                local choice = room:askForChoice(owner, name, table.concat(choices, "+"))
                c205_02_option(room, owner, name, choice)
                for j = #choices, 1, -1 do if choices[j] == choice then table.remove(choices, j) end end
            end
        elseif event == sgs.Damage then
            local d = data:toDamage()
            if d.from == owner and d.card and d.card:isKindOf("Slash") and owner:getMark(name .. "_recover-Clear") > 0 then
                c205_02_recover(room, owner)
            end
        else
            local use = data:toCardUse()
            if not use.card or not use.card:isKindOf("Slash") or use.from ~= owner then return end
            -- Snapshot only the original targets: targets added by this skill do not grant another pindian.
            local original = {}; for _, to in sgs.qlist(use.to) do table.insert(original, to) end
            for _, to in ipairs(original) do
                if owner:isAlive() and to:isAlive() and owner:canPindian(to)
                    and gu_invoke(owner, name, sgs.QVariant(to)) and owner:pindian(to, name, nil) and owner:isAlive() then
                    local candidates = sgs.SPlayerList()
                    for _, extra in sgs.qlist(room:getOtherPlayers(owner)) do
                        if not use.to:contains(extra) and owner:canSlash(extra, use.card,
                            owner:getMark(name .. "_reach-Clear") == 0) then candidates:append(extra) end
                    end
                    if not candidates:isEmpty() then
                        local extra = room:askForPlayerChosen(owner, candidates, name, "@hljx_tianyi-extra", true, true)
                        if extra then use.to:append(extra); room:sortByActionOrder(use.to); data:setValue(use) end
                    end
                end
            end
            if owner:getMark(name .. "_reach-Clear") > 0 then
                for _, to in sgs.qlist(use.to) do to:addQinggangTag(use.card) end
            end
        end
    end)

local function c205_02_mod(name, main)
    return sgs.CreateTargetModSkillV2 {
        name = name, pattern = "Slash", holder_selector = sgs.CorrectSkill_System,
        correct_func = function(self, ctx)
            local p = ctx:getPrimary(); if not p then return 0 end
            if ctx:getModType() == sgs.TargetModSkill_Residue then return p:getMark(main .. "_residue-Clear") end
            if ctx:getModType() == sgs.TargetModSkill_DistanceLimit and p:getMark(main .. "_reach-Clear") > 0 then return 1000 end
            return 0
        end,
    }
end
hlxg_tianyi_taishici_mod = c205_02_mod("#hlxg_tianyi_taishici_mod", "hlxg_tianyi_taishici")
hljx_tianyi_mod = c205_02_mod("#hljx_tianyi_mod", "hljx_tianyi")

hljx_hanzhan = gu_trigger("hljx_hanzhan", {sgs.AskforPindianCard, sgs.Pindian},
    function(self, event, room, p, data, owner)
        local pd = data:toPindian()
        if not pd or not pd.from or not pd.to or (pd.from ~= owner and pd.to ~= owner) then return end
        if event == sgs.AskforPindianCard then
            local other = pd.from == owner and pd.to or pd.from
            if other:isKongcheng() or not gu_invoke(owner, self:objectName(), sgs.QVariant(other)) then return end
            if other == pd.from then pd.from_card = other:getRandomHandCard()
            else pd.to_card = other:getRandomHandCard() end
            data:setValue(pd)
        else
            local ids = sgs.IntList()
            for _, card in ipairs({pd.from_card, pd.to_card}) do
                if card and card:isKindOf("Slash") and room:CardInTable(card) and not ids:contains(card:getEffectiveId()) then
                    ids:append(card:getEffectiveId())
                end
            end
            if not ids:isEmpty() and gu_invoke(owner, self:objectName(), data) then gu_obtain(room, owner, ids, self:objectName()) end
        end
    end)

hlxg_jixuCard = sgs.CreateSkillCard {
    name = "hlxg_jixuCard", will_throw = false,
    filter = function(self, targets, to, from) return #targets < 4 and to ~= from end,
    feasible = function(self, targets) return #targets <= 4 end,
    on_use = function(self, room, source, targets)
        local has_slash = false
        for _, c in sgs.qlist(source:getHandcards()) do if c:isKindOf("Slash") then has_slash = true; break end end
        -- Gather every private answer before revealing any answer or applying effects.
        local answers, wrong = {}, {}
        for _, to in ipairs(targets) do
            answers[to:objectName()] = room:askForChoice(to, "hlxg_jixu", "has+absent", sgs.QVariant(source))
        end
        for _, to in ipairs(targets) do
            local choice = answers[to:objectName()]
            local mistaken = (choice == "has") ~= has_slash
            local log = sgs.LogMessage(); log.type = "#hlxg_jixuGuess"; log.from = to
            log.arg = "hlxg_jixu:" .. choice; log.arg2 = mistaken and "hlxg_jixu:wrong" or "hlxg_jixu:correct"
            room:sendLog(log)
            if mistaken then table.insert(wrong, to) end
        end
        local n = #wrong + 1
        for _, to in ipairs(wrong) do
            if source:isAlive() and to:isAlive() then
                if source:canDiscard(to, "he") then
                    local id = room:askForCardChosen(source, to, "he", "hlxg_jixu", false, sgs.Card_MethodDiscard)
                    room:throwCard(id, to, source)
                end
                if source:isAlive() and to:isAlive() then
                    local slash = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0); slash:setSkillName("hlxg_jixu")
                    if not source:isProhibited(to, slash) then
                        local use = sgs.CardUseStruct(); use.card = slash; use.from = source; use.to:append(to)
                        room:useCard(use, false)
                    end
                    slash:deleteLater()
                end
            end
        end
        if source:isAlive() then
            source:drawCards(n, "hlxg_jixu")
            room:addPlayerMark(source, "hlxg_jixu_limit-Clear", n)
        end
    end,
}
hlxg_jixu = sgs.CreateViewAsSkillV2 {
    name = "hlxg_jixu", n = 0,
    limit_scope = sgs.Skill_Limit_Phase, phase_name = "Play", max_usage_limit = 1,
    can_activate = function(self, request)
        return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
    end,
    create_card = function(self, request)
        local card = hlxg_jixuCard:clone(); card:setSkillName("hlxg_jixu"); return card
    end,
}
hlxg_jixu_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_jixu_max", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary(); return p and p:getMark("hlxg_jixu_limit-Clear") or 0
    end,
}

