-- ==================== c205_03
do
-- c205_03: literal 欢乐杀修改 variants.
local function hl20503_recover(room, p, amount, skill)
    if amount <= 0 then return end
    local rec = sgs.RecoverStruct(); rec.who = p; rec.recover = amount
    room:recover(p, rec)
end
local function hl20503_count(room)
    local n = 0
    for _, p in sgs.qlist(room:getAlivePlayers()) do n = n + p:getMark("&hlxg_chongwei") end
    return n
end
hlxg_taishici3 = sgs.General(extension_hl, "hlxg_taishici3", "god", 4)
hlxg_powei = gu_trigger("hlxg_powei", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p:getPhase() ~= sgs.Player_Finish or owner:getMark(self:objectName()) > 0 or hl20503_count(room) > 0 then return end
    room:setPlayerMark(owner, self:objectName(), 1)
    room:acquireSkill(owner, "hlxg_shenzhu")
    owner:drawCards(owner:getMark("hlxg_chongwei_discard_lun"), self:objectName())
end, true, sgs.Skill_Wake)
hlxg_shenzhu = gu_trigger("hlxg_shenzhu", {sgs.EventPhaseStart, sgs.CardFinished}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.EventPhaseStart then
        if p:getPhase() ~= sgs.Player_RoundStart then return end
        for _, id in sgs.qlist(room:getDrawPile()) do
            if sgs.Sanguosha:getCard(id):isKindOf("Slash") then room:obtainCard(p, id, false); break end
        end
    else
        local use = data:toCardUse()
        if use.from ~= owner or not use.card or not use.card:isKindOf("Slash") or use.card:isVirtualCard() or use.card:getSkillName() ~= "" then return end
        if room:askForChoice(owner, self:objectName(), "extra+stop") == "extra" then
            owner:drawCards(1, self:objectName()); room:addPlayerMark(owner, "hlxg_shenzhu_extra-Clear")
        else
            owner:drawCards(3, self:objectName())
            room:setPlayerCardLimitation(owner, "use", "Slash", true, self:objectName())
        end
    end
end, true)
hlxg_shenzhu_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_shenzhu_mod", pattern = "Slash", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        if ctx:getModType() == sgs.TargetModSkill_Residue then return ctx:getPrimary():getMark("hlxg_shenzhu_extra-Clear") end
        return false
    end,
}
hlxg_dulie = gu_trigger("hlxg_dulie", {sgs.TargetConfirming, sgs.EnterDying}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.TargetConfirming then
        local use = data:toCardUse()
        if not use.card or not use.card:isKindOf("Slash") or not use.from or use.from == owner or not use.to:contains(owner) then return end
        local judge = sgs.JudgeStruct(); judge.who = owner; judge.reason = self:objectName(); judge.pattern = ".|heart"; judge.good = true
        room:judge(judge)
        if judge:isGood() then use.to:removeOne(owner); data:setValue(use) end
    elseif owner:getMark("hlxg_dulie_first") == 0 then
        room:setPlayerMark(owner, "hlxg_dulie_first", 1)
        local n = hl20503_count(room)
        if n > 0 then hl20503_recover(room, owner, n - owner:getHp(), self:objectName()) end
    end
end, true)
hlxg_chongwei = gu_trigger("hlxg_chongwei", {sgs.GameStart, sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if event == sgs.GameStart then
        if p ~= owner then return end
        for _, q in sgs.qlist(room:getOtherPlayers(owner)) do room:addPlayerMark(q, "&hlxg_chongwei") end
        return
    end
    if p:getPhase() ~= sgs.Player_RoundStart then return end
    if p == owner then
        -- Snapshot all piles: marks received during this move do not move twice.
        local moves = {}
        for _, q in sgs.qlist(room:getAlivePlayers()) do
            local n = q:getMark("&hlxg_chongwei")
            if n > 0 then
                local nextp = q:getNextAlive()
                if nextp == owner then nextp = nextp:getNextAlive() end
                table.insert(moves, {nextp, n})
                room:setPlayerMark(q, "&hlxg_chongwei", 0)
            end
        end
        for _, move in ipairs(moves) do room:addPlayerMark(move[1], "&hlxg_chongwei", move[2]) end
    end
    if p:getMark("&hlxg_chongwei") == 0 then return end
    local choices = {"cancel"}
    if not owner:isKongcheng() and owner:canDiscard(owner, "h") then table.insert(choices, "damage") end
    if p:getHp() <= owner:getHp() and not p:isKongcheng() then table.insert(choices, "obtain") end
    if #choices == 1 then return end
    local choice = room:askForChoice(owner, self:objectName(), table.concat(choices, "+"), sgs.QVariant(p))
    if choice == "cancel" then return end
    if choice == "damage" then
        if not room:askForDiscard(owner, self:objectName(), 1, 1, false, false) then return end
        local damage = sgs.DamageStruct(); damage.from = owner; damage.to = p; damage.damage = 1; damage.reason = self:objectName()
        room:damage(damage)
    else
        local id = room:askForCardChosen(owner, p, "h", self:objectName())
        room:obtainCard(owner, id, false)
    end
    if p:isAlive() and owner:isAlive() then
        room:insertAttackRangePair(p, owner)
        p:setTag("hlxg_chongwei_range", sgs.QVariant(owner:objectName()))
    end
end)
-- The mark removal and range cleanup must survive skill loss/death of the owner.
hlxg_chongwei_record = gu_record("#hlxg_chongwei_record", {sgs.Damaged, sgs.EventPhaseChanging}, function(self, event, room, p, data)
    if not p then return end
    if event == sgs.Damaged then
        local n = p:getMark("&hlxg_chongwei")
        if n == 0 then return end
        room:setPlayerMark(p, "&hlxg_chongwei", 0)
        for _, q in sgs.qlist(room:getAllPlayers()) do room:addPlayerMark(q, "hlxg_chongwei_discard_lun", n) end
    elseif data:toPhaseChange().to == sgs.Player_NotActive then
        for _, q in sgs.qlist(room:getAllPlayers()) do
            local name = q:getTag("hlxg_chongwei_range"):toString()
            if name ~= "" then
                local owner = room:findPlayerByObjectName(name)
                if owner then room:removeAttackRangePair(q, owner) end
                q:removeTag("hlxg_chongwei_range")
            end
        end
    end
end)
hlxg_taishici3:addSkill(hlxg_powei); hlxg_taishici3:addSkill(hlxg_dulie); hlxg_taishici3:addSkill(hlxg_chongwei)
hlxg_taishici3:addSkill(hlxg_chongwei_record)
extension_hl:addSkills(hlxg_shenzhu); extension_hl:addSkills(hlxg_shenzhu_mod)
hlxg_taishici3:addRelateSkill("hlxg_shenzhu")
extension_hl:insertRelatedSkills("hlxg_shenzhu", "#hlxg_shenzhu_mod")
extension_hl:insertRelatedSkills("hlxg_chongwei", "#hlxg_chongwei_record")

local function hl20503_tiaoxin(name)
    return gu_trigger(name, {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
        if p ~= owner or p:getPhase() ~= sgs.Player_Play then return end
        local targets = sgs.SPlayerList()
        for _, q in sgs.qlist(room:getOtherPlayers(owner)) do if owner:canDiscard(q, "h") then targets:append(q) end end
        if targets:isEmpty() then return end
        local target = room:askForPlayerChosen(owner, targets, name, "@" .. name, true, true)
        if not target then return end
        local ids = room:askForCardsChosen(owner, target, "h", name, 0, 2, false, sgs.Card_MethodDiscard)
        local slash = false
        for _, id in sgs.qlist(ids) do if sgs.Sanguosha:getCard(id):isKindOf("Slash") then slash = true end end
        gu_throw(room, target, ids, name)
        if slash and owner:isAlive() then room:askForDiscard(owner, name, 1, 1, false, true) end
    end)
end
hlxg_jiangwei = sgs.General(extension_hl, "hlxg_jiangwei", "shu", 4)
hlxg_tiaoxin_jiangwei = hl20503_tiaoxin("hlxg_tiaoxin_jiangwei")
hlxg_zhiji = gu_trigger("hlxg_zhiji", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Start or not p:isKongcheng() or p:getMark(self:objectName()) > 0 then return end
    room:setPlayerMark(p, self:objectName(), 1)
    if room:askForChoice(p, self:objectName(), "recover+draw") == "recover" then hl20503_recover(room, p, 1, self:objectName()) else p:drawCards(2, self:objectName()) end
    room:loseMaxHp(p, 1, self:objectName())
    if p:isAlive() then room:acquireSkill(p, "hlxg_guanxing_jiangwei") end
end, true, sgs.Skill_Wake)
hlxg_guanxing_jiangwei = gu_trigger("hlxg_guanxing_jiangwei", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if p:getPhase() ~= sgs.Player_Start and not (p:getPhase() == sgs.Player_Finish and p:getMark("hlxg_guanxing_jiangwei_bottom-Clear") > 0) then return end
    if not gu_invoke(p, self:objectName()) then return end
    local ids = room:getNCards(room:alivePlayerCount() == 2 and 3 or 5)
    local top = room:askForGuanxing(p, ids)
    if p:getPhase() == sgs.Player_Start and top:isEmpty() then room:setPlayerMark(p, "hlxg_guanxing_jiangwei_bottom-Clear", 1) end
end)
