-- ==================== c205_04
do
-- c205_04; counters track phase occurrences, not just phase types.
hlxg_jiangwei3 = sgs.General(extension_hl, "hlxg_jiangwei3", "shu", 4)
hlxg_kongrong = sgs.General(extension_hl, "hlxg_kongrong", "qun", 3)
hljx_sunqian = sgs.General(extension_hl, "hljx_sunqian", "shu", 3)

hlxg_kunfen_jiangwei3 = gu_trigger("hlxg_kunfen_jiangwei3", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Finish or not gu_invoke(owner, self:objectName()) then return end
    room:loseHp(owner, 1, true, owner, self:objectName())
    if owner:isAlive() then owner:drawCards(2, self:objectName()) end
end)

hlxg_ranji = gu_trigger("hlxg_ranji", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Finish or owner:getMark("@hlxg_ranji") == 0 then return end
    local choices = {}
    local n, hp = owner:getMark("hlxg_ranji_phases-Clear"), owner:getHp()
    if n >= hp then table.insert(choices, "kunfen") end
    if n <= hp then table.insert(choices, "zhaxiang") end
    if #choices == 0 or not gu_invoke(owner, self:objectName(), data) then return end
    -- Both independent clauses apply at equality; offer either or both.
    if #choices == 2 then table.insert(choices, "both") end
    local choice = room:askForChoice(owner, self:objectName(), table.concat(choices, "+"))
    room:removePlayerMark(owner, "@hlxg_ranji")
    if choice == "kunfen" or choice == "both" then room:acquireSkill(owner, "hlxg_kunfen_jiangwei3") end
    if choice == "zhaxiang" or choice == "both" then room:acquireSkill(owner, "hlxg_zhaxiang_jiangwei3") end
    room:setPlayerProperty(owner, "hp", sgs.QVariant(owner:getMaxHp()))
    local maximum = math.max(0, owner:getMaxCards())
    if owner:getHandcardNum() < maximum then owner:drawCards(maximum - owner:getHandcardNum(), self:objectName())
    elseif owner:getHandcardNum() > maximum then
        local c = room:askForExchange(owner, self:objectName(), owner:getHandcardNum() - maximum, owner:getHandcardNum() - maximum)
        if c then room:throwCard(c, owner, owner); c:deleteLater() end
    end
    room:setPlayerMark(owner, "&hlxg_ranji_norecover", 1)
end, false, sgs.Skill_Limited, "@hlxg_ranji")

hlxg_zhaxiang_jiangwei3 = gu_trigger("hlxg_zhaxiang_jiangwei3", {sgs.HpLost, sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.HpLost then
        local n = data:toHpLost().lose
        for i = 1, n do
            if owner:isDead() then break end
            owner:drawCards(3, self:objectName())
            room:addPlayerMark(owner, "hlxg_zhaxiang_jiangwei3-Clear")
        end
    else
        local use = data:toCardUse()
        if owner:getMark("hlxg_zhaxiang_jiangwei3-Clear") == 0 or not use.card or not use.card:isKindOf("Slash") or not use.card:isRed() then return end
        local names = use.no_respond_list
        for _, q in sgs.qlist(use.to) do table.insert(names, q:objectName()) end
        use.no_respond_list = names; data:setValue(use)
    end
end, true)
hlxg_zhaxiang_jiangwei3_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_zhaxiang_jiangwei3_mod", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local p, c = ctx:getPrimary(), ctx:getCard()
        if not p or not c or not c:isKindOf("Slash") then return 0 end
        local n = p:getMark("hlxg_zhaxiang_jiangwei3-Clear")
        if ctx:getModType() == sgs.TargetModSkill_Residue then return n end
        if n > 0 and c:isRed() and ctx:getModType() == sgs.TargetModSkill_DistanceLimit then return 1000 end
        return 0
    end,
}

hlxg_zhuri_use = sgs.CreateViewAsSkillV2 {
    name = "#hlxg_zhuri_use",
    can_activate = function(self, request)
        return request:getPattern() == "@@#hlxg_zhuri_use" and request:getInitiator():getMark("hlxg_zhuri_card") > 0
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function(self, request)
        local id = request:getInitiator():getMark("hlxg_zhuri_card") - 1
        if id < 0 then return nil end
        local original = sgs.Sanguosha:getCard(id)
        local c = sgs.Sanguosha:cloneCard(original:objectName(), original:getSuit(), original:getNumber())
        c:addSubcard(id); c:setSkillName("hlxg_zhuri"); return c
    end,
}
hlxg_zhuri = gu_trigger("hlxg_zhuri", {sgs.EventPhaseEnd}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:getMark("hlxg_zhuri_changed") == 0 then return end
    local candidates = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getAlivePlayers()) do if owner:canPindian(q) then candidates:append(q) end end
    if candidates:isEmpty() then return end
    local q = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_zhuri", true, true)
    if not q then return end
    local pd = owner:pindianSelect(q, self:objectName())
    if not pd then return end
    local first, second = pd.from_card:getEffectiveId(), pd.to_card:getEffectiveId()
    local won = owner:pindian(pd)
    if owner:isDead() then return end
    if won then
        local ids = sgs.IntList()
        for _, id in ipairs({first, second}) do
            local place = room:getCardPlace(id)
            if place == sgs.Player_DiscardPile or place == sgs.Player_PlaceTable then ids:append(id) end
        end
        if ids:isEmpty() then return end
        room:fillAG(ids, owner)
        local id = room:askForAG(owner, ids, true, self:objectName())
        room:clearAG(owner)
        if id >= 0 then
            room:setPlayerMark(owner, "hlxg_zhuri_card", id + 1)
            room:askForUseCard(owner, "@@#hlxg_zhuri_use", "@hlxg_zhuri-use", -1, sgs.Card_MethodUse, false)
            room:setPlayerMark(owner, "hlxg_zhuri_card", 0)
        end
    elseif room:askForChoice(owner, self:objectName(), "losehp+lose_skill") == "losehp" then
        room:loseHp(owner, 1, true, owner, self:objectName())
    else
        room:setPlayerMark(owner, "hlxg_zhuri_restore", 1)
        room:detachSkillFromPlayer(owner, self:objectName())
    end
end)

hlxg_ranji_record = gu_record("#hlxg_ranji_record", {sgs.CardUsed, sgs.CardResponded, sgs.CardsMoveOneTime, sgs.EventPhaseChanging, sgs.Death}, function(self, event, room, p, data)
    if event == sgs.CardUsed or event == sgs.CardResponded then
        local source = event == sgs.CardUsed and data:toCardUse().from or p
        if event == sgs.CardResponded and not data:toCardResponse().m_isUse then return end
        if source and source:getPhase() ~= sgs.Player_NotActive and source:getMark("hlxg_ranji_usedphase") == 0 then
            room:setPlayerMark(source, "hlxg_ranji_usedphase", 1)
            room:addPlayerMark(source, "hlxg_ranji_phases-Clear")
        end
    elseif event == sgs.CardsMoveOneTime then
        local m = data:toMoveOneTime()
        for _, q in sgs.qlist(room:getAlivePlayers()) do
            if q:getPhase() ~= sgs.Player_NotActive then
                local delta = 0
                if m.from and m.from:objectName() == q:objectName() then
                    for _, place in sgs.qlist(m.from_places) do if place == sgs.Player_PlaceHand then delta = delta - 1 end end
                end
                if m.to and m.to:objectName() == q:objectName() and m.to_place == sgs.Player_PlaceHand then delta = delta + m.card_ids:length() end
                if delta ~= 0 then room:setPlayerMark(q, "hlxg_zhuri_changed", 1) end
            end
        end
    elseif event == sgs.EventPhaseChanging then
        room:setPlayerMark(p, "hlxg_ranji_usedphase", 0)
        room:setPlayerMark(p, "hlxg_zhuri_changed", 0)
        if data:toPhaseChange().to == sgs.Player_NotActive then
            for _, q in sgs.qlist(room:getAlivePlayers()) do
                if q:getMark("hlxg_zhuri_restore") > 0 then
                    room:setPlayerMark(q, "hlxg_zhuri_restore", 0); room:acquireSkill(q, "hlxg_zhuri")
                end
            end
        end
    else
        local death = data:toDeath()
        local killer = death.damage and death.damage.from or (death.hplost and death.hplost.from)
        if killer and killer ~= death.who then room:setPlayerMark(killer, "&hlxg_ranji_norecover", 0) end
    end
end)
hlxg_ranji_recover = sgs.CreateRuleSkillV2 {
    name = "#hlxg_ranji_recover", global = true, frequency = sgs.Skill_Compulsory,
    events = {sgs.PreHpRecover},
    can_trigger = function(self, event, room, p, data)
        if p and p:getMark("&hlxg_ranji_norecover") > 0 then return self:objectName(), p end
        return false
    end,
    on_effect = function() return true end,
}

hlxg_zhengyi = gu_trigger("hlxg_zhengyi", {sgs.DamageInflicted}, function(self, event, room, p, data, owner)
    local d = data:toDamage()
    if not p or (p ~= owner and p:getMark("&hlxg_lirang") == 0) or d.transfer_reason == self:objectName() then return end
    for _, q in sgs.qlist(room:getOtherPlayers(p)) do
        if gu_invoke(q, self:objectName(), data) then
            d.to = q; d.transfer = true; d.transfer_reason = self:objectName()
            data:setValue(d) -- Prevent a second owner from transferring this same event.
            room:damage(d)
            if q:isAlive() then q:drawCards(1, self:objectName()) end
            return true
        end
    end
end)
hlxg_lirang = gu_trigger("hlxg_lirang", {sgs.GameStart, sgs.EventPhaseStart, sgs.DrawNCards, sgs.EventPhaseEnd}, function(self, event, room, p, data, owner)
    if event == sgs.GameStart or (event == sgs.EventPhaseStart and p == owner and p:getPhase() == sgs.Player_Start) then
        if p ~= owner then return end
        for _, q in sgs.qlist(room:getAlivePlayers()) do if q:getMark("&hlxg_lirang") > 0 then return end end
        local q = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@hlxg_lirang", true, true)
        if q then room:setPlayerMark(q, "&hlxg_lirang", 1) end
    elseif event == sgs.EventPhaseEnd and p and p:getPhase() == sgs.Player_Discard and p:getMark("&hlxg_lirang") > 0 then
        local ids = sgs.IntList()
        for _, str in ipairs(p:getTag("hlxg_lirang_discard"):toString():split("+")) do
            local id = tonumber(str)
            if id and room:getCardPlace(id) == sgs.Player_DiscardPile then ids:append(id) end
        end
        if not ids:isEmpty() and gu_invoke(owner, self:objectName(), data) then gu_obtain(room, owner, ids, self:objectName()) end
    end
end)
-- Marker effects persist independently of the grantor's skill/death.
hlxg_lirang_record = gu_record("#hlxg_lirang_record", {sgs.DrawNCards, sgs.CardsMoveOneTime, sgs.EventPhaseChanging}, function(self, event, room, p, data)
    if event == sgs.DrawNCards then
        if p and p:getMark("&hlxg_lirang") > 0 then local draw = data:toDraw(); draw.num = draw.num + 1; data:setValue(draw) end
    elseif event == sgs.EventPhaseChanging then
        if p then p:removeTag("hlxg_lirang_discard") end
    else
        local m = data:toMoveOneTime()
        if not m.from or m.from:getPhase() ~= sgs.Player_Discard or m.from:getMark("&hlxg_lirang") == 0
            or m.to_place ~= sgs.Player_DiscardPile or m.reason.m_reason % 16 ~= sgs.CardMoveReason_S_REASON_DISCARD then return end
        local q = room:findPlayerByObjectName(m.from:objectName())
        if not q then return end
        local ids = q:getTag("hlxg_lirang_discard"):toString()
        for _, id in sgs.qlist(m.card_ids) do ids = ids == "" and tostring(id) or ids .. "+" .. id end
        q:setTag("hlxg_lirang_discard", sgs.QVariant(ids))
    end
end)

hljx_shuomeng = gu_trigger("hljx_shuomeng", {sgs.EventPhaseEnd}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Play then return end
    local candidates = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getAlivePlayers()) do if owner:canPindian(q) then candidates:append(q) end end
    if candidates:isEmpty() then return end
    local q = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hljx_shuomeng", true, true)
    if not q then return end
    local won = owner:pindian(q, self:objectName())
    local source, target = won and owner or q, owner
    if source:isDead() or target:isDead() then return end
    local c = sgs.Sanguosha:cloneCard(won and "ex_nihilo" or "dismantlement", sgs.Card_NoSuit, 0)
    c:setSkillName("_hljx_shuomeng"); c:deleteLater()
    if source:isCardLimited(c, sgs.Card_MethodUse) or source:isProhibited(target, c) then return end
    local use = sgs.CardUseStruct(); use.card = c; use.from = source; use.to:append(target)
    room:useCard(use, false)
end)
hljx_qianya = gu_trigger("hljx_qianya", {sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or not use.card or not use.card:isKindOf("TrickCard") or not use.to:contains(owner) then return end
    local others = room:getOtherPlayers(owner)
    if others:isEmpty() or not gu_invoke(owner, self:objectName(), data) then return end
    local q = room:askForPlayerChosen(owner, others, self:objectName(), "@hljx_qianya", false, true)
    if not owner:isKongcheng() then
        local c = room:askForExchange(owner, self:objectName(), owner:getHandcardNum(), 0, false, "@hljx_qianya-give", true)
        if c then room:giveCard(owner, q, c, self:objectName()); c:deleteLater() end
    end
    if owner:isDead() then return end
    for _, id in sgs.qlist(room:getDrawPile()) do
        if not sgs.Sanguosha:getCard(id):isKindOf("EquipCard") then room:obtainCard(owner, id, false); break end
    end
end)

