-- ==================== c205_05
do
hlxg_sunliang = sgs.General(extension_hl, "hlxg_sunliang", "wu", 3)
hlxg_sunxiu = sgs.General(extension_hl, "hlxg_sunxiu", "wu", 3)
hlxg_sunjian = sgs.General(extension_hl, "hlxg_sunjian", "wu", 4)

hlxg_chezheng = gu_trigger("hlxg_chezheng", {sgs.EventPhaseEnd}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Play then return end
    local n = 0
    for _, q in sgs.qlist(room:getOtherPlayers(owner)) do if not q:inMyAttackRange(owner) then n = n + 1 end end
    owner:drawCards(math.max(2, n), self:objectName())
end, true)
hlxg_chezheng_prohibit = sgs.CreateProhibitSkillV2 {
    name = "#hlxg_chezheng_prohibit", holder_selector = sgs.CorrectSkill_System,
    is_prohibited = function(self, ctx)
        local from, to, card = ctx:getFrom(), ctx:getTo(), ctx:getCard()
        return from and to and card and from ~= to and from:hasSkill("hlxg_chezheng")
            and from:getPhase() == sgs.Player_Play and card:isKindOf("Slash") and not to:inMyAttackRange(from)
    end,
}
hlxg_kuizhuCard = sgs.CreateSkillCard {
    name = "hlxg_kuizhuCard", will_throw = false,
    filter = function(self, targets, to, from)
        local x = from:getMark("hlxg_kuizhu_count")
        if from:getMark("hlxg_kuizhu_damage") == 0 then return #targets < x end
        local total = to:getHp()
        for _, q in ipairs(targets) do total = total + q:getHp() end
        return total <= x
    end,
    feasible = function(self, targets, from)
        if from:getMark("hlxg_kuizhu_damage") == 0 then return #targets <= from:getMark("hlxg_kuizhu_count") end
        local total = 0
        for _, q in ipairs(targets) do total = total + q:getHp() end
        return total <= from:getMark("hlxg_kuizhu_count")
    end,
    on_use = function(self, room, source, targets)
        local damage = source:getMark("hlxg_kuizhu_damage") > 0
        for _, q in ipairs(targets) do
            if q:isAlive() then
                if damage then
                    local d = sgs.DamageStruct(); d.from = source; d.to = q; d.damage = 1; d.reason = "hlxg_kuizhu"; room:damage(d)
                else q:drawCards(1, "hlxg_kuizhu") end
            end
        end
    end,
}
hlxg_kuizhu_vs = sgs.CreateViewAsSkillV2 {
    name = "hlxg_kuizhu",
    can_activate = function(self, request) return request:getPattern() == "@@hlxg_kuizhu" end,
    can_select_card = function() return false end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function() return hlxg_kuizhuCard:clone() end,
}
hlxg_kuizhu = gu_trigger("hlxg_kuizhu", {sgs.EventPhaseEnd}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Discard or not gu_invoke(owner, self:objectName()) then return end
    local choice = room:askForChoice(owner, self:objectName(), "draw+damage")
    room:setPlayerMark(owner, "hlxg_kuizhu_damage", choice == "damage" and 1 or 0)
    room:askForUseCard(owner, "@@hlxg_kuizhu", "@hlxg_kuizhu")
end)
hlxg_kuizhu:setViewAsSkill(hlxg_kuizhu_vs)
hlxg_kuizhu_record = gu_record("#hlxg_kuizhu_record", {sgs.EventPhaseStart, sgs.CardsMoveOneTime}, function(self, event, room, p, data)
    if event == sgs.EventPhaseStart then
        if p:getPhase() == sgs.Player_Discard then room:setPlayerMark(p, "hlxg_kuizhu_count", 0) end
        return
    end
    local move = data:toMoveOneTime()
    if move.from and move.from:getPhase() == sgs.Player_Discard
        and bit32.band(move.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON) == sgs.CardMoveReason_S_REASON_DISCARD then
        local from = room:findPlayerByObjectName(move.from:objectName())
        if from then room:addPlayerMark(from, "hlxg_kuizhu_count", move.card_ids:length()) end
    end
end)
hlxg_lijun = gu_trigger("hlxg_lijun" .. "$", {sgs.CardFinished}, function(self, event, room, p, data, owner)
    local use = data:toCardUse(); local from = use.from
    if not owner:hasLordSkill("hlxg_lijun") or not from or from == owner or from:getKingdom() ~= "wu"
        or from:getPhase() ~= sgs.Player_Play or not use.card or not use.card:isKindOf("Slash")
        or owner:getMark("hlxg_lijun_phase") > 0 then return end
    room:setPlayerMark(owner, "hlxg_lijun_phase", 1)
    owner:drawCards(1, "hlxg_lijun")
    if from:isAlive() and owner:isAlive() and gu_invoke(owner, "hlxg_lijun", sgs.QVariant(from)) then from:drawCards(1, "hlxg_lijun") end
end)
hlxg_lijun_reset = gu_record("#hlxg_lijun_reset", {sgs.EventPhaseChanging}, function(self, event, room, p, data)
    for _, q in sgs.qlist(room:getAllPlayers()) do room:setPlayerMark(q, "hlxg_lijun_phase", 0) end
end)

hlxg_xingxue = gu_trigger("hlxg_xingxue", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Finish then return end
    local targets = room:askForPlayersChosen(owner, room:getAlivePlayers(), "hlxg_xingxue", 0, math.max(0, owner:getMaxHp()), "@hlxg_xingxue", true)
    room:sortByActionOrder(targets)
    for _, q in sgs.qlist(targets) do if q:isAlive() then q:drawCards(1, "hlxg_xingxue") end end
    for _, q in sgs.qlist(targets) do
        if q:isAlive() and not q:isNude() then
            local others = sgs.SPlayerList()
            for _, r in sgs.qlist(targets) do if r ~= q and r:isAlive() then others:append(r) end end
            local choice = room:askForChoice(q, "hlxg_xingxue", others:isEmpty() and "top" or "top+give")
            local card = room:askForExchange(q, "hlxg_xingxue", 1, 1, true, "@hlxg_xingxue-card", false)
            if card then
                if choice == "give" then
                    local to = room:askForPlayerChosen(q, others, "hlxg_xingxue", "@hlxg_xingxue-give", false, true)
                    if to then room:obtainCard(to, card, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_GIVE, q:objectName(), to:objectName(), "hlxg_xingxue", ""), false) end
                else
                    room:moveCardTo(card, q, nil, sgs.Player_DrawPile, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_PUT, q:objectName(), "", "hlxg_xingxue", ""), false)
                end
                card:deleteLater()
            end
        end
    end
end)
hlxg_yanzhu = gu_active("hlxg_yanzhu", 1, 0, 0, gu_one, gu_one_feasible, function(self, room, source, targets)
    local to = targets[1]
    local choices = source:getMark("hlxg_yanzhu_modified") > 0 and "discard" or "discard+equip"
    if room:askForChoice(source, "hlxg_yanzhu", choices, sgs.QVariant(to)) == "equip" then
        gu_obtain(room, source, gu_ids(sgs.QList2Table(to:getEquips())), "hlxg_yanzhu")
        room:setPlayerMark(source, "hlxg_yanzhu_modified", 1)
        room:changeTranslation(source, "hlxg_yanzhu", 1)
    else
        room:askForDiscard(to, "hlxg_yanzhu", 1, 1, false, true)
        room:addPlayerMark(to, "&hlxg_yanzhu")
    end
end)
hlxg_yanzhu_record = gu_record("#hlxg_yanzhu_record", {sgs.DamageInflicted, sgs.TurnStart}, function(self, event, room, p, data)
    if not p or p:getMark("&hlxg_yanzhu") == 0 then return end
    if event == sgs.DamageInflicted then
        local d = data:toDamage(); d.damage = d.damage + p:getMark("&hlxg_yanzhu"); data:setValue(d)
    end
    room:setPlayerMark(p, "&hlxg_yanzhu", 0)
end)
hlxg_zhaofuCard = sgs.CreateSkillCard {
    name = "hlxg_zhaofuCard", will_throw = false,
    filter = function(self, targets, to, from) return #targets < 2 end,
    feasible = function(self, targets) return #targets <= 2 end,
    on_use = function(self, room, source, targets)
        for _, q in ipairs(targets) do
            local kingdoms = q:property("inMyAttackRangeKingdoms"):toString()
            if not kingdoms:find("wu", 1, true) then
                room:setPlayerMark(q, "hlxg_zhaofu_added", 1)
                room:setPlayerProperty(q, "inMyAttackRangeKingdoms", sgs.QVariant(kingdoms .. "+wu"))
            end
        end
    end,
}
hlxg_zhaofu = sgs.CreateViewAsSkillV2 {
    name = "hlxg_zhaofu" .. "$", limit_scope = sgs.Skill_Limit_Phase, phase_name = "Play", max_usage_limit = 1,
    can_activate = function(self, request)
        return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY and request:getInitiator():hasLordSkill("hlxg_zhaofu")
    end,
    can_select_card = function() return false end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function() local c = hlxg_zhaofuCard:clone(); c:setSkillName("hlxg_zhaofu"); return c end,
}
hlxg_zhaofu_reset = gu_record("#hlxg_zhaofu_reset", {sgs.RoundEnd}, function(self, event, room, p, data)
    for _, q in sgs.qlist(room:getAllPlayers()) do
        if q:getMark("hlxg_zhaofu_added") > 0 then
            room:setPlayerProperty(q, "inMyAttackRangeKingdoms", sgs.QVariant(q:property("inMyAttackRangeKingdoms"):toString():gsub("%+wu", "")))
            room:setPlayerMark(q, "hlxg_zhaofu_added", 0)
        end
    end
end)
hlxg_yinghun_sunjian = gu_trigger("hlxg_yinghun_sunjian", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Start then return end
    local to = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@hlxg_yinghun_sunjian", true, true)
    if not to then return end
    local x = owner:getLostHp()
    to:drawCards(1, self:objectName())
    if to:isAlive() and x > 0 then room:askForDiscard(to, self:objectName(), x, x, false, true) end
end)
hlxg_sunliang:addSkill(hlxg_chezheng); hlxg_sunliang:addSkill(hlxg_chezheng_prohibit)
hlxg_sunliang:addSkill(hlxg_kuizhu); hlxg_sunliang:addSkill(hlxg_kuizhu_record)
hlxg_sunliang:addSkill(hlxg_lijun); hlxg_sunliang:addSkill(hlxg_lijun_reset)
hlxg_sunxiu:addSkill(hlxg_xingxue); hlxg_sunxiu:addSkill(hlxg_yanzhu); hlxg_sunxiu:addSkill(hlxg_yanzhu_record)
hlxg_sunxiu:addSkill(hlxg_zhaofu); hlxg_sunxiu:addSkill(hlxg_zhaofu_reset)
hlxg_sunjian:addSkill(hlxg_yinghun_sunjian)
extension_hl:insertRelatedSkills("hlxg_chezheng", "#hlxg_chezheng_prohibit")
extension_hl:insertRelatedSkills("hlxg_kuizhu", "#hlxg_kuizhu_record")
extension_hl:insertRelatedSkills("hlxg_lijun", "#hlxg_lijun_reset")
extension_hl:insertRelatedSkills("hlxg_yanzhu", "#hlxg_yanzhu_record")
extension_hl:insertRelatedSkills("hlxg_zhaofu", "#hlxg_zhaofu_reset")
