-- ==================== c205_06
do
-- c205_06: literal current excerpt; acquired skills are registered separately.
hljx_sunjian = sgs.General(extension_hl, "hljx_sunjian", "wu", 4)
hlxg_sunhanhua = sgs.General(extension_hl, "hlxg_sunhanhua", "wu", 3, false)

hljx_wulie = gu_trigger("hljx_wulie", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:getPhase() ~= sgs.Player_RoundStart or owner:getMark("@hljx_wulie") == 0
        or not gu_invoke(owner, self:objectName(), data) then return end
    -- Repeated increment choices avoid imposing an unstated HP-based upper bound.
    local n = 0
    while room:askForChoice(owner, self:objectName(), "more+done", sgs.QVariant(n)) == "more" do n = n + 1 end
    room:removePlayerMark(owner, "@hljx_wulie")
    if n > 0 then room:loseHp(owner, n, true, nil, self:objectName()) end
    room:addPlayerMark(owner, "&hljx_wulie_lie", n)
    if owner:isDead() or n == 0 then return end
    local targets = room:askForPlayersChosen(owner, room:getOtherPlayers(owner), self:objectName(), 0, n, "@hljx_wulie-give", true)
    for _, q in sgs.qlist(targets) do room:addPlayerMark(q, "&hljx_wulie_lie", 1) end
end, false, sgs.Skill_Limited, "@hljx_wulie")
hljx_wulie_prevent = sgs.CreateRuleSkillV2 {
    name = "#hljx_wulie_prevent", global = true, events = {sgs.DamageInflicted},
    can_trigger = function(self, event, room, p, data)
        if p and p:getMark("&hljx_wulie_lie") > 0 then return self:objectName(), p end
        return false
    end,
    on_cost = function(self, event, room, p, ctx)
        return gu_invoke(p, "hljx_wulie_prevent", ctx.original_data)
    end,
    on_effect = function(self, event, room, p, ctx)
        room:removePlayerMark(p, "&hljx_wulie_lie")
        return true
    end,
}
hljx_yinghun_sunjian = gu_trigger("hljx_yinghun_sunjian", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Start then return end
    local q = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@hljx_yinghun_sunjian", true, true)
    if not q then return end
    local x = owner:getLostHp()
    if room:askForChoice(owner, self:objectName(), "draw+discard", sgs.QVariant(q)) == "draw" then
        if x > 0 then q:drawCards(x, self:objectName()) end
    else
        q:drawCards(1, self:objectName())
        if x > 0 and q:isAlive() then room:askForDiscard(q, self:objectName(), x, x, false, true) end
    end
end)
