local function c205_06_colors(room)
    local red, black = 0, 0
    for _, id in sgs.qlist(room:getDiscardPile()) do
        local c = sgs.Sanguosha:getCard(id)
        if c:isRed() then red = red + 1 elseif c:isBlack() then black = black + 1 end
    end
    return red, black
end
local function c205_06_discard(room, owner, skill, optional, zone)
    local list = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getOtherPlayers(owner)) do
        if owner:canDiscard(q, zone) then list:append(q) end
    end
    if list:isEmpty() then return end
    local q = room:askForPlayerChosen(owner, list, skill, "@" .. skill .. "-discard", optional, true)
    if q then
        local id = room:askForCardChosen(owner, q, zone, skill, false, sgs.Card_MethodDiscard)
        room:throwCard(id, skill, q, owner)
    end
end
hlxg_huiling = gu_trigger("hlxg_huiling", {sgs.CardUsed, sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    local card
    if event == sgs.CardUsed then
        if p ~= owner then return end
        card = data:toCardUse().card
        if not card then return end
    else
        local move = data:toMoveOneTime()
        if move.from ~= owner or move.card_ids:isEmpty() or move.to_place ~= sgs.Player_DiscardPile
            or bit32.band(move.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON) ~= sgs.CardMoveReason_S_REASON_DISCARD then return end
    end
    -- Snapshot both comparisons before recovery/discard can change the pile.
    local red, black = c205_06_colors(room)
    local gain = card and ((card:isRed() and red < black) or (card:isBlack() and black < red))
    if red > black then
        local recover = sgs.RecoverStruct(); recover.who = owner; recover.recover = 1
        room:recover(owner, recover)
    elseif black > red then
        c205_06_discard(room, owner, self:objectName(), true, "hej")
    end
    if gain then room:addPlayerMark(owner, "&hlxg_huiling_ling") end
end, true)
local function c205_06_taji_effect(room, owner, mode)
    if owner:isDead() then return end
    if mode == 1 then c205_06_discard(room, owner, "hlxg_taji", false, "he")
    elseif mode == 2 then owner:drawCards(1, "hlxg_taji")
    elseif mode == 3 then
        local recover = sgs.RecoverStruct(); recover.who = owner; recover.recover = 1
        room:recover(owner, recover)
    else room:addPlayerMark(owner, "&hlxg_taji_damage") end
end
hlxg_taji = gu_trigger("hlxg_taji", {sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    local move = data:toMoveOneTime()
    if move.from ~= owner or not move.from_places:contains(sgs.Player_PlaceHand) then return end
    if not gu_invoke(owner, self:objectName(), data) then return end
    local reason = bit32.band(move.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON)
    local mode = reason == sgs.CardMoveReason_S_REASON_USE and 1
        or reason == sgs.CardMoveReason_S_REASON_RESPONSE and 2
        or reason == sgs.CardMoveReason_S_REASON_DISCARD and 3 or 4
    c205_06_taji_effect(room, owner, mode)
    if owner:isAlive() and owner:getMark("hlxg_qinghuang-Clear") > 0 then
        local choices = {}; for i = 1, 4 do if i ~= mode then table.insert(choices, i) end end
        c205_06_taji_effect(room, owner, choices[math.random(#choices)])
    end
end)
hlxg_taji_damage = sgs.CreateRuleSkillV2 {
    name = "#hlxg_taji_damage", global = true, frequency = sgs.Skill_Compulsory,
    events = {sgs.DamageCaused, sgs.Damage},
    can_trigger = function(self, event, room, p, data)
        local d = data:toDamage()
        if d.from and d.to and d.from ~= d.to and d.from:getMark("&hlxg_taji_damage") > 0 then
            return self:objectName(), d.from
        end
        return false
    end,
    on_effect = function(self, event, room, p, ctx)
        local d = ctx.original_data:toDamage()
        if event == sgs.DamageCaused then
            d.damage = d.damage + d.from:getMark("&hlxg_taji_damage")
            ctx.original_data:setValue(d)
        else
            -- A prevented damage does not consume "next damage" bonuses.
            room:setPlayerMark(d.from, "&hlxg_taji_damage", 0)
        end
    end,
}
hlxg_qinghuang = gu_trigger("hlxg_qinghuang", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Play or p:getMaxHp() <= 1
        or not gu_invoke(owner, self:objectName(), data) then return end
    room:loseMaxHp(owner, 1, self:objectName())
    room:setPlayerMark(owner, "hlxg_qinghuang-Clear", 1)
end)
hlxg_chongxuCard = sgs.CreateSkillCard {
    name = "hlxg_chongxuCard", target_fixed = true,
    on_use = function(self, room, source, targets)
        local x = math.min(source:getMark("&hlxg_huiling_ling"), room:getAllPlayers(true):length())
        room:removePlayerMark(source, "@hlxg_chongxu")
        room:detachSkillFromPlayer(source, "hlxg_huiling")
        room:gainMaxHp(source, x, "hlxg_chongxu")
        room:handleAcquireDetachSkills(source, "hlxg_taji|hlxg_qinghuang")
    end,
}
hlxg_chongxu = sgs.CreateViewAsSkillV2 {
