-- ==================== c206_01
do
-- c206_01: independent Sun Shangxiang variants.
local function c206_xiaoji(name)
    return gu_trigger(name, {sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
        local move = data:toMoveOneTime()
        if not move.from or move.from:objectName() ~= owner:objectName() then return end
        for _, place in sgs.qlist(move.from_places) do
            if place == sgs.Player_PlaceEquip and owner:isAlive() and gu_invoke(owner, name, data) then
                owner:drawCards(2, name)
            end
        end
    end)
end
local function c206_recover(room, who, source)
    local recover = sgs.RecoverStruct(); recover.who = source; recover.recover = 1
    room:recover(who, recover)
end
local function c206_gift(name, male, extra)
    local card = sgs.CreateSkillCard {
        name = name .. "Card", will_throw = false,
        filter = function(self, targets, to, from)
            if not gu_one(self, targets, to, from) or (male and not to:isMale()) then return false end
            local id = self:getSubcards():first()
            local c = sgs.Sanguosha:getCard(id)
            return from:getRoom():getCardPlace(id) == sgs.Player_PlaceHand
                or (c:isKindOf("EquipCard") and to:hasEquipArea(c:toEquipCard():location()))
        end, feasible = gu_one_feasible,
        on_use = function(self, room, source, targets)
            local target = targets[1]
            local id = self:getSubcards():first()
            local card = sgs.Sanguosha:getCard(id)
            local hand = room:getCardPlace(id) == sgs.Player_PlaceHand
            local equip = card:isKindOf("EquipCard") and target:hasEquipArea(card:toEquipCard():location())
            local mode = hand and (equip and room:askForChoice(source, name, "give+equip", sgs.QVariant(target)) or "give") or "equip"
            if mode == "give" then
                room:obtainCard(target, card, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_GIVE, source:objectName(), target:objectName(), name, ""), false)
            else
                local old = target:getEquip(card:toEquipCard():location())
                local moves = sgs.CardsMoveList()
                if old then
                    moves:append(sgs.CardsMoveStruct(old:getEffectiveId(), target, nil, sgs.Player_PlaceEquip, sgs.Player_DiscardPile,
                        sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_CHANGE_EQUIP, target:objectName(), name, "")))
                end
                moves:append(sgs.CardsMoveStruct(id, source, target, room:getCardPlace(id), sgs.Player_PlaceEquip,
                    sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_PUT, source:objectName(), target:objectName(), name, "")))
                room:moveCardsAtomic(moves, true)
            end
            if source:isAlive() then c206_recover(room, source, source) end
            if extra and source:isAlive() then
                source:drawCards(1, name)
                if target:isAlive() and gu_invoke(source, name, sgs.QVariant(target)) then
                    if target:getHp() < source:getHp() then c206_recover(room, target, source)
                    else target:drawCards(1, name) end
                end
            end
        end,
    }
    _G[name .. "Card"] = card
    return sgs.CreateViewAsSkillV2 {
        name = name, n = 1, limit_scope = sgs.Skill_Limit_Phase, phase_name = "Play", max_usage_limit = 1,
        can_activate = function(self, request) return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY end,
        can_select_card = function(self, request, c)
            local room = sgs.Sanguosha:currentRoom()
            if not room then return false end
            return request:getSelectedCardIds():isEmpty()
                and (room:getCardPlace(c:getEffectiveId()) == sgs.Player_PlaceHand or c:isKindOf("EquipCard"))
        end,
        card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
        create_card = function(self, request)
            local result = card:clone(); result:addSubcards(request:getSelectedCardIds()); result:setSkillName(name); return result
        end,
    }
end
