hlxg_wujian_sunshangxiang2 = sgs.CreateViewAsSkillV2 {
    name = "hlxg_wujian_sunshangxiang2", n = 1,
    can_activate = function(self, request)
        return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
    end,
    can_select_card = function(self, request, c)
        local p = request:getInitiator()
        local room = sgs.Sanguosha:currentRoom()
        if not room then return false end
        return request:getSelectedCardIds():isEmpty() and c:isKindOf("EquipCard")
            and room:getCardPlace(c:getEffectiveId()) == sgs.Player_PlaceEquip
            and p:getMark("hlxg_wujian_sunshangxiang2_" .. c:toEquipCard():location() .. "-PlayClear") == 0
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        local original = sgs.Sanguosha:getCard(request:getSelectedCardIds():first())
        local slash = sgs.Sanguosha:cloneCard("slash", original:getSuit(), original:getNumber())
        slash:addSubcard(original); slash:setSkillName(self:objectName()); return slash
    end,
}
