local function hl02_recover(room, p, who, skill)
    local r = sgs.RecoverStruct(); r.who = who; r.recover = 1; r.reason = skill
    room:recover(p, r)
end
local function hl02_marked(from, targets, to)
    return #targets == 0 and to ~= from and to:getMark("&hlxg_jieyin_sunshangxiang3") > 0
end
