hlxg_xiaoji_sunshangxiang3 = gu_trigger("hlxg_xiaoji_sunshangxiang3", {sgs.CardsMoveOneTime}, function(self, event, room, player, data, p)
    local move = data:toMoveOneTime()
    if not move.from or move.from:objectName() ~= p:objectName() then return end
    local count = 0
    for _, place in sgs.qlist(move.from_places) do if place == sgs.Player_PlaceEquip then count = count + 1 end end
    for i = 1, count do
        if not p:isAlive() then break end
        p:drawCards(2, self:objectName())
        local candidates = sgs.SPlayerList()
        for _, q in sgs.qlist(room:getAlivePlayers()) do if p:canDiscard(q, "ej") then candidates:append(q) end end
        if not candidates:isEmpty() then
            local q = room:askForPlayerChosen(p, candidates, self:objectName(), "@hlxg_xiaoji_sunshangxiang3", true, true)
            if q then local id = room:askForCardChosen(p, q, "ej", self:objectName(), false, sgs.Card_MethodDiscard); room:throwCard(id, q, p) end
        end
    end
end, true)
