    end, function(request, c)
        local p = request:getInitiator()
        return p:handCards():contains(c:getEffectiveId()) or c:isEquipped()
    end)
hlxg_jieyin_sunshangxiang3_record = gu_trigger("#hlxg_jieyin_sunshangxiang3_record", {sgs.GameStart, sgs.Death}, function(self, event, room, player, data, p)
