local function hl02_zhiheng(name, enhanced)
    return gu_active(name, nil, 0, math.huge, function() return false end, function(self, targets) return #targets == 0 end,
        function(self, room, p, targets)
            local ids = self:getSubcards(); local all = not p:isKongcheng()
            for _, id in sgs.qlist(p:handCards()) do if not ids:contains(id) then all = false end end
            room:addPlayerMark(p, name .. "_used-PlayClear")
            local nth = p:getMark(name .. "_used-PlayClear")
            gu_throw(room, p, ids, name)
            local drawn = room:drawCardsList(p, ids:length() + (all and 1 or 0), name)
            if enhanced and nth <= 2 then
                local ok = true
                for _, id in sgs.qlist(drawn) do
                    local c = sgs.Sanguosha:getCard(id)
                    if (nth == 1 and c:isKindOf("DelayedTrick")) or (nth == 2 and not c:isKindOf("BasicCard")) then ok = false end
                end
                if ok then room:addPlayerMark(p, name .. "_extra-PlayClear") end
            end
        end, function(request, c) return not request:getInitiator():isJilei(c) end,
        function(p) return p:getMark(name .. "_used-PlayClear") < 1 + p:getMark(name .. "_extra-PlayClear") end)
end
local function hl02_jiuyuan(name, enhanced)
    return gu_trigger(name .. "$", {sgs.PreHpRecover}, function(self, event, room, p, data, lord)
        if not p or not lord:hasLordSkill(name) then return end
        local r = data:toRecover()
        if p == lord and r.card and r.card:isKindOf("Peach") and r.who and r.who ~= lord and r.who:getKingdom() == "wu" then
            r.recover = r.recover + 1; data:setValue(r)
        elseif p ~= lord and p:getKingdom() == "wu" and ((enhanced and p:getPhase() ~= sgs.Player_NotActive) or (not enhanced and r.card and r.card:isKindOf("Peach") and r.who == p)) then
            if gu_invoke(p, name, sgs.QVariant(lord)) then
                hl02_recover(room, lord, p, name); p:drawCards(1, name); return true
            end
        end
    end, true)
end
