-- ==================== c206_03
do
-- c206_03: literal 欢乐 variants.
hljx_sundeng = sgs.General(extension_hl, "hljx_sundeng", "wu", 4)
hljx_kuangbi = gu_active("hljx_kuangbi", 1, 0, 0,
    function(self, targets, to, from) return gu_one(self, targets, to, from) and not to:isNude() end,
    gu_one_feasible,
    function(self, room, source, targets)
        local to = targets[1]
        local cards = room:askForExchange(to, "hljx_kuangbi", 3, 0, true, "@hljx_kuangbi-put", false)
        if not cards then return end
        local n = cards:subcardsLength()
        source:addToPile("hljx_kuangbi", cards, true)
        cards:deleteLater()
        if gu_invoke(source, "hljx_kuangbi", sgs.QVariant(to:objectName())) then
            room:setPlayerMark(source, "hljx_kuangbi_pending", 1)
            to:drawCards(n, "hljx_kuangbi")
        end
    end)
hljx_kuangbi_return = gu_trigger("#hljx_kuangbi_return", {sgs.TurnStart, sgs.CardsMoveOneTime, sgs.EventPhaseChanging},
    function(self, event, room, p, data, owner)
        if event == sgs.TurnStart and p == owner then
            if owner:getMark("hljx_kuangbi_pending") == 0 then return end
            room:setPlayerMark(owner, "hljx_kuangbi_pending", 0)
            local ids = owner:getPile("hljx_kuangbi")
            if ids:isEmpty() then return end
            -- Record before obtaining so nested moves cannot confuse the batch.
            local names = {}
            for _, id in sgs.qlist(ids) do table.insert(names, tostring(id)) end
            gu_setnames(owner, "hljx_kuangbi_obtained", names)
            gu_obtain(room, owner, ids, "hljx_kuangbi")
        elseif event == sgs.EventPhaseChanging and p == owner and data:toPhaseChange().to == sgs.Player_NotActive then
            owner:removeTag("hljx_kuangbi_obtained")
        elseif event == sgs.CardsMoveOneTime then
            local move = data:toMoveOneTime()
            if not move.from or move.from:objectName() ~= owner:objectName() then return end
            local tracked = gu_names(owner, "hljx_kuangbi_obtained")
            if #tracked == 0 then return end
            local remaining = {}
            for _, id in ipairs(tracked) do
                local n = tonumber(id)
                local holder = room:getCardOwner(n)
                local place = room:getCardPlace(n)
                if holder and holder:objectName() == owner:objectName()
                    and (place == sgs.Player_PlaceHand or place == sgs.Player_PlaceEquip) then table.insert(remaining, id) end
            end
            gu_setnames(owner, "hljx_kuangbi_obtained", remaining)
            if #remaining == 0 and owner:isAlive() then
                owner:drawCards(2, "hljx_kuangbi")
                local recover = sgs.RecoverStruct(); recover.who = owner; recover.recover = 1
                room:recover(owner, recover)
            end
        end
    end, true)
hljx_sundeng:addSkill(hljx_kuangbi); hljx_sundeng:addSkill(hljx_kuangbi_return)
extension_hl:insertRelatedSkills("hljx_kuangbi", "#hljx_kuangbi_return")

hlxg_sunhao = sgs.General(extension_hl, "hlxg_sunhao" .. "$", "wu", 5)
hlxg_chouhai = gu_trigger("hlxg_chouhai", {sgs.DamageInflicted}, function(self, event, room, p, data, owner)
    local damage = data:toDamage()
    if p == owner and owner:isNude() and damage.card and damage.card:isKindOf("Slash") then
        damage.damage = damage.damage + 1; data:setValue(damage)
    end
end, true)
hlxg_guiming = gu_trigger("hlxg_guiming" .. "$", {sgs.GameStart}, function() end, true)
hlxg_canshi_sunhao = gu_trigger("hlxg_canshi_sunhao", {sgs.DrawNCards, sgs.CardUsed}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.DrawNCards then
        local draw = data:toDraw()
        if draw.reason ~= "draw_phase" or not gu_invoke(owner, "hlxg_canshi_sunhao", data) then return end
        local x = 0
        for _, q in sgs.qlist(room:getAlivePlayers()) do
            if q:isWounded() or (owner:hasLordSkill("hlxg_guiming") and q:getKingdom() == "wu") then x = x + 1 end
        end
        draw.num = draw.num + x; data:setValue(draw)
        room:setPlayerMark(owner, "hlxg_canshi_sunhao-Clear", 1)
    else
        local use = data:toCardUse()
        if owner:getMark("hlxg_canshi_sunhao-Clear") > 0 and use.card and use.card:isKindOf("Slash") then
            room:askForDiscard(owner, "hlxg_canshi_sunhao", 1, 1, false, true)
        end
    end
end)
hlxg_sunhao:addSkill(hlxg_chouhai); hlxg_sunhao:addSkill(hlxg_guiming); hlxg_sunhao:addSkill(hlxg_canshi_sunhao)

