do
-- c206_05: literal 欢乐 variants.
hlxg_sunluyu = sgs.General(extension_hl, "hlxg_sunluyu", "wu", 3, false)
hlxg_menghuo = sgs.General(extension_hl, "hlxg_menghuo", "shu", 4)
hljx_menghuo = sgs.General(extension_hl, "hljx_menghuo", "shu", 4)

hlxg_zhixi = gu_trigger("hlxg_zhixi", {sgs.CardUsed}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or owner:getPhase() ~= sgs.Player_Play or not use.card
        or not (use.card:isKindOf("Slash") or use.card:isKindOf("TrickCard")) then return end
    local discarded = room:askForDiscard(owner, self:objectName(), 1, 1, false, false)
    if not discarded then return end
    for _, name in ipairs(gu_names(owner, "hlxg_meibu_receivers")) do
        local receiver = room:findPlayerByObjectName(name)
        if receiver and receiver:isAlive() then
            local ids = sgs.IntList()
            for _, id in sgs.qlist(discarded:getSubcards()) do
                if room:getCardPlace(id) == sgs.Player_DiscardPile then ids:append(id) end
            end
            gu_obtain(room, receiver, ids, "hlxg_meibu")
        end
    end
end, true)
hlxg_mumu = gu_trigger("hlxg_mumu", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Play then return end
    local candidates = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getOtherPlayers(owner)) do
        if not q:getEquips():isEmpty() then candidates:append(q) end
    end
    if candidates:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_mumu", true, true)
    if not to then return end
    local choices = "obtain"
    if owner:canDiscard(to, "e") then choices = "discard+obtain" end
    local choice = room:askForChoice(owner, self:objectName(), choices)
    local method = choice == "discard" and sgs.Card_MethodDiscard or sgs.Card_MethodNone
    local id = room:askForCardChosen(owner, to, "e", self:objectName(), false, method)
    if choice == "discard" then
        room:throwCard(sgs.Sanguosha:getCard(id), self:objectName(), to, owner)
        room:addPlayerMark(owner, "hlxg_mumu_plus-Clear")
    else
        room:obtainCard(owner, id, false)
        room:addPlayerMark(owner, "hlxg_mumu_minus-Clear")
    end
end)
