local function c206_05_reveal(room, owner, n, skill)
    if n <= 0 then return end
    local ids = room:getNCards(n, false)
    room:fillAG(ids)
    local hearts, rest = sgs.IntList(), sgs.IntList()
    for _, id in sgs.qlist(ids) do
        if sgs.Sanguosha:getCard(id):getSuit() == sgs.Card_Heart then hearts:append(id)
        else rest:append(id) end
    end
    gu_throw(room, nil, hearts, skill)
    if not hearts:isEmpty() then
        local recover = sgs.RecoverStruct(); recover.who = owner; recover.recover = hearts:length()
        room:recover(owner, recover)
    end
    gu_obtain(room, owner, rest, skill)
    room:clearAG()
end
local function c206_05_zaiqi(name, enhanced)
    return gu_trigger(name, {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
        if p ~= owner then return end
        local draw = p:getPhase() == sgs.Player_Draw and p:isWounded()
        local finish = enhanced and p:getPhase() == sgs.Player_Finish
        if not draw and not finish then return end
        if not gu_invoke(owner, self:objectName(), data) then return end
        c206_05_reveal(room, owner, draw and owner:getLostHp() or owner:getMark("hljx_zaiqi_damage-Clear"), self:objectName())
        return draw
    end)
end
