local function c206_05_huoshou(name, enhanced)
    return gu_trigger(name, {sgs.CardEffected, sgs.TargetSpecified, sgs.EventPhaseStart, sgs.CardUsed}, function(self, event, room, p, data, owner)
        if event == sgs.CardEffected then
            local effect = data:toCardEffect()
            if effect.to == owner and effect.card and effect.card:isKindOf("SavageAssault") then
                effect.nullified = true; data:setValue(effect)
            end
        elseif event == sgs.TargetSpecified then
            local use = data:toCardUse()
            if p ~= use.from or not use.card or not use.card:isKindOf("SavageAssault") or use.from == owner then return end
            use.card:setTag("c206_05_huoshou_source", sgs.QVariant(owner:objectName()))
            owner:drawCards(1, self:objectName())
        elseif enhanced and event == sgs.EventPhaseStart and p == owner and p:getPhase() == sgs.Player_Play then
            local ids = {}
            for _, id in sgs.qlist(room:getDiscardPile()) do
                if sgs.Sanguosha:getCard(id):isKindOf("SavageAssault") then table.insert(ids, id) end
            end
            if #ids > 0 then room:obtainCard(owner, ids[math.random(#ids)], false) end
        elseif enhanced and event == sgs.CardUsed and p == owner and p:getPhase() == sgs.Player_Play then
            local use = data:toCardUse()
            if use.card and use.card:isKindOf("SavageAssault") then
                room:setPlayerCardLimitation(owner, "use", "SavageAssault", false, "hljx_huoshou")
            end
        end
    end, true)
end
hlxg_huoshou_menghuo = c206_05_huoshou("hlxg_huoshou_menghuo", false)
