-- c206_06: discard history is recorded even while Panqin is absent.
local function c20606_item(room, p, i)
    if i == 1 then
        if not p:hasSkill("hlxg_panqin") then room:acquireSkill(p, "hlxg_panqin") end
    elseif i == 2 then p:drawCards(1, "hlxg_manwang")
    elseif i == 3 then room:recover(p, sgs.RecoverStruct(p, nil, 1, "hlxg_manwang"))
    elseif i == 4 then
        p:drawCards(2, "hlxg_manwang")
        room:detachSkillFromPlayer(p, "hlxg_panqin")
    end
end
hlxg_panqin = gu_trigger("hlxg_panqin", {sgs.EventPhaseEnd, sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.TargetSpecified then
        local use = data:toCardUse()
        if use.card and use.card:getSkillName() == self:objectName() and use.to:length() >= use.card:subcardsLength() then
            local n = owner:getMark("hlxg_manwang_removed")
            if n < 4 then
                room:setPlayerMark(owner, "hlxg_manwang_removed", n + 1)
                c20606_item(room, owner, 4 - n)
            end
        end
        return
    end
    if p:getPhase() ~= sgs.Player_Play and p:getPhase() ~= sgs.Player_Discard then return end
    local ids = sgs.IntList()
    for id in string.gmatch(p:getTag("hlxg_panqin_ids"):toString(), "%d+") do
        id = tonumber(id)
        if room:getCardPlace(id) == sgs.Player_DiscardPile then ids:append(id) end
    end
    if ids:isEmpty() then return end
    local card = sgs.Sanguosha:cloneCard("savage_assault", sgs.Card_NoSuit, 0)
    card:addSubcards(ids); card:setSkillName(self:objectName()); card:deleteLater()
    if p:canUse(card) and gu_invoke(p, self:objectName(), data) then
        room:useCard(sgs.CardUseStruct(card, p, sgs.SPlayerList()), true)
    end
end)
hlxg_manwang = gu_active("hlxg_manwang", nil, 0, 999, function() return false end,
    function(self, targets) return #targets == 0 end,
    function(self, room, source, targets)
        local n = self:subcardsLength()
        local last = 4 - source:getMark("hlxg_manwang_removed")
        gu_throw(room, source, self:getSubcards(), "hlxg_manwang")
        for i = 1, math.min(n, last) do
            if source:isDead() then break end
            c20606_item(room, source, i)
        end
        if source:isAlive() and not source:hasSkill("hlxg_huoshou_menghuo2") then
            room:setPlayerMark(source, "hlxg_manwang_temporary", 1)
            room:acquireSkill(source, "hlxg_huoshou_menghuo2")
        end
    end,
    function(request, c) return not request:getInitiator():isJilei(c) end)
