    if event == sgs.CardEffected then
        local effect = data:toCardEffect()
        if effect.to == owner and effect.card and effect.card:isKindOf("SavageAssault") then return true end
    else
        local use = data:toCardUse()
        if use.from == p and use.from ~= owner and use.card and use.card:isKindOf("SavageAssault") then
            use.card:setTag("hlxg_huoshou_source", sgs.QVariant(owner:objectName()))
            owner:drawCards(1, self:objectName())
