end, true)
local c20606_record = gu_record("#hlxg_panqin_record", {sgs.CardsMoveOneTime, sgs.EventPhaseChanging, sgs.ConfirmDamage, sgs.CardFinished}, function(self, event, room, p, data)
    if event == sgs.CardsMoveOneTime then
        local move = data:toMoveOneTime()
        if not move.from or (move.from:getPhase() ~= sgs.Player_Play and move.from:getPhase() ~= sgs.Player_Discard)
            or bit32.band(move.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON) ~= sgs.CardMoveReason_S_REASON_DISCARD then return end
        local from = room:findPlayerByObjectName(move.from:objectName())
        if not from then return end
        local text = from:getTag("hlxg_panqin_ids"):toString()
        for _, id in sgs.qlist(move.card_ids) do
            if not string.find("," .. text .. ",", "," .. id .. ",", 1, true) then text = text == "" and tostring(id) or text .. "," .. id end
        end
        from:setTag("hlxg_panqin_ids", sgs.QVariant(text))
    elseif event == sgs.EventPhaseChanging and p then
        p:removeTag("hlxg_panqin_ids")
        if data:toPhaseChange().to == sgs.Player_RoundStart and p:getMark("hlxg_manwang_temporary") > 0 then
            room:setPlayerMark(p, "hlxg_manwang_temporary", 0)
            room:detachSkillFromPlayer(p, "hlxg_huoshou_menghuo2")
        end
    elseif event == sgs.ConfirmDamage then
        local d = data:toDamage()
        if d.card and d.card:isKindOf("SavageAssault") then
            local name = d.card:getTag("hlxg_huoshou_source"):toString()
            if name ~= "" then d.from = room:findPlayerByObjectName(name); data:setValue(d) end
        end
    elseif event == sgs.CardFinished then
        local use = data:toCardUse()
        if use.card then use.card:removeTag("hlxg_huoshou_source") end
    end
end)
