-- ==================== c207_01
do
-- c207_01: literal Huanle variants.
hlxg_yinfuren = sgs.General(extension_hl, "hlxg_yinfuren", "wei", 3, false)
hlxg_yingyu = gu_trigger("hlxg_yingyu", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or (p:getPhase() ~= sgs.Player_Start and
        not (p:getPhase() == sgs.Player_Finish and p:getMark("hlxg_yongbi_used") > 0)) then return end
    local candidates = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getAlivePlayers()) do if not q:isKongcheng() then candidates:append(q) end end
    if candidates:length() < 2 or not gu_invoke(owner, self:objectName()) then return end
    local a = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_yingyu-first", false)
    candidates:removeOne(a)
    local b = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_yingyu-second", false)
    local ca = room:askForCardChosen(owner, a, "h", self:objectName())
    local cb = room:askForCardChosen(owner, b, "h", self:objectName())
    room:showCard(a, ca); room:showCard(b, cb)
    if sgs.Sanguosha:getCard(ca):getSuit() == sgs.Sanguosha:getCard(cb):getSuit() then return end
    local pair = sgs.SPlayerList(); pair:append(a); pair:append(b)
    local recipient = room:askForPlayerChosen(owner, pair, self:objectName(), "@hlxg_yingyu-get", false)
    local id = recipient == a and cb or ca
    local giver = recipient == a and b or a
    if recipient:isAlive() and room:getCardOwner(id) == giver and room:getCardPlace(id) == sgs.Player_PlaceHand then
        room:obtainCard(recipient, id, false)
    end
end)
hlxg_yongbiCard = sgs.CreateSkillCard {
    name = "hlxg_yongbiCard", will_throw = false, filter = gu_one, feasible = gu_one_feasible,
    on_use = function(self, room, source, targets)
        if source:getMark("@hlxg_yongbi") == 0 then return end
        room:removePlayerMark(source, "@hlxg_yongbi")
        room:setPlayerMark(source, "hlxg_yongbi_used", 1)
        local suits, n = {}, 0
        for _, id in sgs.qlist(self:getSubcards()) do
            local suit = sgs.Sanguosha:getCard(id):getSuit()
            if not suits[suit] then suits[suit] = true; n = n + 1 end
        end
        local to = targets[1]
        if not self:getSubcards():isEmpty() then room:obtainCard(to, self, false) end
        for _, q in ipairs({source, to}) do
            if n >= 2 then room:addPlayerMark(q, "&hlxg_yongbi_max", 2) end
            if n >= 3 then room:setPlayerMark(q, "&hlxg_yongbi_guard", 1) end
        end
    end,
}
hlxg_yongbi = sgs.CreateViewAsSkillV2 {
    name = "hlxg_yongbi", frequency = sgs.Skill_Limited, limit_mark = "@hlxg_yongbi",
    can_activate = function(self, request)
        return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
            and request:getInitiator():getMark("@hlxg_yongbi") > 0
    end,
    can_select_card = function(self, request, c) return not c:isEquipped() end,
    card_selection_feasible = function() return true end,
    create_card = function(self, request)
        local c = hlxg_yongbiCard:clone(); c:addSubcards(request:getSelectedCardIds())
        c:setSkillName("hlxg_yongbi"); return c
    end,
}
hlxg_yongbi_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_yongbi_max", holder_selector = sgs.CorrectSkill_System,
