        return 0
    end,
}
hlxg_yongbi_guard = gu_record("#hlxg_yongbi_guard", {sgs.DamageInflicted}, function(self, event, room, p, data)
    if not p or p:getMark("&hlxg_yongbi_guard") == 0 then return end
    local damage = data:toDamage()
