hlxg_xinsheng = gu_trigger("hlxg_xinsheng", {sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner or not gu_invoke(owner, self:objectName(), data) then return end
    local ids = room:getNCards(3, false)
    room:moveCardsAtomic(sgs.CardsMoveStruct(ids, nil, sgs.Player_PlaceTable,
        sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_TURNOVER, owner:objectName(), self:objectName(), "")), true)
    local suits, chosen = {}, sgs.IntList()
    for _, id in sgs.qlist(ids) do
        local suit = sgs.Sanguosha:getCard(id):getSuit()
        suits[suit] = true
    end
    for suit = sgs.Card_Spade, sgs.Card_NoSuit do
        if suits[suit] and owner:isAlive() then
            local options = sgs.IntList()
            for _, id in sgs.qlist(ids) do
                if room:getCardPlace(id) == sgs.Player_PlaceTable and sgs.Sanguosha:getCard(id):getSuit() == suit then options:append(id) end
            end
            if not options:isEmpty() then
                room:fillAG(options, owner)
                local id = room:askForAG(owner, options, false, self:objectName()); room:clearAG(owner)
                if not options:contains(id) then id = options:first() end
                chosen:append(id)
            end
        end
    end
    gu_obtain(room, owner, chosen, self:objectName())
    local rest = sgs.IntList()
    for _, id in sgs.qlist(ids) do if room:getCardPlace(id) == sgs.Player_PlaceTable then rest:append(id) end end
    if not rest:isEmpty() then
        local dummy = gu_dummy(rest)
        room:throwCard(dummy, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_NATURAL_ENTER, owner:objectName(), self:objectName(), ""), nil)
        dummy:deleteLater()
    end
end)
hlxg_shendao = gu_trigger("hlxg_shendao", {sgs.FinishRetrial}, function(self, event, room, p, data, owner)
    local judge = data:toJudge()
    if judge.who ~= owner or not judge.card or not gu_invoke(owner, self:objectName(), data) then return end
    local choice = room:askForChoice(owner, self:objectName(), "spade+club+heart+diamond", data)
    local suits = {spade = sgs.Card_Spade, club = sgs.Card_Club, heart = sgs.Card_Heart, diamond = sgs.Card_Diamond}
    local result = sgs.Sanguosha:cloneCard(judge.card:objectName(), suits[choice], judge.card:getNumber())
    result:addSubcard(judge.card:getEffectiveId())
    result:setSkillName(self:objectName())
    judge.card = result; judge:updateResult(); data:setValue(judge)
    result:deleteLater()
end)
hlxg_zuoci:addSkill(hlxg_xinsheng); hlxg_zuoci:addSkill(hlxg_shendao)

