hlxg_jianchu = gu_trigger("hlxg_jianchu", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if use.from ~= owner or not use.card or not use.card:isKindOf("Slash") then return end
