-- ==================== c207_02
do
-- c207_02: literal Huanle variants.
hljx_pangde = sgs.General(extension_hl, "hljx_pangde", "qun", 4)
hlxg_pangde2 = sgs.General(extension_hl, "hlxg_pangde2", "wei", 4)
hlxg_pangdegong = sgs.General(extension_hl, "hlxg_pangdegong", "qun", 3)

hljx_jianchu = gu_trigger("hljx_jianchu", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or use.from ~= owner or not use.card or not use.card:isKindOf("Slash") then return end
    for _, to in sgs.qlist(use.to) do
        if owner:isAlive() and to:isAlive() and owner:canDiscard(to, "he")
            and gu_invoke(owner, self:objectName(), sgs.QVariant(to)) then
            local id = room:askForCardChosen(owner, to, "he", self:objectName(), false, sgs.Card_MethodDiscard)
            if id >= 0 then
                local basic = sgs.Sanguosha:getCard(id):isKindOf("BasicCard")
                room:throwCard(id, self:objectName(), to, owner)
                use = data:toCardUse()
                if basic then
                    if use.m_addHistory then
                        room:addPlayerHistory(owner, use.card:getClassName(), -1)
                        use.m_addHistory = false
                    end
                else
                    local list = use.no_respond_list
                    if not table.contains(list, to:objectName()) then table.insert(list, to:objectName()) end
                    use.no_respond_list = list
                    data:setValue(use)
                    owner:drawCards(1, self:objectName())
                    use = data:toCardUse()
                end
                data:setValue(use)
            end
        end
    end
end)
hljx_mashu = sgs.CreateDistanceSkillV2 {
    name = "hljx_mashu",
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        return p and p:hasSkill(self:objectName()) and -1 or 0
    end,
}
hlxg_juesi = gu_active("hlxg_juesi", nil, 1, 1,
    function(self, targets, to, from) return gu_one(self, targets, to, from) and from:inMyAttackRange(to) end,
    gu_one_feasible,
    function(self, room, source, targets)
        gu_throw(room, source, self:getSubcards(), "hlxg_juesi")
        local to = targets[1]
        if not to:isAlive() then return end
        local c = room:askForDiscard(to, "hlxg_juesi", 1, 1, false, true)
        if not c or c:getSubcards():isEmpty() then return end
        local slash = sgs.Sanguosha:getCard(c:getSubcards():first()):isKindOf("Slash")
        if slash and source:isAlive() and to:isAlive() then
            local duel = sgs.Sanguosha:cloneCard("duel", sgs.Card_NoSuit, 0)
            duel:setSkillName("hlxg_juesi"); duel:deleteLater()
            local use = sgs.CardUseStruct(); use.from = source; use.to:append(to); use.card = duel
            room:useCard(use, false)
        elseif not slash and source:isAlive() and to:getHp() >= source:getHp() then source:drawCards(2, "hlxg_juesi") end
    end,
    function(request, c) return c:isKindOf("Slash") and not request:getInitiator():isJilei(c) end)
hlxg_yuma_pangde2 = gu_trigger("hlxg_yuma_pangde2", {sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    local move = data:toMoveOneTime()
    if not move.from or move.from:objectName() ~= owner:objectName() then return end
    local n = 0
    for i = 0, move.card_ids:length() - 1 do
        local c = sgs.Sanguosha:getCard(move.card_ids:at(i))
        if move.from_places:at(i) == sgs.Player_PlaceEquip and (c:isKindOf("OffensiveHorse") or c:isKindOf("DefensiveHorse")) then n = n + 1 end
    end
    for i = 1, n do if owner:isAlive() then owner:drawCards(2, self:objectName()) end end
end, true)
hlxg_yuma_pangde2_distance = sgs.CreateDistanceSkillV2 {
    name = "#hlxg_yuma_pangde2_distance",
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        return p and p:hasSkill("hlxg_yuma_pangde2") and -1 or 0
    end,
}

local function c207_basic(p, name, ids)
    local c = sgs.Sanguosha:cloneCard(name, sgs.Card_NoSuit, 0)
    if not c then return nil end
    c:setSkillName("hlxg_heqia"); if ids then c:addSubcards(ids) end
    c:deleteLater(); return c
end
hlxg_heqia_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_heqia_mod", pattern = "BasicCard", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local c, p = ctx:getCard(), ctx:getPrimary()
        if not c or not p or c:getSkillName() ~= "hlxg_heqia" then return 0 end
        if ctx:getModType() == sgs.TargetModSkill_DistanceLimit then return 1000 end
        if ctx:getModType() == sgs.TargetModSkill_Residue then return sgs.CorrectSkillResult.unlimitedResidue() end
        if ctx:getModType() == sgs.TargetModSkill_ExtraTarget then return math.max(0, p:getMark("hlxg_heqia_count") - 1) end
        return 0
    end,
}
hlxg_heqia_useCard = sgs.CreateSkillCard {
    name = "hlxg_heqia_useCard", will_throw = false,
    filter = function(self, targets, to, from)
        local c = c207_basic(from, self:getUserString(), self:getSubcards())
        if not c or c:targetFixed() or #targets >= from:getMark("hlxg_heqia_count") then return false end
        local list = sgs.PlayerList(); for _, p in ipairs(targets) do list:append(p) end
        return c:targetFilter(list, to, from) and not from:isProhibited(to, c)
    end,
    feasible = function(self, targets, from)
        local c = c207_basic(from, self:getUserString(), self:getSubcards())
        if not c or #targets > from:getMark("hlxg_heqia_count") then return false end
        local list = sgs.PlayerList(); for _, p in ipairs(targets) do list:append(p) end
        return c:targetsFeasible(list, from)
    end,
    on_validate = function(self, use) return c207_basic(use.from, self:getUserString(), self:getSubcards()) end,
}
hlxg_heqia_use = sgs.CreateViewAsSkillV2 {
    name = "#hlxg_heqia_use",
    can_activate = function(self, request) return request:getPattern() == "@@hlxg_heqia_use" end,
    can_select_card = function(self, request, c)
        return request:getSelectedCardIds():isEmpty() and not c:isEquipped()
            and request:getInitiator():handCards():contains(c:getEffectiveId())
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        local c = hlxg_heqia_useCard:clone(); c:addSubcards(request:getSelectedCardIds())
        c:setUserString(request:getInitiator():property("hlxg_heqia_name"):toString()); c:setSkillName("hlxg_heqia")
        return c
    end,
}
hlxg_heqia = gu_active("hlxg_heqia", 1, 0, math.huge,
    function(self, targets, to, from)
        return gu_one(self, targets, to, from) and (not self:getSubcards():isEmpty() or not to:isKongcheng())
    end, gu_one_feasible,
    function(self, room, source, targets)
        local to, recipient, count = targets[1], targets[1], self:subcardsLength()
        if count == 0 then
            local c = room:askForExchange(to, "hlxg_heqia", to:getHandcardNum(), 1, false, "@hlxg_heqia-give", false)
            if not c then return end
            count = c:subcardsLength(); recipient = source; room:giveCard(to, source, c, "hlxg_heqia")
        else room:giveCard(source, to, self, "hlxg_heqia") end
        if count == 0 or not recipient:isAlive() or recipient:isKongcheng() then return end
        room:setPlayerMark(recipient, "hlxg_heqia_count", count)
        local choices = {"cancel"}
        for _, name in ipairs(sgs.Sanguosha:getCardNames("BasicCard")) do
            local c = c207_basic(recipient, name)
            if c and c:isAvailable(recipient) then table.insert(choices, name) end
        end
        local name = room:askForChoice(recipient, "hlxg_heqia", table.concat(choices, "+"))
        if name ~= "cancel" then
            room:setPlayerProperty(recipient, "hlxg_heqia_name", sgs.QVariant(name))
            room:askForUseCardWithBorrowedSkill(recipient, "hlxg_heqia_use", "#hlxg_heqia_use", "@hlxg_heqia-use", -1, sgs.Card_MethodUse, false)
            room:setPlayerProperty(recipient, "hlxg_heqia_name", sgs.QVariant(""))
        end
        room:setPlayerMark(recipient, "hlxg_heqia_count", 0)
    end)
hlxg_yinyi = sgs.CreateTriggerSkillV2 {
    name = "hlxg_yinyi", frequency = sgs.Skill_Compulsory, events = {sgs.DamageInflicted},
    can_trigger = function(self, event, room, p, data)
        if not p or not p:hasSkill(self:objectName()) or p:getMark("hlxg_yinyi-Clear") > 0 then return false end
        local d = data:toDamage()
        return d.from and d.nature == sgs.DamageStruct_Normal and d.from:getHp() ~= p:getHp()
            and d.from:getHandcardNum() ~= p:getHandcardNum() and self:objectName() or false
    end,
    on_effect = function(self, event, room, p, ctx) room:addPlayerMark(p, "hlxg_yinyi-Clear"); return true end,
}
