do
-- c207_03: standalone batch fragment; GU helpers are provided by the assembler.
local function c207_recover(room, p, n)
    if n <= 0 then return end
    local r = sgs.RecoverStruct(); r.who = p; r.recover = n; room:recover(p, r)
end
local function c207_niepan(name, mark, upgraded)
    return gu_trigger(name, {sgs.AskForPeachesDone}, function(self, event, room, p, data, owner)
        if p ~= owner or owner:getHp() > 0 or owner:getMark(mark) == 0 then return end
        if not gu_invoke(owner, name, data) then return end
        room:removePlayerMark(owner, mark)
        owner:throwAllCards(name)
        if not owner:faceUp() then owner:turnOver() end
        if owner:isChained() then room:setPlayerChained(owner, false) end
        owner:drawCards(3, name)
        c207_recover(room, owner, math.min(3, owner:getMaxHp()) - owner:getHp())
        if upgraded and owner:isAlive() then
            local choice = room:askForChoice(owner, name, "hljx_huoji+hljx_bazhen", data)
            if choice == "hljx_huoji" then room:acquireSkill(owner, "hljx_huoji")
            else room:acquireSkill(owner, "bazhen"); room:acquireSkill(owner, "hljx_bazhen"); room:acquireSkill(owner, "hljx_kanpo") end
        end
    end, false, sgs.Skill_Limited, mark)
end
hlxg_pangtong = sgs.General(extension_hl, "hlxg_pangtong", "shu", 3)
hlxg_niepan = c207_niepan("hlxg_niepan", "@hlxg_niepan", false)
hlxg_lianhuan_pangtong = gu_trigger("hlxg_lianhuan_pangtong", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Play then return end
    local chosen = room:askForPlayersChosen(owner, room:getAlivePlayers(), self:objectName(), 0, 2, "@hlxg_lianhuan_pangtong")
    for _, to in sgs.qlist(chosen) do room:setPlayerChained(to, not to:isChained()) end
    if chosen:contains(owner) then owner:drawCards(1, self:objectName()) end
end)
hlxg_pangtong:addSkill(hlxg_niepan)
