hljx_bazhen = gu_trigger("hljx_bazhen", {sgs.FinishJudge}, function(self, event, room, p, data, owner)
    local judge = data:toJudge()
    if judge.who == owner and judge.reason == "eight_diagram" and judge.card and judge.card:isBlack() then owner:drawCards(1, self:objectName()) end
end, true)
local function c207_convert(name, target, red)
    return sgs.CreateViewAsSkillV2 {
        name = name, response_or_use = true,
        can_activate = function(self, request)
            if target == "nullification" then
                local reason = request:getReason()
                return request:getPattern() == "nullification" and (reason == sgs.CardUseStruct_CARD_USE_REASON_RESPONSE or reason == sgs.CardUseStruct_CARD_USE_REASON_RESPONSE_USE)
            end
            if request:getReason() ~= sgs.CardUseStruct_CARD_USE_REASON_PLAY then return false end
            local c = sgs.Sanguosha:cloneCard(target); local ok = c:isAvailable(request:getInitiator()); c:deleteLater(); return ok
        end,
        can_select_card = function(self, request, c)
            return request:getSelectedCardIds():isEmpty() and request:getInitiator():handCards():contains(c:getEffectiveId()) and (red and c:isRed() or not red and c:isBlack())
        end,
        card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
        create_card = function(self, request)
            if request:getSelectedCardIds():length() ~= 1 then return nil end
            local old = sgs.Sanguosha:getCard(request:getSelectedCardIds():first())
            local c = sgs.Sanguosha:cloneCard(target, old:getSuit(), old:getNumber()); c:addSubcard(old); c:setSkillName(name); return c
        end,
    }
end
