    if use.from and use.from:hasSkill("hljx_kanpo") and use.card:isKindOf("Nullification") then
        local names = use.no_respond_list; table.insert(names, "_ALL_TARGETS"); use.no_respond_list = names; data:setValue(use)
    end
end)
