hljx_huoji_effect = sgs.CreateRuleSkillV2 {
    name = "#hljx_huoji_effect", global = true, events = {sgs.CardEffected}, priority = 0,
    can_trigger = function(self, event, room, p, data)
        local e = data:toCardEffect()
        return e.from and e.from:hasSkill("hljx_huoji") and e.card:isKindOf("FireAttack") and self:objectName() or false
    end,
    on_effect = function(self, event, room, p, ctx)
        local e = ctx.original_data:toCardEffect()
        if e.nullified then return true end
        if not e.offset_card then e.offset_card = room:isCanceled(e); ctx.original_data:setValue(e) end
        if e.offset_card and not room:getThread():trigger(sgs.CardOffset, room, e.from, ctx.original_data) then return true end
        room:getThread():trigger(sgs.CardOnEffect, room, e.to, ctx.original_data)
        e = ctx.original_data:toCardEffect()
        for iteration = 0, e.extra_effect do
        if not e.to:isAlive() or e.to:isKongcheng() then break end
        local shown = room:askForCardShow(e.to, e.from, "fire_attack"); room:showCard(e.to, shown:getEffectiveId())
        local paid = false
        if e.from:isAlive() and gu_invoke(e.from, "hljx_huoji", ctx.original_data) then
            local ids = room:getNCards(4, false)
            local disabled = sgs.IntList()
            for _, id in sgs.qlist(ids) do if sgs.Sanguosha:getCard(id):getSuit() ~= shown:getSuit() then disabled:append(id) end end
            e.from:setTag("hljx_huoji_suit", sgs.QVariant(shown:getSuit()))
            room:fillAG(ids, e.from, disabled)
            local id = room:askForAG(e.from, ids, true, "hljx_huoji")
            room:clearAG(e.from)
            e.from:removeTag("hljx_huoji_suit")
            if id >= 0 and ids:contains(id) and not disabled:contains(id) then
                ids:removeOne(id); local cost = sgs.IntList(); cost:append(id); gu_throw(room, e.from, cost, "hljx_huoji"); paid = true
            end
            room:returnToTopDrawPile(ids)
        end
        if not paid and e.from:isAlive() then
            paid = room:askForCard(e.from, ".|" .. shown:getSuitString() .. "|.|hand", "@hljx_huoji-discard:" .. e.to:objectName(), ctx.original_data) ~= nil
        end
        if paid and e.from:isAlive() then
            local d = sgs.DamageStruct(); d.card = e.card; d.from = e.from; d.to = e.to; d.damage = 1; d.nature = sgs.DamageStruct_Fire; room:damage(d)
        end
        end
        return true
    end,
}
extension_hl:addSkills(hljx_huoji_effect)

hljx_lianhuan = gu_trigger("hljx_lianhuan", {sgs.EventPhaseStart, sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.EventPhaseStart then
        if p:getPhase() == sgs.Player_Play then room:askForUseCard(p, "@@hljx_lianhuan", "@hljx_lianhuan") end
    else
        local use = data:toCardUse()
        if not use.card:isKindOf("IronChain") then return end
        for _, to in sgs.qlist(use.to) do
            if to == owner then owner:drawCards(1, self:objectName())
            elseif not to:isChained() then
                local cards = to:getCards("he")
                if not cards:isEmpty() then
                    local c = cards:at(math.random(0, cards:length() - 1))
                    room:throwCard(c, self:objectName(), to, owner)
                end
            end
        end
    end
end)
