    local m = data:toMoveOneTime()
    if owner:getPhase() == sgs.Player_Play and m.to and m.to:objectName() == owner:objectName() and m.to_place == sgs.Player_PlaceHand and m.reason.m_reason == sgs.CardMoveReason_S_REASON_DRAW and m.reason.m_skillName ~= self:objectName() then owner:drawCards(1, self:objectName()) end
end, true)
hlxg_guolun = gu_active("hlxg_guolun", 1, 0, 0,
    function(self, targets, to, from) return gu_one(self, targets, to, from) and not to:isKongcheng() end, gu_one_feasible,
    function(self, room, source, targets)
        local to = targets[1]
        local id = room:askForCardChosen(source, to, "h", "hlxg_guolun")
        room:showCard(to, id)
        if source:isNude() or not source:isAlive() or not to:isAlive() then return end
        local c = room:askForCard(source, "..", "@hlxg_guolun", sgs.QVariant(id), sgs.Card_MethodNone, to)
        if not c then return end
        local own = c:getEffectiveId()
        room:showCard(source, own)
        if room:getCardOwner(id) ~= to or room:getCardPlace(id) ~= sgs.Player_PlaceHand or room:getCardOwner(own) ~= source then return end
        local number = sgs.Sanguosha:getCard(id):getNumber()
        local moves = sgs.CardsMoveList()
        moves:append(sgs.CardsMoveStruct(own, to, sgs.Player_PlaceHand, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_SWAP, source:objectName(), "hlxg_guolun", "")))
        moves:append(sgs.CardsMoveStruct(id, source, sgs.Player_PlaceHand, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_SWAP, to:objectName(), "hlxg_guolun", "")))
        room:moveCardsAtomic(moves, true)
        if c:getNumber() > number then to:drawCards(1, "hlxg_guolun"); c207_recover(room, source, 1)
        else source:drawCards(2, "hlxg_guolun") end
    end)
hlxg_songsang = gu_trigger("hlxg_songsang", {sgs.Death}, function(self, event, room, p, data, owner)
    if data:toDeath().who ~= owner and gu_invoke(owner, self:objectName(), data) then room:gainMaxHp(owner, 1, self:objectName()); c207_recover(room, owner, 1) end
end)
