-- ==================== c207_04
do
-- c207_04: literal 欢乐 variants.
local function c207_04_dangxian(name)
    return gu_trigger(name, {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
        if p ~= owner or p:getPhase() ~= sgs.Player_RoundStart then return end
        room:sendCompulsoryTriggerLog(owner, self:objectName(), true)
        owner:insertPhase(sgs.Player_Play)
        local ids = sgs.IntList()
        for _, pile in ipairs({room:getDrawPile(), room:getDiscardPile()}) do
            for _, id in sgs.qlist(pile) do
                if sgs.Sanguosha:getCard(id):isKindOf("Slash") then ids:append(id) end
            end
        end
        if ids:isEmpty() then return end
        room:fillAG(ids, owner)
        local id = room:askForAG(owner, ids, false, self:objectName())
        room:clearAG(owner)
        if id >= 0 then room:obtainCard(owner, id, self:objectName(), false) end
    end, true)
end
