hljx_fuli = gu_trigger("hljx_fuli", {sgs.EnterDying}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:getHp() > 0 or owner:getMark("@hljx_fuli") == 0 then return end
    if not gu_invoke(owner, self:objectName(), data) then return end
    room:removePlayerMark(owner, "@hljx_fuli")
    local kingdoms, x = {}, 0
    for _, who in sgs.qlist(room:getAlivePlayers()) do
        local kingdom = who:getKingdom()
        if not kingdoms[kingdom] then kingdoms[kingdom] = true; x = x + 1 end
    end
    room:recover(owner, sgs.RecoverStruct(self:objectName(), owner, x - owner:getHp()))
    if owner:isAlive() and owner:getHandcardNum() < x then owner:drawCards(x - owner:getHandcardNum(), self:objectName()) end
    if owner:isAlive() and x > 3 then owner:turnOver() end
end, false, sgs.Skill_Limited, "@hljx_fuli")
