hlxg_tongli = gu_trigger("hlxg_tongli", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if use.from ~= owner or owner:getPhase() ~= sgs.Player_Play or not use.card then return end
    local suits, x = {}, 0
    for _, card in sgs.qlist(owner:getHandcards()) do
        local suit = card:getSuit()
        if suit >= sgs.Card_Spade and suit <= sgs.Card_Diamond and not suits[suit] then
            suits[suit] = true; x = x + 1
        end
    end
    if owner:getMark("hlxg_tongli_count-PlayClear") ~= x or not gu_invoke(owner, self:objectName(), data) then return end
    -- GameRule repeats Card::use for extra_use without another cost/use event.
    use.extra_use = use.extra_use + x
    data:setValue(use)
end)
hlxg_shezang = gu_trigger("hlxg_shezang", {sgs.EnterDying}, function(self, event, room, p, data, owner)
    if p ~= owner and room:getCurrent() ~= owner then return end
    if owner:getMark("hlxg_shezang_used-Clear") > 0 or not gu_invoke(owner, self:objectName(), data) then return end
    room:addPlayerMark(owner, "hlxg_shezang_used-Clear")
    local selected = sgs.IntList()
    for _, suit in ipairs({sgs.Card_Spade, sgs.Card_Club, sgs.Card_Heart, sgs.Card_Diamond}) do
        local mark = "hlxg_shezang_suit" .. tostring(suit) .. "_lun"
        if owner:getMark(mark) == 0 then
            local ids = sgs.IntList()
            for _, id in sgs.qlist(room:getDiscardPile()) do
                if sgs.Sanguosha:getCard(id):getSuit() == suit then ids:append(id) end
            end
            if not ids:isEmpty() then
                room:fillAG(ids, owner)
                local id = room:askForAG(owner, ids, false, self:objectName())
                room:clearAG(owner)
                if id >= 0 then
                    selected:append(id)
                    room:setPlayerMark(owner, mark, 1)
                end
            end
        end
    end
    gu_obtain(room, owner, selected, self:objectName())
end)
