hlxg_difaCard = sgs.CreateSkillCard {
    name = "hlxg_difaCard", target_fixed = true, will_throw = false,
    on_use = function(self, room, source)
        local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_RECAST, source:objectName(), "hlxg_difa", "")
        room:throwCard(self, reason, source)
        source:drawCards(1, "hlxg_difa")
        if not source:isAlive() then return end
        local choices = {}
        for _, name in sgs.qlist(sgs.Sanguosha:getCardNames()) do
            local c = sgs.Sanguosha:cloneCard(name)
            if c then
                if c:isNDTrick() and c:isAvailable(source) then table.insert(choices, name) end
                c:deleteLater()
            end
        end
        if #choices == 0 then return end
        local name = room:askForChoice(source, "hlxg_difa", table.concat(choices, "+"))
        source:setTag("hlxg_difa_trick", sgs.QVariant(name))
        local c = sgs.Sanguosha:cloneCard(name)
        c:setSkillName("hlxg_difa")
        if c:targetFixed() then
            local use = sgs.CardUseStruct(); use.card = c; use.from = source
            room:useCard(use)
        else
            local used = room:askForUseCard(source, "@@hlxg_difa_use!", "@hlxg_difa-use")
            -- The consequence is mandatory even if the target-selection dialog is dismissed.
            if not used and source:isAlive() then
                local selected = sgs.PlayerList()
                local answer
                local function find_targets()
                    if c:targetsFeasible(selected, source) then
                        answer = sgs.SPlayerList()
                        for _, p in sgs.qlist(selected) do answer:append(p) end
                        return true
                    end
                    for _, p in sgs.qlist(room:getAlivePlayers()) do
                        if not selected:contains(p) and not source:isProhibited(p, c, selected)
                            and c:targetFilter(selected, p, source) then
                            selected:append(p)
                            if find_targets() then return true end
                            selected:removeOne(p)
                        end
                    end
                    return false
                end
                if find_targets() then
                    local use = sgs.CardUseStruct(); use.card = c; use.from = source; use.to = answer
                    room:useCard(use)
                end
            end
        end
        c:deleteLater()
        source:removeTag("hlxg_difa_trick")
    end,
}
hlxg_difa = sgs.CreateViewAsSkillV2 {
    name = "hlxg_difa", limit_scope = sgs.Skill_Limit_Phase, phase_name = "Play", max_usage_limit = 1,
    can_activate = function(self, request)
        return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY and not request:getInitiator():isKongcheng()
    end,
    can_select_card = function(self, request, card)
        return request:getSelectedCardIds():isEmpty() and request:getInitiator():handCards():contains(card:getEffectiveId()) and card:isRed()
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        local c = hlxg_difaCard:clone(); c:addSubcards(request:getSelectedCardIds()); return c
    end,
}
hlxg_difa_use = sgs.CreateViewAsSkillV2 {
    name = "#hlxg_difa_use",
    can_activate = function(self, request) return (request:getPattern() == "@@hlxg_difa_use!" or request:getPattern() == "@@hlxg_difa_use") end,
    can_select_card = function() return false end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function(self, request)
        local c = sgs.Sanguosha:cloneCard(request:getInitiator():getTag("hlxg_difa_trick"):toString())
        if c then c:setSkillName("hlxg_difa") end
        return c
    end,
}

hlxg_tianze = gu_trigger("hlxg_tianze", {sgs.FinishJudge, sgs.CardUsed, sgs.CardFinished},
    function(self, event, room, actor, data, owner)
        if not actor or actor == owner then return end
        if event == sgs.FinishJudge then
            local judge = data:toJudge()
            if judge.card and judge.card:isBlack() then owner:drawCards(1, self:objectName()) end
            return
        end
        local use = data:toCardUse()
        if not use.card then return end
        local flag = "hlxg_tianze_" .. owner:objectName()
        if event == sgs.CardUsed then
            if actor:getPhase() == sgs.Player_Play and use.m_isHandcard and use.card:isBlack() then
                room:setCardFlag(use.card, flag)
            end
        elseif use.card:hasFlag(flag) then
            room:setCardFlag(use.card, "-" .. flag)
            if owner:getMark("hlxg_tianze-Clear") == 0 and actor:isAlive() then
                local card = room:askForCard(owner, ".|black", "@hlxg_tianze:" .. actor:objectName(), data, sgs.Card_MethodDiscard)
                if card then
                    room:setPlayerMark(owner, "hlxg_tianze-Clear", 1)
                    room:damage(sgs.DamageStruct(self:objectName(), owner, actor, 1))
                end
            end
        end
    end)

hlxg_zhoufu = gu_active("hlxg_zhoufu", 1, 0, 1,
    function(self, targets, to, from)
        return gu_one(self, targets, to, from) and
            ((self:subcardsLength() == 1 and to:getPile("hlxg_zhoufu"):isEmpty()) or
             (self:subcardsLength() == 0 and not to:getPile("hlxg_zhoufu"):isEmpty()))
    end, gu_one_feasible,
    function(self, room, source, targets)
        local target = targets[1]
        if self:subcardsLength() == 1 then
            target:setTag("hlxg_zhoufu_owner", sgs.QVariant(source:objectName()))
            for _, p in sgs.qlist(room:getAlivePlayers()) do
                room:setPlayerMark(target, "hlxg_yingbing_count_" .. p:objectName(), 0)
            end
            target:addToPile("hlxg_zhoufu", self:getSubcards(), true)
        else
            local c = gu_dummy(target:getPile("hlxg_zhoufu"))
            room:throwCard(c, "hlxg_zhoufu", nil); c:deleteLater()
        end
    end,
    function(request, card) return request:getInitiator():handCards():contains(card:getEffectiveId()) end)
hlxg_zhoufu_record = gu_record("#hlxg_zhoufu_record", {sgs.CardsMoveOneTime, sgs.EventPhaseChanging},
    function(self, event, room, actor, data)
        if event == sgs.CardsMoveOneTime then
            local move = data:toMoveOneTime()
            if move.from then
                for i = 0, move.card_ids:length() - 1 do
                    if move.from_places:at(i) == sgs.Player_PlaceSpecial and move.from_pile_names[i + 1] == "hlxg_zhoufu" then
                        local p = room:findPlayerByObjectName(move.from:objectName())
                        if p then room:setPlayerMark(p, "hlxg_zhoufu_lost-Clear", 1) end
                    end
                end
            end
        elseif event == sgs.EventPhaseChanging and data:toPhaseChange().to == sgs.Player_NotActive then
            for _, p in sgs.qlist(room:getAlivePlayers()) do
                if p:getMark("hlxg_zhoufu_lost-Clear") > 0 then room:loseHp(p, 1) end
            end
        end
    end)
-- The engine StartJudge rule uses this supplied card instead of drawing, and moves/logs it normally.
hlxg_zhoufu_judge = sgs.CreateRuleSkillV2 {
    name = "#hlxg_zhoufu_judge", global = true, priority = 10, events = {sgs.StartJudge},
    can_trigger = function(self, event, room, player, data)
        return player and not player:getPile("hlxg_zhoufu"):isEmpty() and self:objectName() or false
    end,
    on_effect = function(self, event, room, player, ctx)
        local judge = ctx.original_data:toJudge()
        judge.card = sgs.Sanguosha:getCard(player:getPile("hlxg_zhoufu"):first())
        judge:updateResult(); ctx.original_data:setValue(judge)
        return false
    end,
}
hlxg_yingbing = gu_trigger("hlxg_yingbing", {sgs.CardUsed}, function(self, event, room, actor, data, owner)
    if not actor or actor:getPile("hlxg_zhoufu"):isEmpty() then return end
    local card = data:toCardUse().card
    local curse = sgs.Sanguosha:getCard(actor:getPile("hlxg_zhoufu"):first())
    if card and card:getColor() == curse:getColor() then
        local mark = "hlxg_yingbing_count_" .. owner:objectName()
        room:addPlayerMark(actor, mark)
        local second = actor:getMark(mark) == 2
        local id = curse:getEffectiveId()
        owner:drawCards(1, self:objectName())
        if second and actor:getPile("hlxg_zhoufu"):contains(id) then room:throwCard(curse, "hlxg_yingbing", nil) end
    end
end, true)

hlxg_wurong = gu_active("hlxg_wurong", 1, 1, 1,
    function(self, targets, to, from) return gu_one(self, targets, to, from) and not to:isKongcheng() end,
    gu_one_feasible, function(self, room, source, targets)
        local target = targets[1]
        local chosen = room:askForExchange(target, "hlxg_wurong", 1, 1, false, "@hlxg_wurong-show")
        if not chosen then return end
        local a = self:getSubcards():first(); local b = chosen:getSubcards():first()
        local slash = sgs.Sanguosha:getCard(a):isKindOf("Slash")
        local jink = sgs.Sanguosha:getCard(b):isKindOf("Jink")
        room:showCard(source, a); room:showCard(target, b)
        if slash and not jink then room:damage(sgs.DamageStruct("hlxg_wurong", source, target, 1))
        elseif not slash and jink and not target:isNude() then
            room:obtainCard(source, room:askForCardChosen(source, target, "he", "hlxg_wurong"), false)
        end
    end, function(request, card) return request:getInitiator():handCards():contains(card:getEffectiveId()) end)
