-- ==================== c207_06
do
-- c207_06: literal Huanle modifications.
hlxg_zhanggong = sgs.General(extension_hl, "hlxg_zhanggong", "wei", 3)
hlxg_zhangchangpu = sgs.General(extension_hl, "hlxg_zhangchangpu", "wei", 3, false)
hlxg_zhangxingcai = sgs.General(extension_hl, "hlxg_zhangxingcai", "shu", 3, false)

hlxg_qianxin = gu_active("hlxg_qianxin", 2, 1, 1,
    function(self, targets, to, from) return #targets == 0 end, gu_one_feasible,
    function(self, room, source, targets)
        local to = targets[1]
        local letters = gu_names(to, "hlxg_qianxin_letters")
        table.insert(letters, tostring(self:getSubcards():first()) .. ":" .. source:objectName())
        gu_setnames(to, "hlxg_qianxin_letters", letters)
        room:giveCard(source, to, self, "hlxg_qianxin", true)
        room:showCard(to, self:getSubcards())
    end,
    function(request, c) return request:getInitiator():handCards():contains(c:getEffectiveId()) end)
hlxg_qianxin_record = gu_record("#hlxg_qianxin_record", {sgs.EventPhaseStart}, function(self, event, room, p, data)
    if not p or p:getPhase() ~= sgs.Player_Start then return end
    local letters = gu_names(p, "hlxg_qianxin_letters")
    gu_setnames(p, "hlxg_qianxin_letters", {})
    local senders = {}
    for _, entry in ipairs(letters) do
        local id, sender = entry:match("^(%d+):(.+)$")
        if id and p:handCards():contains(tonumber(id)) then senders[sender] = true end
    end
    for _, source in sgs.qlist(room:getAllPlayers()) do
        if senders[source:objectName()] and p:isAlive() then
            local choice = room:askForChoice(p, "hlxg_qianxin", "draw+maxcards", sgs.QVariant(source))
            if choice == "draw" then
                if source:isAlive() then source:drawCards(2, "hlxg_qianxin") end
            else room:addPlayerMark(p, "hlxg_qianxin_penalty-Clear", 2) end
        end
    end
end)
hlxg_qianxin_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_qianxin_max", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        return p and -p:getMark("hlxg_qianxin_penalty-Clear") or 0
    end,
}
local function c207_06_reveal(room, n, skill)
    local ids = room:getNCards(n)
    local c = gu_dummy(ids)
    room:moveCardTo(c, nil, sgs.Player_PlaceTable,
        sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_TURNOVER, "", skill, ""), true)
    c:deleteLater()
    return ids
end
hlxg_zhenxing = gu_trigger("hlxg_zhenxing", {sgs.EventPhaseStart, sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner or (event == sgs.EventPhaseStart and p:getPhase() ~= sgs.Player_Finish)
        or not gu_invoke(owner, self:objectName(), data) then return end
    local n = tonumber(room:askForChoice(owner, self:objectName(), "0+1+2+3")) or 0
    if n == 0 then return end
    local ids = c207_06_reveal(room, n, self:objectName())
    local eligible = sgs.IntList()
    for _, id in sgs.qlist(ids) do
        local unique = true
        for _, other in sgs.qlist(ids) do
            if id ~= other and sgs.Sanguosha:getCard(id):getSuit() == sgs.Sanguosha:getCard(other):getSuit() then unique = false end
        end
        if unique then eligible:append(id) end
    end
    if not eligible:isEmpty() and owner:isAlive() then
        room:fillAG(ids, owner)
        local id = room:askForAG(owner, eligible, false, self:objectName())
        room:clearAG(owner)
        if id >= 0 then room:obtainCard(owner, id, true); ids:removeOne(id) end
    end
    if not ids:isEmpty() then room:returnToTopDrawPile(ids) end
end)

hlxg_yanjiao = gu_active("hlxg_yanjiao", 1, 0, 0, gu_one, gu_one_feasible,
    function(self, room, source, targets)
        local to = targets[1]
        local n = 3 + source:getMark("hlxg_shengshen_bonus")
        room:setPlayerMark(source, "hlxg_shengshen_bonus", 0)
        local ids = c207_06_reveal(room, n, "hlxg_yanjiao")
        local sum = 0
        for _, id in sgs.qlist(ids) do sum = sum + sgs.Sanguosha:getCard(id):getNumber() end
        local cap, chosen = math.floor(sum / 2), sgs.IntList()
        while to:isAlive() do
            local eligible = sgs.IntList()
            for _, id in sgs.qlist(ids) do
                if sgs.Sanguosha:getCard(id):getNumber() <= cap then eligible:append(id) end
            end
            if eligible:isEmpty() then break end
            room:fillAG(ids, to)
            local id = room:askForAG(to, eligible, not chosen:isEmpty(), "hlxg_yanjiao")
            room:clearAG(to)
            if id < 0 then break end
            chosen:append(id); ids:removeOne(id)
            cap = cap - sgs.Sanguosha:getCard(id):getNumber()
        end
        if to:isAlive() and not chosen:isEmpty() then
            local c = gu_dummy(chosen); room:obtainCard(to, c, true); c:deleteLater()
        elseif not chosen:isEmpty() then
            for _, id in sgs.qlist(chosen) do ids:append(id) end
        end
        if source:isAlive() then
            local c = gu_dummy(ids); if not ids:isEmpty() then room:obtainCard(source, c, true) end; c:deleteLater()
        elseif not ids:isEmpty() then
            local c = gu_dummy(ids); room:moveCardTo(c, nil, sgs.Player_DiscardPile, true); c:deleteLater()
        end
    end)
hlxg_shengshen = gu_trigger("hlxg_shengshen", {sgs.Damaged}, function(self, event, room, p, data, owner)
