-- c207_07: literal Huanle variants.
local function c207_shangshi(name, enhanced)
    return gu_trigger(name, {sgs.GameStart, sgs.HpChanged, sgs.MaxHpChanged, sgs.CardsMoveOneTime, sgs.EventAcquireSkill},
        function(self, event, room, player, data, owner)
            if owner:hasFlag(name .. "_busy") then return end
            local n = math.max(1, owner:getLostHp()) - owner:getHandcardNum()
            if n <= 0 then return end
            room:setPlayerFlag(owner, name .. "_busy")
            owner:drawCards(n, name)
            if enhanced and owner:isAlive() and owner:getMark(name .. "-Clear") == 0 then
                local count = owner:getHandcardNum()
                local chosen = room:askForDiscard(owner, name, count, 1, true, false, "@" .. name .. "-discard")
                if chosen then
                    local empty = chosen:subcardsLength() == count
                    room:setPlayerMark(owner, name .. "-Clear", 1)
                    if empty then room:addPlayerMark(owner, name .. "_pending") end
                end
            end
            room:setPlayerFlag(owner, "-" .. name .. "_busy")
            -- The voluntary discard is followed by the same unconditional refill.
            if owner:isAlive() then
                n = math.max(1, owner:getLostHp()) - owner:getHandcardNum()
                if n > 0 then owner:drawCards(n, name) end
            end
        end)
end
