hljx_jueqing = gu_trigger("hljx_jueqing", {sgs.Predamage}, function(self, event, room, player, data, owner)
    local damage = data:toDamage()
    if damage.from ~= owner or not damage.to or not gu_invoke(owner, self:objectName(), data) then return end
    if room:askForChoice(owner, self:objectName(), "increase+losehp", data) == "increase" then
        room:loseHp(owner, 1, true, owner, self:objectName())
