hlxg_guzheng_record = gu_record("#hlxg_guzheng_record", {sgs.EventPhaseStart, sgs.CardsMoveOneTime}, function(self, event, room, player, data)
    if event == sgs.EventPhaseStart then
        if player and player:getPhase() == sgs.Player_Discard then
            player:removeTag("hlxg_guzheng_all")
            player:removeTag("hlxg_guzheng_hand")
        end
        return
    end
    local move = data:toMoveOneTime()
    local current = room:getCurrent()
    if not current or current:getPhase() ~= sgs.Player_Discard or move.from ~= current
        or move.to_place ~= sgs.Player_DiscardPile
        or bit32.band(move.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON) ~= sgs.CardMoveReason_S_REASON_DISCARD then return end
    local all = current:getTag("hlxg_guzheng_all"):toIntList()
    local hand = current:getTag("hlxg_guzheng_hand"):toIntList()
    for i, id in sgs.qlist(move.card_ids) do
        if not all:contains(id) then all:append(id) end
        if move.from_places:at(i) == sgs.Player_PlaceHand and not hand:contains(id) then hand:append(id) end
    end
    current:setTag("hlxg_guzheng_all", sgs.QVariant(all))
    current:setTag("hlxg_guzheng_hand", sgs.QVariant(hand))
end)
hlxg_guzheng = gu_trigger("hlxg_guzheng", {sgs.EventPhaseEnd}, function(self, event, room, player, data, owner)
    if not player or player == owner or player:getPhase() ~= sgs.Player_Discard then return end
    local hand = sgs.IntList()
    for _, id in sgs.qlist(player:getTag("hlxg_guzheng_hand"):toIntList()) do
        if room:getCardPlace(id) == sgs.Player_DiscardPile then hand:append(id) end
    end
    if hand:isEmpty() or not gu_invoke(owner, self:objectName(), sgs.QVariant(player)) then return end
    room:fillAG(hand, owner)
    local id = room:askForAG(owner, hand, false, self:objectName())
    room:clearAG(owner)
    room:obtainCard(player, id, false)
    if not owner:isAlive() then return end
    if room:askForChoice(owner, self:objectName(), "obtain+draw", data) == "draw" then
        owner:drawCards(1, self:objectName())
    else
        local rest = sgs.IntList()
        for _, other in sgs.qlist(player:getTag("hlxg_guzheng_all"):toIntList()) do
            if other ~= id and room:getCardPlace(other) == sgs.Player_DiscardPile then rest:append(other) end
        end
        gu_obtain(room, owner, rest, self:objectName())
    end
end)
