hlxg_zhangliang = sgs.General(extension_hl, "hlxg_zhangliang", "qun", 4, true)
hlxg_jijun = gu_trigger("hlxg_jijun", {sgs.TargetSpecified, sgs.TargetConfirmed, sgs.FinishJudge},
    function(self, event, room, player, data, owner)
        if event == sgs.FinishJudge then
            local judge = data:toJudge()
            if judge.who == owner and judge.reason == self:objectName() and judge.card and judge.card:isBlack()
                and room:getCardPlace(judge.card:getEffectiveId()) == sgs.Player_PlaceJudge then
                owner:addToPile("hlxg_fang", judge.card, true)
            end
            return
        end
        local use = data:toCardUse()
        if not use.card or use.to:length() ~= 1 then return end
        local own = event == sgs.TargetSpecified and use.from == owner
            and (use.card:isKindOf("Slash") or use.card:isNDTrick())
        local incoming = event == sgs.TargetConfirmed and player == owner and use.from ~= owner
            and use.card:isKindOf("Slash") and use.to:contains(owner)
        if not own and not incoming then return end
        room:sendCompulsoryTriggerLog(owner, self:objectName())
        local judge = sgs.JudgeStruct()
        judge.who = owner; judge.reason = self:objectName(); judge.pattern = ".|black"; judge.good = true
        room:judge(judge)
    end, true)
hlxg_fangtong = gu_trigger("hlxg_fangtong", {sgs.EventPhaseStart},
    function(self, event, room, player, data, owner)
        if player ~= owner or owner:getPhase() ~= sgs.Player_Finish or owner:getPile("hlxg_fang"):isEmpty()
            or not gu_invoke(owner, self:objectName()) then return end
        local available = sgs.IntList()
        for _, id in sgs.qlist(owner:getPile("hlxg_fang")) do available:append(id) end
        local selected = sgs.IntList()
        for i = 1, math.min(3, available:length()) do
            room:fillAG(available, owner)
            local id = room:askForAG(owner, available, true, self:objectName())
            room:clearAG(owner)
            if id < 0 then break end
            selected:append(id); available:removeOne(id)
        end
        local n = selected:length()
        if n == 0 then return end
        gu_throw(room, owner, selected, self:objectName())
        if not owner:isAlive() then return end
        if n == 1 then owner:drawCards(1, self:objectName())
        elseif n == 2 then
            local recover = sgs.RecoverStruct(); recover.who = owner; recover.recover = 1
            room:recover(owner, recover)
        else
            local target = room:askForPlayerChosen(owner, room:getAlivePlayers(), self:objectName(), "@hlxg_fangtong", false, true)
            if target then
                local damage = sgs.DamageStruct()
                damage.from = owner; damage.to = target; damage.damage = 2
                damage.nature = sgs.DamageStruct_Thunder; damage.reason = self:objectName()
                room:damage(damage)
            end
        end
    end)
hlxg_zhangliang:addSkill(hlxg_jijun)
hlxg_zhangliang:addSkill(hlxg_fangtong)

local function hlxg_take_three(room, owner, target)
    if not owner:isAlive() or not target:isAlive() then return end
    local n = math.min(3, target:getCards("hej"):length())
    if n == 0 then return end
    local ids = room:askForCardsChosen(owner, target, "hej", "hlxg_jizhong", n, n, false, sgs.Card_MethodNone, sgs.IntList(), false)
    gu_obtain(room, owner, ids, "hlxg_jizhong")
end
