hlxg_guangshi = gu_trigger("hlxg_guangshi", {sgs.EventPhaseStart},
    function(self, event, room, player, data, owner)
        if player ~= owner or owner:getPhase() ~= sgs.Player_Start then return end
        for _, p in sgs.qlist(room:getOtherPlayers(owner)) do
            if p:getMark("&hlxg_xinzhong") == 0 then return end
        end
        local n = 0
        for _, p in sgs.qlist(room:getAlivePlayers()) do n = n + p:getMark("&hlxg_xinzhong") end
        if not gu_invoke(owner, self:objectName()) then return end
        owner:drawCards(n, self:objectName())
        if owner:isAlive() then room:loseHp(owner, 1, true, owner, self:objectName()) end
    end)
hlxg_rihui = gu_trigger("hlxg_rihui", {sgs.CardFinished},
    function(self, event, room, player, data, owner)
        local use = data:toCardUse()
        if use.from ~= owner or owner:getPhase() ~= sgs.Player_Play or owner:getMark("hlxg_rihui-PlayClear") > 0
            or not use.card or use.to:length() ~= 1
            or not (use.card:isKindOf("BasicCard") or use.card:isNDTrick()) then return end
        local target = use.to:first()
        if not target:isAlive() or not gu_invoke(owner, self:objectName(), data) then return end
        room:setPlayerMark(owner, "hlxg_rihui-PlayClear", 1)
        if target:getMark("&hlxg_xinzhong") > 0 then
            if not target:getCards("hej"):isEmpty() then
                local id = room:askForCardChosen(owner, target, "hej", self:objectName())
                room:obtainCard(owner, id, self:objectName(), false)
            end
        else
            -- Snapshot followers before any replay can change marks or kill a follower.
            local followers = {}
            for _, p in sgs.qlist(room:getAlivePlayers()) do
                if p:getMark("&hlxg_xinzhong") > 0 then table.insert(followers, p) end
            end
            for _, p in ipairs(followers) do
                if p:isAlive() and target:isAlive() then
                    local card = sgs.Sanguosha:cloneCard(use.card:objectName(), sgs.Card_NoSuit, 0)
                    card:setSkillName(self:objectName())
                    if not p:isProhibited(target, card) then
                        local replay = sgs.CardUseStruct(); replay.from = p; replay.card = card; replay.to:append(target)
                        room:useCard(replay, false)
                    end
                    card:deleteLater()
                end
            end
        end
    end)
hlxg_jizhong = gu_active("hlxg_jizhong", 1, 0, 0, gu_one, gu_one_feasible,
    function(self, room, owner, targets)
        local target = targets[1]
        target:drawCards(2, "hlxg_jizhong")
        if not target:isAlive() then return end
        if target:getMark("&hlxg_xinzhong") == 0 then
            local choice = room:askForChoice(target, "hlxg_jizhong", "hlxg_follower+hlxg_give", sgs.QVariant(owner))
            if choice == "hlxg_follower" then room:setPlayerMark(target, "&hlxg_xinzhong", 1)
            else hlxg_take_three(room, owner, target) end
        else hlxg_take_three(room, owner, target) end
    end)
hlxg_zhangchu:addSkill(hlxg_guangshi)
