hlxg_tunjunCard = sgs.CreateSkillCard {
    name = "hlxg_tunjunCard", will_throw = false,
    filter = function(self, targets, to, from) return #targets == 0 end,
    feasible = gu_one_feasible,
    on_use = function(self, room, source, targets)
        room:removePlayerMark(source, "@hlxg_tunjun")
        local target = targets[1]
        local available = {}
        for _, id in sgs.qlist(room:getDrawPile()) do
            local card = sgs.Sanguosha:getCard(id)
            if card:isKindOf("EquipCard") then available[#available + 1] = id end
        end
        local selected = {}
        for i = 1, source:getMark("hlxg_lveming_count") + 1 do
            if #available == 0 then break end
            local id = available[math.random(#available)]
            selected[#selected + 1] = id
            local slot = sgs.Sanguosha:getCard(id):toEquipCard():location()
            for j = #available, 1, -1 do
                if sgs.Sanguosha:getCard(available[j]):toEquipCard():location() == slot then table.remove(available, j) end
            end
        end
        for _, id in ipairs(selected) do
            if not target:isAlive() then break end
            local card = sgs.Sanguosha:getCard(id)
            local slot = card:toEquipCard():location()
            if room:getCardPlace(id) == sgs.Player_DrawPile and not target:getEquip(slot)
                and target:hasEquipArea(slot) and card:isAvailable(target) and not target:isProhibited(target, card) then
                local use = sgs.CardUseStruct(); use.card = card; use.from = target; use.to:append(target)
                room:useCard(use, false)
            end
        end
    end,
}
