hlxg_sibian = gu_trigger("hlxg_sibian", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Draw or not gu_invoke(owner, self:objectName()) then return end
    local ids = room:getNCards(4)
    local all = gu_dummy(ids)
    room:moveCardTo(all, nil, sgs.Player_PlaceTable, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_TURNOVER, owner:objectName(), "hlxg_sibian", ""), true)
    all:deleteLater()
    local low, high = 14, 0
    for _, id in sgs.qlist(ids) do local n = sgs.Sanguosha:getCard(id):getNumber(); low = math.min(low, n); high = math.max(high, n) end
    local obtain = sgs.IntList()
    for _, id in sgs.qlist(ids) do
        local n = sgs.Sanguosha:getCard(id):getNumber()
        if (n == low or n == high) and room:getCardPlace(id) == sgs.Player_PlaceTable then obtain:append(id) end
    end
    if owner:isAlive() then gu_obtain(room, owner, obtain, "hlxg_sibian") end
    local rest = sgs.IntList()
    for _, id in sgs.qlist(ids) do if room:getCardPlace(id) == sgs.Player_PlaceTable then rest:append(id) end end
    if not rest:isEmpty() and owner:isAlive() then
        local minimum, maximum = 999, -1
        for _, q in sgs.qlist(room:getAlivePlayers()) do minimum = math.min(minimum, q:getHandcardNum()); maximum = math.max(maximum, q:getHandcardNum()) end
        local candidates = sgs.SPlayerList()
        for _, q in sgs.qlist(room:getAlivePlayers()) do if q:getHandcardNum() == minimum or q:getHandcardNum() == maximum then candidates:append(q) end end
        room:fillAG(rest, owner)
        local to = room:askForPlayerChosen(owner, candidates, "hlxg_sibian", "@hlxg_sibian", true, true)
        room:clearAG(owner)
        if to then gu_obtain(room, to, rest, "hlxg_sibian") end
    end
    local discard = sgs.IntList()
    for _, id in sgs.qlist(ids) do if room:getCardPlace(id) == sgs.Player_PlaceTable then discard:append(id) end end
    gu_throw(room, nil, discard, "hlxg_sibian")
    return true
end)
