    if target:isAlive() and (suit == sgs.Card_Spade or suit == sgs.Card_Club) then
        room:damage(sgs.DamageStruct("hlxg_leiji", owner, target, suit == sgs.Card_Spade and 2 or 1, sgs.DamageStruct_Thunder))
    end
end)
