hlxg_huangtian = gu_trigger("hlxg_huangtian$", {sgs.GameStart, sgs.TurnStart, sgs.EventAcquireSkill, sgs.CardFinished, sgs.PostCardResponded}, function(self, event, room, p, data, owner)
    if not owner:hasLordSkill("hlxg_huangtian") then return end
    if event == sgs.GameStart or event == sgs.TurnStart or event == sgs.EventAcquireSkill then
        for _, q in sgs.qlist(room:getAlivePlayers()) do if not q:hasSkill("hlxg_huangtian_give") then room:attachSkillToPlayer(q, "hlxg_huangtian_give") end end
        return
    end
    if not p or p == owner or p:getKingdom() ~= "qun" or owner:getMark("hlxg_huangtian-Clear") > 0 then return end
    local card = event == sgs.CardFinished and data:toCardUse().card or data:toCardResponse().m_card
    if not card or not card:isKindOf("Jink") then return end
    -- Both response methods finish in PostCardResponded, without CardFinished.
    local ids = card:isVirtualCard() and card:getSubcards() or gu_ids({card})
    local available = sgs.IntList()
    for _, id in sgs.qlist(ids) do
        local place = room:getCardPlace(id)
        if place == sgs.Player_PlaceTable or place == sgs.Player_DiscardPile then available:append(id) end
    end
    room:setPlayerMark(owner, "hlxg_huangtian-Clear", 1)
    gu_obtain(room, owner, available, "hlxg_huangtian")
end)
