-- ==================== c208_02
do
hljx_leiji = gu_trigger("hljx_leiji", {sgs.CardUsed, sgs.CardResponded}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    local card = event == sgs.CardUsed and data:toCardUse().card or data:toCardResponse().m_card
    if not card or not (card:isKindOf("Jink") or event == sgs.CardUsed and card:isKindOf("Lightning")) then return end
    local to = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@hljx_leiji", true, true)
    if not to then return end
    local judge = sgs.JudgeStruct()
    judge.who = to; judge.reason = self:objectName(); judge.pattern = ".|black"; judge.good = false
    room:judge(judge)
    if judge.card:getSuit() == sgs.Card_Club then
        local recover = sgs.RecoverStruct(); recover.who = owner; recover.recover = 1
        room:recover(owner, recover)
        if to:isAlive() then room:damage(sgs.DamageStruct(self:objectName(), owner, to, 1, sgs.DamageStruct_Thunder)) end
    elseif judge.card:getSuit() == sgs.Card_Spade and to:isAlive() then
        room:damage(sgs.DamageStruct(self:objectName(), owner, to, 2, sgs.DamageStruct_Thunder))
    end
end)
hljx_leiji_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hljx_leiji_max", holder_selector = sgs.CorrectSkill_Primary,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        return p and p:hasSkill("hljx_leiji") and 2 or 0
    end,
}
hljx_guidao = gu_trigger("hljx_guidao", {sgs.AskForRetrial}, function(self, event, room, p, data, owner)
    local judge = data:toJudge()
    local card = room:askForCard(owner, ".|black", "@hljx_guidao", data, sgs.Card_MethodNone, judge.who, true, self:objectName())
    if not card then return end
    local draw = card:getSuit() == sgs.Card_Spade and card:getNumber() >= 2 and card:getNumber() <= 9
    room:retrial(card, owner, judge, self:objectName(), false)
    if draw and owner:isAlive() then owner:drawCards(1, self:objectName()) end
end)
-- A separate attached view-as skill makes the lord's gift available to other players.
