        local room = sgs.Sanguosha:currentRoom()
        if not room then return false end
        for _, q in sgs.qlist(room:getOtherPlayers(p)) do if q:hasLordSkill("hljx_huangtian") then return true end end
        return false
    end)
extension_hl:addSkills(hljx_huangtian_give)
hljx_huangtian = gu_trigger("hljx_huangtian$", {sgs.GameStart, sgs.EventAcquireSkill, sgs.EventPhaseStart, sgs.CardResponded, sgs.CardFinished}, function(self, event, room, p, data, owner)
    if not owner:hasLordSkill("hljx_huangtian") then return end
    if event == sgs.GameStart or event == sgs.EventAcquireSkill or event == sgs.EventPhaseStart then
        for _, q in sgs.qlist(room:getOtherPlayers(owner)) do
            if not q:hasSkill("hljx_huangtian_give") then room:attachSkillToPlayer(q, "hljx_huangtian_give") end
        end
        return
    end
    if not p or p == owner or p:getKingdom() ~= "qun" or owner:getMark("hljx_huangtian-Clear") > 0 then return end
    local card = event == sgs.CardResponded and data:toCardResponse().m_card or data:toCardUse().card
