hlxg_duorui = gu_trigger("hlxg_duorui", {sgs.EventPhaseStart, sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.EventPhaseStart then
        if owner:getPhase() ~= sgs.Player_Play then return end
        local to = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@hlxg_duorui", true, true)
        if not to then return end
        for _, q in sgs.qlist(room:getAllPlayers()) do
            room:setPlayerMark(q, "hlxg_duorui_red_" .. owner:objectName(), 0)
            room:setPlayerMark(q, "hlxg_duorui_black_" .. owner:objectName(), 0)
        end
        room:showAllCards(to, owner)
        if to:isKongcheng() then return end
        local id = room:askForCardChosen(owner, to, "h", self:objectName())
        local card = sgs.Sanguosha:getCard(id)
        local color = card:isRed() and "red" or card:isBlack() and "black" or nil
        room:obtainCard(owner, id, false)
        if color then room:setPlayerMark(to, "hlxg_duorui_" .. color .. "_" .. owner:objectName(), 1) end
    else
        local use = data:toCardUse()
        if not use.card then return end
        local color = use.card:isRed() and "red" or use.card:isBlack() and "black" or nil
        if not color then return end
        local names = use.no_respond_list
        for _, q in sgs.qlist(room:getOtherPlayers(owner)) do
            if q:getMark("hlxg_duorui_" .. color .. "_" .. owner:objectName()) > 0 and not table.contains(names, q:objectName()) then table.insert(names, q:objectName()) end
        end
        use.no_respond_list = names; data:setValue(use)
    end
end)
local function hl208_wounded(room)
    local n = 0
    for _, p in sgs.qlist(room:getAlivePlayers()) do if p:isWounded() then n = n + 1 end end
    return n
end
hlxg_zhiti = gu_trigger("hlxg_zhiti", {sgs.DrawNCards}, function(self, event, room, p, data, owner)
    if p == owner and hl208_wounded(room) > 1 then local draw = data:toDraw(); draw.num = draw.num + 1; data:setValue(draw) end
end, true)
hlxg_zhiti_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_zhiti_mod", pattern = "Slash", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        local room = sgs.Sanguosha:currentRoom()
        if not room then return 0 end
        if p and p:hasSkill("hlxg_zhiti") and ctx:getModType() == sgs.TargetModSkill_Residue and hl208_wounded(room) > 2 then return 1 end
        return 0
    end,
}
