-- c208_03: the three literal Huanle variants.
local function hl208_take_hands(room, owner, skill, maximum, others_only)
    local candidates = sgs.SPlayerList()
    for _, p in sgs.qlist(room:getAlivePlayers()) do
        if not p:isKongcheng() and (not others_only or p ~= owner) then candidates:append(p) end
    end
    for i = 1, maximum do
        if candidates:isEmpty() or not owner:isAlive() then break end
        local to = room:askForPlayerChosen(owner, candidates, skill, "@" .. skill .. "-take", true, true)
        if not to then break end
        candidates:removeOne(to)
        local id = room:askForCardChosen(owner, to, "h", skill)
        room:obtainCard(owner, id, false)
    end
end

hlxg_zhangliao2 = sgs.General(extension_hl, "hlxg_zhangliao2", "qun", 4)
hlxg_mubingCard = sgs.CreateSkillCard {
    name = "hlxg_mubingCard", target_fixed = true, will_throw = false,
    on_use = function(self, room, source, targets)
        local top = room:getNCards(4)
        room:fillAG(top, source)
        local paid = room:askForDiscard(source, "hlxg_mubing", source:getHandcardNum(), 0, true, false, "@hlxg_mubing-discard")
        local budget = 0
        if paid then
            for _, id in sgs.qlist(paid:getSubcards()) do budget = budget + sgs.Sanguosha:getCard(id):getNumber() end
        end
        room:clearAG(source)
        local chosen = sgs.IntList()
        while source:isAlive() and not top:isEmpty() do
            local disabled = sgs.IntList()
            for _, id in sgs.qlist(top) do
                if sgs.Sanguosha:getCard(id):getNumber() > budget then disabled:append(id) end
            end
            if disabled:length() == top:length() then break end
            room:fillAG(top, source, disabled)
            source:setTag("hlxg_mubing_budget", sgs.QVariant(budget))
            local id = room:askForAG(source, top, true, "hlxg_mubing")
            source:removeTag("hlxg_mubing_budget")
            room:clearAG(source)
            if id < 0 or disabled:contains(id) then break end
            top:removeOne(id); chosen:append(id)
            budget = budget - sgs.Sanguosha:getCard(id):getNumber()
        end
        if not chosen:isEmpty() then
            local tracked = gu_names(source, "hlxg_mubing_ids")
            for _, id in sgs.qlist(chosen) do table.insert(tracked, tostring(id)) end
            gu_setnames(source, "hlxg_mubing_ids", tracked)
            room:fillAG(chosen); room:clearAG()
            local cards = gu_dummy(chosen)
            room:obtainCard(source, cards, true); cards:deleteLater()
        end
        if not top:isEmpty() then
            local cards = gu_dummy(top)
            room:throwCard(cards, "hlxg_mubing", nil); cards:deleteLater()
        end
    end,
}
hlxg_mubing = sgs.CreateViewAsSkillV2 {
    name = "hlxg_mubing", limit_scope = sgs.Skill_Limit_Phase, phase_name = "Play", max_usage_limit = 1,
    can_activate = function(self, request) return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY end,
    can_select_card = function() return false end,
    create_card = function(self, request)
        local card = hlxg_mubingCard:clone(); card:setSkillName(self:objectName()); return card
    end,
}
hlxg_diaolingCard = sgs.CreateSkillCard {
    name = "hlxg_diaolingCard", will_throw = false, filter = gu_one, feasible = gu_one_feasible,
    on_use = function(self, room, source, targets)
        local ids = self:getSubcards()
        if ids:isEmpty() then return end
        local numbers = {}
        for _, id in sgs.qlist(ids) do numbers[#numbers + 1] = sgs.Sanguosha:getCard(id):getNumber() end
        table.sort(numbers)
        local consecutive = true
        for i = 2, #numbers do if numbers[i] ~= numbers[i - 1] + 1 then consecutive = false end end
        room:showCard(source, ids)
        room:obtainCard(targets[1], self, true)
        if consecutive then hl208_take_hands(room, source, "hlxg_diaoling", #numbers - 1, false) end
    end,
}
hlxg_diaoling = sgs.CreateViewAsSkillV2 {
    name = "hlxg_diaoling",
    can_activate = function(self, request) return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY end,
    can_select_card = function(self, request, card)
        local p = request:getInitiator()
        return table.contains(gu_names(p, "hlxg_mubing_ids"), tostring(card:getEffectiveId()))
    end,
    card_selection_feasible = function() return true end,
    create_card = function(self, request)
        local card = hlxg_diaolingCard:clone()
        card:addSubcards(request:getSelectedCardIds()); card:setSkillName(self:objectName()); return card
    end,
}
hlxg_mubing_record = gu_record("#hlxg_mubing_record", {sgs.EventPhaseChanging}, function(self, event, room, p, data)
    if data:toPhaseChange().to == sgs.Player_NotActive then
        for _, owner in sgs.qlist(room:getAllPlayers()) do owner:removeTag("hlxg_mubing_ids") end
    end
end)
hlxg_ziqu = gu_trigger("hlxg_ziqu", {sgs.DamageCaused}, function(self, event, room, p, data, owner)
    local damage = data:toDamage()
    if damage.from ~= owner or not damage.to or damage.to == owner
        or owner:getMark("hlxg_ziqu_" .. damage.to:objectName() .. "_lun") > 0
        or not gu_invoke(owner, self:objectName(), data) then return end
    room:setPlayerMark(owner, "hlxg_ziqu_" .. damage.to:objectName() .. "_lun", 1)
    local to = damage.to
    room:showAllCards(to)
    local highest, choices = -1, sgs.IntList()
    for _, c in sgs.qlist(to:getHandcards()) do
        if c:getNumber() > highest then highest = c:getNumber(); choices = sgs.IntList() end
        if c:getNumber() == highest then choices:append(c:getEffectiveId()) end
    end
    if not choices:isEmpty() then
        room:fillAG(choices, to)
        local id = room:askForAG(to, choices, false, "hlxg_ziqu")
        room:clearAG(to); room:obtainCard(owner, id, true)
    end
    return true
end)
