hlxg_qiaobian = gu_trigger("hlxg_qiaobian", {sgs.EventPhaseChanging, sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.EventPhaseStart then
        if p:getPhase() == sgs.Player_Finish and p:getMark("hlxg_qiaobian-Clear") >= 3 then p:drawCards(2, self:objectName()) end
        return
    end
    local phase = data:toPhaseChange().to
    if phase ~= sgs.Player_Judge and phase ~= sgs.Player_Draw and phase ~= sgs.Player_Play and phase ~= sgs.Player_Discard then return end
    if p:isSkipped(phase) or p:isKongcheng() then return end
    p:setTag("hlxg_qiaobian_phase", sgs.QVariant(phase))
    local paid = room:askForDiscard(p, self:objectName(), 1, 1, true, false, "@hlxg_qiaobian-discard")
    p:removeTag("hlxg_qiaobian_phase")
    if not paid then return end
    p:skip(phase); room:addPlayerMark(p, "hlxg_qiaobian-Clear")
    if phase == sgs.Player_Draw then hl208_take_hands(room, p, self:objectName(), 2, true)
    elseif phase == sgs.Player_Play then room:moveField(p, self:objectName(), false, "ej") end
end)
hlxg_zhanghe:addSkill(hlxg_qiaobian)

hlxg_zhanghe2 = sgs.General(extension_hl, "hlxg_zhanghe2", "qun", 4)
hlxg_zhouxuan = gu_trigger("hlxg_zhouxuan", {sgs.EventPhaseStart, sgs.CardFinished, sgs.CardUsed, sgs.CardResponded, sgs.PostCardResponded}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    local pile = "hlxg_zhouxuan_xuan"
    if event == sgs.EventPhaseStart then
        if p:getPhase() ~= sgs.Player_Discard then return end
        local maximum = math.min(p:getHandcardNum(), 5 - p:getPile(pile):length())
        if maximum <= 0 then return end
        local cards = room:askForExchange(p, self:objectName(), maximum, 0, false, "@hlxg_zhouxuan-store", true)
        if cards and not cards:getSubcards():isEmpty() then p:addToPile(pile, cards, true) end
        return
    end
    local card
    if event == sgs.CardResponded or event == sgs.PostCardResponded then
        local response = data:toCardResponse()
        if event == sgs.PostCardResponded and not response.m_isUse then return end
        card = response.m_card
    else card = data:toCardUse().card end
    if not card or card:getTypeId() == sgs.Card_TypeSkill then return end
    if event == sgs.CardFinished or event == sgs.PostCardResponded then
        if not p:getPile(pile):isEmpty() or card:isKindOf("EquipCard") or not gu_invoke(p, self:objectName(), data) then return end
        local ids = card:isVirtualCard() and card:getSubcards() or sgs.IntList()
        if not card:isVirtualCard() then ids:append(card:getEffectiveId()) end
        local available = sgs.IntList()
        for _, id in sgs.qlist(ids) do
            local place = room:getCardPlace(id)
            if place == sgs.Player_PlaceTable or place == sgs.Player_DiscardPile then available:append(id) end
        end
        if not available:isEmpty() then p:addToPile(pile, available, true) end
        return
    end
    local n = p:getPile(pile):length()
    if n == 0 then return end
    local unique = true
    for _, other in sgs.qlist(room:getOtherPlayers(p)) do
        if other:getHandcardNum() >= p:getHandcardNum() then unique = false; break end
    end
    p:drawCards(unique and 1 or n, self:objectName())
    if not p:isAlive() then return end
    for i = 1, (unique and 1 or 2) do
        local ids = p:getPile(pile)
        if ids:isEmpty() then break end
        room:fillAG(ids, p)
        local id = room:askForAG(p, ids, false, self:objectName())
        room:clearAG(p)
        local remove = sgs.IntList(); remove:append(id)
        gu_throw(room, p, remove, self:objectName())
    end
end)
hlxg_zhanghe2:addSkill(hlxg_zhouxuan)

