do
-- c208_04: literal 欢乐 variants.
hlxg_zhangfei = sgs.General(extension_hl, "hlxg_zhangfei", "shu", 4, true)
hljx_zhangfei = sgs.General(extension_hl, "hljx_zhangfei", "shu", 4, true)
hlxg_zhanglu = sgs.General(extension_hl, "hlxg_zhanglu", "qun", 3, true)

hlxg_paoxiao_zhangfei = sgs.CreateTargetModSkillV2 {
    name = "hlxg_paoxiao_zhangfei", pattern = "Slash", frequency = sgs.Skill_Compulsory,
    holder_selector = sgs.CorrectSkill_Primary,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        if p and p:hasSkill(self:objectName()) and ctx:getModType() == sgs.TargetModSkill_Residue then return 1000 end
        return false
    end,
}
hljx_paoxiao = sgs.CreateTargetModSkillV2 {
    name = "hljx_paoxiao", pattern = "Slash", frequency = sgs.Skill_Compulsory,
    holder_selector = sgs.CorrectSkill_Primary,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        if not p or not p:hasSkill(self:objectName()) then return false end
        if ctx:getModType() == sgs.TargetModSkill_Residue then return 1000 end
        if ctx:getModType() == sgs.TargetModSkill_DistanceLimit and p:getPhase() == sgs.Player_Play
            and p:getMark("hljx_paoxiao_used-PlayClear") > 0 then return 1000 end
        return false
    end,
}
local function c208_tishen(name)
    return gu_trigger(name, {sgs.CardFinished, sgs.SlashMissed, sgs.CardUsed}, function(self, event, room, p, data, owner)
        if event == sgs.SlashMissed then
            local effect = data:toSlashEffect()
            if name == "hljx_tishen" and effect.from == owner and owner:getPhase() == sgs.Player_Play then
                room:setPlayerMark(owner, "hljx_tishen_next-PlayClear", 1)
            end
            return
        end
        local use = data:toCardUse()
        if not use.card or not use.card:isKindOf("Slash") then return end
        if event == sgs.CardUsed then
            if name == "hljx_tishen" and use.from == owner and owner:getPhase() == sgs.Player_Play
                and owner:getMark("hljx_tishen_next-PlayClear") > 0 then
                room:setPlayerMark(owner, "hljx_tishen_next-PlayClear", 0)
                room:setCardFlag(use.card, "hljx_tishen_boost")
                local list = use.no_respond_list
                table.insert(list, "_ALL_TARGETS")
                use.no_respond_list = list
                data:setValue(use)
            end
        elseif owner:getPhase() == sgs.Player_NotActive and use.to:contains(owner)
            and not use.card:hasFlag("c208_hit_" .. owner:objectName()) then
            local ids = use.card:isVirtualCard() and use.card:getSubcards() or gu_ids({use.card})
            local available = sgs.IntList()
            for _, id in sgs.qlist(ids) do
                if room:getCardPlace(id) == sgs.Player_PlaceTable then available:append(id) end
            end
            gu_obtain(room, owner, available, name)
        end
    end, true)
end
hlxg_tishen = c208_tishen("hlxg_tishen")
hljx_tishen = c208_tishen("hljx_tishen")
hljx_paoxiao_record = gu_record("#hljx_paoxiao_record", {sgs.CardUsed, sgs.DamageDone, sgs.ConfirmDamage}, function(self, event, room, p, data)
    if event == sgs.DamageDone or event == sgs.ConfirmDamage then
        local d = data:toDamage()
        if not d.card or not d.card:isKindOf("Slash") then return end
        if event == sgs.DamageDone and d.to then room:setCardFlag(d.card, "c208_hit_" .. d.to:objectName()) end
        if event == sgs.ConfirmDamage and d.card:hasFlag("hljx_tishen_boost") then
            d.damage = d.damage + 1
            data:setValue(d)
        end
    else
        local use = data:toCardUse()
