    if event == sgs.EventPhaseStart then
        if p ~= owner or owner:getPhase() ~= sgs.Player_Finish or not room:askForSkillInvoke(owner, self:objectName(), data) then return end
        owner:drawCards(2, self:objectName())
        if owner:isAlive() and not owner:isNude() then
            local cards = room:askForExchange(owner, self:objectName(), 2, 2, true, "@hlxg_yishe")
            if cards then owner:addToPile("hlxg_yishe_rice", cards) end
        end
    else
        local move = data:toMoveOneTime()
        if not move.from or move.from:objectName() ~= owner:objectName() or not owner:getPile("hlxg_yishe_rice"):isEmpty() then return end
        for i = 0, move.card_ids:length() - 1 do
            if move.from_places:at(i) == sgs.Player_PlaceSpecial and move.from_pile_names:at(i) == "hlxg_yishe_rice" then
                local recover = sgs.RecoverStruct()
                recover.who = owner
                room:recover(owner, recover)
                break
            end
        end
    end
end)
local function c208_rice(room, owner, reason, optional)
    local pile = owner:getPile("hlxg_yishe_rice")
    if pile:isEmpty() then return -1 end
    room:fillAG(pile, owner)
    local id = room:askForAG(owner, pile, optional, reason)
    room:clearAG(owner)
    return id
end
hlxg_bushi = gu_trigger("hlxg_bushi", {sgs.Damaged, sgs.Damage}, function(self, event, room, p, data, owner)
    local d = data:toDamage()
    local target
    if event == sgs.Damaged and d.to == owner then target = owner end
    if event == sgs.Damage and d.from == owner and d.to ~= owner then target = d.to end
    if not target then return end
    for i = 1, d.damage do
        if not owner:isAlive() or not target:isAlive() or owner:getPile("hlxg_yishe_rice"):isEmpty() then break end
        if room:askForSkillInvoke(owner, self:objectName(), sgs.QVariant(target)) then
            local id = c208_rice(room, owner, self:objectName(), false)
            if id >= 0 then room:obtainCard(target, id, false) end
        end
    end
end)
hlxg_midao = gu_trigger("hlxg_midao", {sgs.AskForRetrial}, function(self, event, room, p, data, owner)
    if owner:getPile("hlxg_yishe_rice"):isEmpty() or not room:askForSkillInvoke(owner, self:objectName(), data) then return end
    owner:setTag("hlxg_midao_judge", data)
    local id = c208_rice(room, owner, self:objectName(), true)
    owner:removeTag("hlxg_midao_judge")
    if id < 0 then return end
    local judge = data:toJudge()
    room:retrial(sgs.Sanguosha:getCard(id), owner, judge, self:objectName())
    if owner:isAlive() then owner:drawCards(1, self:objectName()) end
end)
