        if player ~= owner or (owner:getPhase() ~= sgs.Player_Start and owner:getPhase() ~= sgs.Player_Finish) then return false end
        local card = room:askForCard(owner, "^BasicCard", "@hlxg_jujian-discard", data,
            sgs.Card_MethodDiscard, nil, false, self:objectName())
        if not card or not owner:isAlive() then return false end
