        if choice == "draw" then target:drawCards(2, self:objectName())
        elseif choice == "recover" then room:recover(target, sgs.RecoverStruct(self:objectName(), owner, 1))
        else
            if not target:faceUp() then target:turnOver() end
            if target:isChained() then room:setPlayerChained(target, false, owner) end
        end
        return false
    end)
