-- Temporary removal is represented by a private special pile, returned at turn end.
local function hl_pojun_effect(self, event, room, player, data, owner)
    local name = self:objectName()
    if event == sgs.DamageCaused then
        local d = data:toDamage()
        if d.from == owner and d.to and d.card and d.card:isKindOf("Slash")
            and d.to:getHandcardNum() <= owner:getHandcardNum()
            and d.to:getEquips():length() <= owner:getEquips():length() then
            d.damage = d.damage + 1
            data:setValue(d)
        end
        return false
    end
    local use = data:toCardUse()
    if use.from ~= owner or not use.card or not use.card:isKindOf("Slash") then return false end
    for _, target in sgs.qlist(use.to) do
        if not owner:isAlive() then break end
        local maximum = math.min(target:getHp(), target:getCards("hej"):length())
        if target:isAlive() and maximum > 0 and gu_invoke(owner, name, sgs.QVariant(target)) then
            local ids = sgs.IntList()
            for i = 1, maximum do
                local id = room:askForCardChosen(owner, target, "hej", name, false, sgs.Card_MethodNone, ids, true)
                if id < 0 then break end
                ids:append(id)
            end
            if not ids:isEmpty() then
                local equips = sgs.IntList()
                local has_jink = false
                for _, id in sgs.qlist(ids) do
                    local card = sgs.Sanguosha:getCard(id)
                    if card:isKindOf("EquipCard") then equips:append(id) end
                    if card:isKindOf("Jink") then has_jink = true end
                end
                target:addToPile(name, ids, false)
                if not equips:isEmpty() then
                    room:fillAG(equips, owner)
                    local id = room:askForAG(owner, equips, false, name)
                    room:clearAG(owner)
                    room:throwCard(id, name, target, owner)
                end
                if has_jink and owner:isAlive() then owner:drawCards(1, name) end
            end
        end
    end
    return false
end
hlxg_pojun = gu_trigger("hlxg_pojun", {sgs.TargetSpecified}, hl_pojun_effect)
hljx_pojun = gu_trigger("hljx_pojun", {sgs.TargetSpecified, sgs.DamageCaused}, hl_pojun_effect)
local function hl_return_pojun(self, event, room, player, data)
    if data:toPhaseChange().to ~= sgs.Player_NotActive then return end
    for _, target in sgs.qlist(room:getAllPlayers()) do
        local ids = target:getPile(self:objectName():sub(2):gsub("_return$", ""))
        if not ids:isEmpty() then gu_obtain(room, target, ids, self:objectName()) end
    end
end
hlxg_pojun_return = gu_record("#hlxg_pojun_return", {sgs.EventPhaseChanging}, hl_return_pojun)
hljx_pojun_return = gu_record("#hljx_pojun_return", {sgs.EventPhaseChanging}, hl_return_pojun)

hlxg_jiedao = gu_trigger("hlxg_jiedao", {sgs.DamageCaused}, function(self, event, room, player, data, owner)
    local d = data:toDamage()
    if d.from ~= owner or not d.to or owner:getMark("hlxg_jiedao-Clear") > 0 then return false end
    if not gu_invoke(owner, self:objectName(), data) then return false end
    room:addPlayerMark(owner, "hlxg_jiedao-Clear")
    local choices = {}
    for i = 0, math.max(1, owner:getLostHp()) do choices[#choices + 1] = tostring(i) end
    local n = tonumber(room:askForChoice(owner, self:objectName(), table.concat(choices, "+"), data)) or 0
    d.damage = d.damage + n
    local tips = d.tips
    table.insert(tips, "hlxg_jiedao:" .. n .. ":" .. owner:objectName())
    d.tips = tips
    data:setValue(d)
    return false
end)
hlxg_jiedao_payment = gu_record("#hlxg_jiedao_payment", {sgs.DamageComplete}, function(self, event, room, player, data)
    local d = data:toDamage()
    if not d.to or not d.to:isAlive() then return end
    for _, tip in ipairs(d.tips) do
        local n, source = tip:match("^hlxg_jiedao:(%d+):(.+)$")
        if n and tonumber(n) > 0 then
            for _, p in sgs.qlist(room:getAlivePlayers()) do
                if p:objectName() == source then
                    room:askForDiscard(p, "hlxg_jiedao", tonumber(n), tonumber(n), false, true)
                    break
                end
            end
        end
    end
end)

