hlxg_xizhicai = sgs.General(extension_hl, "hlxg_xizhicai", "wei", 3)
hlxg_xianfu = gu_trigger("hlxg_xianfu", {sgs.GameStart, sgs.Damaged, sgs.HpRecover},
    function(self, event, room, player, data, owner)
        if event == sgs.GameStart then
            if player ~= owner then return end
            local chosen = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@hlxg_xianfu", false, true)
            if chosen then owner:setTag("hlxg_xianfu_target", sgs.QVariant(chosen:objectName())) end
        elseif player and owner:getTag("hlxg_xianfu_target"):toString() == player:objectName() then
            if event == sgs.Damaged and player:isAlive() then
                room:damage(sgs.DamageStruct(self:objectName(), owner, owner, data:toDamage().damage, sgs.DamageStruct_Normal))
            elseif event == sgs.HpRecover then
                local recover = sgs.RecoverStruct()
                recover.who = owner; recover.recover = data:toRecover().recover
                room:recover(owner, recover)
            end
        end
    end, true)
hlxg_chouce = gu_trigger("hlxg_chouce", {sgs.Damaged},
    function(self, event, room, player, data, owner)
        if player ~= owner then return end
        for i = 1, data:toDamage().damage do
            if not owner:isAlive() or not gu_invoke(owner, self:objectName(), data) then break end
            local judge = sgs.JudgeStruct()
            judge.who = owner; judge.reason = self:objectName(); judge.pattern = ".|red"; judge.good = true
            room:judge(judge)
            if not owner:isAlive() then break end
            if judge.card:isBlack() then
                local candidates = sgs.SPlayerList()
                for _, p in sgs.qlist(room:getAlivePlayers()) do
                    if not p:getCards("hej"):isEmpty() then candidates:append(p) end
                end
                if not candidates:isEmpty() then
                    local chosen = room:askForPlayerChosen(owner, candidates, "hlxg_chouce_black", "@hlxg_chouce_black", false, true)
                    local id = room:askForCardChosen(owner, chosen, "hej", self:objectName())
                    room:obtainCard(owner, id, false)
                end
            elseif judge.card:isRed() then
                local chosen = room:askForPlayerChosen(owner, room:getAlivePlayers(), "hlxg_chouce_red", "@hlxg_chouce_red", false, true)
                if chosen then
                    local n = owner:getTag("hlxg_xianfu_target"):toString() == chosen:objectName() and 2 or 1
                    chosen:drawCards(n, self:objectName())
                end
            end
        end
    end)
