    on_use = function(self, room, source, targets)
        room:setPlayerMark(source, "hlxg_xieju-PlayClear", 1)
        for _, p in ipairs(targets) do
            if p:isAlive() then room:askForUseCardWithBorrowedSkill(p, "hlxg_xieju", "hlxg_xieju", "@hlxg_xieju_slash", -1, sgs.Card_MethodUse, false) end
        end
    end,
}
hlxg_xieju = sgs.CreateViewAsSkillV2 {
    name = "hlxg_xieju", response_or_use = true,
    can_activate = function(self, request)
        return request:getPattern() == "@@hlxg_xieju"
            or (request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
                and request:getInitiator():getMark("hlxg_xieju-PlayClear") == 0)
    end,
    can_select_card = function() return false end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function(self, request)
        if request:getPattern() == "@@hlxg_xieju" then
            local slash = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0)
            slash:setSkillName("_hlxg_xieju")
            return slash
        end
        local card = hlxg_xiejuCard:clone(); card:setSkillName("hlxg_xieju"); return card
    end,
}
