hlxg_huiqi = gu_trigger("hlxg_huiqi", {sgs.EventPhaseChanging},
    function(self, event, room, player, data, owner)
        if data:toPhaseChange().to ~= sgs.Player_NotActive or owner:getMark(self:objectName()) > 0
            or owner:getMark("hlxg_huiqi_target") == 0 then return end
        local n = 0
        for _, p in sgs.qlist(room:getAllPlayers()) do
            if p:getMark("hlxg_huiqi_target") > 0 then n = n + 1 end
        end
        if n ~= 3 then return end
        room:setPlayerMark(owner, self:objectName(), 1)
        local recover = sgs.RecoverStruct(); recover.who = owner; recover.recover = 1
        room:recover(owner, recover)
        room:acquireSkill(owner, "hlxg_xieju")
        if owner:isAlive() then owner:gainAnExtraTurn() end
    end, true, sgs.Skill_Wake)
hlxg_guangao = gu_trigger("hlxg_guangao", {sgs.CardUsed},
    function(self, event, room, player, data, owner)
        local use = data:toCardUse()
        if not use.card or not use.card:isKindOf("Slash") or not use.from then return end
        if use.from ~= owner and not use.to:contains(owner) and not use.from:isProhibited(owner, use.card)
            and use.from:askForSkillInvoke(self:objectName(), sgs.QVariant(owner)) then
            use.to:append(owner)
            room:sortByActionOrder(use.to)
            data:setValue(use)
        end
        if (use.from == owner or use.to:contains(owner)) and owner:getHandcardNum() % 2 == 0 then
            owner:drawCards(1, self:objectName())
            if owner:isAlive() then
                local chosen = room:askForPlayersChosen(owner, use.to, "hlxg_guangao_nullify", 0, use.to:length(), "@hlxg_guangao_nullify", true, true)
                local nullified = use.nullified_list
                for _, p in sgs.qlist(chosen) do table.insert(nullified, p:objectName()) end
                use.nullified_list = nullified
                data:setValue(use)
            end
        end
    end)
hlxg_guangao_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_guangao_mod", pattern = "Slash", holder_selector = sgs.CorrectSkill_Primary,
    correct_func = function(self, ctx)
        local from = ctx:getPrimary()
        if ctx:getModType() == sgs.TargetModSkill_ExtraTarget and from and from:hasSkill("hlxg_guangao") then return 1 end
        return 0
    end,
}
