-- c208_08: literal Cao Ren variants.
local function c208_08_jushou(name)
    return gu_trigger(name, {sgs.EventPhaseStart}, function(self, event, room, player, data, owner)
        if player ~= owner or owner:getPhase() ~= sgs.Player_Finish or not gu_invoke(owner, name) then return end
        owner:turnOver()
        if not owner:isAlive() then return end
        owner:drawCards(4, name)
        if owner:isAlive() then room:askForUseCard(owner, "EquipCard", "@" .. name .. "-equip") end
    end)
end
hlxg_jushou = c208_08_jushou("hlxg_jushou")
hljx_jushou = c208_08_jushou("hljx_jushou")

hljx_jiewei = sgs.CreateViewAsSkillV2 {
    name = "hljx_jiewei", n = 1, response_or_use = true,
    can_activate = function(self, request)
        return request:getReason() ~= sgs.CardUseStruct_CARD_USE_REASON_PLAY
            and request:getPattern() == "nullification" and not request:getInitiator():getEquips():isEmpty()
    end,
    can_select_card = function(self, request, card)
        return request:getSelectedCardIds():isEmpty() and not card:hasFlag("using")
            and request:getInitiator():getEquips():contains(card)
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        local material = sgs.Sanguosha:getCard(request:getSelectedCardIds():first())
        local card = sgs.Sanguosha:cloneCard("nullification", material:getSuit(), material:getNumber())
        card:addSubcards(request:getSelectedCardIds()); card:setSkillName("hljx_jiewei")
        return card
    end,
}
hljx_jiewei.response_pattern = "nullification"

hljx_jiewei_turn = sgs.CreateTriggerSkillV2 {
    name = "#hljx_jiewei_turn", events = {sgs.TurnedOver},
    can_trigger = function(self, event, room, player, data)
        if player and player:isAlive() and player:hasSkill("hljx_jiewei") and player:faceUp()
            and player:canDiscard(player, "he") then return self:objectName(), player end
        return false
    end,
    on_cost = function(self, event, room, player, ctx)
        return room:askForDiscard(player, "hljx_jiewei", 1, 1, true, true, "@hljx_jiewei-discard") ~= nil
    end,
    on_effect = function(self, event, room, player, ctx)
        if player:isAlive() then room:moveField(player, "hljx_jiewei", true, "ej") end
        return false
    end,
}

hlxg_weikui = gu_active("hlxg_weikui", 1, 0, 0,
    function(self, targets, to, from) return gu_one(self, targets, to, from) and not to:isKongcheng() end,
    gu_one_feasible,
    function(self, room, source, targets)
        local target = targets[1]
        room:loseHp(source, 1, true, source, "hlxg_weikui")
        if not source:isAlive() or not target:isAlive() then return end
        room:showAllCards(target, source)
        local has_jink = false
        for _, card in sgs.qlist(target:getHandcards()) do
            if card:isKindOf("Jink") then has_jink = true; break end
        end
        if has_jink then
            if not target:isKongcheng() then
                local id = room:askForCardChosen(source, target, "h", "hlxg_weikui", false, sgs.Card_MethodNone)
                room:obtainCard(source, id, false)
            end
            if source:isAlive() then
                local recover = sgs.RecoverStruct(); recover.who = source; recover.recover = 1
                room:recover(source, recover)
            end
        else
            local names = gu_names(source, "hlxg_weikui_targets")
            if not table.contains(names, target:objectName()) then
                table.insert(names, target:objectName())
                gu_setnames(source, "hlxg_weikui_targets", names)
                room:setFixedDistance(source, target, 1)
            end
            local slash = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0)
            slash:setSkillName("hlxg_weikui")
            if not source:isProhibited(target, slash) then
                local use = sgs.CardUseStruct(); use.card = slash; use.from = source; use.to:append(target)
                room:useCard(use, true)
            end
            slash:deleteLater()
        end
    end)
-- Remove only the fixed-distance contribution installed by this skill.
hlxg_weikui_clear = gu_record("#hlxg_weikui_clear", {sgs.EventPhaseChanging, sgs.Death},
    function(self, event, room, player, data)
        if not player then return end
        if event == sgs.EventPhaseChanging and data:toPhaseChange().to ~= sgs.Player_NotActive then return end
        if event == sgs.Death and data:toDeath().who ~= player then return end
        for _, name in ipairs(gu_names(player, "hlxg_weikui_targets")) do
            local target = room:findPlayerByObjectName(name, true)
            if target then room:removeFixedDistance(player, target, 1) end
        end
        player:removeTag("hlxg_weikui_targets")
    end)

hlxg_lizhan = gu_trigger("hlxg_lizhan", {sgs.EventPhaseStart}, function(self, event, room, player, data, owner)
    if player ~= owner or owner:getPhase() ~= sgs.Player_Finish then return end
    local candidates = sgs.SPlayerList()
    for _, target in sgs.qlist(room:getAlivePlayers()) do
        if target:isWounded() then candidates:append(target) end
    end
    if candidates:isEmpty() then return end
    local chosen = room:askForPlayersChosen(owner, candidates, "hlxg_lizhan", 0, candidates:length(), "@hlxg_lizhan", true, true)
    if chosen:isEmpty() then return end
    for _, target in sgs.qlist(chosen) do
        if target:isAlive() then target:drawCards(1, "hlxg_lizhan") end
    end
    local x = 0
    for _, target in sgs.qlist(chosen) do
        if target:getHandcardNum() == target:getHp() then x = x + 1 end
    end
    if owner:isAlive() and x > 0 then owner:drawCards(x, "hlxg_lizhan") end
end)

