-- c208_09: 曹休（欢乐杀修改）
hlxg_caoxiu = sgs.General(extension_hl, "hlxg_caoxiu", "wei", 4)

hlxg_qianju = sgs.CreateDistanceSkillV2 {
    name = "hlxg_qianju", frequency = sgs.Skill_Compulsory,
    holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local from = ctx:getPrimary()
        if from and from:hasSkill(self:objectName()) and from:getLostHp() > 0 then
            return -from:getLostHp()
        end
        return false
    end,
}

hlxg_qingxi = gu_trigger("hlxg_qingxi", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if use.from ~= owner or p ~= owner or not use.card
        or not (use.card:isKindOf("Slash") or use.card:isKindOf("Duel")) then return end
    for _, target in sgs.qlist(use.to) do
        if owner:isAlive() and target:isAlive()
            and gu_invoke(owner, self:objectName(), sgs.QVariant(target)) then
            local n = 0
            for _, other in sgs.qlist(room:getOtherPlayers(owner)) do
                if owner:inMyAttackRange(other) then n = n + 1 end
            end
            n = math.min(n, owner:getWeapon() and 4 or 2)
            local available = 0
            for _, card in sgs.qlist(target:getHandcards()) do
                if not target:isJilei(card) then available = available + 1 end
            end
            local choices = available >= n and "discard+damage" or "damage"
            target:setTag("hlxg_qingxi_count", sgs.QVariant(n))
            local choice = room:askForChoice(target, self:objectName(), choices, sgs.QVariant(owner))
            target:removeTag("hlxg_qingxi_count")
            if choice == "discard" then
                if n > 0 then
                    room:askForDiscard(target, self:objectName(), n, n, false, false,
                        "@hlxg_qingxi-discard::" .. tostring(n))
                end
                local weapon = owner:getWeapon()
                if weapon then room:throwCard(weapon, owner, target) end
            else
                use.card:setTag("hlxg_qingxi_" .. target:objectName(), sgs.QVariant(true))
                local judge = sgs.JudgeStruct()
                judge.who = target; judge.reason = self:objectName()
                judge.pattern = ".|red"; judge.good = true
                room:judge(judge)
                if judge.card and judge.card:isRed() then
                    local names = use.no_respond_list
                    if not table.contains(names, target:objectName()) then
                        table.insert(names, target:objectName())
                    end
                    use.no_respond_list = names
                    data:setValue(use)
                elseif judge.card and judge.card:isBlack() and owner:isAlive() then
                    owner:drawCards(2, self:objectName())
                end
            end
        end
    end
end)

-- Record the card's effect independently of whether its user still has the skill.
hlxg_qingxi_effect = gu_record("#hlxg_qingxi_effect", {sgs.DamageCaused, sgs.CardFinished},
    function(self, event, room, p, data)
        if event == sgs.DamageCaused then
            local damage = data:toDamage()
            if damage.card and damage.to
                and damage.card:getTag("hlxg_qingxi_" .. damage.to:objectName()):toBool() then
                damage.damage = damage.damage + 1
                data:setValue(damage)
            end
        else
            local use = data:toCardUse()
            if use.card then
                for _, target in sgs.qlist(room:getAllPlayers(true)) do
                    use.card:removeTag("hlxg_qingxi_" .. target:objectName())
                end
            end
        end
    end)
hlxg_caoxiu:addSkill(hlxg_qingxi)
hlxg_caoxiu:addSkill(hlxg_qingxi_effect)
hlxg_caoxiu:addSkill(hlxg_qianju)
