-- c209_01: literal 欢乐杀修改 variants.
hlxg_caochong = sgs.General(extension_hl, "hlxg_caochong", "wei", 3)
hlxg_caorui = sgs.General(extension_hl, "hlxg_caorui", "wei", 3)
hlxg_caoying = sgs.General(extension_hl, "hlxg_caoying", "wei", 4, false)

hlxg_renxin = sgs.CreateRuleSkillV2 {
    name = "hlxg_renxin", events = {sgs.DamageInflicted}, global = true,
    can_trigger = function(self, event, room, p, data)
        if not p or p:getHp() ~= 1 then return false end
        for _, owner in sgs.qlist(room:getOtherPlayers(p)) do
            if owner:hasSkill(self:objectName()) then return self:objectName(), owner end
        end
        return false
    end,
    on_effect = function(self, event, room, p, ctx)
        for _, owner in sgs.qlist(room:getOtherPlayers(p)) do
            if owner:hasSkill(self:objectName()) then
                local card = room:askForCard(owner, ".Equip", "@hlxg_renxin:" .. p:objectName(), ctx.original_data, sgs.Card_MethodNone, nil, false, self:objectName())
                if card and owner:canDiscard(owner, card:getEffectiveId()) then
                    owner:turnOver()
                    room:throwCard(card, self:objectName(), owner)
                    return true
                end
            end
        end
        return false
    end,
}
hlxg_chengxiang = gu_trigger("hlxg_chengxiang", {sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    local ids = room:getNCards(4)
    local all = gu_dummy(ids)
    room:moveCardTo(all, nil, sgs.Player_PlaceTable, true)
    all:deleteLater()
    local picked, sum = sgs.IntList(), 0
    room:fillAG(ids)
    while owner:isAlive() do
        local enabled = sgs.IntList()
        for _, id in sgs.qlist(ids) do
            if not picked:contains(id) and sum + sgs.Sanguosha:getCard(id):getNumber() <= 13 then enabled:append(id) end
        end
        if enabled:isEmpty() then break end
        local id = room:askForAG(owner, enabled, true, self:objectName())
        if not enabled:contains(id) then break end
        picked:append(id); sum = sum + sgs.Sanguosha:getCard(id):getNumber()
        room:takeAG(owner, id, false)
    end
    room:clearAG()
    if owner:isAlive() then gu_obtain(room, owner, picked, self:objectName()) end
    local rest = sgs.IntList()
    for _, id in sgs.qlist(ids) do
        if room:getCardPlace(id) == sgs.Player_PlaceTable then rest:append(id) end
    end
    if not rest:isEmpty() then
        local c = gu_dummy(rest)
        room:throwCard(c, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_NATURAL_ENTER, owner:objectName(), self:objectName(), ""), nil)
        c:deleteLater()
    end
end, true)

hlxg_xingshuai = gu_trigger("hlxg_xingshuai$", {sgs.Dying}, function(self, event, room, p, data, owner)
    if data:toDying().who ~= owner or not owner:hasLordSkill(self:objectName()) or owner:getMark("@hlxg_xingshuai") == 0 then return end
    if not gu_invoke(owner, self:objectName(), data) then return end
    room:removePlayerMark(owner, "@hlxg_xingshuai")
    local names = {}
    for _, other in sgs.qlist(room:getOtherPlayers(owner)) do
        if other:getKingdom() == "wei" and room:askForChoice(other, "hlxg_xingshuai", "yes+no", sgs.QVariant(owner)) == "yes" then
            table.insert(names, other:objectName())
            local recover = sgs.RecoverStruct(); recover.who = other; recover.recover = 1
            room:recover(owner, recover)
        end
    end
    gu_setnames(owner, "hlxg_xingshuai_pending", names)
end, false, sgs.Skill_Limited, "@hlxg_xingshuai")
hlxg_xingshuai_settle = gu_record("#hlxg_xingshuai_settle", {sgs.QuitDying}, function(self, event, room, p, data)
    if not p then return end
    local names = gu_names(p, "hlxg_xingshuai_pending")
    p:removeTag("hlxg_xingshuai_pending")
    for _, name in ipairs(names) do
        local other = room:findPlayerByObjectName(name)
        if other and other:isAlive() then
            local damage = sgs.DamageStruct(); damage.to = other; damage.damage = 1; damage.reason = "hlxg_xingshuai"
            room:damage(damage)
            if other:isAlive() then other:drawCards(1, "hlxg_xingshuai") end
        end
    end
end)
hlxg_huituo = gu_trigger("hlxg_huituo", {sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    local to = room:askForPlayerChosen(owner, room:getAlivePlayers(), self:objectName(), "@hlxg_huituo", true, true)
    if not to then return end
    local n = data:toDamage().damage
    local judge = sgs.JudgeStruct(); judge.who = to; judge.reason = self:objectName(); judge.pattern = ".|red"; judge.good = true
    room:judge(judge)
    if not to:isAlive() or not judge.card then return end
    if judge.card:isRed() then
        local recover = sgs.RecoverStruct(); recover.who = owner; room:recover(to, recover)
    elseif judge.card:isBlack() then to:drawCards(n, self:objectName()) end
end)
hlxg_mingjian = gu_active("hlxg_mingjian", 1, 0, 2147483647, gu_one, gu_one_feasible,
    function(self, room, source, targets)
        if not self:getSubcards():isEmpty() then room:obtainCard(targets[1], self, false) end
        room:addPlayerMark(targets[1], "hlxg_mingjian_pending")
    end,
    function(request, c) return not request:getInitiator():isEquipped(c) end)
hlxg_mingjian_turn = gu_record("#hlxg_mingjian_turn", {sgs.TurnStart, sgs.EventPhaseChanging}, function(self, event, room, p, data)
    if not p then return end
    if event == sgs.TurnStart then
        room:setPlayerMark(p, "hlxg_mingjian_active", p:getMark("hlxg_mingjian_pending"))
        room:setPlayerMark(p, "hlxg_mingjian_pending", 0)
    elseif data:toPhaseChange().to == sgs.Player_NotActive then room:setPlayerMark(p, "hlxg_mingjian_active", 0) end
end)
hlxg_mingjian_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_mingjian_max", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx) return ctx:getPrimary():getMark("hlxg_mingjian_active") end,
}
hlxg_mingjian_slash = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_mingjian_slash", pattern = "Slash", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        if ctx:getModType() == sgs.TargetModSkill_Residue then return ctx:getPrimary():getMark("hlxg_mingjian_active") end
        return 0
    end,
}

hlxg_fujian = gu_trigger("hlxg_fujian", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or (p:getPhase() ~= sgs.Player_Start and p:getPhase() ~= sgs.Player_Finish) then return end
    local candidates = sgs.SPlayerList()
    for _, other in sgs.qlist(room:getOtherPlayers(owner)) do if not other:isKongcheng() then candidates:append(other) end end
    if candidates:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_fujian", false, true)
    local id = room:askForCardChosen(owner, to, "h", self:objectName())
    room:showCard(to, id, owner)
end, true)
hlxg_lingren = gu_trigger("hlxg_lingren", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or owner:getPhase() ~= sgs.Player_Play or owner:getMark("hlxg_lingren-PlayClear") > 0
        or not use.card or not (use.card:isKindOf("Slash") or (use.card:isKindOf("TrickCard") and use.card:isDamageCard())) then return end
    local candidates = sgs.SPlayerList()
    for _, to in sgs.qlist(use.to) do if to ~= owner then candidates:append(to) end end
    if candidates:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_lingren", true, true)
    if not to then return end
    room:setPlayerMark(owner, "hlxg_lingren-PlayClear", 1)
    local guesses = {}
    for _, kind in ipairs({"basic", "trick", "equip"}) do
        guesses[kind] = room:askForChoice(owner, self:objectName(), kind .. "_yes+" .. kind .. "_no", sgs.QVariant(to)) == kind .. "_yes"
    end
    local has = {basic = false, trick = false, equip = false}
    for _, c in sgs.qlist(to:getHandcards()) do
        if c:isKindOf("BasicCard") then has.basic = true
        elseif c:isKindOf("TrickCard") then has.trick = true
        elseif c:isKindOf("EquipCard") then has.equip = true end
    end
    room:showAllCards(to, owner)
    local correct = 0
    for kind, guess in pairs(guesses) do if guess == has[kind] then correct = correct + 1 end end
    if correct >= 1 then room:setCardFlag(use.card, "hlxg_lingren_" .. to:objectName()) end
    if correct >= 2 then owner:drawCards(2, self:objectName()) end
    if correct == 3 then
        for _, skill in ipairs({"hlxg_jianxiong_caoying", "hlxg_xingshang_caoying"}) do
            if not owner:hasSkill(skill, true) then
                room:acquireSkill(owner, skill)
                room:setPlayerMark(owner, skill .. "_temporary", 1)
            end
        end
    end
end)
hlxg_lingren_effect = gu_record("#hlxg_lingren_effect", {sgs.DamageCaused, sgs.CardFinished, sgs.TurnStart}, function(self, event, room, p, data)
    if event == sgs.DamageCaused then
        local d = data:toDamage()
        if d.card and d.to and d.card:hasFlag("hlxg_lingren_" .. d.to:objectName()) then
            d.damage = d.damage + 1; data:setValue(d)
        end
    elseif event == sgs.CardFinished then
        local card = data:toCardUse().card
        if card then for _, to in sgs.qlist(room:getAllPlayers(true)) do room:setCardFlag(card, "-hlxg_lingren_" .. to:objectName()) end end
    elseif p then
        for _, skill in ipairs({"hlxg_jianxiong_caoying", "hlxg_xingshang_caoying"}) do
            if p:getMark(skill .. "_temporary") > 0 then
                room:setPlayerMark(p, skill .. "_temporary", 0)
                room:detachSkillFromPlayer(p, skill, false, true)
            end
        end
    end
end)
hlxg_jianxiong_caoying = gu_trigger("hlxg_jianxiong_caoying", {sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner or not gu_invoke(owner, self:objectName(), data) then return end
    local card = data:toDamage().card
    if card then
        local ids = card:isVirtualCard() and card:getSubcards() or gu_ids({card})
        local available = not ids:isEmpty()
        for _, id in sgs.qlist(ids) do if room:getCardPlace(id) ~= sgs.Player_PlaceTable then available = false end end
        if available then room:obtainCard(owner, card, true) end
    end
    owner:drawCards(1, self:objectName())
end)
hlxg_xingshang_caoying = gu_trigger("hlxg_xingshang_caoying", {sgs.Death}, function(self, event, room, p, data, owner)
    local dead = data:toDeath().who
    if dead == owner or not dead or not gu_invoke(owner, self:objectName(), data) then return end
    local ids = gu_ids(sgs.QList2Table(dead:getCards("hej")))
    for _, pile in sgs.qlist(dead:getPileNames()) do
        for _, id in sgs.qlist(dead:getPile(pile)) do if not ids:contains(id) then ids:append(id) end end
    end
    gu_obtain(room, owner, ids, self:objectName())
    owner:drawCards(1, self:objectName())
end)

hlxg_caochong:addSkill(hlxg_renxin); hlxg_caochong:addSkill(hlxg_chengxiang)
hlxg_caorui:addSkill(hlxg_xingshuai); hlxg_caorui:addSkill(hlxg_huituo); hlxg_caorui:addSkill(hlxg_mingjian)
hlxg_caoying:addSkill(hlxg_fujian); hlxg_caoying:addSkill(hlxg_lingren)
for _, skill in ipairs({hlxg_xingshuai_settle, hlxg_mingjian_turn, hlxg_mingjian_max, hlxg_mingjian_slash, hlxg_lingren_effect, hlxg_jianxiong_caoying, hlxg_xingshang_caoying}) do extension_hl:addSkills(skill) end
for _, pair in ipairs({{"hlxg_xingshuai", "#hlxg_xingshuai_settle"}, {"hlxg_mingjian", "#hlxg_mingjian_turn"}, {"hlxg_mingjian", "#hlxg_mingjian_max"}, {"hlxg_mingjian", "#hlxg_mingjian_slash"}, {"hlxg_lingren", "#hlxg_lingren_effect"}}) do extension_hl:insertRelatedSkills(pair[1], pair[2]) end

