hlxg_caoanmin = sgs.General(extension_hl, "hlxg_caoanmin", "wei", 4)
hlxg_xianwei = gu_trigger("hlxg_xianwei", {sgs.EventPhaseStart, sgs.ThrowEquipArea}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.ThrowEquipArea then
        if owner:hasEquipArea() or owner:getMark("hlxg_xianwei_complete") > 0 then return end
        room:setPlayerMark(owner, "hlxg_xianwei_complete", 1)
        room:gainMaxHp(owner, 2, self:objectName())
        for _, q in sgs.qlist(room:getAllPlayers(true)) do
            if q ~= owner then
                room:insertAttackRangePair(owner, q)
                room:insertAttackRangePair(q, owner)
            end
        end
        return
    end
    if owner:getPhase() ~= sgs.Player_Start or not owner:hasEquipArea() then return end
    local choices = {}
    for i = 0, 4 do if owner:hasEquipArea(i) then table.insert(choices, tostring(i)) end end
    local area = tonumber(room:askForChoice(owner, self:objectName(), table.concat(choices, "+")))
    owner:throwEquipArea(area)
    local n = 1
    for i = 0, 4 do if owner:hasEquipArea(i) then n = n + 1 end end
    owner:drawCards(n, self:objectName())
    if owner:isDead() then return end
    -- Snapshot the current draw pile: no match means reveal it all, without reshuffling forever.
    local pile = sgs.QList2Table(room:getDrawPile())
    local revealed, match = sgs.IntList(), nil
    for _, id in ipairs(pile) do
        local c = sgs.Sanguosha:getCard(id)
        room:moveCardTo(c, nil, sgs.Player_PlaceTable, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_TURNOVER, owner:objectName(), self:objectName(), ""), true)
        revealed:append(id)
        if c:isKindOf("EquipCard") and c:getRealCard():toEquipCard():location() == area then match = c; break end
    end
    local others = room:getOtherPlayers(owner)
    if not others:isEmpty() then
        local q = room:askForPlayerChosen(owner, others, self:objectName(), "@hlxg_xianwei-use")
        if match then
            if q:canUse(match, q, true) then room:useCard(sgs.CardUseStruct(match, q, q)) end
        else q:drawCards(1, self:objectName()) end
    end
    local remaining = sgs.IntList()
    for _, id in sgs.qlist(revealed) do
        if room:getCardPlace(id) == sgs.Player_PlaceTable then remaining:append(id) end
    end
    if not remaining:isEmpty() then
        local dummy = gu_dummy(remaining)
        room:moveCardTo(dummy, nil, sgs.Player_DiscardPile, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_NATURAL_ENTER, owner:objectName(), self:objectName(), ""), true)
        dummy:deleteLater()
    end
end, true)
hlxg_caoanmin:addSkill(hlxg_xianwei)

hlxg_caozhang = sgs.General(extension_hl, "hlxg_caozhang", "wei", 4)
hlxg_jiangchi = gu_trigger("hlxg_jiangchi", {sgs.EventPhaseStart, sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.Damaged then
        if owner:getMark("hlxg_jiangchi_guard") > 0 then owner:drawCards(1, self:objectName()) end
        return
    end
    if owner:getPhase() ~= sgs.Player_Play or not gu_invoke(owner, self:objectName(), data) then return end
    room:setPlayerMark(owner, "hlxg_jiangchi_guard", 0)
    local choice = room:askForChoice(owner, self:objectName(), "draw+guard+attack")
    if choice == "draw" then
        room:addPlayerMark(owner, "hlxg_jiangchi_max-Clear", 2)
        room:setPlayerCardLimitation(owner, "use,response", "Slash", true, self:objectName())
        owner:drawCards(3, self:objectName())
    elseif choice == "guard" then
        room:setPlayerMark(owner, "hlxg_jiangchi_guard", 1)
        owner:drawCards(1, self:objectName())
    else
        room:addPlayerMark(owner, "hlxg_jiangchi_slash-Clear")
        room:setPlayerMark(owner, "hlxg_jiangchi_distance-PlayClear", 1)
    end
end)
hlxg_jiangchi_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_jiangchi_max", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx) return ctx:getPrimary():getMark("hlxg_jiangchi_max-Clear") end,
}
hlxg_jiangchi_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_jiangchi_mod", pattern = "Slash", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        if not p then return 0 end
        if ctx:getModType() == sgs.TargetModSkill_Residue then return p:getMark("hlxg_jiangchi_slash-Clear") end
        if ctx:getModType() == sgs.TargetModSkill_DistanceLimit and p:getMark("hlxg_jiangchi_distance-PlayClear") > 0 then return 1000 end
        return 0
    end,
}
hlxg_caozhang:addSkill(hlxg_jiangchi)
