extension_hl:insertRelatedSkills("hlxg_jiangchi", "#hlxg_jiangchi_mod")

hlxg_caoxing = sgs.General(extension_hl, "hlxg_caoxing", "qun", 4)
hlxg_liushi = gu_active("hlxg_liushi", nil, 1, 1, function(self, targets, to, from)
    local slash = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0)
    slash:setSkillName("_hlxg_liushi")
    local ok = #targets == 0 and not from:isLocked(slash) and from:canSlash(to, slash, false)
    slash:deleteLater()
    return ok
end, gu_one_feasible, function(self, room, source, targets)
    room:moveCardTo(self, source, nil, sgs.Player_DrawPile, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_PUT, source:objectName(), "hlxg_liushi", ""), true)
    if source:isDead() or targets[1]:isDead() then return end
    local slash = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0)
    slash:setSkillName("_hlxg_liushi")
    room:useCard(sgs.CardUseStruct(slash, source, targets[1]), false)
    slash:deleteLater()
end, function(request, c) return c:getSuit() == sgs.Card_Heart end)
hlxg_liushi_damage = gu_trigger("#hlxg_liushi_damage", {sgs.Damage}, function(self, event, room, p, data, owner)
    local d = data:toDamage()
    if d.from == owner and d.to and d.to ~= owner and d.card and d.card:isKindOf("Slash") then
