-- c209_03: only the supplied L1646-1665 excerpts.
local function hl03_adjust(room, p, skill)
    if not p:isAlive() then return end
    local n = p:getMark("&hlxg_zhishi")
    local choices = {"cancel"}
    if n < 2 then table.insert(choices, "increase") end
    if n > 0 then table.insert(choices, "decrease") end
    local choice = room:askForChoice(p, skill, table.concat(choices, "+"))
    if choice == "increase" then room:setPlayerMark(p, "&hlxg_zhishi", n + 1)
    elseif choice == "decrease" then room:setPlayerMark(p, "&hlxg_zhishi", n - 1) end
end
local function hl03_suit_discardable(p, suit)
    for _, c in sgs.qlist(p:getHandcards()) do
        if c:getSuit() == suit and not p:canDiscard(p, c:getEffectiveId()) then return false end
    end
    return true
end

hlxg_caocao = sgs.General(extension_hl, "hlxg_caocao", "god", 3)
hlxg_guixin = gu_trigger("hlxg_guixin", {sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    local amount = data:toDamage().damage
    for i = 1, amount do
        if not owner:isAlive() then break end
        if gu_invoke(owner, self:objectName(), data) then
            local gained = 0
            for _, other in sgs.qlist(room:getOtherPlayers(owner)) do
                if owner:isAlive() and not other:getCards("hej"):isEmpty() then
                    local id = room:askForCardChosen(owner, other, "hej", self:objectName())
                    if id >= 0 then
                        room:obtainCard(owner, id, false)
                        if room:getCardOwner(id) == owner then gained = gained + 1 end
                    end
                end
            end
            if owner:isAlive() and gained > 4 and owner:faceUp() then owner:turnOver() end
        end
    end
end)
hlxg_feiying_caocao = sgs.CreateDistanceSkillV2 {
    name = "hlxg_feiying_caocao", frequency = sgs.Skill_Compulsory,
    holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local from, to = ctx:getPrimary(), ctx:getSecondary()
        if from and to and from ~= to and to:hasSkill(self:objectName()) then return 1 end
        return 0
    end,
}
hlxg_caocao:addSkill(hlxg_guixin)
hlxg_caocao:addSkill(hlxg_feiying_caocao)

hlxg_caocao2 = sgs.General(extension_hl, "hlxg_caocao2$", "wei", 4)
hlxg_jianxiong_caocao2 = gu_trigger("hlxg_jianxiong_caocao2", {sgs.GameStart, sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.GameStart then
        local choice = room:askForChoice(owner, self:objectName(), "zero+one+two")
        room:setPlayerMark(owner, "&hlxg_zhishi", choice == "two" and 2 or (choice == "one" and 1 or 0))
        return
    end
    if not gu_invoke(owner, self:objectName(), data) then return end
    local damage = data:toDamage()
    local n = 2 - owner:getMark("&hlxg_zhishi")
    if damage.card then room:obtainCard(owner, damage.card, false) end
    if owner:isAlive() and n > 0 then owner:drawCards(n, self:objectName()) end
    hl03_adjust(room, owner, self:objectName())
end)
hlxg_hujia = sgs.CreateTriggerSkillV2 {
    name = "hlxg_hujia$", events = {sgs.DamageInflicted},
    can_trigger = function(self, event, room, p, data)
        if not p or not p:hasLordSkill(self:objectName()) or p:getMark("hlxg_hujia_lun") > 0 then return false end
        for _, q in sgs.qlist(room:getOtherPlayers(p)) do
            if q:getKingdom() == "wei" then return self:objectName(), p end
        end
        return false
    end,
    on_cost = function(self, event, room, p, ctx)
        local targets = sgs.SPlayerList()
        for _, q in sgs.qlist(room:getOtherPlayers(p)) do
            if q:getKingdom() == "wei" then targets:append(q) end
        end
        local target = room:askForPlayerChosen(p, targets, self:objectName(), "@hlxg_hujia", true, true)
        if not target then return false end
        ctx.targets:append(target)
        return true
    end,
    on_effect = function(self, event, room, p, ctx)
        room:setPlayerMark(p, "hlxg_hujia_lun", 1)
        local damage = ctx.original_data:toDamage()
        damage.to = ctx.targets:first()
        damage.transfer = true
        damage.transfer_reason = "hlxg_hujia"
        room:damage(damage)
        return true
    end,
}
hlxg_qingzhengCard = sgs.CreateSkillCard {
    name = "hlxg_qingzhengCard", will_throw = false,
    filter = function(self, targets, to, from) return gu_one(self, targets, to, from) and not to:isKongcheng() end,
    feasible = gu_one_feasible,
    on_use = function(self, room, source, targets)
        local target = targets[1]
        local suits, ids = {}, sgs.IntList()
        for _, id in sgs.qlist(self:getSubcards()) do suits[sgs.Sanguosha:getCard(id):getSuit()] = true end
        for _, c in sgs.qlist(source:getHandcards()) do
            if suits[c:getSuit()] then ids:append(c:getEffectiveId()) end
        end
        local count = ids:length()
        gu_throw(room, source, ids, "hlxg_qingzheng")
        if source:isAlive() and target:isAlive() and not target:isKongcheng() then
            -- Empty enabled IDs: inspection only; the explicit suit choice performs the discard.
            room:doGongxin(source, target, sgs.IntList(), "hlxg_qingzheng")
            source:removeTag("hlxg_qingzheng")
            local choices, present = {}, {}
            for _, c in sgs.qlist(target:getHandcards()) do
                if not present[c:getSuitString()] then
                    present[c:getSuitString()] = true; table.insert(choices, c:getSuitString())
                end
            end
            if #choices > 0 then
                local suit = room:askForChoice(source, "hlxg_qingzheng", table.concat(choices, "+"), ToData(target))
                local discard = sgs.IntList()
                for _, c in sgs.qlist(target:getHandcards()) do
                    if c:getSuitString() == suit then discard:append(c:getEffectiveId()) end
                end
                local n = discard:length()
                gu_throw(room, target, discard, "hlxg_qingzheng")
                if n < count and target:isAlive() then room:damage(sgs.DamageStruct("hlxg_qingzheng", source, target, 1)) end
            end
        end
        hl03_adjust(room, source, "hlxg_qingzheng")
    end,
}
hlxg_qingzheng = sgs.CreateViewAsSkillV2 {
    name = "hlxg_qingzheng", limit_scope = sgs.Skill_Limit_Phase, phase_name = "Play", max_usage_limit = 1,
    can_activate = function(self, request)
        return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
    end,
    can_select_card = function(self, request, card)
        local p, selected = request:getInitiator(), request:getSelectedCardIds()
        if selected:length() >= 3 - p:getMark("&hlxg_zhishi") or not p:handCards():contains(card:getEffectiveId())
            or not hl03_suit_discardable(p, card:getSuit()) then return false end
        for _, id in sgs.qlist(selected) do
            if sgs.Sanguosha:getCard(id):getSuit() == card:getSuit() then return false end
        end
        return true
    end,
    card_selection_feasible = function(self, request)
        return request:getSelectedCardIds():length() == 3 - request:getInitiator():getMark("&hlxg_zhishi")
    end,
    create_card = function(self, request)
        local c = hlxg_qingzhengCard:clone()
        c:addSubcards(request:getSelectedCardIds()); c:setSkillName(self:objectName()); return c
    end,
}
hlxg_caocao2:addSkill(hlxg_jianxiong_caocao2)
hlxg_caocao2:addSkill(hlxg_hujia)
hlxg_caocao2:addSkill(hlxg_qingzheng)

