hlxg_kangkai = gu_trigger("hlxg_kangkai", {sgs.TargetConfirmed}, function(self, event, room, target, data, owner)
    local use = data:toCardUse()
    if not target or not use.card or not use.card:isKindOf("Slash") or not use.to:contains(target)
        or owner:distanceTo(target) > 1 or owner:getMark("hlxg_kangkai-Clear") >= 2 then return end
    room:addPlayerMark(owner, "hlxg_kangkai-Clear")
    owner:drawCards(1, self:objectName())
    local card = room:askForCard(owner, "..", "@hlxg_kangkai-give:" .. target:objectName(), data, sgs.Card_MethodNone)
    if card then
        room:obtainCard(target, card, false)
        room:showCard(target, card:getEffectiveId())
        if card:isKindOf("EquipCard") and target:isAlive() then
            room:askForUseCard(target, tostring(card:getEffectiveId()), "@hlxg_kangkai-use")
        end
    end
end, true)
hlxg_caoang:addSkill(hlxg_kangkai)

hlxg_luoying = gu_trigger("hlxg_luoying", {sgs.CardsMoveOneTime, sgs.EventPhaseStart}, function(self, event, room, player, data, owner)
    if event == sgs.EventPhaseStart then
        if player ~= owner or owner:getPhase() ~= sgs.Player_Discard or owner:isKongcheng() then return end
        local cards = room:askForExchange(owner, self:objectName(), owner:getHandcardNum(), 0, false, "@hlxg_luoying-show", true, ".|club|.|hand")
        if cards and not cards:getSubcards():isEmpty() then
            room:showCard(owner, cards:getSubcards())
            room:ignoreCards(owner, cards)
        end
    else
        local move = data:toMoveOneTime()
        if not move.from or move.from:objectName() == owner:objectName() or move.to_place ~= sgs.Player_DiscardPile then return end
        local reason = bit32.band(move.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON)
        if reason ~= sgs.CardMoveReason_S_REASON_DISCARD and move.reason.m_reason ~= sgs.CardMoveReason_S_REASON_JUDGEDONE then return end
        for _, id in sgs.qlist(move.card_ids) do
            if sgs.Sanguosha:getCard(id):getSuit() == sgs.Card_Club and room:getCardPlace(id) == sgs.Player_DiscardPile
                and gu_invoke(owner, self:objectName(), sgs.QVariant(id)) then room:obtainCard(owner, id, true) end
        end
    end
end)
hlxg_caozhi:addSkill(hlxg_luoying)
hlxg_jiushi = sgs.CreateViewAsSkillV2 {
    name = "hlxg_jiushi", response_or_use = true,
    can_activate = function(self, request)
        local p = request:getInitiator()
        if not p or not p:faceUp() then return false end
        if request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY then local c = sgs.Sanguosha:cloneCard("analeptic", sgs.Card_NoSuit, 0); local ok = c:isAvailable(p); c:deleteLater(); return ok end
        return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_RESPONSE_USE and string.find(request:getPattern(), "analeptic", 1, true) ~= nil
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function(self, request)
        local c = sgs.Sanguosha:cloneCard("analeptic", sgs.Card_NoSuit, 0); c:setSkillName(self:objectName()); return c
    end,
    pay = function(self, room, ctx, request)
        local p = request:getInitiator()
        if not p or not p:faceUp() then return false end
        p:turnOver(); return true
    end,
}
hlxg_jiushi_record = gu_record("#hlxg_jiushi_record", {sgs.DamageDone, sgs.DamageComplete}, function(self, event, room, player, data)
    if not player then return end
    local stack = player:getTag("hlxg_jiushi_frames"):toString()
    if event == sgs.DamageDone then
        player:setTag("hlxg_jiushi_frames", sgs.QVariant(stack .. (player:faceUp() and "0" or "1")))
    elseif not data:toDamage().prevented then
        player:setTag("hlxg_jiushi_frames", sgs.QVariant(stack:sub(1, -2)))
    end
end)
hlxg_jiushi_flip = gu_trigger("#hlxg_jiushi_flip", {sgs.Damaged, sgs.TurnedOver}, function(self, event, room, player, data, owner)
    if player ~= owner then return end
    if event == sgs.Damaged then
        if not owner:faceUp() and owner:getTag("hlxg_jiushi_frames"):toString():sub(-1) == "1" and gu_invoke(owner, "hlxg_jiushi", data) then owner:turnOver() end
    else
        local ids = {}
        for _, id in sgs.qlist(room:getDiscardPile()) do
            if sgs.Sanguosha:getCard(id):isKindOf("TrickCard") then table.insert(ids, id) end
        end
        if #ids > 0 then room:obtainCard(owner, ids[math.random(#ids)], true) end
    end
end)
