hlxg_caojie = sgs.General(extension_hl, "hlxg_caojie", "qun", 3, false)
hlxg_shouxi = gu_trigger("hlxg_shouxi", {sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or not use.card or not use.card:isKindOf("Slash") or not use.to:contains(owner) then return end
    local choices, seen = {}, {}
    local used = gu_names(owner, "hlxg_shouxi_names")
    for _, name in ipairs(used) do seen[name] = true end
    for id = 0, sgs.Sanguosha:getCardCount() - 1 do
        local c = sgs.Sanguosha:getEngineCard(id)
        if c and (c:isKindOf("BasicCard") or c:isKindOf("TrickCard")) and not seen[c:objectName()] then
            seen[c:objectName()] = true
            table.insert(choices, c:objectName())
        end
    end
    if #choices == 0 or not gu_invoke(owner, self:objectName(), data) then return end
    local name = room:askForChoice(owner, self:objectName(), table.concat(choices, "+"), data)
    table.insert(used, name); gu_setnames(owner, "hlxg_shouxi_names", used)
    local discarded = use.from and use.from:isAlive() and room:askForCard(use.from, name, "@hlxg_shouxi-discard:" .. name, data, sgs.Card_MethodDiscard, owner, false, self:objectName())
    if discarded then
        if not owner:isNude() then
            local id = room:askForCardChosen(use.from, owner, "he", self:objectName())
            room:obtainCard(use.from, id, false)
        end
    else
        table.insert(use.nullified_list, owner:objectName()); data:setValue(use)
        for _, id in sgs.qlist(room:getDrawPile()) do
            if sgs.Sanguosha:getCard(id):objectName() == name then room:obtainCard(owner, id, false); break end
        end
    end
end)
hlxg_huimin = gu_trigger("hlxg_huimin", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Finish then return end
    local recipients = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getAlivePlayers()) do
        if q:getHandcardNum() <= q:getHp() then recipients:append(q) end
    end
    local x = recipients:length()
    if x == 0 or not gu_invoke(owner, self:objectName()) then return end
    owner:drawCards(x, self:objectName())
    if not owner:isAlive() then return end
    local n = math.max(0, x - 1)
    local ids = sgs.IntList()
    if n > 0 then
        local c = room:askForExchange(owner, self:objectName(), n, n, false, "@hlxg_huimin-show", false)
        if c then
            for _, id in sgs.qlist(c:getSubcards()) do ids:append(id) end
            c:deleteLater()
        end
    end
    if not ids:isEmpty() then room:showCard(owner, ids) end
    local first = room:askForPlayerChosen(owner, recipients, self:objectName(), "@hlxg_huimin-first", false)
    local ordered, start = {}, 1
    for _, q in sgs.qlist(recipients) do table.insert(ordered, q); if q == first then start = #ordered end end
    for offset = 0, #ordered - 1 do
        if ids:isEmpty() then break end
        local q = ordered[(start + offset - 1) % #ordered + 1]
        if q:isAlive() then
            room:fillAG(ids, q)
            local id = room:askForAG(q, ids, false, self:objectName())
            room:clearAG(q)
            ids:removeOne(id); room:obtainCard(q, id, true)
        end
    end
end)
hlxg_caojie:addSkill(hlxg_shouxi)
hlxg_caojie:addSkill(hlxg_huimin)

hlxg_zhujun = sgs.General(extension_hl, "hlxg_zhujun", "qun", 4)
hlxg_jujiang = gu_trigger("hlxg_jujiang", {sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    local move = data:toMoveOneTime()
    if not move.to or move.to:objectName() ~= owner:objectName() or owner:getPhase() == sgs.Player_Draw
        or (move.to_place ~= sgs.Player_PlaceHand and move.to_place ~= sgs.Player_PlaceEquip) then return end
    local candidates = sgs.IntList()
    for _, id in sgs.qlist(move.card_ids) do
        if room:getCardOwner(id) == owner and owner:canDiscard(owner, id) then candidates:append(id) end
    end
    if candidates:isEmpty() then return end
    local disabled = sgs.IntList()
    for _, c in sgs.qlist(owner:getCards("he")) do
        if not candidates:contains(c:getEffectiveId()) then disabled:append(c:getEffectiveId()) end
    end
    local ids = room:askForCardsChosen(owner, owner, "he", self:objectName(), 0, candidates:length(), false, sgs.Card_MethodDiscard, disabled, true)
    if ids:isEmpty() then return end
    local suits, n = {}, 0
    for _, id in sgs.qlist(ids) do
        local suit = sgs.Sanguosha:getCard(id):getSuit()
        if not suits[suit] then suits[suit] = true; n = n + 1 end
    end
    gu_throw(room, owner, ids, self:objectName())
    local current = room:getCurrent()
    if current and current:isAlive() and current:getPhase() ~= sgs.Player_NotActive then room:addPlayerMark(current, "hlxg_jujiang-Clear", n) end
end)
hlxg_jujiang_mod = sgs.CreateTargetModSkillV2 {
