    correct_func = function(self, ctx)
        local p, c = ctx:getPrimary(), ctx:getCard()
        if p and c and c:isKindOf("Slash") and ctx:getModType() == sgs.TargetModSkill_Residue then return p:getMark("hlxg_jujiang-Clear") end
        return 0
    end,
}
