hlxg_gongjian_record = gu_record("#hlxg_gongjian_record", {sgs.CardUsed}, function(self, event, room, p, data)
    local use = data:toCardUse()
    if not use.card or not use.card:isKindOf("Slash") then return end
    local previous = room:getTag("hlxg_gongjian_last"):toString()
    room:setTag("hlxg_gongjian_previous_" .. use.card:toString(), sgs.QVariant(previous))
    local names = {}
    for _, q in sgs.qlist(use.to) do table.insert(names, q:objectName()) end
    room:setTag("hlxg_gongjian_last", sgs.QVariant(table.concat(names, "+")))
end)
hlxg_gongjian = gu_trigger("hlxg_gongjian", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if not use.card or not use.card:isKindOf("Slash") or owner:getMark("hlxg_gongjian-Clear") > 0 then return end
    local previous = room:getTag("hlxg_gongjian_previous_" .. use.card:toString()):toString():split("+")
    local common = {}
    for _, q in sgs.qlist(use.to) do
        if table.contains(previous, q:objectName()) then table.insert(common, q) end
    end
    if #common == 0 or not gu_invoke(owner, self:objectName(), data) then return end
    room:addPlayerMark(owner, "hlxg_gongjian-Clear")
    for _, q in ipairs(common) do
        if owner:isAlive() and q:isAlive() and owner:canDiscard(q, "he") then
            local ids = room:askForCardsChosen(owner, q, "he", self:objectName(), 0, 2, false, sgs.Card_MethodDiscard)
            gu_throw(room, q, ids, self:objectName())
            local basics = sgs.IntList()
            for _, id in sgs.qlist(ids) do
                if room:getCardPlace(id) == sgs.Player_DiscardPile and sgs.Sanguosha:getCard(id):isKindOf("BasicCard") then basics:append(id) end
            end
            if owner:isAlive() then gu_obtain(room, owner, basics, self:objectName()) end
        end
    end
end)
