do
-- c209_06: literal 欢乐杀修改 text, V2 skills.
hlxg_zhuzhi = sgs.General(extension_hl, "hlxg_zhuzhi", "wu", 4)
hlxg_liyan = sgs.General(extension_hl, "hlxg_liyan", "shu", 3)

local function hlxg_anguo_lowest(room, p, kind)
    if p:isDead() then return false end
    local function value(q)
        if kind == "hand" then return q:getHandcardNum() end
        if kind == "hp" then return q:getHp() end
        return q:getEquips():length()
    end
    for _, q in sgs.qlist(room:getAlivePlayers()) do
        if value(q) < value(p) then return false end
    end
    return true
end
local function hlxg_anguo_equip(room, p)
    local pool = {}
    for _, id in sgs.qlist(room:getDrawPile()) do
        if sgs.Sanguosha:getCard(id):isKindOf("EquipCard") then table.insert(pool, id) end
    end
    if #pool == 0 then return end
    local card = sgs.Sanguosha:getCard(pool[math.random(#pool)])
    if card:isAvailable(p) then
        local use = sgs.CardUseStruct(); use.card = card; use.from = p; use.to:append(p)
        room:useCard(use)
    end
end
hlxg_anguo = gu_active("hlxg_anguo", 1, 0, 0,
    function(self, targets, to, from) return #targets == 0 end,
    gu_one_feasible,
    function(self, room, source, targets)
        local target = targets[1]
        local done = {}
        for _, kind in ipairs({"hand", "hp", "equip"}) do
            done[kind] = hlxg_anguo_lowest(room, target, kind)
            if done[kind] then
                if kind == "hand" then target:drawCards(1, "hlxg_anguo")
                elseif kind == "hp" then
                    local rec = sgs.RecoverStruct(); rec.who = source; rec.recover = 1
                    room:recover(target, rec)
                else hlxg_anguo_equip(room, target) end
            end
        end
        for _, kind in ipairs({"hand", "hp", "equip"}) do
            if not done[kind] and hlxg_anguo_lowest(room, source, kind) then
                if kind == "hand" then source:drawCards(1, "hlxg_anguo")
                elseif kind == "hp" then
                    local rec = sgs.RecoverStruct(); rec.who = source; rec.recover = 1
                    room:recover(source, rec)
                else hlxg_anguo_equip(room, source) end
            end
        end
    end)

hlxg_duliang = gu_active("hlxg_duliang", 1, 0, 0,
    function(self, targets, to, from)
        return gu_one(self, targets, to, from) and not to:isKongcheng()
    end,
    gu_one_feasible,
    function(self, room, source, targets)
        local target = targets[1]
        if target:isKongcheng() then return end
        local id = room:askForCardChosen(source, target, "h", "hlxg_duliang")
        room:obtainCard(source, id, false)
        if target:isDead() or source:isDead() then return end
        if room:askForChoice(source, "hlxg_duliang", "watch+draw", sgs.QVariant(target)) == "watch" then
            local ids = room:getNCards(2)
            room:fillAG(ids, target)
            room:askForAG(target, ids, true, "hlxg_duliang")
            room:clearAG(target)
            local gain = sgs.IntList()
            for _, cid in sgs.qlist(ids) do
                if not sgs.Sanguosha:getCard(cid):isKindOf("TrickCard") then gain:append(cid) end
            end
            room:returnToTopDrawPile(ids)
            if not gain:isEmpty() then
                room:showCard(target, gain)
                gu_obtain(room, target, gain, "hlxg_duliang")
            end
        else
            local names = gu_names(target, "hlxg_duliang_pending")
            table.insert(names, source:objectName())
            gu_setnames(target, "hlxg_duliang_pending", names)
            room:setPlayerMark(target, "&hlxg_duliang", #names)
        end
    end)
-- Persist grants independently of the grantor retaining 督粮.
hlxg_duliang_delay = sgs.CreateTriggerSkillV2 {
    name = "#hlxg_duliang_delay", global = true, frequency = sgs.Skill_Compulsory,
    events = {sgs.DrawNCards, sgs.AfterDrawNCards},
    can_trigger = function(self, event, room, player, data)
        if not player or player:getPhase() ~= sgs.Player_Draw then return false end
        local draw = data:toDraw()
        if draw.reason ~= "draw_phase" then return false end
        local key = event == sgs.DrawNCards and "hlxg_duliang_pending" or "hlxg_duliang_due"
        if player:getTag(key):toString() ~= "" then return self:objectName(), player end
        return false
    end,
    on_effect = function(self, event, room, player, ctx)
        local draw = ctx.original_data:toDraw()
        if event == sgs.DrawNCards then
            local names = gu_names(player, "hlxg_duliang_pending")
            player:removeTag("hlxg_duliang_pending")
            gu_setnames(player, "hlxg_duliang_due", names)
            room:setPlayerMark(player, "&hlxg_duliang", 0)
            draw.num = draw.num + #names
            ctx.original_data:setValue(draw)
        else
            local names = gu_names(player, "hlxg_duliang_due")
            player:removeTag("hlxg_duliang_due")
            for _, name in ipairs(names) do
                local recipient = room:findPlayerByObjectName(name)
                if recipient and recipient:isAlive() and player:isAlive() then
                    local ids = sgs.IntList()
                    for _, id in sgs.qlist(draw.card_ids) do
                        if room:getCardOwner(id) == player and room:getCardPlace(id) == sgs.Player_PlaceHand then ids:append(id) end
                    end
                    if not ids:isEmpty() then
                        -- Exchange, rather than discard: ignores discard restrictions.
                        local pattern = {}
                        for _, id in sgs.qlist(ids) do table.insert(pattern, tostring(id)) end
                        local c = room:askForExchange(player, "hlxg_duliang", 1, 1, false,
                            "@hlxg_duliang-give:" .. name, false, table.concat(pattern, ","))
                        if c then room:giveCard(player, recipient, c, "hlxg_duliang"); c:deleteLater() end
                    end
                end
            end
        end
        return false
    end,
}

