-- c209_07: literal Huanle Li Ru / Li Su variants.
local function c209_mieji(name, revised)
    return gu_active(name, 1, 1, 1,
        function(self, targets, to, from) return gu_one(self, targets, to, from) and not to:isKongcheng() end,
        gu_one_feasible, function(self, room, source, targets)
            room:moveCardTo(sgs.Sanguosha:getCard(self:getSubcards():first()), source, nil, sgs.Player_DrawPile,
                sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_PUT, source:objectName(), name, ""), true)
            local to = targets[1]
            if not to:isAlive() then return end
            local choice = room:askForChoice(to, name, "trick+discard", sgs.QVariant(source))
            if choice == "trick" then
                if revised then
                    local c = room:askForExchange(to, name, 1, 1, true, "@" .. name .. "-trick", true, "TrickCard")
                    if c then room:obtainCard(source, c, false); return end
                elseif room:askForDiscard(to, name, 1, 1, true, true, "@" .. name .. "-trick", "TrickCard") then return end
            end
            for i = 1, 2 do
                if not to:isAlive() then break end
                room:askForDiscard(to, name, 1, 1, false, true, "@" .. name .. "-discard", "^TrickCard")
            end
        end, function(request, c) return revised or c:isBlack() end)
end
local function c209_fencheng(name, revised)
    local skill = gu_active(name, nil, 0, 0,
        function(self, targets, to, from) return revised and gu_one(self, targets, to, from) end,
        function(self, targets) return #targets == (revised and 1 or 0) end,
        function(self, room, source, targets)
            room:removePlayerMark(source, "@" .. name)
            local order = sgs.QList2Table(room:getOtherPlayers(source))
            if revised then
                for i, p in ipairs(order) do
                    if p == targets[1] then
                        local rotated = {}
                        for j = 0, #order - 1 do rotated[#rotated + 1] = order[(i + j - 1) % #order + 1] end
                        order = rotated; break
                    end
                end
            end
            local previous = 0
            for _, to in ipairs(order) do
                if to:isAlive() then
                    local n = previous + 1
                    local discarded = room:askForDiscard(to, name, 999, n, true, true, "@" .. name .. "-discard:" .. n)
                    previous = discarded and discarded:subcardsLength() or 0
                    if not discarded then room:damage(sgs.DamageStruct(name, source, to, 2, sgs.DamageStruct_Fire)) end
                end
            end
        end, nil, function(p) return p:getMark("@" .. name) > 0 end)
    return skill
end
