local function c209_juece(name, revised)
    return gu_trigger(name, {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
        if p ~= owner or p:getPhase() ~= sgs.Player_Finish then return end
        local list = sgs.SPlayerList()
        for _, to in sgs.qlist(room:getOtherPlayers(owner)) do
            if (revised and to:getHandcardNum() <= owner:getHandcardNum()) or (not revised and to:isKongcheng()) then list:append(to) end
        end
        if list:isEmpty() then return end
        local to = room:askForPlayerChosen(owner, list, name, "@" .. name, true, true)
        if not to then return end
        if revised then owner:drawCards(math.min(5, to:getMark("hljx_juece_lost-Clear")), name) end
        if to:isAlive() then room:damage(sgs.DamageStruct(name, owner, to, 1)) end
    end)
end
