hlxg_qiaoyan = gu_trigger("hlxg_qiaoyan", {sgs.DamageCaused}, function(self, event, room, p, data, owner)
    local d = data:toDamage()
    if d.to ~= owner or not d.from or d.from == owner or owner:getPhase() ~= sgs.Player_NotActive then return end
    room:sendCompulsoryTriggerLog(owner, self:objectName())
    if not owner:getPile("hlxg_pearl"):isEmpty() then
        gu_obtain(room, d.from, owner:getPile("hlxg_pearl"), self:objectName())
        return
    end
    owner:drawCards(1, self:objectName())
    if owner:isAlive() and not owner:isNude() then
        local c = room:askForExchange(owner, self:objectName(), 1, 1, true, "@hlxg_qiaoyan-put")
        if c then owner:addToPile("hlxg_pearl", c:getSubcards(), true) end
    end
    return true
end, true)
hlxg_xianzhu = gu_trigger("hlxg_xianzhu", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Play or owner:getPile("hlxg_pearl"):isEmpty() then return end
    local to = room:askForPlayerChosen(owner, room:getAlivePlayers(), self:objectName(), "@hlxg_xianzhu", false, true)
    if not to then return end
    gu_obtain(room, to, owner:getPile("hlxg_pearl"), self:objectName())
    if to == owner or not to:isAlive() or not owner:isAlive() then return end
    local slash = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0)
    slash:setSkillName("_hlxg_xianzhu")
    local list = sgs.SPlayerList()
    for _, victim in sgs.qlist(room:getAlivePlayers()) do
        if owner:inMyAttackRange(victim) and to:canSlash(victim, slash, false) then list:append(victim) end
    end
    if not list:isEmpty() then
        local victim = room:askForPlayerChosen(owner, list, "hlxg_xianzhu_target", "@hlxg_xianzhu-target", true, true)
        if victim then
            local use = sgs.CardUseStruct(); use.card = slash; use.from = to; use.to:append(victim)
            room:useCard(use, false)
        end
    end
    slash:deleteLater()
end, true)
