hlxg_yijiao = gu_active("hlxg_yijiao", 1, 0, 0, gu_one, gu_one_feasible,
    function(self, room, source, targets)
        local n = tonumber(room:askForChoice(source, "hlxg_yijiao", "1+2+3+4")) or 1
        local target = targets[1]
        room:addPlayerMark(target, "&hlxg_yijiao", n * 10)
        room:addPlayerMark(target, "hlxg_yijiao_from_" .. source:objectName(), 1)
    end)
hlxg_yijiao_record = gu_record("#hlxg_yijiao_record",
    {sgs.PreCardUsed, sgs.PreCardResponded, sgs.EventPhaseStart, sgs.EventPhaseChanging},
    function(self, event, room, p, data)
        if not p then return end
        if event == sgs.PreCardUsed or event == sgs.PreCardResponded then
            local card
            if event == sgs.PreCardUsed then card = data:toCardUse().card
            else
                local response = data:toCardResponse()
                if response.m_isUse then card = response.m_card end
            end
            if card and not card:isKindOf("SkillCard") then
                room:addPlayerMark(p, "hlxg_yijiao_sum-Clear", card:getNumber())
            end
        elseif event == sgs.EventPhaseStart then
            if p:getPhase() == sgs.Player_Finish and p:getMark("&hlxg_yijiao") > 0 then
                local sum, yi = p:getMark("hlxg_yijiao_sum-Clear"), p:getMark("&hlxg_yijiao")
                for _, owner in sgs.qlist(room:getAllPlayers(true)) do
                    local count = p:getMark("hlxg_yijiao_from_" .. owner:objectName())
                    for i = 1, count do
                        if sum < yi and p:isAlive() then
                            local ids = {}
                            for _, c in sgs.qlist(p:getHandcards()) do
                                if p:canDiscard(p, c:getEffectiveId()) then table.insert(ids, c:getEffectiveId()) end
                            end
                            local chosen = sgs.IntList()
                            for j = 1, math.min(math.random(2, 3), #ids) do
                                local index = math.random(#ids)
                                chosen:append(table.remove(ids, index))
                            end
                            gu_throw(room, p, chosen, "hlxg_yijiao")
                        elseif sum == yi then
                            if owner:isAlive() then owner:drawCards(2, "hlxg_yijiao") end
                            room:addPlayerMark(p, "hlxg_yijiao_extra", 1)
                        elseif owner:isAlive() then owner:drawCards(3, "hlxg_yijiao") end
                    end
                end
            elseif p:getPhase() == sgs.Player_NotActive then
                local n = p:getMark("hlxg_yijiao_extra")
                room:setPlayerMark(p, "hlxg_yijiao_extra", 0)
                for i = 1, n do if p:isAlive() then p:gainAnExtraTurn() end end
            end
        elseif data:toPhaseChange().to == sgs.Player_NotActive then
            room:setPlayerMark(p, "&hlxg_yijiao", 0)
            for _, owner in sgs.qlist(room:getAllPlayers(true)) do
                room:setPlayerMark(p, "hlxg_yijiao_from_" .. owner:objectName(), 0)
            end
        end
    end)
hlxg_qibie = gu_trigger("hlxg_qibie", {sgs.Death}, function(self, event, room, p, data, owner)
    if owner:isKongcheng() or not gu_invoke(owner, self:objectName(), data) then return end
    local discarded = room:askForDiscard(owner, self:objectName(), owner:getHandcardNum(), 0, false, false, "@hlxg_qibie")
    local n = discarded and discarded:subcardsLength() or 0
    if owner:isAlive() then
        room:recover(owner, sgs.RecoverStruct(self:objectName(), owner))
        owner:drawCards(n + 1, self:objectName())
    end
end)

hlxg_yise = gu_trigger("hlxg_yise", {sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    local move = data:toMoveOneTime()
    if not move.from or not move.to or move.from:objectName() ~= owner:objectName()
        or move.to:objectName() == owner:objectName()
        or (move.to_place ~= sgs.Player_PlaceHand and move.to_place ~= sgs.Player_PlaceEquip) then return end
    local target = room:findPlayerByObjectName(move.to:objectName())
    if not target or not target:isAlive() then return end
    local red, black = false, false
    for _, id in sgs.qlist(move.card_ids) do
        local c = sgs.Sanguosha:getCard(id)
        red = red or c:isRed(); black = black or c:isBlack()
    end
    if red then
        local choice = room:askForChoice(owner, self:objectName(), "draw+recover+cancel", ToData(target))
        if choice == "draw" then owner:drawCards(1, self:objectName())
        elseif choice == "recover" then room:recover(target, sgs.RecoverStruct(self:objectName(), owner)) end
    end
    if black and owner:isAlive() and target:isAlive() and gu_invoke(owner, self:objectName(), ToData(target)) then
        room:addPlayerMark(target, "&hlxg_yise", 1)
    end
end)
hlxg_yise_damage = sgs.CreateRuleSkillV2 {
    name = "#hlxg_yise_damage", global = true, frequency = sgs.Skill_Compulsory,
    events = {sgs.DamageInflicted},
    can_trigger = function(self, event, room, p, data)
        local d = data:toDamage()
        return p and p:getMark("&hlxg_yise") > 0 and d.card and d.card:isKindOf("Slash") and self:objectName() or false
    end,
    on_effect = function(self, event, room, p, ctx)
        local d = ctx.original_data:toDamage()
        d.damage = d.damage + p:getMark("&hlxg_yise")
        room:setPlayerMark(p, "&hlxg_yise", 0)
        ctx.original_data:setValue(d)
        return false
    end,
}
hlxg_shunshi = gu_trigger("hlxg_shunshi", {sgs.EventPhaseStart, sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:isNude() then return end
    if event == sgs.EventPhaseStart and owner:getPhase() ~= sgs.Player_Start then return end
    if event == sgs.Damaged and owner:getPhase() ~= sgs.Player_NotActive then return end
    if not gu_invoke(owner, self:objectName(), data) then return end
    local card = room:askForExchange(owner, self:objectName(), 1, 1, true, "@hlxg_shunshi-card")
    if not card then return end
    local to = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@hlxg_shunshi-target")
    if to then
