hlxg_shawu = gu_trigger("hlxg_shawu", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or not use.card or not use.card:isKindOf("Slash") then return end
    for _, to in sgs.qlist(use.to) do
        if not owner:isAlive() then break end
        local choices = {"cancel"}
        local available = 0
        for _, c in sgs.qlist(owner:getHandcards()) do if owner:canDiscard(owner, c:getEffectiveId()) then available = available + 1 end end
        if available >= 2 then table.insert(choices, "discard") end
        if owner:getMark("&hlxg_shawu_sand") > 0 then table.insert(choices, "sand") end
        if to:isAlive() and #choices > 1 then
            local choice = room:askForChoice(owner, self:objectName(), table.concat(choices, "+"), ToData(to))
            local paid = false
            if choice == "discard" then
                local c = room:askForDiscard(owner, self:objectName(), 2, 2, false, false, "@hlxg_shawu-discard")
                paid = c and c:subcardsLength() == 2
            elseif choice == "sand" then room:removePlayerMark(owner, "&hlxg_shawu_sand"); paid = true end
            if paid then
                if to:isAlive() then room:damage(sgs.DamageStruct(self:objectName(), owner, to, 1)) end
                if choice == "sand" and owner:isAlive() then owner:drawCards(2, self:objectName()) end
            end
        end
    end
end)
hlxg_xiaowu = gu_active("hlxg_xiaowu", 1, 0, 0,
    function() return false end, function(self, targets) return #targets == 0 end,
    function(self, room, source, targets)
        local forward = room:askForChoice(source, "hlxg_xiaowu", "next+previous") == "next"
        local seats, count = {}, room:getAlivePlayers():length()
        for i = 1, count - 1 do
            table.insert(seats, source:getNextAlive(forward and i or count - i))
        end
        local candidates = sgs.SPlayerList()
        for _, to in ipairs(seats) do candidates:append(to) end
        if candidates:isEmpty() then return end
        local last = room:askForPlayerChosen(source, candidates, "hlxg_xiaowu", "@hlxg_xiaowu-end")
        if not last then return end
        local others, votes = {}, 0
        for _, to in ipairs(seats) do
            if to:isAlive() then
                local choices = source:isAlive() and "draw+selfdraw" or "selfdraw"
                if room:askForChoice(to, "hlxg_xiaowu", choices, ToData(source)) == "draw" then
                    votes = votes + 1; source:drawCards(1, "hlxg_xiaowu")
                else table.insert(others, to); to:drawCards(1, "hlxg_xiaowu") end
            end
            if to == last then break end
        end
        if source:isAlive() then room:addPlayerMark(source, "&hlxg_shawu_sand", math.ceil(votes / 2)) end
        if #others > votes then
            for _, to in ipairs(others) do
                if to:isAlive() then room:damage(sgs.DamageStruct("hlxg_xiaowu", source:isAlive() and source or nil, to, 1)) end
            end
        end
    end)
hlxg_huaping = sgs.CreateRuleSkillV2 {
    name = "hlxg_huaping", global = true, events = {sgs.Death}, frequency = sgs.Skill_Limited,
    limit_mark = "@hlxg_huaping",
    can_trigger = function(self, event, room, p, data)
        local dead = data:toDeath().who
        for _, owner in sgs.qlist(room:getAllPlayers(true)) do
            if owner:hasSkill(self:objectName()) and (owner == dead or owner:isAlive() and owner:getMark("@hlxg_huaping") > 0) then
                return self:objectName(), owner
            end
        end
        return false
    end,
    on_effect = function(self, event, room, p, ctx)
        local dead = ctx.original_data:toDeath().who
        if not dead then return false end
        for _, owner in sgs.qlist(room:getAllPlayers(true)) do
            if owner:hasSkill(self:objectName()) then
                if owner == dead then
                    local to = room:askForPlayerChosen(owner, room:getAlivePlayers(), self:objectName(), "@hlxg_huaping-target", true, true)
                    if to then
                        room:acquireSkill(to, "hlxg_shawu")
                        room:addPlayerMark(to, "&hlxg_shawu_sand", owner:getMark("&hlxg_shawu_sand"))
                        room:setPlayerMark(owner, "&hlxg_shawu_sand", 0)
                    end
                elseif owner:isAlive() and owner:getMark("@hlxg_huaping") > 0 and gu_invoke(owner, self:objectName(), ToData(dead)) then
                    room:removePlayerMark(owner, "@hlxg_huaping")
                    local names, seen = {}, {}
                    for _, general in ipairs({dead:getGeneral(), dead:getGeneral2()}) do
                        for _, skill in sgs.qlist(general:getSkillList()) do
                            local name = skill:objectName()
                            if not seen[name] then seen[name] = true; table.insert(names, name) end
                        end
                    end
                    if #names > 0 then room:handleAcquireDetachSkills(owner, table.concat(names, "|")) end
                    room:handleAcquireDetachSkills(owner, "-hlxg_xiaowu")
                    local n = owner:getMark("&hlxg_shawu_sand")
                    room:setPlayerMark(owner, "&hlxg_shawu_sand", 0)
                    if n > 0 and owner:isAlive() then owner:drawCards(n, self:objectName()) end
                end
            end
        end
        return false
    end,
}

