-- c210_01: source lines 1786-1808. All quotas are per actual phase instance.
local function c210_01_reveal(room, owner, n, skill)
    local ids = room:getNCards(n, false)
    if not ids:isEmpty() then
        room:moveCardsAtomic(sgs.CardsMoveStruct(ids, nil, sgs.Player_PlaceTable,
            sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_TURNOVER, owner:objectName(), skill, "")), true)
    end
    return ids
end
local function c210_01_restore(room, ids)
    local rest = sgs.IntList()
    for _, id in sgs.qlist(ids) do
        if room:getCardPlace(id) == sgs.Player_PlaceTable then rest:append(id) end
    end
    if not rest:isEmpty() then room:returnToTopDrawPile(rest) end
end
local function c210_01_pick(room, owner, ids, skill)
    if ids:isEmpty() or owner:isDead() then return nil end
    room:fillAG(ids)
    local id = room:askForAG(owner, ids, false, skill)
    room:clearAG()
    if not ids:contains(id) then id = ids:first() end
    return id
end

