hlxg_youyan = sgs.CreateTriggerSkillV2 {
    name = "hlxg_youyan", view_as_skill = c210_01_youyan_vs,
    events = {sgs.CardsMoveOneTime},
    can_trigger = function(self, event, room, p, data)
        if not p or not p:isAlive() or not p:hasSkill(self:objectName()) then return false end
        if p:getPhase() ~= sgs.Player_Play and p:getPhase() ~= sgs.Player_Discard then return false end
        local m = data:toMoveOneTime()
        if m.from ~= p or m.to_place ~= sgs.Player_DiscardPile or m.card_ids:isEmpty()
            or bit32.band(m.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON) ~= sgs.CardMoveReason_S_REASON_DISCARD
            or p:getMark("hlxg_youyan_reveal") > 0 then return false end
        return self:objectName()
    end,
    on_cost = function(self, event, room, p, ctx)
        return room:askForSkillInvoke(p, self:objectName(), ctx.original_data)
    end,
    on_effect = function(self, event, room, p, ctx)
        room:setPlayerMark(p, "hlxg_youyan_reveal", 1)
        local m = ctx.original_data:toMoveOneTime()
        local excluded = {}
        for _, id in sgs.qlist(m.card_ids) do excluded[sgs.Sanguosha:getCard(id):getSuit()] = true end
        local ids = c210_01_reveal(room, p, 2 * m.card_ids:length(), self:objectName())
        local suits, got = {}, sgs.IntList()
        for _, id in sgs.qlist(ids) do
            local suit = sgs.Sanguosha:getCard(id):getSuit()
            if not excluded[suit] and not table.contains(suits, suit) then table.insert(suits, suit) end
        end
        for _, suit in ipairs(suits) do
            local choices = sgs.IntList()
            for _, id in sgs.qlist(ids) do
                if room:getCardPlace(id) == sgs.Player_PlaceTable
                    and sgs.Sanguosha:getCard(id):getSuit() == suit then choices:append(id) end
            end
            local id = c210_01_pick(room, p, choices, self:objectName())
            if id then got:append(id) end
        end
        if p:isAlive() then gu_obtain(room, p, got, self:objectName()) end
        c210_01_restore(room, ids)
        return false
    end,
}
