-- A global recorder keeps a pending promise alive after Yang Wan dies/loses her skill.
hlxg_zhuihuan_effect = gu_record("#hlxg_zhuihuan_effect", {sgs.DamageDone, sgs.EventPhaseStart, sgs.Death},
    function(self, event, room, p, data)
        if event == sgs.DamageDone then
            local d = data:toDamage()
            if not d.to or not d.from or d.to:isDead() or d.to:getMark("&hlxg_zhuihuan") == 0 then return end
            local names = gu_names(d.to, "hlxg_zhuihuan_sources")
            if not table.contains(names, d.from:objectName()) then
                table.insert(names, d.from:objectName()); gu_setnames(d.to, "hlxg_zhuihuan_sources", names)
            end
        elseif event == sgs.Death then
            local who = data:toDeath().who
            if who then who:removeTag("hlxg_zhuihuan_sources"); room:setPlayerMark(who, "&hlxg_zhuihuan", 0) end
        elseif p and p:isAlive() and p:getPhase() == sgs.Player_Start then
            local names = gu_names(p, "hlxg_zhuihuan_sources")
            p:removeTag("hlxg_zhuihuan_sources")
            room:setPlayerMark(p, "&hlxg_zhuihuan", 0)
            for _, name in ipairs(names) do
                local source = room:findPlayerByObjectName(name)
                if source and source:isAlive() then
                    if source:getHp() > p:getHp() then
                        local d = sgs.DamageStruct(); d.from = p; d.to = source; d.damage = 2; d.reason = "hlxg_zhuihuan"
                        room:damage(d)
                    else
                        local choices, ids = {}, sgs.IntList()
                        for _, id in sgs.qlist(source:handCards()) do
                            if source:canDiscard(source, id) then table.insert(choices, id) end
                        end
                        for i = 1, math.min(2, #choices) do
                            local index = math.random(#choices); ids:append(table.remove(choices, index))
                        end
                        gu_throw(room, source, ids, "hlxg_zhuihuan")
                    end
                end
            end
        end
    end)
