hlxg_lulve = gu_trigger("hlxg_lulve", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:getPhase() ~= sgs.Player_Play then return end
    local candidates = sgs.SPlayerList()
    for _, to in sgs.qlist(room:getOtherPlayers(owner)) do
        if not to:isKongcheng() and to:getHandcardNum() <= owner:getHandcardNum() then candidates:append(to) end
    end
    if candidates:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_lulve", true, true)
    if not to then return end
    local choice = room:askForChoice(to, self:objectName(), "give+turnover", sgs.QVariant(owner))
    if choice == "give" then
        gu_obtain(room, owner, to:handCards(), self:objectName())
        if owner:isAlive() then owner:turnOver() end
    else
        to:turnOver()
        if to:isAlive() and owner:isAlive() then
            local slash = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0)
            slash:setSkillName("hlxg_lulve")
            if not to:isProhibited(owner, slash) then room:useCard(sgs.CardUseStruct(slash, to, owner), false) end
            slash:deleteLater()
        end
    end
end)
