    local choices = sgs.IntList()
    for _, id in sgs.qlist(ids) do
        if room:getCardPlace(id) == sgs.Player_PlaceTable and sgs.Sanguosha:getCard(id):getNumber() == 6 then choices:append(id) end
    end
    local id = c210_01_pick(room, owner, choices, self:objectName())
    if id then room:obtainCard(owner, id, self:objectName(), true) end
    c210_01_restore(room, ids)
    if choices:isEmpty() and owner:isAlive() then owner:drawCards(6, self:objectName()) end
end)
hlxg_fanchou:addSkill(hlxg_xingluan)

