-- ==================== c210_02
do
-- c210_02: literal 欢乐杀修改 variants.
hlxg_bulianshi = sgs.General(extension_hl, "hlxg_bulianshi", "wu", 3, false)
hlxg_buzhi = sgs.General(extension_hl, "hlxg_buzhi", "wu", 3)
hlxg_guanqiujian = sgs.General(extension_hl, "hlxg_guanqiujian", "wei", 4)

hlxg_anxu = gu_trigger("hlxg_anxu", {sgs.EventPhaseStart, sgs.EventPhaseEnd},
    function(self, event, room, player, data, owner)
        if player ~= owner or owner:getPhase() ~= sgs.Player_Play then return end
        local maximum = 0
        for _, p in sgs.qlist(room:getOtherPlayers(owner)) do maximum = math.max(maximum, p:getHandcardNum()) end
        if maximum == 0 then return end
        local candidates = sgs.SPlayerList()
        for _, p in sgs.qlist(room:getOtherPlayers(owner)) do
            if p:getHandcardNum() == maximum then candidates:append(p) end
        end
        local target = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_anxu", true, true)
        if not target then return end
        local id = room:askForCardChosen(owner, target, "h", self:objectName())
        local spade = sgs.Sanguosha:getCard(id):getSuit() == sgs.Card_Spade
        room:obtainCard(owner, id, self:objectName(), false)
        if spade and target:isAlive() then target:drawCards(1, self:objectName()) end
    end)

-- Death must dispatch to the deceased holder, rather than gu_trigger's alive-only loop.
hlxg_zhuiyi = sgs.CreateTriggerSkillV2 {
    name = "hlxg_zhuiyi", events = {sgs.Death},
    can_trigger = function(self, event, room, player, data)
        return player and data:toDeath().who == player and player:hasSkill(self:objectName())
            and self:objectName() or false
    end,
    on_cost = function(self, event, room, player, ctx)
        local death = ctx.original_data:toDeath()
        local killer = death.damage and death.damage.from or nil
        local candidates = sgs.SPlayerList()
        for _, p in sgs.qlist(room:getAlivePlayers()) do
            if p ~= player and p ~= killer then candidates:append(p) end
        end
        if candidates:isEmpty() then return false end
        local target = room:askForPlayerChosen(player, candidates, self:objectName(), "@hlxg_zhuiyi", true, true)
        if not target then return false end
        ctx.targets:append(target)
        return true
    end,
    on_effect = function(self, event, room, player, ctx)
        local target = ctx.targets:first()
        if target then
            target:drawCards(3, self:objectName())
            if target:isAlive() then
                local recover = sgs.RecoverStruct(); recover.who = player; recover.recover = 1
                room:recover(target, recover)
            end
        end
        return false
    end,
}

local function hlxg_c210_02_kingdoms(player)
    local found, count = {}, 0
    for _, p in sgs.qlist(player:getRoom():getAlivePlayers()) do
        if not found[p:getKingdom()] then found[p:getKingdom()] = true; count = count + 1 end
    end
    return count
end
hlxg_dingpanCard = sgs.CreateSkillCard {
    name = "hlxg_dingpanCard", will_throw = false,
    filter = function(self, targets, to, from) return #targets == 0 and not to:getEquips():isEmpty() end,
    feasible = gu_one_feasible,
    on_use = function(self, room, source, targets)
        room:addPlayerMark(source, "hlxg_dingpan-PlayClear")
        local target = targets[1]
        target:drawCards(1, "hlxg_dingpan")
        if not target:isAlive() then return end
        local choice = room:askForChoice(target, "hlxg_dingpan", "discard+obtain", sgs.QVariant(source))
        if choice == "discard" then
            if source:isAlive() and source:canDiscard(target, "e") then
                local id = room:askForCardChosen(source, target, "e", "hlxg_dingpan", false, sgs.Card_MethodDiscard)
                room:throwCard(id, target, source)
            end
        else
            local cards = target:getEquips()
            if not cards:isEmpty() then gu_obtain(room, target, gu_ids(sgs.QList2Table(cards)), "hlxg_dingpan") end
            if target:isAlive() then
                local damage = sgs.DamageStruct(); damage.from = source; damage.to = target
                damage.damage = 1; damage.reason = "hlxg_dingpan"; room:damage(damage)
            end
        end
    end,
}
hlxg_dingpan = sgs.CreateViewAsSkillV2 {
    name = "hlxg_dingpan",
    can_activate = function(self, request)
        local player = request:getInitiator()
        return player and request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
            and player:getMark("hlxg_dingpan-PlayClear") < hlxg_c210_02_kingdoms(player)
    end,
    can_select_card = function() return false end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function()
        local card = hlxg_dingpanCard:clone(); card:setSkillName("hlxg_dingpan"); return card
    end,
}

hlxg_hongde = gu_trigger("hlxg_hongde", {sgs.CardsMoveOneTime},
    function(self, event, room, player, data, owner)
        local move = data:toMoveOneTime()
        -- Gaining means entering hand/equipment; moving one's own cards between zones is not a gain/loss.
        local own_destination = move.to and move.to:objectName() == owner:objectName()
            and (move.to_place == sgs.Player_PlaceHand or move.to_place == sgs.Player_PlaceEquip)
        local gained, lost = 0, false
        for i, id in sgs.qlist(move.card_ids) do
            local place = move.from_places:at(i)
            local own_origin = move.from and move.from:objectName() == owner:objectName()
                and (place == sgs.Player_PlaceHand or place == sgs.Player_PlaceEquip)
            if own_destination and not own_origin then gained = gained + 1 end
            if own_origin and not own_destination then lost = true end
        end
        if gained >= 2 then
            local candidates = room:getOtherPlayers(owner)
            if not candidates:isEmpty() then
                local target = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_hongde", true, true)
                if target then target:drawCards(1, self:objectName()) end
            end
        end
        if owner:isAlive() and lost and owner:getMark("hlxg_hongde-Clear") < 2
            and gu_invoke(owner, self:objectName(), data) then
            room:addPlayerMark(owner, "hlxg_hongde-Clear")
            owner:drawCards(1, self:objectName())
        end
    end)

hlxg_zhengrong = gu_trigger("hlxg_zhengrong", {sgs.Damage},
    function(self, event, room, player, data, owner)
        local damage = data:toDamage()
        local target = damage.to
        if damage.from ~= owner or not target or target == owner or target:isNude() then return end
        if gu_invoke(owner, self:objectName(), data) then
            local id = room:askForCardChosen(owner, target, "he", self:objectName())
            owner:addToPile("hlxg_zhengrong_rong", id, true)
        end
    end)

hlxg_qingceCard = sgs.CreateSkillCard {
    name = "hlxg_qingceCard", will_throw = false,
    filter = function(self, targets, to, from) return #targets == 0 and from:canDiscard(to, "ej") end,
    feasible = gu_one_feasible,
    on_use = function(self, room, source, targets)
        local pile = source:getPile("hlxg_zhengrong_rong")
        room:fillAG(pile, source)
        local id = room:askForAG(source, pile, false, "hlxg_qingce")
        room:clearAG(source)
        local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_REMOVE_FROM_PILE, source:objectName(), "hlxg_qingce", "")
        room:throwCard(sgs.Sanguosha:getCard(id), reason, nil)
        local target = targets[1]
        if source:isAlive() and target:isAlive() and source:canDiscard(target, "ej") then
            local discard = room:askForCardChosen(source, target, "ej", "hlxg_qingce", false, sgs.Card_MethodDiscard)
            local who = target
            if room:getCardPlace(discard) == sgs.Player_PlaceDelayedTrick then who = nil end
            room:throwCard(discard, who, source)
        end
    end,
}
hlxg_qingce = sgs.CreateViewAsSkillV2 {
    name = "hlxg_qingce",
    can_activate = function(self, request)
        local player = request:getInitiator()
        if not player or request:getReason() ~= sgs.CardUseStruct_CARD_USE_REASON_PLAY then return false end
        if player:getPile("hlxg_zhengrong_rong"):isEmpty() then return false end
        local room = sgs.Sanguosha:currentRoom()
        if not room then return false end
        for _, p in sgs.qlist(room:getAlivePlayers()) do
            if player:canDiscard(p, "ej") then return true end
        end
        return false
    end,
    can_select_card = function() return false end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function()
        local card = hlxg_qingceCard:clone(); card:setSkillName("hlxg_qingce"); return card
    end,
}

hlxg_hongju = sgs.CreateTriggerSkillV2 {
    name = "hlxg_hongju", frequency = sgs.Skill_Wake, events = {sgs.EventPhaseStart},
    can_trigger = function(self, event, room, player, data)
        if not player or not player:isAlive() or not player:hasSkill(self:objectName())
            or player:getPhase() ~= sgs.Player_Start or player:getMark(self:objectName()) > 0
            or player:getPile("hlxg_zhengrong_rong"):length() < 3 then return false end
        for _, p in sgs.qlist(room:getAllPlayers(true)) do
            if p:isDead() then return self:objectName() end
        end
        return false
    end,
    on_effect = function(self, event, room, player, ctx)
        room:setPlayerMark(player, self:objectName(), 1)
        room:sendCompulsoryTriggerLog(player, self:objectName())
        local pile = player:getPile("hlxg_zhengrong_rong")
        if not player:isKongcheng() then
            local hand = room:askForExchange(player, self:objectName(), math.min(pile:length(), player:getHandcardNum()),
                0, false, "@hlxg_hongju", true)
            if hand and not hand:getSubcards():isEmpty() then
                local selected = sgs.IntList()
                local available = sgs.IntList()
                for _, id in sgs.qlist(pile) do available:append(id) end
                for i = 1, hand:getSubcards():length() do
                    room:fillAG(available, player)
                    local id = room:askForAG(player, available, false, self:objectName())
                    room:clearAG(player); selected:append(id); available:removeOne(id)
                end
                player:addToPile("hlxg_zhengrong_rong", hand:getSubcards(), true)
                gu_obtain(room, player, selected, self:objectName())
            end
        end
        if player:isAlive() then room:acquireSkill(player, "hlxg_qingce") end
        return false
    end,
}

