-- ==================== c210_03
do
-- c210_03: 欢乐杀修改; ordinary card use includes response-use.
hlxg_shamoke = sgs.General(extension_hl, "hlxg_shamoke", "shu", 4)
hlxg_jushou = sgs.General(extension_hl, "hlxg_jushou", "qun", 3)
hlxg_fazheng = sgs.General(extension_hl, "hlxg_fazheng", "shu", 3)

hlxg_jili_shamoke = gu_trigger("hlxg_jili_shamoke", {sgs.CardUsed, sgs.CardResponded, sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.EventPhaseStart then
        if p:getPhase() == sgs.Player_Finish and room:askForDiscard(p, self:objectName(), 1, 1, true, true, "@hlxg_jili_shamoke-discard") then
            if p:isAlive() then p:drawCards(1, self:objectName()) end
        end
        return
    end
    local card = event == sgs.CardUsed and data:toCardUse().card or data:toCardResponse().m_card
    if not card or card:getTypeId() == sgs.Card_TypeSkill then return end
    local used = sgs.getHegemonyCardUsedTimes(p, "")
    local responded = sgs.getHegemonyCardRespondedTimes(p, "")
    local x = p:getAttackRange()
    if used >= 0 and responded >= 0 and used + responded == x and gu_invoke(p, self:objectName(), data) then
        p:drawCards(x, self:objectName())
    end
end)

-- Record all players, including before skill acquisition. Snapshot the match on
-- the current card before optional effects can cause nested card use.
hlxg_jianying_record = gu_record("#hlxg_jianying_record", {sgs.CardUsed, sgs.CardResponded, sgs.EventPhaseChanging}, function(self, event, room, p, data)
    if not p then return end
    if event == sgs.EventPhaseChanging then
        if data:toPhaseChange().from == sgs.Player_Play or data:toPhaseChange().to == sgs.Player_Play then
            room:setPlayerMark(p, "hlxg_jianying_previous", 0)
        end
        return
    end
    if p:getPhase() ~= sgs.Player_Play then return end
    if event == sgs.CardResponded and not data:toCardResponse().m_isUse then return end
    local card = event == sgs.CardUsed and data:toCardUse().card or data:toCardResponse().m_card
    if not card or card:getTypeId() == sgs.Card_TypeSkill then return end
    local flag = "hlxg_jianying_match_" .. p:objectName()
    room:setCardFlag(card, "-" .. flag)
    if p:getMark("hlxg_jianying_previous") > 0 and
        (p:getMark("hlxg_jianying_suit") == card:getSuit() or p:getMark("hlxg_jianying_number") == card:getNumber()) then
        room:setCardFlag(card, flag)
    end
    room:setPlayerMark(p, "hlxg_jianying_previous", 1)
    room:setPlayerMark(p, "hlxg_jianying_suit", card:getSuit())
    room:setPlayerMark(p, "hlxg_jianying_number", card:getNumber())
end)
hlxg_jianying = gu_trigger("hlxg_jianying", {sgs.CardUsed, sgs.CardResponded}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Play then return end
    if event == sgs.CardResponded and not data:toCardResponse().m_isUse then return end
    local card = event == sgs.CardUsed and data:toCardUse().card or data:toCardResponse().m_card
    local flag = "hlxg_jianying_match_" .. p:objectName()
    if not card or not card:hasFlag(flag) then return end
    room:setCardFlag(card, "-" .. flag)
    if gu_invoke(p, self:objectName(), data) then p:drawCards(1, self:objectName()) end
end, false, sgs.Skill_Frequent)

hlxg_shibei_record = gu_record("#hlxg_shibei_record", {sgs.Damaged}, function(self, event, room, p, data)
    if p then room:addPlayerMark(p, "hlxg_shibei_damage-Clear") end
end)
hlxg_shibei = gu_trigger("hlxg_shibei", {sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if p:getMark("hlxg_shibei_damage-Clear") == 1 then
        local recover = sgs.RecoverStruct()
        recover.who = p; recover.recover = 1
        room:recover(p, recover)
        if p:isAlive() then p:drawCards(1, self:objectName()) end
    else
        room:loseHp(p, 1, true, p, self:objectName())
    end
end, true)

hlxg_enyuan = gu_trigger("hlxg_enyuan", {sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    -- The engine dispatches the same move once for each seat.
    if p ~= owner then return end
    local move = data:toMoveOneTime()
    if move.card_ids:isEmpty() or not move.from or not move.to or move.from:objectName() == move.to:objectName() then return end
    -- Gaining cards means hand/equipment/private-pile ownership, not judgment
    -- placement or transient movement to the shared table/discard pile.
    if move.to_place ~= sgs.Player_PlaceHand and move.to_place ~= sgs.Player_PlaceEquip and move.to_place ~= sgs.Player_PlaceSpecial then return end
    if move.to:objectName() == owner:objectName() then
        local source = room:findPlayerByObjectName(move.from:objectName())
        if source and source:isAlive() and gu_invoke(owner, self:objectName(), data) then source:drawCards(1, self:objectName()) end
    elseif move.from:objectName() == owner:objectName() then
        owner:drawCards(1, self:objectName())
    end
end)

hlxg_xuanhuo = gu_trigger("hlxg_xuanhuo", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Draw then return end
    local others = room:getOtherPlayers(p)
    if others:isEmpty() then return end
    local target = room:askForPlayerChosen(p, others, self:objectName(), "@hlxg_xuanhuo-target", true, true)
    if not target then return end
    local victims = room:getOtherPlayers(target)
    local victim = room:askForPlayerChosen(p, victims, self:objectName(), "@hlxg_xuanhuo-victim", false, false)
    -- The current text deletes the attack-range restriction. The engine still
    -- checks prohibition and ordinary Slash legality.
    local slash = victim and room:askForUseSlashTo(target, victim, "@hlxg_xuanhuo-slash:" .. victim:objectName(), false)
    if not slash and p:isAlive() and target:isAlive() and not target:isNude() then
        local id = room:askForCardChosen(p, target, "he", self:objectName())
        if id >= 0 then room:obtainCard(p, id, self:objectName(), false) end
    end
end)

