hljx_enyuan = gu_trigger("hljx_enyuan", {sgs.CardsMoveOneTime, sgs.Damaged}, function(self, event, room, p, data, owner)
    local name = self:objectName()
    if event == sgs.CardsMoveOneTime then
        if p ~= owner then return end
        local m = data:toMoveOneTime()
        if not m.from or not m.to or m.from:objectName() == m.to:objectName() or m.card_ids:isEmpty() then return end
        local from = room:findPlayerByObjectName(m.from:objectName())
        local to = room:findPlayerByObjectName(m.to:objectName())
        if not from or not to then return end
        if to == owner and from:isAlive() and gu_invoke(owner, name, sgs.QVariant(from)) then from:drawCards(1, name) end
        if from == owner and owner:isAlive() then owner:drawCards(1, name) end
    elseif p == owner then
        local d = data:toDamage()
        for i = 1, d.damage do
            if owner:isDead() or not d.from or d.from:isDead() then break end
            if gu_invoke(owner, name, data) then
                local c = room:askForCard(d.from, ".|red|.|hand", "@hljx_enyuan-give:" .. owner:objectName(), data, sgs.Card_MethodNone)
                if c then
                    local heart = c:getSuit() == sgs.Card_Heart
                    room:obtainCard(owner, c, name, false)
                    if not heart and owner:isAlive() then owner:drawCards(1, name) end
                else room:loseHp(d.from, 1, true, owner, name) end
            end
        end
    end
end)

hljx_xuanhuo = gu_trigger("hljx_xuanhuo", {sgs.EventPhaseEnd}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Draw or not gu_invoke(owner, self:objectName()) then return end
    local name = self:objectName()
    local to = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), name, "@hljx_xuanhuo-give", false, true)
    if not to then return end
    if not owner:isKongcheng() then
        local gift = room:askForExchange(owner, name, 2, 0, false, "@hljx_xuanhuo-cards", true)
        if gift and not gift:getSubcards():isEmpty() then room:obtainCard(to, gift, name, false) end
    end
    if owner:isDead() or to:isDead() then return end
    local victims = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getOtherPlayers(owner)) do if q ~= to then victims:append(q) end end
    local victim
    if not victims:isEmpty() then victim = room:askForPlayerChosen(owner, victims, name, "@hljx_xuanhuo-victim", false, true) end
    local choices, seen = {}, {}
    if victim then
        local names = {"duel", "slash", "fire_slash", "thunder_slash"}
        for id = 0, sgs.Sanguosha:getCardCount() - 1 do
            local c = sgs.Sanguosha:getEngineCard(id)
            if c and c:isKindOf("Slash") then table.insert(names, c:objectName()) end
        end
        for _, cn in ipairs(names) do
            if not seen[cn] then
                seen[cn] = true
                local c = sgs.Sanguosha:cloneCard(cn, sgs.Card_NoSuit, 0)
                if c then
                    c:setSkillName(name)
                    local targets = sgs.PlayerList()
                    if not to:isCardLimited(c, sgs.Card_MethodUse) and not to:isProhibited(victim, c)
                        and c:targetFilter(targets, victim, to) then table.insert(choices, cn) end
                    c:deleteLater()
                end
            end
        end
    end
    table.insert(choices, "take")
    local choice = room:askForChoice(to, name, table.concat(choices, "+"), sgs.QVariant(victim))
    if choice ~= "take" and victim and victim:isAlive() then
        local c = sgs.Sanguosha:cloneCard(choice, sgs.Card_NoSuit, 0)
        c:setSkillName(name)
        local use = sgs.CardUseStruct(); use.card = c; use.from = to; use.to:append(victim)
        room:useCard(use, false); c:deleteLater()
    else
        room:showAllCards(to, owner)
        local ids = to:handCards()
        local selected = sgs.IntList()
        room:fillAG(ids, owner)
        while owner:isAlive() and not ids:isEmpty() do
            local id = room:askForAG(owner, ids, true, name)
            if id < 0 then break end
            ids:removeOne(id); selected:append(id); room:takeAG(owner, id, false)
        end
        room:clearAG(owner)
        gu_obtain(room, owner, selected, name)
    end
end)

hlxg_kuangfu = gu_active("hlxg_kuangfu", 1, 0, 0,
    function(self, targets, to, from)
        if #targets ~= 0 then return false end
        local c = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0); c:setSkillName("hlxg_kuangfu")
        local ok = to ~= from and not from:isProhibited(to, c) and not from:isCardLimited(c, sgs.Card_MethodUse)
        c:deleteLater(); return ok
    end, gu_one_feasible,
    function(self, room, source, targets)
        local holders = sgs.SPlayerList()
        for _, q in sgs.qlist(room:getAlivePlayers()) do if source:canDiscard(q, "e") then holders:append(q) end end
        if holders:isEmpty() then return end
        local holder = room:askForPlayerChosen(source, holders, "hlxg_kuangfu", "@hlxg_kuangfu-equip", false, true)
        local id = room:askForCardChosen(source, holder, "e", "hlxg_kuangfu", false, sgs.Card_MethodDiscard)
        room:throwCard(id, holder, source)
        if source:isDead() or targets[1]:isDead() then return end
        local c = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0); c:setSkillName("hlxg_kuangfu")
        local use = sgs.CardUseStruct(); use.card = c; use.from = source; use.to:append(targets[1])
        room:useCard(use, false); c:deleteLater()
    end, nil, function(p)
        for _, q in sgs.qlist(p:getRoom():getAlivePlayers()) do if p:canDiscard(q, "e") then return true end end
        return false
    end)

hlxg_kuangfu_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_kuangfu_mod", pattern = "Slash", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local c = ctx:getCard()
        if c and c:getSkillName() == "hlxg_kuangfu" and (ctx:getModType() == sgs.TargetModSkill_DistanceLimit or ctx:getModType() == sgs.TargetModSkill_Residue) then return 1000 end
        return 0
    end,
}
hlxg_kuangfu_damage = gu_record("#hlxg_kuangfu_damage", {sgs.Damage, sgs.CardFinished}, function(self, event, room, p, data)
    if event == sgs.Damage then
        local d = data:toDamage()
        if d.card and d.card:getSkillName() == "hlxg_kuangfu" then room:setCardFlag(d.card, "hlxg_kuangfu_hit") end
    else
        local use = data:toCardUse()
        if use.card and use.card:getSkillName() == "hlxg_kuangfu" and use.card:hasFlag("hlxg_kuangfu_hit") and use.from and use.from:isAlive() then use.from:drawCards(2, "hlxg_kuangfu") end
    end
end)

hlxg_gongqing = gu_trigger("hlxg_gongqing", {sgs.DamageInflicted}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    local d = data:toDamage()
    if not d.from then return end
    room:sendCompulsoryTriggerLog(owner, self:objectName(), true)
    if d.from:getAttackRange() < 3 then d.damage = 1; data:setValue(d)
    else owner:drawCards(1, self:objectName()) end
end, true)
hlxg_guanwei_record = gu_record("#hlxg_guanwei_record", {sgs.CardUsed}, function(self, event, room, p, data)
    local use = data:toCardUse()
    if use.from and use.card and not use.card:isKindOf("SkillCard") and room:getCurrent() and room:getCurrent():getPhase() ~= sgs.Player_NotActive then
        room:addPlayerMark(use.from, "hlxg_guanwei_suit" .. tostring(use.card:getSuit()) .. "-Clear")
    end
end)
hlxg_guanwei = gu_trigger("hlxg_guanwei", {sgs.EventPhaseEnd}, function(self, event, room, p, data, owner)
    if not p or p:getPhase() ~= sgs.Player_Play or owner:getMark("hlxg_guanwei_used-Clear") > 0 then return end
    local match = false
    for suit = sgs.Card_Spade, sgs.Card_Diamond do if p:getMark("hlxg_guanwei_suit" .. tostring(suit) .. "-Clear") >= 2 then match = true end end
    if not match then return end
    local c = room:askForCard(owner, "..", "@hlxg_guanwei:" .. p:objectName(), sgs.QVariant(p), sgs.Card_MethodDiscard, nil, false, self:objectName())
    if not c then return end
    room:setPlayerMark(owner, "hlxg_guanwei_used-Clear", 1)
    if p:isAlive() then p:drawCards(2, self:objectName()); if p:isAlive() then p:insertPhase(sgs.Player_Play) end end
end)
hljx_fazheng:addSkill(hljx_enyuan); hljx_fazheng:addSkill(hljx_xuanhuo)
hlxg_panfeng:addSkill(hlxg_kuangfu); hlxg_panfeng:addSkill(hlxg_kuangfu_mod); hlxg_panfeng:addSkill(hlxg_kuangfu_damage)
