extension_hl:insertRelatedSkills("hlxg_kuangfu", "#hlxg_kuangfu_damage")
hlxg_panjun:addSkill(hlxg_gongqing); hlxg_panjun:addSkill(hlxg_guanwei); hlxg_panjun:addSkill(hlxg_guanwei_record)
