-- ==================== c210_05
do
-- c210_05: literal Huanle variants.
hlxg_wangyun = sgs.General(extension_hl, "hlxg_wangyun", "qun", 4)
hlxg_wangshuang = sgs.General(extension_hl, "hlxg_wangshuang", "wei", 8)
hljx_wangji = sgs.General(extension_hl, "hljx_wangji", "wei", 3)

hlxg_jingong = sgs.CreateViewAsSkillV2 {
    name = "hlxg_jingong", n = 1, guhuo_type = "r",
    limit_scope = sgs.Skill_Limit_Phase, phase_name = "Play", max_usage_limit = 1,
    can_activate = function(self, request)
        return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
    end,
    can_select_card = function(self, request, c)
        return request:getSelectedCardIds():isEmpty() and (c:isKindOf("EquipCard") or c:isKindOf("Slash"))
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    allow_declaration = function(self, player, name)
        local c = sgs.Sanguosha:cloneCard(name, sgs.Card_NoSuit, 0)
        if not c then return false end
        local ok = c:isNDTrick(); c:deleteLater(); return ok
    end,
    build_card = function(self, request, name)
        local ids = request:getSelectedCardIds(); if ids:length() ~= 1 then return nil end
        local original = sgs.Sanguosha:getCard(ids:first())
        local c = sgs.Sanguosha:cloneCard(name, original:getSuit(), original:getNumber())
        if not c then return nil end
        if not c:isNDTrick() then c:deleteLater(); return nil end
        c:addSubcards(ids); c:setSkillName("hlxg_jingong"); return c
    end,
}
extension_hl:addSkills(hlxg_jingong)

hlxg_lianji = gu_active("hlxg_lianji", 1, 0, 0, gu_one, gu_one_feasible,
    function(self, room, source, targets)
        local wielder = targets[1]
        local revealed = sgs.IntList()
        local weapon
        -- Keep revealed non-weapons on the table so reshuffling cannot reveal them twice.
        while not room:getDrawPile():isEmpty() or not room:getDiscardPile():isEmpty() do
            local ids = room:getNCards(1)
            if ids:isEmpty() then break end
            local id = ids:first(); local c = sgs.Sanguosha:getCard(id)
            room:moveCardTo(c, nil, sgs.Player_PlaceTable, true)
            if c:isKindOf("Weapon") then weapon = c; break end
            revealed:append(id)
        end
        if weapon and wielder:isAlive() then
            local equip = sgs.CardUseStruct(); equip.card = weapon; equip.from = wielder; equip.to:append(wielder)
            room:useCard(equip, false)
            if source:isAlive() and wielder:isAlive() then
                local slash = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0)
                slash:setSkillName("hlxg_lianji")
                slash:setTag("hlxg_lianji_owner", sgs.QVariant(source:objectName()))
                local candidates = sgs.SPlayerList()
                for _, q in sgs.qlist(room:getOtherPlayers(wielder)) do
                    if wielder:canSlash(q, slash, false) then candidates:append(q) end
                end
                if not candidates:isEmpty() then
                    local to = room:askForPlayerChosen(source, candidates, "hlxg_lianji", "@hlxg_lianji-slash", false, true)
                    local use = sgs.CardUseStruct(); use.card = slash; use.from = wielder; use.to:append(to)
                    room:useCard(use, false)
                end
                slash:deleteLater()
            end
            if source:isAlive() and wielder:isAlive() and wielder:getWeapon() then
                room:setPlayerFlag(source, "hlxg_lianji_giving")
                local to = room:askForPlayerChosen(source, room:getAlivePlayers(), "hlxg_lianji", "@hlxg_lianji-give", false, true)
                room:setPlayerFlag(source, "-hlxg_lianji_giving")
                room:obtainCard(to, wielder:getWeapon(), true)
            end
        elseif weapon then room:throwCard(weapon, "hlxg_lianji", nil) end
        if not revealed:isEmpty() then
            local dummy = gu_dummy(revealed); room:throwCard(dummy, "hlxg_lianji", nil); dummy:deleteLater()
        end
    end)
hlxg_lianji_record = gu_record("#hlxg_lianji_record", {sgs.Damage}, function(self, event, room, player, data)
    local d = data:toDamage()
    if not d.card or not d.card:isKindOf("Slash") or d.damage <= 0 then return end
    local name = d.card:getTag("hlxg_lianji_owner"):toString()
    for _, p in sgs.qlist(room:getAllPlayers()) do
        if p:objectName() == name then room:setPlayerMark(p, "hlxg_lianji_damage", 1) end
    end
end)
hlxg_moucheng = gu_trigger("hlxg_moucheng", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_RoundStart or p:getMark("hlxg_moucheng") > 0
        or p:getMark("hlxg_lianji_damage") == 0 then return end
    room:sendCompulsoryTriggerLog(p, self:objectName(), true)
    room:setPlayerMark(p, "hlxg_moucheng", 1)
    room:acquireSkill(p, "hlxg_jingong")
end, true, sgs.Skill_Wake)
hlxg_wangyun:addSkill(hlxg_lianji)
hlxg_wangyun:addSkill(hlxg_lianji_record)
hlxg_wangyun:addSkill(hlxg_moucheng)
extension_hl:insertRelatedSkills("hlxg_lianji", "#hlxg_lianji_record")

hlxg_zhuilie = gu_trigger("hlxg_zhuilie", {sgs.TargetSpecified, sgs.ConfirmDamage, sgs.FinishJudge},
    function(self, event, room, p, data, owner)
        if p ~= owner then return end
        if event == sgs.FinishJudge then
            local judge = data:toJudge()
            if judge.reason == self:objectName() and judge.card:isKindOf("TrickCard") then
                room:obtainCard(owner, judge.card, true)
            end
        elseif event == sgs.ConfirmDamage then
            local d = data:toDamage()
            if d.from ~= owner or not d.to or not d.card or not d.card:hasFlag("hlxg_zhuilie_" .. d.to:objectName()) then return end
            -- “增加至” never reduces damage already above the target's HP.
            d.damage = math.max(d.damage, d.to:getHp()); data:setValue(d)
        else
            local use = data:toCardUse()
            if use.from ~= owner or not use.card or not use.card:isKindOf("Slash") then return end
            for _, to in sgs.qlist(use.to) do
                if owner:isAlive() and not owner:inMyAttackRange(to) then
                    use.m_addHistory = false; data:setValue(use)
                    room:sendCompulsoryTriggerLog(owner, self:objectName(), true)
                    local judge = sgs.JudgeStruct(); judge.who = owner; judge.reason = self:objectName()
                    judge.pattern = "."; judge.good = true; room:judge(judge)
                    local c = judge.card
                    if c:isKindOf("Weapon") or c:isKindOf("OffensiveHorse") or c:isKindOf("DefensiveHorse") then
