hljx_qizhi = gu_trigger("hljx_qizhi", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:getPhase() == sgs.Player_NotActive then return end
    local use = data:toCardUse()
    if use.from ~= owner or not use.card or not (use.card:isKindOf("BasicCard") or use.card:isKindOf("TrickCard")) then return end
    local candidates = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getAlivePlayers()) do
        if not use.to:contains(q) and owner:canDiscard(q, "he") then candidates:append(q) end
    end
    if candidates:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hljx_qizhi", true, true)
    if not to then return end
    room:addPlayerMark(owner, "hljx_qizhi-Clear")
    local id = room:askForCardChosen(owner, to, "he", self:objectName(), false, sgs.Card_MethodDiscard)
    local same = sgs.Sanguosha:getCard(id):getTypeId() == use.card:getTypeId()
    room:throwCard(id, to, owner)
    local drawer = same and owner or to
    if drawer:isAlive() then drawer:drawCards(1, self:objectName()) end
end)
hljx_jinqu = gu_trigger("hljx_jinqu", {sgs.EventPhaseChanging}, function(self, event, room, p, data, owner)
    if p ~= owner or data:toPhaseChange().to ~= sgs.Player_Discard or owner:isSkipped(sgs.Player_Discard)
        or not gu_invoke(owner, self:objectName(), data) then return end
    owner:skip(sgs.Player_Discard)
    owner:drawCards(2, self:objectName())
    local n = owner:getHandcardNum() - owner:getMark("hljx_qizhi-Clear") - 1
    if n > 0 then room:askForDiscard(owner, self:objectName(), n, n, false, false) end
end)
