hlxg_binglve = gu_trigger("hlxg_binglve", {sgs.CardUsed}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or not use.card or use.card:getSkillName() ~= "hlxg_feijun" or use.to:isEmpty() then return end
    local target = use.to:first()
    local names = gu_names(owner, "hlxg_feijun_targets")
    local first = not table.contains(names, target:objectName())
    if first then table.insert(names, target:objectName()) end
    local x = 0
    if first then
        for _, q in sgs.qlist(room:getAlivePlayers()) do
            if table.contains(names, q:objectName()) then x = x + 1 end
        end
    end
    owner:drawCards(1 + x, self:objectName())
end, true)

hlxg_feijun = gu_active("hlxg_feijun", 1, 1, 1, gu_one, gu_one_feasible,
    function(self, room, source, targets)
        local target = targets[1]
        gu_throw(room, source, self:getSubcards(), "hlxg_feijun")
        local names = gu_names(source, "hlxg_feijun_targets")
        if not table.contains(names, target:objectName()) then table.insert(names, target:objectName()) end
        gu_setnames(source, "hlxg_feijun_targets", names)
        if not source:isAlive() or not target:isAlive() then return end
        local choice = room:askForChoice(source, "hlxg_feijun", "give+equip", sgs.QVariant(target))
        if choice == "give" then
            if target:isNude() then return end
            local c = room:askForExchange(target, "hlxg_feijun", 1, 1, true, "@hlxg_feijun-give:" .. source:objectName(), false)
            if c then room:obtainCard(source, c, false); c:deleteLater() end
        elseif not target:getEquips():isEmpty() then
            room:askForDiscard(target, "hlxg_feijun", 1, 1, false, true, "@hlxg_feijun-equip", ".|.|.|equipped")
        end
    end,
    function(request, c) return not request:getInitiator():isJilei(c) end,
    function(p) return not p:isNude() end)
