local function c210_06_miji(room, owner)
    if not owner:isAlive() or not gu_invoke(owner, "hljx_miji") then return end
    local x = owner:getLostHp()
    if x > 0 then owner:drawCards(x, "hljx_miji") end
    while x > 0 and owner:isAlive() and not owner:isKongcheng() do
        local ids = gu_ids(sgs.QList2Table(owner:getHandcards()))
        local before = ids:length()
        local target = room:askForYiji(owner, ids, "hljx_miji", false, false, true, x, room:getOtherPlayers(owner))
        local given = before - ids:length()
        if not target or given <= 0 then break end
        x = x - given
    end
end
hljx_miji = gu_trigger("hljx_miji", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p == owner and p:getPhase() == sgs.Player_Finish then c210_06_miji(room, owner) end
end)
hljx_zhenlie = gu_trigger("hljx_zhenlie", {sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or not use.from or use.from == owner or not use.to:contains(owner) or not use.card
        or not (use.card:isKindOf("Slash") or use.card:isNDTrick()) then return end
    if not gu_invoke(owner, self:objectName(), data) then return end
    room:loseHp(owner, 1)
    -- Preserve modifications made by nested dying/recovery triggers.
    use = data:toCardUse()
    local nullified = use.nullified_list
    if not table.contains(nullified, owner:objectName()) then table.insert(nullified, owner:objectName()) end
    use.nullified_list = nullified
    data:setValue(use)
    if not owner:isAlive() or not use.from:isAlive() or use.from:isNude() then return end
    local choices = "obtain"
    local current = room:getCurrent()
    if current and current ~= owner then choices = choices .. "+miji" end
    if room:askForChoice(owner, self:objectName(), choices, data) == "miji" then
        room:addPlayerMark(owner, "hljx_zhenlie_pending-Clear")
    else
        local id = room:askForCardChosen(owner, use.from, "he", self:objectName())
        if id >= 0 then room:obtainCard(owner, id, false) end
    end
end)
hljx_zhenlie_delay = sgs.CreateRuleSkillV2 {
    name = "#hljx_zhenlie_delay", events = {sgs.EventPhaseStart}, global = true,
    can_trigger = function(self, event, room, p, data)
        if not p or p:getPhase() ~= sgs.Player_Finish then return false end
        for _, owner in sgs.qlist(room:getAlivePlayers()) do
            if owner:getMark("hljx_zhenlie_pending-Clear") > 0 then return self:objectName(), p end
        end
        return false
    end,
    on_effect = function(self, event, room, p, ctx)
        for _, owner in sgs.qlist(room:getAlivePlayers()) do
            local n = owner:getMark("hljx_zhenlie_pending-Clear")
            room:setPlayerMark(owner, "hljx_zhenlie_pending-Clear", 0)
            for i = 1, n do
                if owner:isAlive() then c210_06_miji(room, owner) end
            end
        end
        return false
    end,
}
