hlxg_huguan_record = gu_record("#hlxg_huguan_record", {sgs.PreCardUsed, sgs.HpRecover, sgs.EventPhaseEnd}, function(self, event, room, p, data)
    if event == sgs.PreCardUsed then
        local use = data:toCardUse()
        if p and p:getPhase() == sgs.Player_Play and use.card and use.card:isRed() then
            room:addPlayerMark(p, "hlxg_huguan_red-PlayClear")
        end
    elseif event == sgs.HpRecover then
        for _, q in sgs.qlist(room:getAlivePlayers()) do room:setPlayerMark(q, "hlxg_mingluan_recovered-Clear", 1) end
    elseif p and p:getPhase() == sgs.Player_Discard then
        for _, id in ipairs(gu_names(p, "hlxg_huguan_ignored")) do
            room:removePlayerCardLimitation(p, "ignore", id .. "$1")
        end
        p:removeTag("hlxg_huguan_ignored")
    end
end)
hlxg_huguan_show = sgs.CreateRuleSkillV2 {
    name = "#hlxg_huguan_show", events = {sgs.EventPhaseStart}, global = true,
    can_trigger = function(self, event, room, p, data)
        if not p or p:getPhase() ~= sgs.Player_Discard or p:isKongcheng() then return false end
        for _, suit in ipairs({"spade", "club", "heart", "diamond"}) do
            if p:getMark("hlxg_huguan_show_" .. suit .. "-Clear") > 0 then return self:objectName(), p end
        end
        return false
    end,
    on_effect = function(self, event, room, p, ctx)
        for _, suit in ipairs({"spade", "club", "heart", "diamond"}) do
            if p:getMark("hlxg_huguan_show_" .. suit .. "-Clear") > 0 and not p:isKongcheng() then
                local c = room:askForExchange(p, "hlxg_huguan", p:getHandcardNum(), 1, false,
                    "@hlxg_huguan-show:" .. suit, true, ".|" .. suit .. "|.|hand")
                if c then
                    room:showCard(p, c:getSubcards())
                    room:ignoreCards(p, c)
                    local ids = gu_names(p, "hlxg_huguan_ignored")
                    for _, id in sgs.qlist(c:getSubcards()) do table.insert(ids, tostring(id)) end
                    gu_setnames(p, "hlxg_huguan_ignored", ids)
                    c:deleteLater()
                end
            end
        end
        return false
    end,
}
hlxg_huguan = gu_trigger("hlxg_huguan", {sgs.PreCardUsed}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if not p or p:getPhase() ~= sgs.Player_Play or not use.card or not use.card:isRed()
        or p:getMark("hlxg_huguan_red-PlayClear") ~= 1 then return end
    if not gu_invoke(owner, self:objectName(), sgs.QVariant(p)) then return end
    local suit = room:askForChoice(owner, self:objectName(), "spade+club+heart+diamond", sgs.QVariant(p))
    local choice = room:askForChoice(owner, self:objectName(), "show+protect", sgs.QVariant(p))
    if choice == "show" then
        room:setPlayerMark(p, "hlxg_huguan_show_" .. suit .. "-Clear", 1)
