hlxg_mingluan = gu_trigger("hlxg_mingluan", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if not p or p == owner or p:getPhase() ~= sgs.Player_Finish or owner:getMark("hlxg_mingluan_recovered-Clear") == 0 then return end
    if not gu_invoke(owner, self:objectName(), sgs.QVariant(p)) then return end
    local n = p:getHandcardNum()
