-- ==================== c210_07
do
-- c210_07: literal 欢乐杀修改 variants.
local function c21007_sum(ids)
    local n = 0
    for _, id in sgs.qlist(ids) do n = n + sgs.Sanguosha:getCard(id):getNumber() end
    return n
end

hlxg_qiai = gu_trigger("hlxg_qiai", {sgs.EnterDying}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:getMark("@hlxg_qiai") == 0 or not gu_invoke(owner, self:objectName()) then return end
    room:removePlayerMark(owner, "@hlxg_qiai")
    local moves = sgs.CardsMoveList()
    for _, donor in sgs.qlist(room:getOtherPlayers(owner)) do
        if not donor:isNude() then
            local card = room:askForExchange(donor, self:objectName(), 1, 1, true, "@hlxg_qiai-give:" .. owner:objectName(), false)
            local ids = card and card:getSubcards() or sgs.IntList()
            if ids:isEmpty() then ids:append(donor:getCards("he"):first():getEffectiveId()) end
            local move = sgs.CardsMoveStruct()
            move.card_ids = ids; move.from = donor; move.to = owner; move.to_place = sgs.Player_PlaceHand
            move.reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_GIVE, donor:objectName(), owner:objectName(), self:objectName(), "")
            moves:append(move)
        end
    end
    if not moves:isEmpty() then room:moveCardsAtomic(moves, false) end
end, false, sgs.Skill_Limited, "@hlxg_qiai")

hlxg_sanwen = gu_trigger("hlxg_sanwen", {sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    local move = data:toMoveOneTime()
    if not move.to or move.to:objectName() ~= owner:objectName() or move.to_place ~= sgs.Player_PlaceHand
        or owner:getMark("hlxg_sanwen-Clear") > 0 then return end
    local discard, show = sgs.IntList(), sgs.IntList()
    for _, id in sgs.qlist(move.card_ids) do
        if room:getCardOwner(id) == owner and room:getCardPlace(id) == sgs.Player_PlaceHand then
            local gained = sgs.Sanguosha:getCard(id)
            for _, old in sgs.qlist(owner:getHandcards()) do
                if not move.card_ids:contains(old:getEffectiveId()) and old:sameNameWith(gained) then
                    if not discard:contains(id) then discard:append(id) end
                    break
                end
            end
        end
    end
    if discard:isEmpty() or not gu_invoke(owner, self:objectName(), data) then return end
    room:setPlayerMark(owner, "hlxg_sanwen-Clear", 1)
    for _, card in sgs.qlist(owner:getHandcards()) do
        for _, id in sgs.qlist(discard) do
            if card:sameNameWith(sgs.Sanguosha:getCard(id)) then show:append(card:getEffectiveId()); break end
        end
    end
    room:showCard(owner, show)
    local n = discard:length()
    gu_throw(room, owner, discard, self:objectName())
    if owner:isAlive() then owner:drawCards(2 * n, self:objectName()) end
end)

hlxg_denglouvs = sgs.CreateViewAsSkillV2 {
    name = "hlxg_denglou", n = 1, expand_pile = "#hlxg_denglou_available",
    can_activate = function(self, request) return request:getPattern() == "@@hlxg_denglou" end,
    can_select_card = function(self, request, card)
        return request:getSelectedCardIds():isEmpty()
            and request:getInitiator():getTag("hlxg_denglou_ids"):toIntList():contains(card:getEffectiveId())
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request) return sgs.Sanguosha:getCard(request:getSelectedCardIds():first()) end,
}
hlxg_denglou = gu_trigger("hlxg_denglou", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:getPhase() ~= sgs.Player_Finish or not owner:isKongcheng() or not gu_invoke(owner, self:objectName()) then return end
    local ids = room:getNCards(4)
    local reveal = sgs.CardsMoveStruct()
    reveal.card_ids = ids; reveal.to_place = sgs.Player_PlaceTable
    reveal.reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_TURNOVER, owner:objectName(), self:objectName(), "")
    room:moveCardsAtomic(reveal, true)
    local basic, other = sgs.IntList(), sgs.IntList()
    for _, id in sgs.qlist(ids) do
        if sgs.Sanguosha:getCard(id):isKindOf("BasicCard") then basic:append(id) else other:append(id) end
    end
    gu_obtain(room, owner, other, self:objectName())
    while owner:isAlive() and not basic:isEmpty() do
        local usable, fallback = sgs.IntList(), {}
        for _, id in sgs.qlist(basic) do
            local card = sgs.Sanguosha:getCard(id)
            if room:getCardPlace(id) == sgs.Player_PlaceTable and card:isAvailable(owner)
                and not owner:isCardLimited(card, sgs.Card_MethodUse) then
                if card:targetFixed() then usable:append(id); fallback[id] = false
                else
                    local targets = sgs.SPlayerList()
                    for _, target in sgs.qlist(room:getAlivePlayers()) do
                        if card:targetFilter(sgs.PlayerList(), target, owner) and not room:isProhibited(owner, target, card) then targets:append(target) end
                    end
                    if not targets:isEmpty() then usable:append(id); fallback[id] = targets end
                end
            end
        end
        if usable:isEmpty() then break end
        owner:setTag("hlxg_denglou_ids", ToData(usable))
        room:notifyMoveToPile(owner, usable, "hlxg_denglou_available", sgs.Player_PlaceTable, true)
        local used = room:askForUseCard(owner, "@@hlxg_denglou", "@hlxg_denglou-use", -1, sgs.Card_MethodUse)
        room:notifyMoveToPile(owner, usable, "hlxg_denglou_available", sgs.Player_PlaceTable, false)
        owner:removeTag("hlxg_denglou_ids")
        if not used and owner:isAlive() then
            local id = usable:first()
            local use = sgs.CardUseStruct()
            use.card = sgs.Sanguosha:getCard(id); use.from = owner
            if fallback[id] then
                use.to:append(room:askForPlayerChosen(owner, fallback[id], self:objectName(), "@hlxg_denglou-target", false, true))
            end
            room:useCard(use)
            basic:removeOne(id)
        end
        local remaining = sgs.IntList()
        for _, id in sgs.qlist(basic) do if room:getCardPlace(id) == sgs.Player_PlaceTable then remaining:append(id) end end
        basic = remaining
    end
    if not basic:isEmpty() then
        local trash = gu_dummy(basic)
        room:throwCard(trash, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_NATURAL_ENTER, owner:objectName(), self:objectName(), ""), nil)
        trash:deleteLater()
    end
end)
