hlxg_minsi_record = gu_record("#hlxg_minsi_record", {sgs.CardsMoveOneTime, sgs.EventPhaseChanging, sgs.EventPhaseProceeding}, function(self, event, room, p, data)
    if event == sgs.CardsMoveOneTime then
        local move = data:toMoveOneTime()
        if not move.to or move.to_place ~= sgs.Player_PlaceHand or move.reason.m_skillName ~= "hlxg_minsi" then return end
        local recipient = room:findPlayerByObjectName(move.to:objectName())
        if not recipient then return end
        local ids = recipient:getTag("hlxg_minsi_ids"):toIntList()
        for _, id in sgs.qlist(move.card_ids) do if not ids:contains(id) then ids:append(id) end end
        recipient:setTag("hlxg_minsi_ids", ToData(ids))
    elseif event == sgs.EventPhaseProceeding then
        if p and p:getPhase() == sgs.Player_Discard then room:ignoreCards(p, p:getTag("hlxg_minsi_ids"):toIntList()) end
    elseif data:toPhaseChange().to == sgs.Player_NotActive then
        for _, q in sgs.qlist(room:getAllPlayers()) do q:removeTag("hlxg_minsi_ids") end
    end
end)
