hlxg_zhuide = sgs.CreateTriggerSkillV2 {
    name = "hlxg_zhuide", events = {sgs.Death},
    can_trigger = function(self, event, room, p, data)
        return p and data:toDeath().who == p and p:hasSkill(self:objectName()) and self:objectName() or false
    end,
    on_effect = function(self, event, room, p, ctx)
        local target = room:askForPlayerChosen(p, room:getOtherPlayers(p), self:objectName(), "@hlxg_zhuide-target", true, true)
        if not target then return false end
        local groups, names = {}, {}
        for _, id in sgs.qlist(room:getDrawPile()) do
            local card = sgs.Sanguosha:getCard(id)
            if card:isKindOf("BasicCard") then
                local name = card:isKindOf("Slash") and "slash" or card:objectName()
                if not groups[name] then groups[name] = {}; table.insert(names, name) end
                table.insert(groups[name], id)
            end
        end
        local ids = sgs.IntList()
        for i = 1, math.min(4, #names) do
            local name = table.remove(names, math.random(#names))
            local cards = groups[name]; ids:append(cards[math.random(#cards)])
        end
        gu_obtain(room, target, ids, self:objectName())
        return false
    end,
}

