-- ==================== c210_08
do
-- c210_08: literal Zhen Ji variants.
local function c21008_jink(name)
    return sgs.CreateViewAsSkillV2 {
        name = name,
        can_activate = function(self, request) return request:getPattern() == "jink" end,
        can_select_card = function(self, request, c)
            return request:getSelectedCardIds():isEmpty() and c:isBlack() and request:getInitiator():getCards("he"):contains(c)
        end,
        card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
        create_card = function(self, request)
            local c = sgs.Sanguosha:cloneCard("jink", sgs.Card_NoSuit, 0)
            c:addSubcards(request:getSelectedCardIds()); c:setSkillName(name); return c
        end,
    }
end
hljx_qingguo = c21008_jink("hljx_qingguo")
hlxg_feifu = c21008_jink("hlxg_feifu")
local function c21008_judge(room, owner)
    repeat
        local judge = sgs.JudgeStruct()
        judge.who = owner; judge.reason = "hljx_luoshen"; judge.pattern = ".|black"; judge.good = true
        room:judge(judge)
        if owner:isDead() or not judge.card then return end
        local id = judge.card:getEffectiveId()
        if judge.card:isRed() then room:setCardFlag(id, "hljx_luoshen_red_" .. owner:objectName()) end
        room:obtainCard(owner, judge.card, "hljx_luoshen", true)
        if not judge.card:isBlack() then return end
    until owner:isDead() or not gu_invoke(owner, "hljx_luoshen")
end
hljx_luoshen = gu_trigger("hljx_luoshen", {sgs.EventPhaseStart, sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    if event == sgs.EventPhaseStart then
        if p == owner and owner:getPhase() == sgs.Player_Start and gu_invoke(owner, self:objectName()) then c21008_judge(room, owner) end
        return
    end
    local move = data:toMoveOneTime()
    if move.from ~= owner then return end
    local lost = false
    local flag = "hljx_luoshen_red_" .. owner:objectName()
    for _, id in sgs.qlist(move.card_ids) do
        local c = sgs.Sanguosha:getCard(id)
        if c:hasFlag(flag) then lost = true; room:setCardFlag(id, "-" .. flag) end
    end
    if lost and owner:getMark("hljx_luoshen_lun") == 0 and gu_invoke(owner, self:objectName()) then
        room:addPlayerMark(owner, "hljx_luoshen_lun"); c21008_judge(room, owner)
    end
end)

hlxg_qixian = gu_trigger("hlxg_qixian", {sgs.EventPhaseEnd, sgs.EventPhaseChanging}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.EventPhaseEnd and owner:getPhase() == sgs.Player_Play then
        local c = room:askForCard(owner, ".|.|.|hand", "@hlxg_qixian-store", data, sgs.Card_MethodNone)
        if c then owner:addToPile("hlxg_qixian", c, false) end
    elseif event == sgs.EventPhaseChanging and data:toPhaseChange().to == sgs.Player_NotActive then
        gu_obtain(room, owner, owner:getPile("hlxg_qixian"), self:objectName())
    end
end)
hlxg_qixian_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_qixian_max", holder_selector = sgs.CorrectSkill_System,
    correct_func = function() return false end,
    fixed_func = function(self, ctx)
        local p = ctx:getPrimary()
        if p and p:hasSkill("hlxg_qixian") then return 7 end
        return false
    end,
}
hlxg_shenfu = gu_trigger("hlxg_shenfu", {sgs.EventPhaseStart, sgs.EventPhaseChanging}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    local name = self:objectName()
    if event == sgs.EventPhaseChanging then
        if data:toPhaseChange().to == sgs.Player_NotActive then
            local n = owner:getMark("hlxg_shenfu_count")
            room:setPlayerMark(owner, "hlxg_shenfu_count", 0)
            if n > 0 then owner:drawCards(math.min(5, n), name) end
        end
        return
    end
    if owner:getPhase() ~= sgs.Player_Finish then return end
    local odd = owner:getHandcardNum() % 2 == 1
    while owner:isAlive() do
        local candidates = sgs.SPlayerList()
        for _, q in sgs.qlist(room:getAlivePlayers()) do
            if (odd and q ~= owner) or (not odd and q:getMark("hlxg_shenfu_chosen-Clear") == 0) then candidates:append(q) end
        end
        if candidates:isEmpty() then break end
        local q = room:askForPlayerChosen(owner, candidates, name, "@hlxg_shenfu-target", true, true)
        if not q then break end
        room:addPlayerMark(owner, "hlxg_shenfu_count")
        if odd then
            local damage = sgs.DamageStruct(); damage.from = owner; damage.to = q; damage.damage = 1
            damage.nature = sgs.DamageStruct_Thunder; damage.reason = name; room:damage(damage)
            if q:isAlive() then break end
        else
            room:addPlayerMark(q, "hlxg_shenfu_chosen-Clear")
            local choices = "draw"
            if owner:canDiscard(q, "he") then choices = choices .. "+discard" end
            if room:askForChoice(owner, name, choices, sgs.QVariant(q:objectName())) == "discard" then
                local id = room:askForCardChosen(owner, q, "he", name, false, sgs.Card_MethodDiscard)
                room:throwCard(id, q, owner)
            else q:drawCards(1, name) end
            if q:isDead() or q:getHandcardNum() ~= q:getHp() then break end
        end
    end
end)

