hlxg_luoshen_zhenji3_use = sgs.CreateViewAsSkillV2 {
    name = "#hlxg_luoshen_zhenji3_use",
    can_activate = function(self, request) return request:getPattern() == "@@#hlxg_luoshen_zhenji3_use" and request:getInitiator():getMark("hlxg_luoshen_zhenji3_card") > 0 end,
