hlxg_luoshen_zhenji3 = gu_trigger("hlxg_luoshen_zhenji3", {sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    local move = data:toMoveOneTime()
    if move.from ~= owner then return end
    local lost = false
    for i, id in sgs.qlist(move.card_ids) do
        if move.from_places:at(i) == sgs.Player_PlaceHand and sgs.Sanguosha:getCard(id):isRed() then lost = true end
    end
    if not lost then return end
    for _, c in sgs.qlist(owner:getHandcards()) do if c:isRed() then return end end
    if not gu_invoke(owner, self:objectName()) then return end
    while owner:isAlive() do
        local ids = room:getNCards(1)
        if ids:isEmpty() then return end
        local id = ids:first(); local c = sgs.Sanguosha:getCard(id)
        room:moveCardTo(c, nil, sgs.Player_PlaceTable, true)
        if c:isRed() then room:obtainCard(owner, c, self:objectName(), true); return end
        room:setPlayerMark(owner, "hlxg_luoshen_zhenji3_card", id + 1)
        room:askForUseCard(owner, "@@#hlxg_luoshen_zhenji3_use", "@hlxg_luoshen_zhenji3-use", -1, sgs.Card_MethodUse, false)
        room:setPlayerMark(owner, "hlxg_luoshen_zhenji3_card", 0)
        if room:getCardPlace(id) == sgs.Player_PlaceTable then room:moveCardTo(c, nil, sgs.Player_DiscardPile, true) end
    end
end)

