-- ==================== c211_01
do
-- c211_01: literal Huanle variants; GU helpers are supplied by the assembler.
hlxg_ganfuren = sgs.General(extension_hl, "hlxg_ganfuren", "shu", 3, false)
hlxg_ganning = sgs.General(extension_hl, "hlxg_ganning", "wu", 4)
hljx_ganning = sgs.General(extension_hl, "hljx_ganning", "wu", 4)

hlxg_shushen = sgs.CreateRuleSkillV2 {
    name = "hlxg_shushen", global = true,
    events = {sgs.DamageInflicted, sgs.HpRecover},
    can_trigger = function(self, event, room, player, data)
        if event == sgs.HpRecover then
            return player and player:isAlive() and player:hasSkill(self:objectName())
                and self:objectName() or false, player
        end
        for _, owner in sgs.qlist(room:getAlivePlayers()) do
            if owner:hasSkill(self:objectName()) then return self:objectName(), owner end
        end
        return false
    end,
    on_effect = function(self, event, room, player, ctx)
        local data = ctx.original_data
        if event == sgs.DamageInflicted then
            local damage = data:toDamage()
            if not damage.to or damage.damage <= 0 then return false end
            for _, owner in sgs.qlist(room:getAlivePlayers()) do
                if owner:hasSkill(self:objectName()) and gu_invoke(owner, self:objectName(), data) then
                    room:loseHp(owner, 1, true, owner, self:objectName())
                    if owner:isAlive() then owner:drawCards(1, self:objectName()) end
                    if damage.to:isAlive() then damage.to:drawCards(1, self:objectName()) end
                    return true -- Only one prevention can resolve for this damage.
                end
            end
        else
            local n = data:toRecover().recover
            -- HpRecover carries the requested value in this engine. Prefer its
            -- committed recovery receipt, which is frozen before nested HpChanged.
            local parent = room:historyParent(room:currentHistoryEventId(), "recover", true)
            if parent and parent.id then
                local facts = room:queryHistoryFacts({kind = "actual_recover", event_id = parent.id, limit = 1})
                if facts and facts.items and facts.items[1] then
                    n = facts.items[1].data.amount
                end
            end
            for _ = 1, n do
                if not player:isAlive() then break end
                local to = room:askForPlayerChosen(player, room:getOtherPlayers(player), self:objectName(),
                    "@hlxg_shushen-recover", true, true)
                if to then to:drawCards(1, self:objectName()) end
            end
        end
        return false
    end,
}

hlxg_huangsi = gu_trigger("hlxg_huangsi", {sgs.EnterDying}, function(self, event, room, player, data, owner)
    if player ~= owner or owner:getMark("@hlxg_huangsi") == 0
        or not gu_invoke(owner, self:objectName(), data) then return end
    room:setPlayerMark(owner, "@hlxg_huangsi", 0)
    local ids = owner:handCards()
    local n = ids:length()
    if n > 0 then room:throwCard(ids, self:objectName(), owner) end
    if owner:isAlive() and owner:getHp() < 1 then
        room:recover(owner, sgs.RecoverStruct(self:objectName(), owner, 1 - owner:getHp()))
    end
    if owner:isAlive() then
        local to = room:askForPlayerChosen(owner, room:getAlivePlayers(), self:objectName(), "@hlxg_huangsi-target", false, true)
        if to then to:drawCards(n + 2, self:objectName()) end
    end
end, false, sgs.Skill_Limited, "@hlxg_huangsi")

local function hl_qixi_start(self, event, room, player, data, owner)
    if player ~= owner or player:getPhase() ~= sgs.Player_Play then return end
    local targets = sgs.SPlayerList()
    for _, to in sgs.qlist(room:getOtherPlayers(owner)) do
        if owner:canDiscard(to, "hej") then targets:append(to) end
    end
    if targets:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, targets, self:objectName(), "@" .. self:objectName() .. "-target", true, true)
    if to then
        local id = room:askForCardChosen(owner, to, "hej", self:objectName(), false, sgs.Card_MethodDiscard)
        if id >= 0 then room:throwCard(id, to, owner) end
    end
end
hlxg_qixi_ganning = gu_trigger("hlxg_qixi_ganning", {sgs.EventPhaseStart}, hl_qixi_start)
hljx_qixi = sgs.CreateViewAsSkillV2 {
    name = "hljx_qixi", n = 1, response_or_use = true,
    card_selection_feasible = function(self, request)
        return request:getSelectedCardIds():length() == 1
    end,
    can_activate = function(self, request)
        local owner = request:getInitiator()
        if not owner or request:getReason() ~= sgs.CardUseStruct_CARD_USE_REASON_PLAY then return false end
        local card = sgs.Sanguosha:cloneCard("dismantlement", sgs.Card_NoSuit, 0)
        local available = card:isAvailable(owner)
        card:deleteLater()
        return available
    end,
    can_select_card = function(self, request, card)
        return request:getSelectedCardIds():isEmpty() and card:isBlack()
    end,
    create_card = function(self, request)
        local ids = request:getSelectedCardIds()
        if ids:length() ~= 1 then return nil end
        local original = sgs.Sanguosha:getCard(ids:first())
        local card = sgs.Sanguosha:cloneCard("dismantlement", original:getSuit(), original:getNumber())
        card:addSubcard(original); card:setSkillName(self:objectName())
        return card
    end,
}
hljx_qixi_start = gu_trigger("#hljx_qixi_start", {sgs.EventPhaseStart}, function(self, event, room, player, data, owner)
    hl_qixi_start(hljx_qixi, event, room, player, data, owner)
end)

hljx_fenwei = gu_trigger("hljx_fenwei", {sgs.TargetSpecified, sgs.CardsMoveOneTime}, function(self, event, room, player, data, owner)
    if event == sgs.CardsMoveOneTime then
        local move = data:toMoveOneTime()
        if move.from and move.from:objectName() == owner:objectName() and move.is_last_handcard
            and move.from_places:contains(sgs.Player_PlaceHand) then
            room:setPlayerMark(owner, "@hljx_fenwei", 1)
        end
        return
    end
    local use = data:toCardUse()
    if not use.card or not use.card:isKindOf("TrickCard") or use.to:length() <= 1
        or owner:getMark("@hljx_fenwei") == 0 then return end
    owner:setTag("hljx_fenwei_use", data)
    local invoke = gu_invoke(owner, self:objectName(), data)
    if not invoke then owner:removeTag("hljx_fenwei_use"); return end
    room:setPlayerMark(owner, "@hljx_fenwei", 0)
    local chosen = room:askForPlayersChosen(owner, use.to, self:objectName(), 0, use.to:length(), "@hljx_fenwei-target", true)
    owner:removeTag("hljx_fenwei_use")
    local nullified = use.nullified_list
    for _, to in sgs.qlist(chosen) do
        if not table.contains(nullified, to:objectName()) then table.insert(nullified, to:objectName()) end
    end
    use.nullified_list = nullified; data:setValue(use)
    owner:drawCards(1, self:objectName())
end, false, sgs.Skill_Limited, "@hljx_fenwei")

hlxg_ganfuren:addSkill(hlxg_shushen)
hlxg_ganfuren:addSkill(hlxg_huangsi)
hlxg_ganning:addSkill(hlxg_qixi_ganning)
hljx_ganning:addSkill(hljx_qixi)
