-- ==================== c211_02
do
hlxg_ganning2 = sgs.General(extension_hl, "hlxg_ganning2", "god", 6, true, false, false, 3)
hlxg_jieying_ganning2 = gu_trigger("hlxg_jieying_ganning2", {sgs.TurnStart, sgs.EventPhaseStart, sgs.EventPhaseChanging}, function(self, event, room, p, data, owner)
    if event == sgs.TurnStart then
        if p ~= owner then return end
        for _, q in sgs.qlist(room:getAlivePlayers()) do if q:getMark("&hlxg_jieying_ganning2") > 0 then return end end
        room:setPlayerMark(p, "&hlxg_jieying_ganning2", 1)
    elseif event == sgs.EventPhaseStart then
        if p ~= owner then return end
        if p:getPhase() == sgs.Player_Finish and p:getMark("&hlxg_jieying_ganning2") > 0 then
            local q = room:askForPlayerChosen(p, room:getOtherPlayers(p), self:objectName(), "@hlxg_jieying_ganning2", true, true)
            if q then room:setPlayerMark(p, "&hlxg_jieying_ganning2", 0); room:setPlayerMark(q, "&hlxg_jieying_ganning2", 1) end
        end
    elseif data:toPhaseChange().to == sgs.Player_NotActive and p ~= owner and p:getMark("&hlxg_jieying_ganning2") > 0 then
        room:setPlayerMark(p, "&hlxg_jieying_ganning2", 0)
        gu_obtain(room, owner, p:handCards(), self:objectName())
    end
end)
hlxg_jieying_ganning2_draw = gu_record("#hlxg_jieying_ganning2_draw", {sgs.DrawNCards}, function(self, event, room, p, data)
    if p and p:getMark("&hlxg_jieying_ganning2") > 0 then local draw = data:toDraw(); draw.num = draw.num + 1; data:setValue(draw) end
end)
hlxg_jieying_ganning2_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_jieying_ganning2_max", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx) local p = ctx:getPrimary(); return p and p:getMark("&hlxg_jieying_ganning2") > 0 and 1 or 0 end,
}
hlxg_jieying_ganning2_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_jieying_ganning2_mod", holder_selector = sgs.CorrectSkill_System, pattern = "Slash",
    correct_func = function(self, ctx)
        local p, c = ctx:getPrimary(), ctx:getCard()
        if p and c and c:isKindOf("Slash") and ctx:getModType() == sgs.TargetModSkill_Residue and p:getMark("&hlxg_jieying_ganning2") > 0 then return 1 end
        return 0
    end,
}
hlxg_poxi = gu_active("hlxg_poxi", 1, 0, 0, gu_one, gu_one_feasible,
    function(self, room, source, targets)
        local to = targets[1]
        room:showAllCards(to, source)
        local picked, suits = sgs.IntList(), {}
        local own = sgs.IntList()
        for i = 1, 3 do
            local pool = sgs.IntList()
            for _, p in ipairs({source, to}) do
                for _, c in sgs.qlist(p:getHandcards()) do
                    if not suits[c:getSuit()] and source:canDiscard(p, c:getEffectiveId()) then pool:append(c:getEffectiveId()) end
                end
            end
            if pool:isEmpty() then return end
            room:fillAG(pool, source)
            local id = room:askForAG(source, pool, true, "hlxg_poxi")
            room:clearAG(source)
            if id < 0 then return end
            picked:append(id); suits[sgs.Sanguosha:getCard(id):getSuit()] = true
            if room:getCardOwner(id) == source then own:append(id) end
        end
        -- Selection is completed before any card is discarded.
        local all = gu_dummy(picked)
        local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_DISMANTLE, source:objectName(), to:objectName(), "hlxg_poxi", "")
        room:throwCard(all, reason, nil, source); all:deleteLater()
        if source:isDead() then return end
        if own:length() == 0 then room:loseMaxHp(source, 1)
        elseif own:length() == 2 then
            local r = sgs.RecoverStruct(); r.who = source; r.recover = 1; room:recover(source, r)
            if source:isAlive() then source:drawCards(1, "hlxg_poxi") end
        elseif own:length() == 3 then source:drawCards(3, "hlxg_poxi") end
    end)
hlxg_ganning2:addSkill(hlxg_jieying_ganning2); hlxg_ganning2:addSkill(hlxg_poxi)
hlxg_ganning2:addSkill(hlxg_jieying_ganning2_draw); hlxg_ganning2:addSkill(hlxg_jieying_ganning2_max); hlxg_ganning2:addSkill(hlxg_jieying_ganning2_mod)
extension_hl:insertRelatedSkills("hlxg_jieying_ganning2", "#hlxg_jieying_ganning2_draw")
extension_hl:insertRelatedSkills("hlxg_jieying_ganning2", "#hlxg_jieying_ganning2_max")
extension_hl:insertRelatedSkills("hlxg_jieying_ganning2", "#hlxg_jieying_ganning2_mod")

sgs.LoadTranslationTable {
    ["hlxg_ganning2"] = "甘宁[欢乐修改]", ["&hlxg_ganning2"] = "甘宁",
    ["hlxg_jieying_ganning2"] = "劫营",
    [":hlxg_jieying_ganning2"] = "回合开始时，若没有角色有“营”，你获得“营”。结束阶段，你可以将“营”交给一名其他角色。有“营”的角色摸牌阶段多摸一张牌、使用【杀】的次数上限+1、手牌上限+1。有“营”的其他角色的回合结束后，其弃其“营”，你获得其所有手牌。",
    ["&hlxg_jieying_ganning2"] = "营", ["@hlxg_jieying_ganning2"] = "劫营：你可以将“营”交给一名其他角色",
    ["hlxg_poxi"] = "魄袭",
    [":hlxg_poxi"] = "出牌阶段限一次，你可以观看一名其他角色的手牌，且可以弃置你与其手牌中三张花色均不同的牌，然后若你以此法被弃置的牌数为：0，你减1点体力上限；2，你回复1点体力并摸一张牌；3，你摸三张牌。",
}
end

-- ==================== c211_03
do
-- c211_03: literal 欢乐 variants.
hlxg_zumao = sgs.General(extension_hl, "hlxg_zumao", "wu", 4)
hlxg_zhurong = sgs.General(extension_hl, "hlxg_zhurong", "shu", 4, false)
hljx_zhurong = sgs.General(extension_hl, "hljx_zhurong", "shu", 4, false)

hlxg_yinbing = gu_trigger("hlxg_yinbing", {sgs.EventPhaseChanging, sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.EventPhaseChanging then
        if data:toPhaseChange().to ~= sgs.Player_Discard then return end
        local cards = room:askForExchange(owner, self:objectName(), 999, 1, true, "@hlxg_yinbing", true, "^BasicCard")
        if cards then owner:addToPile("hlxg_yinbing", cards, true); cards:deleteLater() end
    else
        local d = data:toDamage()
        if not d.card or not d.card:isKindOf("Slash") then return end
        local ids = owner:getPile("hlxg_yinbing")
        if not ids:isEmpty() then
            room:fillAG(ids, owner)
            local id = room:askForAG(owner, ids, false, self:objectName())
            room:clearAG(owner)
            room:throwCard(id, self:objectName(), owner)
        end
        if owner:isAlive() then owner:drawCards(1, self:objectName()) end
    end
end)
hlxg_juedi = gu_trigger("hlxg_juedi", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Start or owner:getPile("hlxg_yinbing"):isEmpty() then return end
    local candidates = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getOtherPlayers(owner)) do
        if q:getHp() <= owner:getHp() then candidates:append(q) end
    end
    local choice = candidates:isEmpty() and "remove" or room:askForChoice(owner, self:objectName(), "remove+give")
    local ids = owner:getPile("hlxg_yinbing")
    local n = ids:length()
    if choice == "remove" then
        gu_throw(room, owner, ids, self:objectName())
        local count = owner:getMaxHp() + 1 - owner:getHandcardNum()
        if owner:isAlive() and count > 0 then owner:drawCards(count, self:objectName()) end
    else
        local q = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_juedi", false, true)
        gu_obtain(room, q, ids, self:objectName())
        if q:isAlive() then
            local recover = sgs.RecoverStruct(); recover.who = owner; recover.recover = 1
            room:recover(q, recover)
            if q:isAlive() then q:drawCards(n, self:objectName()) end
        end
    end
end, true)
