local function c211_03_juxiang(name, enhanced)
    return gu_trigger(name, {sgs.CardEffected, sgs.PreCardUsed, sgs.Damage, sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
        local flag = name .. "_damage"
        if event == sgs.CardEffected then
            local e = data:toCardEffect()
            if e.to == owner and e.card and e.card:isKindOf("SavageAssault") then
                e.nullified = true; data:setValue(e)
            end
        elseif event == sgs.PreCardUsed then
            local use = data:toCardUse()
            if use.card and use.card:isKindOf("SavageAssault") then room:setCardFlag(use.card, "-" .. flag) end
        elseif event == sgs.Damage then
            local d = data:toDamage()
            if d.card and d.card:isKindOf("SavageAssault") then room:setCardFlag(d.card, flag) end
        else
            local m = data:toMoveOneTime()
            if m.to_place ~= sgs.Player_DiscardPile then return end
            local reason = m.reason.m_reason % 16
            local use = m.reason.m_useStruct
            if reason == sgs.CardMoveReason_S_REASON_USE and use.card and use.card:isKindOf("SavageAssault") and use.from ~= owner then
                local ids = sgs.IntList()
                local materials = use.card:isVirtualCard() and use.card:getSubcards() or nil
                for _, id in sgs.qlist(m.card_ids) do
                    if room:getCardPlace(id) == sgs.Player_DiscardPile
                        and ((materials and materials:contains(id)) or (not materials and id == use.card:getEffectiveId())) then ids:append(id) end
                end
                if not ids:isEmpty() then
                    local damaged = use.card:hasFlag(flag)
                    gu_obtain(room, owner, ids, name)
                    if enhanced and damaged and owner:isAlive() then owner:drawCards(1, name) end
                end
            elseif enhanced and reason == sgs.CardMoveReason_S_REASON_DISCARD and m.from and m.from:objectName() ~= owner:objectName() then
                for _, id in sgs.qlist(m.card_ids) do
                    local card = sgs.Sanguosha:getCard(id)
                    if card:isKindOf("SavageAssault") and room:getCardPlace(id) == sgs.Player_DiscardPile then
                        room:obtainCard(owner, card, name, true)
                    end
                end
            end
        end
    end, true)
end
