        or owner:getMark("hlxg_lieren-Clear") >= 2 then return end
    room:addPlayerMark(owner, "hlxg_lieren-Clear")
    if d.to:isDead() or not owner:canDiscard(d.to, "h") then return end
    local id = room:askForCardChosen(owner, d.to, "h", self:objectName(), false, sgs.Card_MethodDiscard)
    local number = sgs.Sanguosha:getCard(id):getNumber()
