hljx_zhangbiao = sgs.CreateViewAsSkillV2 {
    name = "hljx_zhangbiao", limit_scope = sgs.Skill_Limit_Phase, phase_name = "Play", max_usage_limit = 1,
    can_activate = function(self, request)
        return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY and sgs.Slash_IsAvailable(request:getInitiator())
    end,
    can_select_card = function(self, request, card)
        return request:getInitiator():handCards():contains(card:getEffectiveId())
    end,
    card_selection_feasible = function(self, request) return not request:getSelectedCardIds():isEmpty() end,
    create_card = function(self, request)
        if request:getSelectedCardIds():isEmpty() then return nil end
        local card = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0)
        card:addSubcards(request:getSelectedCardIds()); card:setSkillName("hljx_zhangbiao")
        return card
    end,
}
