hlxg_zhuandui = gu_trigger("hlxg_zhuandui", {sgs.TargetSpecified, sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    local use = data:toCardUse()
    if not use.card or not use.card:isKindOf("Slash") then return end
    local opponents = {}
    if event == sgs.TargetSpecified and use.from == owner then
        for _, to in sgs.qlist(use.to) do if to ~= owner then table.insert(opponents, to) end end
    elseif event == sgs.TargetConfirmed and use.to:contains(owner) and use.from ~= owner then
        table.insert(opponents, use.from)
    end
    for _, to in ipairs(opponents) do
        if to and owner:canPindian(to) and gu_invoke(owner, self:objectName(), sgs.QVariant(to)) and owner:pindian(to, self:objectName()) then
            owner:drawCards(1, self:objectName())
            use = data:toCardUse()
            if event == sgs.TargetSpecified then
                local names = use.no_respond_list; table.insert(names, to:objectName()); use.no_respond_list = names
            else
                local names = use.nullified_list; table.insert(names, owner:objectName()); use.nullified_list = names
            end
            data:setValue(use)
        end
    end
end)
hlxg_tianbian = gu_trigger("hlxg_tianbian", {sgs.AskforPindianCard, sgs.PindianVerifying}, function(self, event, room, p, data, owner)
    local pd = data:toPindian()
    if not pd or p ~= pd.from or (owner ~= pd.from and owner ~= pd.to) then return end
    local from = owner == pd.from
    local card = from and pd.from_card or pd.to_card
    if event == sgs.AskforPindianCard then
        if not card and gu_invoke(owner, self:objectName(), data) then
            local top = sgs.Sanguosha:getCard(room:drawCard())
            if from then pd.from_card = top else pd.to_card = top end
            data:setValue(pd)
        end
    elseif card and card:getSuit() == sgs.Card_Heart then
        if from then pd.from_number = 13 else pd.to_number = 13 end
        data:setValue(pd)
    end
end)
hlxg_jianzheng = gu_trigger("hlxg_jianzheng", {sgs.TargetSpecifying}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if not use.card or not use.card:isKindOf("Slash") or not use.from or p ~= use.from or use.from == owner
        or use.to:isEmpty() or use.to:contains(owner) or not use.from:inMyAttackRange(owner) or owner:isKongcheng() then return end
    local card = room:askForCard(owner, ".|.|.|hand", "@hlxg_jianzheng", data, sgs.Card_MethodNone)
    if not card then return end
    room:moveCardTo(card, owner, nil, sgs.Player_DrawPile, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_PUT, owner:objectName(), self:objectName(), ""), false)
    for _, to in sgs.qlist(use.to) do to:removeQinggangTag(use.card) end
    use.to = sgs.SPlayerList()
    if not use.card:isBlack() then use.to:append(owner) end
    data:setValue(use)
end)

hlxg_lihuo = gu_trigger("hlxg_lihuo", {sgs.ChangeSlash, sgs.Damage, sgs.CardFinished}, function(self, event, room, p, data, owner)
    if event == sgs.ChangeSlash then
        local use = data:toCardUse()
        if use.from ~= owner or not use.card or use.card:objectName() ~= "slash" or not gu_invoke(owner, self:objectName(), data) then return end
        local fire = sgs.Sanguosha:cloneCard("fire_slash", use.card:getSuit(), use.card:getNumber())
        if use.card:isVirtualCard() then fire:addSubcards(use.card:getSubcards()) else fire:addSubcard(use.card) end
        fire:setSkillName(self:objectName()); fire:setFlags("hlxg_lihuo_changed")
        use:changeCard(fire); fire:deleteLater()
        local extra = sgs.SPlayerList()
        for _, to in sgs.qlist(room:getAlivePlayers()) do
            if not use.to:contains(to) and owner:canSlash(to, fire, true) then extra:append(to) end
        end
        if not extra:isEmpty() then
            local to = room:askForPlayerChosen(owner, extra, self:objectName(), "@hlxg_lihuo-extra", true)
            if to then use.to:append(to); room:sortByActionOrder(use.to) end
        end
        data:setValue(use)
    elseif event == sgs.Damage then
        local d = data:toDamage()
        if d.from ~= owner or not d.card or not d.card:isKindOf("FireSlash") then return end
        if d.card:hasFlag("hlxg_lihuo_changed") then d.card:setTag("hlxg_lihuo_damage", sgs.QVariant(d.card:getTag("hlxg_lihuo_damage"):toInt() + d.damage)) end
        if owner:getMark("hlxg_lihuo-Clear") == 0 then
            room:setPlayerMark(owner, "hlxg_lihuo-Clear", 1); owner:drawCards(1, self:objectName())
        end
    else
        local use = data:toCardUse()
        if use.from == owner and use.card and use.card:hasFlag("hlxg_lihuo_changed") and use.card:getTag("hlxg_lihuo_damage"):toInt() >= 2 then room:loseHp(owner, 1) end
    end
end)
hlxg_lihuo_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_lihuo_mod", pattern = "Slash", holder_selector = sgs.CorrectSkill_Primary,
    correct_func = function(self, ctx)
        local p, c = ctx:getPrimary(), ctx:getCard()
        if p and p:hasSkill("hlxg_lihuo") and c and c:isKindOf("FireSlash") and ctx:getModType() == sgs.TargetModSkill_ExtraTarget then return 1 end
        return 0
    end,
}
hlxg_chunlao = gu_trigger("hlxg_chunlao", {sgs.EventPhaseStart, sgs.AskForPeaches}, function(self, event, room, p, data, owner)
    if event == sgs.EventPhaseStart then
        if p ~= owner or p:getPhase() ~= sgs.Player_Finish or not owner:getPile("hlxg_chunlao"):isEmpty() or owner:isKongcheng() then return end
        local cards = room:askForExchange(owner, self:objectName(), owner:getHandcardNum(), 1, false, "@hlxg_chunlao", true, "Slash")
        if cards then owner:addToPile("hlxg_chunlao", cards) end
    else
        local dying = data:toDying().who
        while dying and dying:isAlive() and dying:getHp() <= 0 and owner:isAlive() and not owner:getPile("hlxg_chunlao"):isEmpty() do
            local ids = owner:getPile("hlxg_chunlao")
            room:fillAG(ids, owner)
            local id = room:askForAG(owner, ids, true, self:objectName())
            room:clearAG(owner)
            if id < 0 then break end
            local card = sgs.Sanguosha:getCard(id)
            room:throwCard(card, self:objectName(), nil)
            local wine = sgs.Sanguosha:cloneCard("analeptic", sgs.Card_NoSuit, 0)
            wine:setSkillName("_hlxg_chunlao")
            room:useCard(sgs.CardUseStruct(wine, dying, dying), false)
            if card:isBlack() then owner:drawCards(2, self:objectName())
            elseif card:isRed() then local rec = sgs.RecoverStruct(); rec.who = owner; rec.recover = 1; room:recover(owner, rec) end
        end
    end
end)

