hlxg_qiaoshuo_effect = gu_trigger("#hlxg_qiaoshuo_effect", {sgs.PreCardUsed, sgs.EventPhaseProceeding}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.EventPhaseProceeding then
        if p:getPhase() == sgs.Player_Discard and p:getMark("hlxg_qiaoshuo_failed-Clear") == 0 then
            for _, card in sgs.qlist(p:getHandcards()) do if card:isKindOf("TrickCard") then room:ignoreCards(p, card) end end
        end
        return
    end
    if p:getMark("hlxg_qiaoshuo_ready-Clear") == 0 or p:getMark("hlxg_qiaoshuo_failed-Clear") > 0 then return end
    local use = data:toCardUse(); local c = use.card
    if not c or not (c:isKindOf("BasicCard") or c:isNDTrick()) then return end
    room:setPlayerMark(p, "hlxg_qiaoshuo_ready-Clear", 0)
    c:setFlags("hlxg_qiaoshuo_select")
    local extra = sgs.SPlayerList()
    for _, to in sgs.qlist(room:getAlivePlayers()) do
        if not use.to:contains(to) and p:canUse(c, to) then
            if not c:isKindOf("Collateral") then extra:append(to)
            elseif to:getWeapon() then
                for _, v in sgs.qlist(room:getOtherPlayers(to)) do
                    if to:canSlash(v) then extra:append(to); break end
                end
            end
        end
    end
    local choices = {"cancel"}
    if not extra:isEmpty() then table.insert(choices, "add") end
    if not use.to:isEmpty() then table.insert(choices, "remove") end
    local choice = room:askForChoice(p, "hlxg_qiaoshuo", table.concat(choices, "+"), data)
    if choice == "add" then
        local to = room:askForPlayerChosen(p, extra, "hlxg_qiaoshuo", "@hlxg_qiaoshuo-add")
        if c:isKindOf("Collateral") then
            local victims = sgs.SPlayerList()
            for _, v in sgs.qlist(room:getOtherPlayers(to)) do if to:canSlash(v) then victims:append(v) end end
            if not victims:isEmpty() then to:setTag("attachTarget", sgs.QVariant(room:askForPlayerChosen(p, victims, "hlxg_qiaoshuo", "@hlxg_qiaoshuo-victim"))); use.to:append(to) end
        else use.to:append(to) end
        room:sortByActionOrder(use.to)
    elseif choice == "remove" then use.to:removeOne(room:askForPlayerChosen(p, use.to, "hlxg_qiaoshuo", "@hlxg_qiaoshuo-remove")) end
    c:setFlags("-hlxg_qiaoshuo_select"); data:setValue(use)
end)
hlxg_zongshi_jianyong = gu_trigger("hlxg_zongshi_jianyong", {sgs.Pindian}, function(self, event, room, p, data, owner)
    local pd = data:toPindian()
    if not pd or (owner ~= pd.from and owner ~= pd.to) then return end
    local won = owner == pd.from and pd.from_number > pd.to_number or owner == pd.to and pd.to_number > pd.from_number
    local card
    if won then card = owner == pd.from and pd.to_card or pd.from_card
    else card = owner == pd.from and pd.from_card or pd.to_card end
    if card and room:getCardPlace(card:getEffectiveId()) == sgs.Player_PlaceTable and gu_invoke(owner, self:objectName(), data) then room:obtainCard(owner, card) end
end)
