-- ==================== c211_05
do
-- c211_05; GU helpers are supplied by the assembler.
hlxg_guanlu = sgs.General(extension_hl, "hlxg_guanlu", "wei", 3)
hlxg_mifuren = sgs.General(extension_hl, "hlxg_mifuren", "shu", 3, false)
hlxg_mizhu = sgs.General(extension_hl, "hlxg_mizhu", "shu", 3)

local function hl_bosuan_transform(room, id)
    local name = room:getTag("hlxg_bosuan_identity_" .. id):toString()
    if name == "" then return end
    local original = sgs.Sanguosha:getEngineCard(id)
    local card = sgs.Sanguosha:cloneCard(name, original:getSuit(), original:getNumber())
    card:setSkillName("hlxg_bosuan")
    local wrapped = sgs.Sanguosha:getWrappedCard(id)
    wrapped:takeOver(card)
    card:deleteLater()
    -- The draw already reveals these cards; subsequent public moves stay public.
    local holder = room:getCardOwner(id)
    if holder and room:getCardPlace(id) == sgs.Player_PlaceHand then
        room:notifyUpdateCard(holder, id, wrapped)
    else
        room:broadcastUpdateCard(room:getAllPlayers(), id, wrapped)
    end
    return wrapped
end
hlxg_bosuan_filter = sgs.CreateFilterSkill {
    name = "#hlxg_bosuan_filter",
    view_filter = function(self, card)
        local room = sgs.Sanguosha:currentRoom()
        return room and room:getTag("hlxg_bosuan_identity_" .. card:getId()):toString() ~= ""
    end,
    view_as = function(self, card)
        return hl_bosuan_transform(sgs.Sanguosha:currentRoom(), card:getId())
    end,
}
extension_hl:addSkills(hlxg_bosuan_filter)
hlxg_bosuan = gu_active("hlxg_bosuan", 1, 0, 0, gu_one, gu_one_feasible,
    function(self, room, source, targets)
        local names, seen = {}, {}
        for _, id in sgs.qlist(sgs.Sanguosha:getRandomCards()) do
            local c = sgs.Sanguosha:getEngineCard(id)
            if not c:isKindOf("EquipCard") and not seen[c:objectName()] then
                seen[c:objectName()] = true
                table.insert(names, c:objectName())
            end
        end
        table.sort(names)
        if #names < 2 then return end
        local first = room:askForChoice(source, "hlxg_bosuan", table.concat(names, "+"))
        for i = #names, 1, -1 do if names[i] == first then table.remove(names, i) end end
        local second = room:askForChoice(source, "hlxg_bosuan", table.concat(names, "+"))
        local pending = gu_names(targets[1], "hlxg_bosuan_pending")
        table.insert(pending, first); table.insert(pending, second)
        gu_setnames(targets[1], "hlxg_bosuan_pending", pending)
        -- Identity has no expiry in the excerpt. Every future holder can refilter it.
        for _, p in sgs.qlist(room:getAllPlayers()) do
            if not p:hasSkill("#hlxg_bosuan_filter", true) then room:acquireSkill(p, "#hlxg_bosuan_filter", false) end
        end
    end)
hlxg_bosuan_draw = sgs.CreateRuleSkillV2 {
    name = "#hlxg_bosuan_draw", global = true,
    events = {sgs.EventPhaseProceeding},
    can_trigger = function(self, event, room, player, data)
        return player and player:isAlive() and player:getPhase() == sgs.Player_Draw
            and player:getTag("hlxg_bosuan_pending"):toString() ~= "" and self:objectName() or false, player
    end,
    on_effect = function(self, event, room, player, ctx)
        local pending = gu_names(player, "hlxg_bosuan_pending")
        player:removeTag("hlxg_bosuan_pending")
        local ids = player:drawCardsList(2, "hlxg_bosuan")
        room:showCard(player, ids)
        -- If several declarations precede this draw, later declarations win.
        local offset = #pending - 2
        for i, id in sgs.qlist(ids) do
            room:setTag("hlxg_bosuan_identity_" .. id, sgs.QVariant(pending[offset + i + 1]))
            hl_bosuan_transform(room, id)
        end
        return true -- Replace the normal draw-phase proceeding, not other draws.
    end,
}
hlxg_bosuan_moves = gu_record("#hlxg_bosuan_moves", {sgs.CardsMoveOneTime}, function(self, event, room, player, data)
    for _, id in sgs.qlist(data:toMoveOneTime().card_ids) do hl_bosuan_transform(room, id) end
end)
extension_hl:addSkills(hlxg_bosuan_draw)
extension_hl:addSkills(hlxg_bosuan_moves)
extension_hl:insertRelatedSkills("hlxg_bosuan", "#hlxg_bosuan_filter")
extension_hl:insertRelatedSkills("hlxg_bosuan", "#hlxg_bosuan_draw")
extension_hl:insertRelatedSkills("hlxg_bosuan", "#hlxg_bosuan_moves")

hlxg_mingjie = gu_trigger("hlxg_mingjie", {sgs.EventPhaseStart}, function(self, event, room, player, data, owner)
    if player ~= owner or owner:getPhase() ~= sgs.Player_Finish then return end
    local n, allred = 0, true
    while n < 3 and owner:isAlive() and gu_invoke(owner, self:objectName(), data) do
        local ids = owner:drawCardsList(1, self:objectName())
        if ids:isEmpty() then break end
        n = n + 1
        if not sgs.Sanguosha:getCard(ids:first()):isRed() then allred = false; break end
    end
    if n > 0 and allred and owner:isAlive() then room:recover(owner, sgs.RecoverStruct(self:objectName(), owner, 1)) end
end)
hlxg_guanlu:addSkill(hlxg_bosuan)
hlxg_guanlu:addSkill(hlxg_mingjie)
-- tenyeartuiyan has exactly the same text; reuse rather than duplicate its logic.
hlxg_guanlu:addSkill("tenyeartuiyan")

hlxg_yongjue_record = gu_record("#hlxg_yongjue_record", {sgs.CardUsed}, function(self, event, room, player, data)
    local use = data:toCardUse()
    if use.card then use.card:setTag("hlxg_yongjue_first", sgs.QVariant(false)) end
    if use.from and use.from:getPhase() == sgs.Player_Play and use.card and use.card:isKindOf("Slash") then
        if use.from:getMark("hlxg_yongjue_slashes-PlayClear") == 0 then use.card:setTag("hlxg_yongjue_first", sgs.QVariant(true)) end
        room:addPlayerMark(use.from, "hlxg_yongjue_slashes-PlayClear")
    end
end)
extension_hl:addSkills(hlxg_yongjue_record)
hlxg_yongjue = gu_trigger("hlxg_yongjue", {sgs.CardFinished, sgs.DamageInflicted}, function(self, event, room, player, data, owner)
    if event == sgs.CardFinished then
        local use = data:toCardUse()
        if use.from == owner or not use.card or not use.card:getTag("hlxg_yongjue_first"):toBool() then return end
        local ids = use.card:getSubcards()
        if not use.card:isVirtualCard() then ids = sgs.IntList(); ids:append(use.card:getEffectiveId()) end
        if ids:isEmpty() then return end
        for _, id in sgs.qlist(ids) do
            local place = room:getCardPlace(id)
            if place ~= sgs.Player_PlaceTable and place ~= sgs.Player_DiscardPile then return end
        end
        if not ids:isEmpty() and gu_invoke(owner, self:objectName(), data) then
            gu_obtain(room, owner, ids, self:objectName())
        end
    else
        local damage = data:toDamage()
        if damage.to ~= owner or not damage.card or not damage.card:isKindOf("Slash")
            or owner:getMark("hlxg_yongjue_prevent-Clear") > 0 then return end
        local pattern = "Slash|.|" .. math.max(0, damage.card:getNumber()) .. "~13|."
        if room:askForCard(owner, pattern, "@hlxg_yongjue-discard", data, sgs.Card_MethodDiscard, nil, false, self:objectName()) then
            room:addPlayerMark(owner, "hlxg_yongjue_prevent-Clear")
            return true
        end
    end
end)
extension_hl:insertRelatedSkills("hlxg_yongjue", "#hlxg_yongjue_record")
local function hl_guixiu(room, owner)
    if owner:getHp() % 2 ~= 0 then owner:drawCards(1, "hlxg_guixiu")
    else room:recover(owner, sgs.RecoverStruct("hlxg_guixiu", owner, 1)) end
end
hlxg_guixiu = gu_trigger("hlxg_guixiu", {sgs.EventPhaseStart, sgs.EnterDying}, function(self, event, room, player, data, owner)
    if player ~= owner then return end
    local modified = owner:getMark("hlxg_guixiu_modified") > 0
    if event == sgs.EventPhaseStart then
        if owner:getPhase() ~= sgs.Player_Finish then return end
    elseif not modified then return end
    if modified then
        if owner:getMark("hlxg_guixiu_used-Clear") > 0 then return end
        room:addPlayerMark(owner, "hlxg_guixiu_used-Clear")
    end
    hl_guixiu(room, owner)
end, true)
hlxg_cunsi = gu_active("hlxg_cunsi", nil, 0, 0, gu_one, gu_one_feasible,
    function(self, room, source, targets)
        room:setPlayerMark(source, "@hlxg_cunsi", 0)
        local to = targets[1]
        room:acquireSkill(to, "hlxg_yongjue")
        room:setPlayerMark(source, "hlxg_guixiu_modified", 1)
        room:changeTranslation(source, "hlxg_guixiu", 2)
        local requested = math.max(0, source:getHp())
        source:setTag("hlxg_cunsi_lost", sgs.QVariant(0))
        if requested > 0 then room:loseHp(source, requested, true, source, "hlxg_cunsi") end
        local x = source:getTag("hlxg_cunsi_lost"):toInt()
        source:removeTag("hlxg_cunsi_lost")
        if to:isAlive() then to:drawCards(x + 1, "hlxg_cunsi") end
    end, nil, function(p) return p:getMark("@hlxg_cunsi") > 0 end)
hlxg_cunsi_loss = gu_record("#hlxg_cunsi_loss", {sgs.HpLost}, function(self, event, room, player, data)
    local lost = data:toHpLost()
    if lost.to and lost.reason == "hlxg_cunsi" then
        lost.to:setTag("hlxg_cunsi_lost", sgs.QVariant(lost.to:getTag("hlxg_cunsi_lost"):toInt() + lost.lose))
    end
end)
extension_hl:addSkills(hlxg_cunsi_loss)
extension_hl:insertRelatedSkills("hlxg_cunsi", "#hlxg_cunsi_loss")
hlxg_cunsi_limit = sgs.CreateTriggerSkillV2 {
    name = "#hlxg_cunsi_limit", frequency = sgs.Skill_Limited, limit_mark = "@hlxg_cunsi",
    events = {sgs.GameStart}, can_trigger = function() return false end,
}
hlxg_mifuren:addSkill(hlxg_yongjue)
hlxg_mifuren:addSkill(hlxg_cunsi)
hlxg_mifuren:addSkill(hlxg_cunsi_limit)
hlxg_mifuren:addSkill(hlxg_guixiu)
extension_hl:insertRelatedSkills("hlxg_cunsi", "#hlxg_cunsi_limit")

hlxg_jugu = gu_trigger("hlxg_jugu", {sgs.EventPhaseStart}, function(self, event, room, player, data, owner)
    if player ~= owner or owner:getPhase() ~= sgs.Player_RoundStart then return end
    local targets = room:askForPlayersChosen(owner, room:getAlivePlayers(), self:objectName(), 0,
        math.max(0, owner:getMaxHp()), "@hlxg_jugu", true, true)
    if targets:isEmpty() then return end
    local card = sgs.Sanguosha:cloneCard("amazing_grace", sgs.Card_NoSuit, 0)
    card:setSkillName(self:objectName())
    local use = sgs.CardUseStruct()
    use.card = card; use.from = owner; use.to = targets
    room:useCard(use, false)
    card:deleteLater()
end, true)
hlxg_jugu_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_jugu_max", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        return p and p:hasSkill("hlxg_jugu") and p:getMaxHp() or 0
    end,
}
hlxg_ziyuan = gu_active("hlxg_ziyuan", 1, 0, math.huge, gu_one, gu_one_feasible,
    function(self, room, source, targets)
        local total = 0
        for _, id in sgs.qlist(self:getSubcards()) do total = total + sgs.Sanguosha:getCard(id):getNumber() end
        gu_obtain(room, targets[1], self:getSubcards(), "hlxg_ziyuan")
        if total >= 13 and targets[1]:isAlive() then room:recover(targets[1], sgs.RecoverStruct("hlxg_ziyuan", source, 1)) end
        if total <= 13 and source:isAlive() then source:drawCards(1, "hlxg_ziyuan") end
    end, function(request, card) return not card:isEquipped() end)
hlxg_mizhu:addSkill(hlxg_jugu)
hlxg_mizhu:addSkill(hlxg_jugu_max)
hlxg_mizhu:addSkill(hlxg_ziyuan)
extension_hl:insertRelatedSkills("hlxg_jugu", "#hlxg_jugu_max")

sgs.LoadTranslationTable {
    ["hlxg_guanlu"] = "管辂[欢乐修改]", ["&hlxg_guanlu"] = "管辂",
    ["hlxg_bosuan"] = "卜算", [":hlxg_bosuan"] = "出牌阶段限一次，你可以令一名其他角色下个摸牌阶段改为摸两张牌并展示之，这两张牌分别视为你声明的两张不同的非装备牌。",
    ["hlxg_mingjie"] = "命戒", [":hlxg_mingjie"] = "结束阶段，你可以摸一张牌，若此牌为红色，你可以重复此流程直到摸到黑色牌或第三张牌。若你以此法摸到的牌均为红色，你回复1点体力。",
    ["hlxg_tuiyan"] = "推演", [":hlxg_tuiyan"] = "出牌阶段开始时，你可以观看牌堆顶的三张牌。",
    ["hlxg_mifuren"] = "糜夫人[欢乐修改]", ["&hlxg_mifuren"] = "糜夫人",
    ["hlxg_yongjue"] = "勇决", [":hlxg_yongjue"] = "当其他角色于其出牌阶段内使用的第一张【杀】结算结束后，你可以获得之。每回合限一次，当你受到【杀】的伤害时，你可以弃置一张点数不小于此【杀】的【杀】，然后防止此伤害。",
    ["@hlxg_yongjue-discard"] = "勇决：你可以弃置一张点数不小于造成伤害的杀的杀，防止此伤害",
    ["hlxg_cunsi"] = "存嗣", [":hlxg_cunsi"] = "限定技，出牌阶段，你可以令一名其他角色获得〖勇决〗，然后你修改〖闺秀〗并失去所有体力，令其摸X+1张牌（X为你以此法失去的体力值）。",
    ["@hlxg_cunsi"] = "存嗣",
