-- ==================== c211_06
do
hlxg_mifangfushiren = sgs.General(extension_hl, "hlxg_mifangfushiren", "shu", 4)
hlxg_jiling = sgs.General(extension_hl, "hlxg_jiling", "qun", 4)
hlxg_yanghu = sgs.General(extension_hl, "hlxg_yanghu", "wei", 3)

hlxg_fengshi = gu_trigger("hlxg_fengshi", {sgs.TargetSpecified, sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if not use.card then return end
    local target
    if event == sgs.TargetSpecified and use.from == owner then
        local candidates = sgs.SPlayerList()
        for _, q in sgs.qlist(use.to) do
            if q:isAlive() and q:getHandcardNum() < owner:getHandcardNum()
                and owner:canDiscard(owner, "he") and owner:canDiscard(q, "he") then candidates:append(q) end
        end
        if candidates:isEmpty() then return end
        target = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_fengshi", true, true)
        if not target then return end
        local id = room:askForCardChosen(owner, owner, "he", self:objectName(), false, sgs.Card_MethodDiscard)
        room:throwCard(id, self:objectName(), owner)
        if target:isAlive() and owner:canDiscard(target, "he") then
            id = room:askForCardChosen(owner, target, "he", self:objectName(), false, sgs.Card_MethodDiscard)
            room:throwCard(id, self:objectName(), target, owner)
        end
    elseif event == sgs.TargetConfirmed and p == owner and use.to:contains(owner)
        and use.from and use.from ~= owner and use.from:isAlive()
        and owner:getHandcardNum() < use.from:getHandcardNum() and owner:canDiscard(use.from, "he") then
        if not gu_invoke(owner, self:objectName(), data) then return end
        local id = room:askForCardChosen(owner, use.from, "he", self:objectName(), false, sgs.Card_MethodDiscard)
        room:throwCard(id, self:objectName(), use.from, owner)
        target = owner
    end
    if target then
        local key = "hlxg_fengshi_" .. target:objectName()
        use.card:setTag(key, sgs.QVariant(use.card:getTag(key):toInt() + 1))
    end
end)
hlxg_fengshi_damage = gu_record("#hlxg_fengshi_damage", {sgs.DamageCaused, sgs.CardFinished}, function(self, event, room, p, data)
    if event == sgs.DamageCaused then
        local d = data:toDamage()
        if d.card and d.to then
            d.damage = d.damage + d.card:getTag("hlxg_fengshi_" .. d.to:objectName()):toInt()
            data:setValue(d)
        end
    else
        local use = data:toCardUse()
        if use.card then
            for _, q in sgs.qlist(room:getAllPlayers(true)) do use.card:removeTag("hlxg_fengshi_" .. q:objectName()) end
        end
    end
end)
hlxg_mifangfushiren:addSkill(hlxg_fengshi)
hlxg_mifangfushiren:addSkill(hlxg_fengshi_damage)
extension_hl:insertRelatedSkills("hlxg_fengshi", "#hlxg_fengshi_damage")

hlxg_shuangren = gu_trigger("hlxg_shuangren", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Play then return end
    local candidates = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getOtherPlayers(owner)) do if owner:canPindian(q) then candidates:append(q) end end
    if candidates:isEmpty() then return end
    local opponent = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_shuangren", true, true)
    if not opponent then return end
    if owner:pindian(opponent, self:objectName()) then
        local slash = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0)
        slash:setSkillName(self:objectName())
        local targets = sgs.SPlayerList()
        for _, q in sgs.qlist(room:getAlivePlayers()) do
            if q:getKingdom() == opponent:getKingdom() and owner:canUse(slash, q, true) then targets:append(q) end
        end
        if owner:isAlive() and not targets:isEmpty() then
            local q = room:askForPlayerChosen(owner, targets, self:objectName(), "@hlxg_shuangren-slash", false)
            local use = sgs.CardUseStruct(); use.card = slash; use.from = owner; use.to:append(q)
            room:useCard(use, false)
        end
        slash:deleteLater()
    else
        room:setPlayerMark(owner, "hlxg_shuangren_ban-PlayClear", 1)
        room:setPlayerCardLimitation(owner, "use", "Slash", false, "hlxg_shuangren")
    end
end)
