hlxg_deshao = gu_trigger("hlxg_deshao", {sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or not use.card or not use.card:isBlack() or not use.to:contains(owner)
