hlxg_mingfa = gu_trigger("hlxg_mingfa", {sgs.CardFinished}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if use.from ~= owner or owner:getPhase() ~= sgs.Player_Play or not use.card
        or not (use.card:isKindOf("Slash") or use.card:isNDTrick())
        or owner:getMark("hlxg_mingfa-PlayClear") > 0 or owner:getTag("hlxg_mingfa_card"):toString() ~= "" then return end
    if not gu_invoke(owner, self:objectName(), data) then return end
    room:addPlayerMark(owner, "hlxg_mingfa-PlayClear")
    -- Preserve the complete card identity, including a converted/virtual card.
    owner:setTag("hlxg_mingfa_card", sgs.QVariant(use.card:toString()))
    owner:addToPile("hlxg_mingfa", use.card, true)
    if not owner:isAlive() then return end
    local targets = room:getOtherPlayers(owner)
    if targets:isEmpty() then owner:clearOnePrivatePile("hlxg_mingfa"); return end
    local q = room:askForPlayerChosen(owner, targets, self:objectName(), "@hlxg_mingfa", false)
    owner:setTag("hlxg_mingfa_target", sgs.QVariant(q:objectName()))
    owner:setTag("hlxg_mingfa_ready", sgs.QVariant(false))
end)
hlxg_mingfa_effect = gu_record("#hlxg_mingfa_effect", {sgs.EventPhaseStart, sgs.EventPhaseChanging, sgs.Death}, function(self, event, room, p, data)
    if not p then return end
    for _, owner in sgs.qlist(room:getAllPlayers(true)) do
        local target = owner:getTag("hlxg_mingfa_target"):toString()
        if target ~= "" and (target == p:objectName() or (event == sgs.Death and data:toDeath().who == owner)) then
            if event == sgs.EventPhaseStart and p:getPhase() == sgs.Player_RoundStart then
                owner:setTag("hlxg_mingfa_ready", sgs.QVariant(true))
            elseif event == sgs.Death or (event == sgs.EventPhaseChanging and data:toPhaseChange().to == sgs.Player_NotActive
                and owner:getTag("hlxg_mingfa_ready"):toBool()) then
                local cardtext = owner:getTag("hlxg_mingfa_card"):toString()
                owner:removeTag("hlxg_mingfa_target")
                owner:removeTag("hlxg_mingfa_ready")
                owner:removeTag("hlxg_mingfa_card")
                if event ~= sgs.Death and owner:isAlive() then
                    local template = sgs.Card_Parse(cardtext)
                    if template then
                        local x = math.max(1, math.min(5, p:getHandcardNum()))
                        for i = 1, x do
                            local c = sgs.Sanguosha:cloneCard(template:objectName(), template:getSuit(), template:getNumber())
                            c:setSkillName("_hlxg_mingfa")
                            if owner:isAlive() and p:isAlive() and owner:canUse(c, p, true) then
                                local use = sgs.CardUseStruct(); use.card = c; use.from = owner; use.to:append(p)
                                room:useCard(use, false)
                            end
                            c:deleteLater()
                        end
                        if template:isVirtualCard() then template:deleteLater() end
                    end
                end
                owner:clearOnePrivatePile("hlxg_mingfa")
            end
        end
    end
end)
