-- c211_07: literal 欢乐杀修改 versions.
local function c21107_recover(room, p, source)
    if not p:isAlive() then return end
    local r = sgs.RecoverStruct(); r.who = source; r.recover = 1
    room:recover(p, r)
end

hlxg_deshi = gu_trigger("hlxg_deshi", {sgs.DamageInflicted}, function(self, event, room, p, data, owner)
    local d = data:toDamage()
    if p ~= owner or not owner:isWounded() or not d.card or not d.card:isKindOf("Slash") then return end
    room:sendCompulsoryTriggerLog(owner, self:objectName(), true, true)
    for _, id in sgs.qlist(room:getDrawPile()) do
        if sgs.Sanguosha:getCard(id):isKindOf("Slash") then
            room:obtainCard(owner, id, self:objectName(), false)
            break
        end
    end
    if owner:isAlive() then room:loseMaxHp(owner, 1, self:objectName()) end
    return true
end, true)
