}
hlxg_wuyuan = gu_active("hlxg_wuyuan", 1, 1, 1, gu_one, gu_one_feasible,
    function(self, room, source, targets)
        local to = targets[1]
        local c = sgs.Sanguosha:getCard(self:getSubcards():first())
        local red, black, elemental = c:isRed(), c:isBlack(), c:objectName() ~= "slash"
        room:obtainCard(to, self, "hlxg_wuyuan", true)
        c21107_recover(room, source, source)
        if source:isAlive() then source:drawCards(1, "hlxg_wuyuan") end
        if to:isAlive() then to:drawCards(1, "hlxg_wuyuan") end
        if red then c21107_recover(room, to, source) end
        if black and to:isAlive() then room:addPlayerMark(to, "hlxg_wuyuan_pending", 1) end
        if elemental and to:isAlive() then to:drawCards(1, "hlxg_wuyuan") end
    end,
    function(request, c) return c:isKindOf("Slash") end)
-- Recipient buffs survive the granting turn and skill loss; activate at the next turn start.
hlxg_wuyuan_record = gu_record("#hlxg_wuyuan_record", {sgs.EventPhaseStart, sgs.EventPhaseChanging},
    function(self, event, room, p, data)
        if not p then return end
        if event == sgs.EventPhaseStart and p:getPhase() == sgs.Player_RoundStart then
            room:setPlayerMark(p, "hlxg_wuyuan_active", p:getMark("hlxg_wuyuan_pending"))
            room:setPlayerMark(p, "hlxg_wuyuan_pending", 0)
        elseif event == sgs.EventPhaseChanging and data:toPhaseChange().to == sgs.Player_NotActive then
            room:setPlayerMark(p, "hlxg_wuyuan_active", 0)
        end
    end)
hlxg_wuyuan_slash = sgs.CreateTargetModSkillV2 {
