local function c21107_wake(room, p)
    if not p:isAlive() or not p:hasSkill("hlxg_zhanyuan") or p:getMark("hlxg_zhanyuan") > 0
        or room:getCurrent() ~= p or p:getPhase() == sgs.Player_NotActive
        or p:getMark("hlxg_mansi_total") < 8 then return end
    -- Awakening occurs once, including when the player chooses to retain 蛮嗣.
    room:setPlayerMark(p, "hlxg_zhanyuan", 1)
    room:sendCompulsoryTriggerLog(p, "hlxg_zhanyuan", true, true)
    local others = room:getOtherPlayers(p)
    if others:isEmpty() or not gu_invoke(p, "hlxg_zhanyuan") then return end
    local to = room:askForPlayerChosen(p, others, "hlxg_zhanyuan", "@hlxg_zhanyuan", false, true)
    if not to then return end
    room:detachSkillFromPlayer(p, "hlxg_mansi")
    room:acquireSkill(p, "hlxg_xili")
    if to:isAlive() then room:acquireSkill(to, "hlxg_xili") end
end
hlxg_mansi_vs = sgs.CreateViewAsSkillV2 {
    name = "hlxg_mansi", limit_scope = sgs.Skill_Limit_Phase, phase_name = "Play", max_usage_limit = 1,
    can_activate = function(self, request)
        local p = request:getInitiator()
        if request:getReason() ~= sgs.CardUseStruct_CARD_USE_REASON_PLAY or p:isKongcheng() then return false end
        local c = sgs.Sanguosha:cloneCard("savage_assault", sgs.Card_NoSuit, 0)
        c:addSubcards(p:handCards()); c:setSkillName("hlxg_mansi")
        local ok = c:isAvailable(p); c:deleteLater(); return ok
    end,
    can_select_card = function(self, request, c)
        return request:getInitiator():handCards():contains(c:getEffectiveId())
            and not request:getSelectedCardIds():contains(c:getEffectiveId())
    end,
    card_selection_feasible = function(self, request)
        return request:getSelectedCardIds():isEmpty()
            or request:getSelectedCardIds():length() == request:getInitiator():getHandcardNum()
    end,
    create_card = function(self, request)
        local c = sgs.Sanguosha:cloneCard("savage_assault", sgs.Card_NoSuit, 0)
        c:addSubcards(request:getInitiator():handCards()); c:setSkillName("hlxg_mansi"); return c
    end,
}
