hlxg_xili = gu_trigger("hlxg_xili", {sgs.DamageCaused}, function(self, event, room, p, data, owner)
    local d = data:toDamage()
    if not d.from or not d.to or d.from == owner or d.to == owner or d.to == d.from
        or not d.from:hasSkill("hlxg_xili") or room:getCurrent() ~= d.from
        or d.from:getPhase() == sgs.Player_NotActive or owner:getMark("hlxg_xili-Clear") > 0
        or not owner:canDiscard(owner, "he") then return end
    if not room:askForCard(owner, "..", "@hlxg_xili", data, self:objectName()) then return end
    room:setPlayerMark(owner, "hlxg_xili-Clear", 1)
    d.damage = d.damage + 1; data:setValue(d)
    if owner:isAlive() then owner:drawCards(2, self:objectName()) end
    if d.from:isAlive() then d.from:drawCards(2, self:objectName()) end
end)
