-- Snapshot whether this exact use repeats each directed source/target pair.
hlxg_souying_record = gu_record("#hlxg_souying_record", {sgs.TargetSpecified, sgs.CardFinished},
    function(self, event, room, p, data)
        local use = data:toCardUse()
        if not use.card or not use.from then return end
        for _, to in sgs.qlist(use.to) do
            local flag = "hlxg_souying_repeat_" .. to:objectName()
            if event == sgs.CardFinished then
                room:setCardFlag(use.card, "-" .. flag)
            else
                local mark = "hlxg_souying_to_" .. to:objectName() .. "-Clear"
                if use.from:getMark(mark) > 0 then room:setCardFlag(use.card, flag) end
                room:addPlayerMark(use.from, mark, 1)
            end
        end
    end)
extension_hl:addSkills(hlxg_souying_record)
extension_hl:insertRelatedSkills("hlxg_souying", "#hlxg_souying_record")
hlxg_souying = gu_trigger("hlxg_souying", {sgs.TargetSpecified, sgs.TargetConfirmed},
    function(self, event, room, p, data, owner)
        local use = data:toCardUse()
        if not use.card or not use.from or use.card:isKindOf("DelayedTrick")
            or owner:getMark("hlxg_souying-Clear") > 0 or not owner:canDiscard(owner, "he") then return end
        local outgoing = event == sgs.TargetSpecified and use.from == owner
        local incoming = event == sgs.TargetConfirmed and p == owner and use.from ~= owner
            and use.to:length() == 1 and use.to:contains(owner)
        local repeated = false
        if outgoing then
            for _, to in sgs.qlist(use.to) do
                if to ~= owner and use.card:hasFlag("hlxg_souying_repeat_" .. to:objectName()) then repeated = true end
            end
        elseif incoming then repeated = use.card:hasFlag("hlxg_souying_repeat_" .. owner:objectName()) end
        if not repeated then return end
        local prompt = outgoing and "@hlxg_souying_obtain" or "@hlxg_souying_nullify"
        if not room:askForCard(owner, "..", prompt, data, self:objectName()) then return end
        room:setPlayerMark(owner, "hlxg_souying-Clear", 1)
        if outgoing then
            room:obtainCard(owner, use.card, self:objectName(), true)
        else
            use.nullified_list:append(owner:objectName()); data:setValue(use)
        end
    end)
hlxg_manyi = gu_trigger("hlxg_manyi", {sgs.CardEffected}, function(self, event, room, p, data, owner)
    local effect = data:toCardEffect()
    if p == owner and effect.card and effect.card:isKindOf("SavageAssault") then
        room:sendCompulsoryTriggerLog(owner, self:objectName(), true, true); return true
    end
end, true)
