-- c212_01: literal Huanle Xun Yu variants.
local function c212_damage(room, from, to, name)
    local d = sgs.DamageStruct(); d.from = from; d.to = to; d.damage = 1; d.reason = name
    room:damage(d)
end
hlxg_jieming = gu_trigger("hlxg_jieming", {sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    for i = 1, data:toDamage().damage do
        if owner:isDead() then break end
