-- Track the currently resolving target, including nested effects. This prevents
-- Chengfeng from countering a trick that is resolving on somebody else.
hlxg_chengfeng_context = gu_record("#hlxg_chengfeng_context", {sgs.CardEffected, sgs.PostCardEffected, sgs.CardUsed, sgs.CardResponded},
    function(self, event, room, p, data)
        if event == sgs.CardEffected or event == sgs.PostCardEffected then
            local effect = data:toCardEffect()
            local key = (effect.to and effect.to:objectName() or "_") .. ":" .. (effect.card and effect.card:toString() or "_")
            local depth = room:getTag("hlxg_chengfeng_depth"):toInt()
            if event == sgs.CardEffected then
                depth = depth + 1
                room:setTag("hlxg_chengfeng_key_" .. depth, sgs.QVariant(key))
                room:setTag("hlxg_chengfeng_to_" .. depth, sgs.QVariant(effect.to:objectName()))
                room:setTag("hlxg_chengfeng_anshu_" .. depth, sgs.QVariant(effect.card:getSkillName() == "hlxg_anshu"))
            elseif depth > 0 and room:getTag("hlxg_chengfeng_key_" .. depth):toString() == key then
                room:removeTag("hlxg_chengfeng_key_" .. depth)
                room:removeTag("hlxg_chengfeng_to_" .. depth)
                room:removeTag("hlxg_chengfeng_anshu_" .. depth)
                depth = depth - 1
            end
            room:setTag("hlxg_chengfeng_depth", sgs.QVariant(depth))
            local target = room:getTag("hlxg_chengfeng_to_" .. depth):toString()
            for _, to in sgs.qlist(room:getAllPlayers()) do
                room:setPlayerMark(to, "hlxg_chengfeng_resolving", target == to:objectName() and 1 or 0)
            end
        else
            local card = event == sgs.CardUsed and data:toCardUse().card or data:toCardResponse().m_card
            if card and card:getSkillName() == "hlxg_chengfeng" and p then
                room:setPlayerMark(p, "hlxg_chengfeng-Clear", 1)
            end
        end
    end)
hlxg_chengfeng = sgs.CreateViewAsSkillV2 {
    name = "hlxg_chengfeng", n = 1, expand_pile = "hlxg_kuangzuo", response_or_use = true,
    can_activate = function(self, request)
        local p = request:getInitiator()
        if p:getMark("hlxg_chengfeng-Clear") > 0 or p:getPile("hlxg_kuangzuo"):isEmpty() then return false end
        local pattern = request:getPattern()
        if pattern ~= "jink" and pattern ~= "nullification" then return false end
        return p:getMark("hlxg_chengfeng_resolving") > 0
    end,
    can_select_card = function(self, request, card)
        return request:getSelectedCardIds():isEmpty() and request:getInitiator():getPile("hlxg_kuangzuo"):contains(card:getEffectiveId())
            and (request:getPattern() == "jink" and card:isRed() or request:getPattern() == "nullification" and card:isBlack())
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        local original = sgs.Sanguosha:getCard(request:getSelectedCardIds():first())
        local card = sgs.Sanguosha:cloneCard(request:getPattern(), original:getSuit(), original:getNumber())
        card:addSubcard(original); card:setSkillName("hlxg_chengfeng"); return card
    end,
}
hlxg_chengfeng.response_pattern = "nullification"
hlxg_chengfeng_refill = gu_record("#hlxg_chengfeng_refill", {sgs.CardFinished, sgs.PostCardResponded}, function(self, event, room, p, data)
    local card, actor
    if event == sgs.CardFinished then local use = data:toCardUse(); card = use.card; actor = use.from
    else local response = data:toCardResponse(); if response.m_isUse and (not response.m_card or not response.m_card:isKindOf("Jink")) then return end; card = response.m_card; actor = p end
    if not card or not actor or actor:isDead() or card:getSkillName() ~= "hlxg_chengfeng" then return end
    local red, black = false, false
    for _, id in sgs.qlist(actor:getPile("hlxg_kuangzuo")) do
        local c = sgs.Sanguosha:getCard(id); red = red or c:isRed(); black = black or c:isBlack()
    end
    if not (red and black) and gu_invoke(actor, "hlxg_chengfeng") then actor:addToPile("hlxg_kuangzuo", room:getNCards(1)) end
end)
hlxg_tongyin = gu_trigger("hlxg_tongyin" .. "$", {sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner or not owner:hasLordSkill("hlxg_tongyin") then return end
    local damage = data:toDamage()
    if not damage.card or not damage.from or damage.from == owner or not gu_invoke(owner, "hlxg_tongyin", data) then return end
    if damage.from:getKingdom() == owner:getKingdom() then owner:addToPile("hlxg_kuangzuo", damage.card)
    elseif not damage.from:isAllNude() then
        local id = room:askForCardChosen(owner, damage.from, "hej", "hlxg_tongyin")
        owner:addToPile("hlxg_kuangzuo", id)
    end
end)
