hlxg_kuangzuoCard = sgs.CreateSkillCard {
    name = "hlxg_kuangzuoCard", will_throw = false,
    filter = function(self, targets, to, from) return #targets < 2 and (#targets == 0 or targets[1]:objectName() ~= to:objectName()) end,
    feasible = function(self, targets) return #targets == 2 end,
    on_use = function(self, room, from, targets)
        room:removePlayerMark(from, "@hlxg_kuangzuo")
        local receiver, donor = targets[1], targets[2]
        local lordskill = false
        for _, skill in sgs.qlist(receiver:getVisibleSkillList()) do if skill:isLordSkill() then lordskill = true end end
        room:acquireSkill(receiver, "hlxg_chengfeng")
        if receiver:isLord() and not lordskill then room:acquireSkill(receiver, "hlxg_tongyin") end
        local ids = sgs.IntList()
        for _, suit in ipairs({sgs.Card_Spade, sgs.Card_Club, sgs.Card_Heart, sgs.Card_Diamond}) do
            local choices = sgs.IntList()
            for _, c in sgs.qlist(donor:getCards("hej")) do if c:getSuit() == suit then choices:append(c:getEffectiveId()) end end
            if not choices:isEmpty() then
                room:fillAG(choices, donor)
                local id = room:askForAG(donor, choices, false, "hlxg_kuangzuo")
                room:clearAG(donor); if id >= 0 then ids:append(id) end
            end
        end
        if not ids:isEmpty() then receiver:addToPile("hlxg_kuangzuo", ids) end
    end,
}
hlxg_kuangzuo = sgs.CreateViewAsSkillV2 {
