}

hlxg_anshu = gu_trigger("hlxg_anshu", {sgs.RoundStart, sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if event == sgs.EventPhaseStart then
        if not p or p:getPhase() ~= sgs.Player_Finish then return end
        for _, to in sgs.qlist(room:getAlivePlayers()) do
            local mark = "hlxg_anshu_pending_" .. owner:objectName() .. "-Clear"
            if to:getMark(mark) > 0 then
                room:setPlayerMark(to, mark, 0)
                if gu_invoke(owner, self:objectName(), (function() local value = sgs.QVariant(); value:setValue(to); return value end)()) then
                    local n = math.min(5, to:getMaxHp()) - to:getHandcardNum()
                    if n > 0 then to:drawCards(n, self:objectName()) end
                end
            end
        end
        return
    end
    if not gu_invoke(owner, self:objectName()) then return end
    local groups, names = {}, {}
    for _, id in sgs.qlist(room:getDiscardPile()) do
        local c = sgs.Sanguosha:getCard(id)
        if c:isKindOf("BasicCard") then
            local name = c:objectName()
            if not groups[name] then groups[name] = sgs.IntList(); table.insert(names, name) end
            groups[name]:append(id)
        end
    end
    local top = sgs.IntList()
    for _, name in ipairs(names) do
        local ids = groups[name]
        room:fillAG(ids, owner)
        local id = room:askForAG(owner, ids, false, "hlxg_anshu")
        room:clearAG(owner); if id >= 0 then top:append(id) end
    end
    if not top:isEmpty() then
        local dummy = gu_dummy(top)
        room:moveCardTo(dummy, nil, sgs.Player_DrawPile, true)
        dummy:deleteLater(); room:returnToTopDrawPile(top)
    end
    local start = room:askForPlayerChosen(owner, room:getAlivePlayers(), "hlxg_anshu", "@hlxg_anshu-start", false, true)
    local card = sgs.Sanguosha:cloneCard("amazing_grace", sgs.Card_NoSuit, 0); card:setSkillName("hlxg_anshu")
    owner:setTag("hlxg_anshu_start", sgs.QVariant(start:objectName()))
    room:setTag("hlxg_anshu_active", sgs.QVariant(owner:objectName()))
    local use = sgs.CardUseStruct(); use.card = card; use.from = owner; room:useCard(use)
    room:removeTag("hlxg_anshu_active"); owner:removeTag("hlxg_anshu_start"); card:deleteLater()
end)
hlxg_anshu_record = gu_record("#hlxg_anshu_record", {sgs.PreCardUsed, sgs.ChoiceMade, sgs.CardsMoveOneTime, sgs.RoundEnd}, function(self, event, room, p, data)
    if event == sgs.RoundEnd then
        for _, to in sgs.qlist(room:getAllPlayers()) do
            for _, owner in sgs.qlist(room:getAllPlayers()) do
                to:removeTag("hlxg_anshu_cards_" .. owner:objectName())
                room:setPlayerMark(to, "hlxg_anshu_pending_" .. owner:objectName() .. "-Clear", 0)
            end
        end
    elseif event == sgs.ChoiceMade then
        local choice = data:toString():split(":")
        local depth = room:getTag("hlxg_chengfeng_depth"):toInt()
        if choice[1] == "AGChosen" and choice[2] == "amazing_grace" and room:getTag("hlxg_chengfeng_anshu_" .. depth):toBool() then
            room:setTag("hlxg_anshu_chosen", sgs.QVariant(tonumber(choice[3]) or -1))
        end
    elseif event == sgs.PreCardUsed then
        local use = data:toCardUse()
        if not use.card or use.card:getSkillName() ~= "hlxg_anshu" or not use.from then return end
        local start = use.from:getTag("hlxg_anshu_start"):toString()
        local list = sgs.QList2Table(room:getAlivePlayers()); local index
        for i, to in ipairs(list) do if to:objectName() == start then index = i end end
        if index then
            local original = use.to; use.to = sgs.SPlayerList()
            for i = 0, #list - 1 do
                local to = list[(index + i - 1) % #list + 1]
                if original:contains(to) then use.to:append(to) end
            end
            data:setValue(use)
        end
    else
        local move = data:toMoveOneTime()
        local loser = move.from and room:findPlayerByObjectName(move.from:objectName(), true)
        local receiver = move.to and room:findPlayerByObjectName(move.to:objectName(), true)
        if loser then
            for _, owner in sgs.qlist(room:getAllPlayers()) do
                local tracked = gu_names(loser, "hlxg_anshu_cards_" .. owner:objectName())
                for _, id in sgs.qlist(move.card_ids) do
                    if table.contains(tracked, tostring(id)) and (not move.to or move.to:objectName() ~= move.from:objectName()) then
                        room:setPlayerMark(loser, "hlxg_anshu_pending_" .. owner:objectName() .. "-Clear", 1)
                    end
                end
            end
        end
        local active = room:getTag("hlxg_anshu_active"):toString()
        local chosen = room:getTag("hlxg_anshu_chosen"):toInt()
        if active ~= "" and receiver and move.to_place == sgs.Player_PlaceHand and room:getTag("hlxg_anshu_chosen"):toString() ~= "" and move.card_ids:contains(chosen) then
            room:removeTag("hlxg_anshu_chosen")
            local tag = "hlxg_anshu_cards_" .. active; local ids = gu_names(receiver, tag)
            table.insert(ids, tostring(chosen)); gu_setnames(receiver, tag, ids)
        end
    end
end)
