-- c212_02: helpers from the enclosing GU block are in scope.
hlxg_gongxin_gexuan = gu_trigger("hlxg_gongxin_gexuan", {sgs.TargetSpecified, sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if not use.card or not use.from or use.to:length() ~= 1 or owner:getMark("hlxg_gongxin_gexuan-Clear") > 0 then return end
    if not (use.card:isKindOf("Slash") or use.card:isNDTrick()) then return end
    local other
    if event == sgs.TargetSpecified and p == owner and use.from == owner then other = use.to:first()
    elseif event == sgs.TargetConfirmed and p == owner and use.to:contains(owner) then other = use.from end
    if not other or other == owner or not gu_invoke(owner, self:objectName(), data) then return end
    room:addPlayerMark(owner, "hlxg_gongxin_gexuan-Clear")
    local red = sgs.IntList()
    for _, c in sgs.qlist(other:getHandcards()) do if c:isRed() then red:append(c:getEffectiveId()) end end
    local id = room:doGongxin(owner, other, red, self:objectName())
    owner:removeTag(self:objectName())
    if id < 0 then return end
    room:showCard(other, id)
    if room:askForChoice(owner, self:objectName(), "obtain+top", data) == "obtain" then room:obtainCard(owner, id)
    else room:moveCardsInToDrawpile(other, id, self:objectName(), 1, true) end
end)

