    can_activate = function(self, request) return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY and request:getInitiator():getMark("@hlxg_zhafu") > 0 end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function() local c = hlxg_zhafuCard:clone(); c:setSkillName("hlxg_zhafu"); return c end,
}
hlxg_zhafu_delay = gu_record("#hlxg_zhafu_delay", {sgs.EventPhaseStart}, function(self, event, room, p, data)
    if not p or p:getPhase() ~= sgs.Player_Discard then return end
    local names = gu_names(p, "hlxg_zhafu_sources"); p:removeTag("hlxg_zhafu_sources")
    for _, name in ipairs(names) do
        local source = room:findPlayerByObjectName(name)
        if source and source:isAlive() and not p:isKongcheng() then
            local keep = room:askForExchange(p, "hlxg_zhafu", 1, 1, false, "@hlxg_zhafu-keep")
            local ids = p:handCards()
            if keep then ids:removeOne(keep:getSubcards():first()); keep:deleteLater() end
            gu_obtain(room, source, ids, "hlxg_zhafu")
        end
    end
end)

hlxg_yingzi_gexuan = gu_trigger("hlxg_yingzi_gexuan", {sgs.DrawNCards}, function(self, event, room, p, data, owner)
    if p == owner then local draw = data:toDraw(); draw.num = draw.num + 1; data:setValue(draw) end
end, true)
hlxg_yingzi_gexuan_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_yingzi_gexuan_max",
    fixed_func = function(self, ctx) local p = ctx:getPrimary(); if p and p:hasSkill("hlxg_yingzi_gexuan") then return p:getMaxHp() end return -1 end,
}
local function c212_02_guanxing(room, p, start)
    if start and p:getMark("hlxg_guanxing_gexuan_start-Clear") > 0 then return end
    if start then room:setPlayerMark(p, "hlxg_guanxing_gexuan_start-Clear", 1) end
    if not gu_invoke(p, "hlxg_guanxing_gexuan") then return end
    local ids = room:getNCards(room:alivePlayerCount() == 2 and 3 or 5, false)
    room:returnToTopDrawPile(ids)
    local top = room:askForGuanxing(p, ids, sgs.Room_GuanxingBothSides)
    if start and top:isEmpty() then room:setPlayerMark(p, "hlxg_guanxing_gexuan_bottom-Clear", 1) end
end
hlxg_guanxing_gexuan = gu_trigger("hlxg_guanxing_gexuan", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if p:getPhase() == sgs.Player_Start then c212_02_guanxing(room, p, true)
    elseif p:getPhase() == sgs.Player_Finish and p:getMark("hlxg_guanxing_gexuan_bottom-Clear") > 0 then c212_02_guanxing(room, p, false) end
end)
hlxg_zhiyan_gexuan = gu_trigger("hlxg_zhiyan_gexuan", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Finish then return end
    local to = room:askForPlayerChosen(p, room:getAlivePlayers(), self:objectName(), "@hlxg_zhiyan_gexuan", true, true)
    if not to then return end
    local ids = room:drawCardsList(to, 1, self:objectName())
    if ids:isEmpty() then return end
    local id = ids:first(); room:showCard(to, id)
    local c = sgs.Sanguosha:getCard(id)
    if not c:isKindOf("EquipCard") then p:drawCards(1, self:objectName())
    else
        if to:isAlive() and room:getCardOwner(id) == to and to:canUse(c, to) then
            local use = sgs.CardUseStruct(); use.card = c; use.from = to; use.to:append(to); room:useCard(use)
        end
        if to:isAlive() then local rec = sgs.RecoverStruct(); rec.who = p; rec.recover = 1; room:recover(to, rec) end
    end
end)

hlxg_lianhua_use = sgs.CreateViewAsSkillV2 {
    name = "#hlxg_lianhua_use",
    can_activate = function(self, request) return request:getPattern() == "@@hlxg_lianhua" and request:getInitiator():getTag("hlxg_lianhua_card"):toString() ~= "" end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function(self, request)
        local c = sgs.Sanguosha:cloneCard(request:getInitiator():getTag("hlxg_lianhua_card"):toString(), sgs.Card_NoSuit, 0)
        c:setSkillName("hlxg_lianhua"); return c
    end,
}
hlxg_lianhua = gu_trigger("hlxg_lianhua", {sgs.Damaged, sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if event == sgs.Damaged then
        if p and p ~= owner and owner:getPhase() == sgs.Player_NotActive then room:addPlayerMark(owner, "&hlxg_lianhua") end
        return
    end
    if p ~= owner then return end
    if p:getPhase() == sgs.Player_Play then room:setPlayerMark(p, "&hlxg_lianhua", 0); return end
    if p:getPhase() ~= sgs.Player_Start then return end
    local n = p:getMark("&hlxg_lianhua"); local skill, cards
    if n <= 3 then skill = "hlxg_yingzi_gexuan"; cards = {"peach"}
    elseif p:getMark("hlxg_lianhua_odd") > 0 and p:getMark("hlxg_lianhua_even") > 0 then skill = "hlxg_gongxin_gexuan"; cards = {"slash", "duel"}
    elseif n % 2 == 1 then skill = "hlxg_guanxing_gexuan"; cards = {"ex_nihilo"}; room:setPlayerMark(p, "hlxg_lianhua_odd", 1)
    else skill = "hlxg_zhiyan_gexuan"; cards = {"snatch"}; room:setPlayerMark(p, "hlxg_lianhua_even", 1) end
    if not p:hasSkill(skill) then room:acquireSkill(p, skill); p:setTag("hlxg_lianhua_granted", sgs.QVariant(skill)) end
    if skill == "hlxg_guanxing_gexuan" then c212_02_guanxing(room, p, true) end
    for _, name in ipairs(cards) do
        if p:isAlive() then
            p:setTag("hlxg_lianhua_card", sgs.QVariant(name))
            room:askForUseCard(p, "@@hlxg_lianhua", "@hlxg_lianhua-use:" .. name)
            p:removeTag("hlxg_lianhua_card")
        end
    end
end)
hlxg_lianhua_cleanup = gu_record("#hlxg_lianhua_cleanup", {sgs.EventPhaseChanging, sgs.Death}, function(self, event, room, p, data)
    if event == sgs.Death then p = data:toDeath().who
    elseif data:toPhaseChange().to ~= sgs.Player_NotActive then return end
    if not p then return end
    local skill = p:getTag("hlxg_lianhua_granted"):toString()
    p:removeTag("hlxg_lianhua_granted")
    if skill ~= "" then room:detachSkillFromPlayer(p, skill, false, true) end
end)
