hlxg_bingzheng = gu_trigger("hlxg_bingzheng", {sgs.EventPhaseEnd}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Play then return end
    local to = room:askForPlayerChosen(p, room:getAlivePlayers(), self:objectName(), "@hlxg_bingzheng", true, true)
    if not to then return end
    local choices = to:isKongcheng() and "draw" or "draw+discard"
    if room:askForChoice(p, self:objectName(), choices, sgs.QVariant(to)) == "draw" then to:drawCards(1, self:objectName())
    else room:askForDiscard(to, self:objectName(), 1, 1, false, false) end
    if to:isAlive() and p:isAlive() and to:getHandcardNum() == to:getHp() then
        p:drawCards(1, self:objectName())
        local c = room:askForExchange(p, self:objectName(), 1, 1, true, "@hlxg_bingzheng-give", true)
        if c then room:obtainCard(to, c, false); c:deleteLater() end
    end
end)
hlxg_sheyan = gu_trigger("hlxg_sheyan", {sgs.TargetConfirming}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or not use.card or not use.from or not use.to:contains(owner) or not use.card:isNDTrick() or use.card:isKindOf("Collateral") then return end
    local extra = sgs.SPlayerList()
    room:setCardFlag(use.card, "tunan_distance")
    for _, to in sgs.qlist(room:getOtherPlayers(use.from)) do if not use.to:contains(to) and use.from:canUse(use.card, to) then extra:append(to) end end
    room:setCardFlag(use.card, "-tunan_distance")
    local choices = {"cancel"}
    if not extra:isEmpty() then table.insert(choices, "add") end
    if use.to:length() > 1 then table.insert(choices, "remove") end
    local choice = room:askForChoice(owner, self:objectName(), table.concat(choices, "+"), data)
    if choice == "cancel" then return end
    local targets = choice == "add" and extra or use.to
    local to = room:askForPlayerChosen(owner, targets, self:objectName(), "@hlxg_sheyan-" .. choice)
    if not to then return end
    if choice == "add" then use.to:append(to); room:sortByActionOrder(use.to) else use.to:removeOne(to) end
    data:setValue(use)
end)
