hlxg_dongyun:addSkill(hlxg_bingzheng); hlxg_dongyun:addSkill(hlxg_sheyan)

hlxg_benghuai_dongzhuo = gu_trigger("hlxg_benghuai_dongzhuo", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Finish then return end
    local lower = false
    for _, to in sgs.qlist(room:getOtherPlayers(p)) do if to:getHp() < p:getHp() then lower = true; break end end
    if not lower then return end
    if room:askForChoice(p, self:objectName(), "maxhp+hp") == "maxhp" then room:loseMaxHp(p, 1) else room:loseHp(p, 1) end
    if p:isAlive() then p:drawCards(1, self:objectName()) end
end, true)
hlxg_baonve = gu_trigger("hlxg_baonve" .. "$", {sgs.Damage}, function(self, event, room, p, data, owner)
    local damage = data:toDamage(); local from = damage.from
    if not owner:hasLordSkill("hlxg_baonve") or not from or from == owner or not from:isAlive() or from:getKingdom() ~= "qun" then return end
    if not gu_invoke(from, "hlxg_baonve", sgs.QVariant(owner)) then return end
    local judge = sgs.JudgeStruct(); judge.who = from; judge.reason = "hlxg_baonve"; judge.pattern = ".|spade"; judge.good = true
    room:judge(judge)
    if judge:isGood() and owner:isAlive() then local rec = sgs.RecoverStruct(); rec.who = from; rec.recover = 1; room:recover(owner, rec) end
end)
hlxg_roulin = gu_trigger("hlxg_roulin", {sgs.TargetSpecified, sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or not use.card or not use.from or not use.card:isKindOf("Slash") then return end
    if event == sgs.TargetSpecified and use.from ~= owner then return end
    if event == sgs.TargetConfirmed and (not use.from:isFemale() or not use.to:contains(owner)) then return end
    local key = "Jink_" .. use.card:toString(); local ids = use.from:getTag(key):toIntList(); local result = sgs.IntList()
    for i, to in sgs.qlist(use.to) do
        local n = ids:length() > i and ids:at(i) or 1
        if n == 1 and ((event == sgs.TargetSpecified and to:isFemale()) or (event == sgs.TargetConfirmed and to == owner)) then n = 2 end
        result:append(n)
    end
    use.from:setTag(key, sgs.QVariant(result))
end, true)
hlxg_jiuchi = sgs.CreateViewAsSkillV2 {
    name = "hlxg_jiuchi", n = 1, response_or_use = true,
    can_activate = function(self, request)
        if request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY then
            local c = sgs.Sanguosha:cloneCard("analeptic", sgs.Card_NoSuit, 0); local ok = c:isAvailable(request:getInitiator()); c:deleteLater(); return ok
        end
        return string.find(request:getPattern(), "analeptic", 1, true) ~= nil
    end,
    can_select_card = function(self, request, c) return request:getSelectedCardIds():isEmpty() and c:isBlack() and request:getInitiator():handCards():contains(c:getEffectiveId()) end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        local id = request:getSelectedCardIds():first(); local original = sgs.Sanguosha:getCard(id)
        local c = sgs.Sanguosha:cloneCard("analeptic", original:getSuit(), original:getNumber()); c:addSubcard(id); c:setSkillName("hlxg_jiuchi"); return c
    end,
}
