-- ==================== c212_03
do
-- c212_03: independent, literal 欢乐 variants.
local function c21203_lowest(room, p)
    for _, q in sgs.qlist(room:getAlivePlayers()) do if q:getHp() < p:getHp() then return false end end
    return true
end
local function c21203_same(a, b) return a and b and a:objectName() == b:objectName() end

hljx_dongzhuo = sgs.General(extension_hl, "hljx_dongzhuo", "qun", 8)
hljx_benghuai = gu_trigger("hljx_benghuai", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if p:getPhase() == sgs.Player_RoundStart then
        room:setPlayerMark(p, "hljx_roulin_others-Clear", c21203_lowest(room, p) and 1 or 0)
    elseif p:getPhase() == sgs.Player_Finish and p:getMark("hljx_benghuai_disabled-Clear") == 0 and not c21203_lowest(room, p) then
        local choice = room:askForChoice(p, self:objectName(), "hp+maxhp")
        if choice == "hp" then room:loseHp(p, 1, true, p, self:objectName()) else room:loseMaxHp(p, 1) end
    end
end, true)
-- '$' is stripped by Skill's constructor, preserving the assigned objectName.
hljx_baonve = gu_trigger("hljx_baonve$", {sgs.Damage}, function(self, event, room, p, data, owner)
    local d = data:toDamage()
    if not owner:hasLordSkill("hljx_baonve") or not d.from or d.from == owner or d.from:getKingdom() ~= "qun"
        or not gu_invoke(owner, "hljx_baonve", data) then return end
    local judge = sgs.JudgeStruct(); judge.who = owner; judge.reason = "hljx_baonve"
    judge.pattern = ".|spade"; judge.good = true
    room:judge(judge)
    if owner:isAlive() and judge.card and judge.card:getSuit() == sgs.Card_Spade then
        room:recover(owner, sgs.RecoverStruct(owner))
        if owner:isAlive() then room:obtainCard(owner, judge.card, "hljx_baonve", true) end
    end
end)
local function c21203_roulin_pair(owner, other)
    return other and other ~= owner and (other:isFemale() or owner:getMark("hljx_roulin_others-Clear") > 0)
end
hljx_roulin = gu_trigger("hljx_roulin", {sgs.TargetSpecified, sgs.TargetConfirmed, sgs.CardFinished}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if not use.card or not use.from or not use.card:isKindOf("Slash") then return end
    local flag = "hljx_roulin_" .. owner:objectName()
    if event == sgs.CardFinished then
        if use.card:hasFlag(flag) then
            room:setCardFlag(use.card, "-" .. flag)
            if not use.card:hasFlag("hljx_roulin_damage") then owner:drawCards(1, self:objectName()) end
        end
        return
    end
    local affected = {}
    if event == sgs.TargetSpecified and use.from == owner then
        for i = 0, use.to:length() - 1 do if c21203_roulin_pair(owner, use.to:at(i)) then affected[i] = true end end
    elseif event == sgs.TargetConfirmed and p == owner and use.to:contains(owner) and c21203_roulin_pair(owner, use.from) then
        affected[use.to:indexOf(owner)] = true
    end
    if not next(affected) then return end
    room:setCardFlag(use.card, flag)
    local key = "Jink_" .. use.card:toString()
    local old, replacement = use.from:getTag(key):toIntList(), sgs.IntList()
    for i = 0, use.to:length() - 1 do
        local n = i < old:length() and old:at(i) or 1
        if affected[i] and n == 1 then n = 2 end
        replacement:append(n)
    end
    local value = sgs.QVariant(); value:setValue(replacement); use.from:setTag(key, value)
end, true)
