hlxg_humei = gu_active("hlxg_humei", nil, 0, 0,
    function(self, targets, to, from) return #targets == 0 end, gu_one_feasible,
    function(self, room, source, targets)
        local choices = {}
        for _, choice in ipairs({"draw", "give", "recover"}) do
            if source:getMark("hlxg_humei_" .. choice .. "-Clear") == 0 then table.insert(choices, choice) end
        end
        if #choices == 0 then return end
        local choice = room:askForChoice(source, "hlxg_humei", table.concat(choices, "+"))
        room:addPlayerMark(source, "hlxg_humei_used-PlayClear")
        room:setPlayerMark(source, "hlxg_humei_" .. choice .. "-Clear", 1)
        local to = targets[1]
        if choice == "draw" then to:drawCards(1, "hlxg_humei")
        elseif choice == "recover" then room:recover(to, sgs.RecoverStruct(source))
        elseif not to:isNude() then
            local c = room:askForExchange(to, "hlxg_humei", 1, 1, true, "@hlxg_humei-give:" .. source:objectName())
            if c then room:obtainCard(source, c, "hlxg_humei", false); c:deleteLater() end
        end
    end, nil,
    function(p)
        return p:getMark("hlxg_humei_used-PlayClear") < p:getMark("hlxg_humei_damage-PlayClear")
            and (p:getMark("hlxg_humei_draw-Clear") == 0 or p:getMark("hlxg_humei_give-Clear") == 0 or p:getMark("hlxg_humei_recover-Clear") == 0)
    end)
hlxg_jiaoxia = sgs.CreateViewAsSkillV2 {
    name = "hlxg_jiaoxia", n = 1, expand_pile = "#hlxg_jiaoxia_original",
    can_activate = function(self, request)
        if request:getPattern() == "@@hlxg_jiaoxia" then return request:getInitiator():getMark("hlxg_jiaoxia_original") > 0 end
        if request:getReason() ~= sgs.CardUseStruct_CARD_USE_REASON_PLAY or request:getInitiator():getPhase() ~= sgs.Player_Play then return false end
        local c = sgs.Sanguosha:cloneCard("slash"); local ok = c:isAvailable(request:getInitiator()); c:deleteLater(); return ok
    end,
    can_select_card = function(self, request, card)
        if not request:getSelectedCardIds():isEmpty() then return false end
        local p = request:getInitiator()
        if request:getPattern() == "@@hlxg_jiaoxia" then return card:getEffectiveId() + 1 == p:getMark("hlxg_jiaoxia_original") end
        return p:handCards():contains(card:getEffectiveId())
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        local original = sgs.Sanguosha:getCard(request:getSelectedCardIds():first())
        if request:getPattern() == "@@hlxg_jiaoxia" then return original end
        local c = sgs.Sanguosha:cloneCard("slash", original:getSuit(), original:getNumber())
        c:addSubcard(original); c:setSkillName("hlxg_jiaoxia"); return c
    end,
}
hlxg_jiaoxia_record = gu_record("#hlxg_jiaoxia_record", {sgs.PreCardUsed, sgs.CardUsed, sgs.Damage, sgs.CardFinished}, function(self, event, room, p, data)
    if event == sgs.Damage then
        local d = data:toDamage()
        if d.card and d.card:getSkillName() == "hlxg_jiaoxia" and d.card:isKindOf("Slash") then room:setCardFlag(d.card, "hlxg_jiaoxia_damage") end
        return
    end
    local use = data:toCardUse()
    if not use.from or not use.card or not use.card:isKindOf("Slash") then return end
    if event == sgs.PreCardUsed then
        room:setCardFlag(use.card, "-hlxg_jiaoxia_damage")
    elseif event == sgs.CardUsed then
        if use.from:getPhase() == sgs.Player_Play then
            for _, to in sgs.qlist(use.to) do room:setPlayerMark(use.from, "hlxg_jiaoxia_to_" .. to:objectName() .. "-PlayClear", 1) end
        end
    elseif use.card:getSkillName() == "hlxg_jiaoxia" and use.card:hasFlag("hlxg_jiaoxia_damage")
        and use.from:isAlive() and use.from:hasSkill("hlxg_jiaoxia") and use.card:subcardsLength() == 1 then
        room:setCardFlag(use.card, "-hlxg_jiaoxia_damage")
        local id = use.card:getSubcards():first()
        local original = sgs.Sanguosha:getCard(id)
        -- Reuse the physical original in its current zone, without obtaining it first.
        if not original:isAvailable(use.from) or use.from:isCardLimited(original, sgs.Card_MethodUse) then return end
        local place = room:getCardPlace(id)
        local old = use.from:getMark("hlxg_jiaoxia_original")
        room:setPlayerMark(use.from, "hlxg_jiaoxia_original", id + 1)
        local ids = sgs.IntList(); ids:append(id)
        room:notifyMoveToPile(use.from, ids, "hlxg_jiaoxia_original", place, true)
        room:askForUseCard(use.from, "@@hlxg_jiaoxia", "@hlxg_jiaoxia-use")
        room:notifyMoveToPile(use.from, ids, "hlxg_jiaoxia_original", place, false)
        room:setPlayerMark(use.from, "hlxg_jiaoxia_original", old)
    end
end)
hlxg_jiaoxia_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_jiaoxia_mod", pattern = "Slash", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local p, to, c = ctx:getPrimary(), ctx:getSecondary(), ctx:getCard()
        if not p or not p:hasSkill("hlxg_jiaoxia") or p:getPhase() ~= sgs.Player_Play or not c or not c:isKindOf("Slash") then return false end
        if to and to ~= p and p:getMark("hlxg_jiaoxia_to_" .. to:objectName() .. "-PlayClear") == 0 then
            if ctx:getModType() == sgs.TargetModSkill_Residue then return sgs.CorrectSkillResult.unlimitedResidue() end
            if ctx:getModType() == sgs.TargetModSkill_DistanceLimit then return 1000 end
        end
        return false
    end,
}
