hlxg_weicheng = gu_trigger("hlxg_weicheng", {sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    local move = data:toMoveOneTime()
    if not c21203_same(move.from, owner) or not move.to or c21203_same(move.to, owner)
        or move.to_place ~= sgs.Player_PlaceHand or owner:getHandcardNum() > owner:getHp() then return end
    local hand = false
    for _, place in sgs.qlist(move.from_places) do if place == sgs.Player_PlaceHand then hand = true; break end end
    if hand and gu_invoke(owner, self:objectName(), data) then owner:drawCards(1, self:objectName()) end
end)
hlxg_daoshu = gu_active("hlxg_daoshu", nil, 0, 0,
    function(self, targets, to, from) return gu_one(self, targets, to, from) and not to:isKongcheng() end, gu_one_feasible,
    function(self, room, source, targets)
        room:setPlayerMark(source, "hlxg_daoshu_used-PlayClear", 1)
        local target = targets[1]
        local suit = room:askForChoice(source, "hlxg_daoshu", "spade+heart+club+diamond")
        local id = room:askForCardChosen(source, target, "h", "hlxg_daoshu")
        local card = sgs.Sanguosha:getCard(id)
        local same = card:getSuitString() == suit
        room:obtainCard(source, id, "hlxg_daoshu", false)
        if same then
            if source:isAlive() and target:isAlive() then room:damage(sgs.DamageStruct("hlxg_daoshu", source, target, 1)) end
            room:setPlayerMark(source, "hlxg_daoshu_used-PlayClear", 0)
        elseif source:isAlive() and not source:isKongcheng() then
            local others = room:getOtherPlayers(source)
            if others:isEmpty() then return end
            local to = room:askForPlayerChosen(source, others, "hlxg_daoshu", "@hlxg_daoshu-target", false, true)
            local give = room:askForExchange(source, "hlxg_daoshu", 1, 1, false, "@hlxg_daoshu-give:" .. to:objectName())
            if give then room:obtainCard(to, give, "hlxg_daoshu", false); give:deleteLater() end
        end
    end, nil, function(p) return p:getMark("hlxg_daoshu_used-PlayClear") == 0 end)
