-- ==================== c212_04
do
-- c212_04: literal 欢乐杀修改 variants.
-- V2 effects receive the decision maker; ctx.invoker retains the event player.
local function c212_trigger(name, events, effect, compulsory)
    return sgs.CreateRuleSkillV2 {
        name = name, events = events, global = true,
        frequency = compulsory and sgs.Skill_Compulsory or sgs.Skill_NotFrequent,
        can_trigger = function(self, event, room, p, data)
            for _, owner in sgs.qlist(room:getAlivePlayers()) do
                if owner:hasSkill(self:objectName()) then return self:objectName(), owner end
            end
            return false
        end,
        on_effect = function(self, event, room, p, ctx)
            for _, owner in sgs.qlist(room:getAlivePlayers()) do
                if owner:hasSkill(self:objectName()) then
                    effect(self, event, room, ctx.invoker, ctx.original_data, owner)
                end
            end
            return false
        end,
    }
end
local function c212_loss(move)
    return move.from and not move.card_ids:isEmpty()
end
local function c212_topup(room, p, skill)
    if p and p:isAlive() and p:getHandcardNum() < 4 then p:drawCards(4 - p:getHandcardNum(), skill) end
end
local function c212_give(room, from, to, card, skill)
    room:obtainCard(to, card, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_GIVE,
        from:objectName(), to:objectName(), skill, ""), false)
end

hlxg_jiangwanfeiyi = sgs.General(extension_hl, "hlxg_jiangwanfeiyi", "shu", 3)
hlxg_shoucheng = c212_trigger("hlxg_shoucheng", {sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    local m = data:toMoveOneTime()
    if not c212_loss(m) or p ~= m.from or not p:isAlive() or p:getPhase() ~= sgs.Player_NotActive
        or p:getHandcardNum() >= p:getHp() or owner:getMark("hlxg_shoucheng-Clear") > 0 then return end
    if gu_invoke(owner, self:objectName(), sgs.QVariant(p)) then
        room:setPlayerMark(owner, "hlxg_shoucheng-Clear", 1)
        p:drawCards(2, self:objectName())
    end
end)
hlxg_shengxi = c212_trigger("hlxg_shengxi", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p == owner and p:getPhase() == sgs.Player_Finish and p:getMark("hlxg_shengxi_damage-Clear") == 0
        and gu_invoke(owner, self:objectName()) then p:drawCards(2, self:objectName()) end
end)
hlxg_shengxi_record = gu_record("#hlxg_shengxi_record", {sgs.Damage}, function(self, event, room, p, data)
    local d = data:toDamage()
    if d.from and d.damage > 0 then room:setPlayerMark(d.from, "hlxg_shengxi_damage-Clear", 1) end
end)
