hlxg_jiangwanfeiyi:addSkill(hlxg_shoucheng)
hlxg_jiangwanfeiyi:addSkill(hlxg_shengxi)

hlxg_jiangqin = sgs.General(extension_hl, "hlxg_jiangqin", "wu", 4)
hlxg_jianyi_record = gu_record("#hlxg_jianyi_record", {sgs.CardsMoveOneTime, sgs.EventPhaseChanging}, function(self, event, room, p, data)
    if event == sgs.EventPhaseChanging then
        if data:toPhaseChange().to == sgs.Player_NotActive then room:removeTag("hlxg_jianyi_ids") end
        return
    end
    local m = data:toMoveOneTime()
    if not m.from or p ~= m.from or m.to_place ~= sgs.Player_DiscardPile
        or bit32.band(m.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON) ~= sgs.CardMoveReason_S_REASON_DISCARD then return end
    local ids = room:getTag("hlxg_jianyi_ids"):toIntList()
    for _, id in sgs.qlist(m.card_ids) do
        local c = sgs.Sanguosha:getCard(id)
        if (c:isKindOf("Weapon") or c:isKindOf("Armor")) and not ids:contains(id) then ids:append(id) end
    end
    room:setTag("hlxg_jianyi_ids", sgs.QVariant(ids))
end)
extension_hl:addSkills(hlxg_jianyi_record)
extension_hl:insertRelatedSkills("hlxg_jianyi", "#hlxg_jianyi_record")
hlxg_jianyi = c212_trigger("hlxg_jianyi", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p == owner or p:getPhase() ~= sgs.Player_Finish then return end
    local ids = sgs.IntList()
    for _, id in sgs.qlist(room:getTag("hlxg_jianyi_ids"):toIntList()) do
        if room:getCardPlace(id) == sgs.Player_DiscardPile then ids:append(id) end
    end
    if ids:isEmpty() then return end
    room:sendCompulsoryTriggerLog(owner, self:objectName(), true)
    room:fillAG(ids, owner)
    local id = room:askForAG(owner, ids, false, self:objectName())
    room:clearAG(owner)
    if not ids:contains(id) then id = ids:first() end
    room:obtainCard(owner, id, self:objectName(), true)
end, true)
hlxg_shangyi = gu_active("hlxg_shangyi", 1, 1, 1,
    function(self, targets, to, from) return gu_one(self, targets, to, from) and not to:isKongcheng() end,
    gu_one_feasible,
    function(self, room, source, targets)
        local to = targets[1]
        gu_throw(room, source, self:getSubcards(), "hlxg_shangyi")
        if source:isDead() or to:isDead() then return end
        room:showAllCards(source, to)
        room:showAllCards(to, source)
        if to:isKongcheng() then return end
        local choices = source:isKongcheng() and "obtain" or "obtain+exchange"
        if room:askForChoice(source, "hlxg_shangyi", choices, sgs.QVariant(to)) == "obtain" then
            local id = room:askForCardChosen(source, to, "h", "hlxg_shangyi", true)
            local black = sgs.Sanguosha:getCard(id):isBlack()
            room:obtainCard(source, id, "hlxg_shangyi", false)
            if black and source:isAlive() then source:drawCards(1, "hlxg_shangyi") end
        else
            local a = room:askForExchange(source, "hlxg_shangyi", 1, 1, false, "@hlxg_shangyi-exchange")
            local b = room:askForExchange(to, "hlxg_shangyi", 1, 1, false, "@hlxg_shangyi-exchange")
            if not a or not b then return end
            local red = sgs.Sanguosha:getCard(b:getSubcards():first()):isRed()
            local moves = sgs.CardsMoveList()
            local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_SWAP, source:objectName(), to:objectName(), "hlxg_shangyi", "")
            moves:append(sgs.CardsMoveStruct(a:getSubcards(), source, to, sgs.Player_PlaceHand, sgs.Player_PlaceHand, reason))
            moves:append(sgs.CardsMoveStruct(b:getSubcards(), to, source, sgs.Player_PlaceHand, sgs.Player_PlaceHand, reason))
            room:moveCardsAtomic(moves, false)
            a:deleteLater(); b:deleteLater()
            if red and source:isAlive() then source:drawCards(1, "hlxg_shangyi") end
        end
    end,
    function(request, c) return not request:getInitiator():isJilei(c) end)
