hlxg_shenshi_receipts = sgs.CreateRuleSkillV2 {
    name = "#hlxg_shenshi_receipts", global = true,
    events = {sgs.CardsMoveOneTime, sgs.Death},
    can_trigger = function(self, event, room, p, data)
        if event ~= sgs.Death then return false end
        local death = data:toDeath()
        local d = death.damage
        if death.who ~= p or not d or d.reason ~= "hlxg_shenshi" or not d.from or d.from:isDead()
            or d.chain or d.transfer or not d.tips:contains("hlxg_shenshi_direct") then return false end
        return self:objectName(), d.from
    end,
    on_cost = function(self, event, room, p, ctx)
        local to = room:askForPlayerChosen(p, room:getAlivePlayers(), "hlxg_shenshi", "@hlxg_shenshi-draw", true, true)
        if not to then return false end
        ctx.targets:append(to)
        return true
    end,
    on_effect = function(self, event, room, p, ctx)
        c212_topup(room, ctx.targets:first(), "hlxg_shenshi")
        return false
    end,
    on_record = function(self, event, room, p, ctx)
        if event ~= sgs.CardsMoveOneTime then return end
        local data = ctx.original_data
        local m = data:toMoveOneTime()
        if not c212_loss(m) or p ~= room:getAllPlayers():first() then return end
        local recipient = m.from
        local due = {}
        for _, owner in sgs.qlist(room:getAllPlayers(true)) do
            local tag = "hlxg_shenshi_gifts_" .. owner:objectName()
            local ids = recipient:getTag(tag):toIntList()
            local n = 0
            for _, id in sgs.qlist(m.card_ids) do
                if ids:contains(id) then ids:removeOne(id); n = n + 1 end
            end
            recipient:setTag(tag, sgs.QVariant(ids))
            if n > 0 then table.insert(due, {owner, n}) end
        end
        for _, receipt in ipairs(due) do
            for i = 1, receipt[2] do c212_topup(room, receipt[1], "hlxg_shenshi") end
        end
    end,
}
extension_hl:addSkills(hlxg_shenshi_receipts)
