-- c212_05: literal 欢乐 variants.
local function c212_damage(room, chooser, range_owner, source, count, skill)
    if count == 0 or not chooser:isAlive() then return end
    local candidates = sgs.SPlayerList()
    for _, p in sgs.qlist(room:getAlivePlayers()) do
        if range_owner:inMyAttackRange(p) then candidates:append(p) end
    end
    if candidates:isEmpty() then return end
    local chosen = room:askForPlayersChosen(chooser, candidates, skill, 0, math.min(count, candidates:length()), "@" .. skill .. "-damage", true)
    for _, p in sgs.qlist(chosen) do
        if p:isAlive() then
            local d = sgs.DamageStruct(); d.from = source; d.to = p; d.damage = 1; d.reason = skill
            room:damage(d)
        end
    end
end
local function c212_xianzhou(name, all)
    local card = sgs.CreateSkillCard {
        name = name .. "Card", will_throw = false, handling_method = sgs.Card_MethodNone,
        filter = gu_one, feasible = gu_one_feasible,
        on_use = function(self, room, source, targets)
            local to = targets[1]
            room:removePlayerMark(source, "@" .. name)
            local ids = all and source:handCards() or self:getSubcards()
            local n = ids:length()
            gu_obtain(room, to, ids, name)
            if all then c212_damage(room, to, to, to, n, name)
            else
                if source:isAlive() then room:recover(source, sgs.RecoverStruct(name, source, n)) end
                c212_damage(room, source, to, source, n, name)
            end
        end,
    }
    return sgs.CreateViewAsSkillV2 {
        name = name, frequency = sgs.Skill_Limited, limit_mark = "@" .. name, n = 999,
        can_activate = function(self, request)
            return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY and request:getInitiator():getMark("@" .. name) > 0
        end,
        can_select_card = function(self, request, c)
            return not all and request:getInitiator():handCards():contains(c:getEffectiveId())
        end,
        card_selection_feasible = function(self, request) return not all or request:getSelectedCardIds():isEmpty() end,
        create_card = function(self, request)
            local c = card:clone(); c:addSubcards(request:getSelectedCardIds()); c:setSkillName(name); return c
        end,
    }
end
hlxg_caifuren = sgs.General(extension_hl, "hlxg_caifuren", "qun", 3, false)
hlxg_xianzhou = c212_xianzhou("hlxg_xianzhou", true)
