hljx_beige = gu_trigger("hljx_beige", {sgs.Damaged}, function(self, event, room, p, data, owner)
    local d = data:toDamage()
    if not d.card or not d.card:isKindOf("Slash") or owner:isNude() then return end
    local c = room:askForCard(owner, "..", "@hljx_beige", data, sgs.Card_MethodDiscard, p, false, self:objectName())
    if not c then return end
    if c:isRed() then
        if d.to:isAlive() then room:recover(d.to, sgs.RecoverStruct(self:objectName(), owner, 1)) end
        if d.to:isAlive() then d.to:drawCards(2, self:objectName()) end
    elseif d.from and d.from:isAlive() then
        if c:getSuit() == sgs.Card_Club then room:askForDiscard(d.from, self:objectName(), 2, 2, false, true)
        elseif c:getSuit() == sgs.Card_Spade then d.from:turnOver() end
    end
end)
-- Mirror the engine duanchang removal policy under the assigned name.
hljx_duanchang = sgs.CreateTriggerSkillV2 {
    name = "hljx_duanchang", events = {sgs.Death}, frequency = sgs.Skill_Compulsory,
    can_trigger = function(self, event, room, p, data)
        return p and p:hasSkill(self:objectName()) and data:toDeath().who == p and self:objectName() or false
    end,
    on_effect = function(self, event, room, p, ctx)
        local death = ctx.original_data:toDeath()
        if not death.damage or not death.damage.from then return end
        local names = {}
        for _, skill in sgs.qlist(death.damage.from:getVisibleSkillList()) do
            if not skill:inherits("SPConvertSkill") and not skill:isAttachedLordSkill() then table.insert(names, "-" .. skill:objectName()) end
        end
        if #names > 0 then room:handleAcquireDetachSkills(death.damage.from, table.concat(names, "|")) end
    end,
}
