-- c212_06: literal 欢乐杀修改 variants, isolated staging fragment.
local function hlc212_recover(room, p, source)
    local rec = sgs.RecoverStruct(); rec.who = source; rec.recover = 1
    room:recover(p, rec)
end
local function hlc212_ag(room, p, ids, optional, skill, prompt)
    room:fillAG(ids, p)
    local id = room:askForAG(p, ids, optional, skill, prompt)
    room:clearAG(p)
    return id
end
local function hlc212_present(room, ids)
    local result = sgs.IntList()
    for _, id in sgs.qlist(ids) do
        if room:getCardPlace(id) == sgs.Player_DiscardPile then result:append(id) end
    end
    return result
end

hlxg_caiwenji = sgs.General(extension_hl, "hlxg_caiwenji", "wei", 3, false)
hlxg_chenqing = gu_trigger("hlxg_chenqing", {sgs.EnterDying}, function(self, event, room, p, data, owner)
    local dying = data:toDying().who
    if not dying or owner:getMark("hlxg_chenqing-Clear") > 0 then return end
    local candidates = room:getAlivePlayers(); candidates:removeOne(dying)
    local target = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_chenqing", true, true)
    if not target then return end
    room:addPlayerMark(owner, "hlxg_chenqing-Clear")
    target:drawCards(5, self:objectName())
    if target:isDead() then return end
    local discarded = room:askForDiscard(target, self:objectName(), 4, 4, false, true, "@hlxg_chenqing-discard")
    if not discarded or discarded:subcardsLength() ~= 4 then return end
    local suits = {}
    for _, id in sgs.qlist(discarded:getSubcards()) do suits[sgs.Sanguosha:getCard(id):getSuit()] = true end
    if suits[sgs.Card_Spade] and suits[sgs.Card_Club] and suits[sgs.Card_Heart] and suits[sgs.Card_Diamond]
        and target:isAlive() and dying:isAlive() then
        local peach = sgs.Sanguosha:cloneCard("peach", sgs.Card_NoSuit, 0); peach:setSkillName(self:objectName())
        local use = sgs.CardUseStruct(); use.card = peach; use.from = target; use.to:append(dying)
        room:useCard(use, false); peach:deleteLater()
    end
end)

-- The attached view-as must share the main name for engine ownership checks.
local hlc212_moshi_name = "hlxg_moshi"
hlxg_moshi_vs = sgs.CreateViewAsSkillV2 {
    name = hlc212_moshi_name, n = 1, response_or_use = true,
    can_activate = function(self, request) return request:getPattern() == "@@hlxg_moshi" end,
    can_select_card = function(self, request, card)
        local p = request:getInitiator()
        return request:getSelectedCardIds():isEmpty() and p:handCards():contains(card:getEffectiveId())
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        local p = request:getInitiator(); local ids = request:getSelectedCardIds()
        if ids:length() ~= 1 then return nil end
        local original = sgs.Sanguosha:getCard(ids:first())
        local card = sgs.Sanguosha:cloneCard(p:property("hlxg_moshi_card"):toString(), original:getSuit(), original:getNumber())
        if card then card:addSubcard(original); card:setSkillName("hlxg_moshi") end
        return card
    end,
}
hlxg_moshi = sgs.CreateTriggerSkillV2 {
    name = "hlxg_moshi", events = {sgs.EventPhaseStart}, view_as_skill = hlxg_moshi_vs,
    can_trigger = function(self, event, room, p, data)
        if p and p:isAlive() and p:hasSkill(self:objectName()) and p:getPhase() == sgs.Player_Finish
            and p:getTag("hlxg_moshi_record"):toString() ~= "" then return self:objectName(), p end
        return false
    end,
    on_effect = function(self, event, room, p, ctx)
        local names = gu_names(p, "hlxg_moshi_record")
        for i = 1, math.min(2, #names) do
            if p:isDead() or p:isKongcheng() then break end
            room:setPlayerProperty(p, "hlxg_moshi_card", sgs.QVariant(names[i]))
            if not room:askForUseCard(p, "@@hlxg_moshi", "@hlxg_moshi:" .. names[i]) then break end
        end
        room:setPlayerProperty(p, "hlxg_moshi_card", sgs.QVariant(""))
        return false
    end,
}
hlxg_moshi_record = gu_record("#hlxg_moshi_record", {sgs.PreCardUsed, sgs.EventPhaseChanging}, function(self, event, room, p, data)
    if not p then return end
    if event == sgs.EventPhaseChanging then
        if data:toPhaseChange().to == sgs.Player_NotActive then p:removeTag("hlxg_moshi_record") end
    elseif p:getPhase() == sgs.Player_Play then
        local card = data:toCardUse().card
        if card and (card:isKindOf("BasicCard") or card:isNDTrick()) then
            local names = gu_names(p, "hlxg_moshi_record")
            if #names < 2 then names[#names + 1] = card:objectName(); p:setTag("hlxg_moshi_record", sgs.QVariant(table.concat(names, "+"))) end
        end
    end
end)
hlxg_caiwenji:addSkill(hlxg_chenqing); hlxg_caiwenji:addSkill(hlxg_moshi); hlxg_caiwenji:addSkill(hlxg_moshi_record)
