hlxg_caiyong = sgs.General(extension_hl, "hlxg_caiyong", "qun", 3)
hlxg_pizhuan = gu_trigger("hlxg_pizhuan", {sgs.CardUsed, sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if not use.card or not use.card:isBlack() or owner:getPile("hlxg_pizhuan_book"):length() >= 4 + owner:getMark("hlxg_tongbo_cap") then return end
    if event == sgs.CardUsed then
        if use.from ~= owner then return end
    elseif p ~= owner or use.from == owner or not use.to:contains(owner) then return end
    if gu_invoke(owner, self:objectName(), data) then owner:addToPile("hlxg_pizhuan_book", room:drawCard(), true) end
end)
hlxg_pizhuan_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_pizhuan_max", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        return p and p:hasSkill("hlxg_pizhuan") and p:getPile("hlxg_pizhuan_book"):length() or 0
    end,
}
hlxg_tongbo = gu_trigger("hlxg_tongbo", {sgs.EventPhaseEnd}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Draw or owner:getPile("hlxg_pizhuan_book"):isEmpty() then return end
    if not gu_invoke(owner, self:objectName()) then return end
    local books = sgs.IntList(); for _, id in sgs.qlist(owner:getPile("hlxg_pizhuan_book")) do books:append(id) end
    local exchange = room:askForExchange(owner, self:objectName(), books:length(), 0, true, "@hlxg_tongbo-exchange", true)
    if exchange and not exchange:getSubcards():isEmpty() then
        local take = sgs.IntList()
        for i = 1, exchange:subcardsLength() do
            local id = hlc212_ag(room, owner, books, false, self:objectName(), "@hlxg_tongbo-book")
            if id < 0 then return end
            take:append(id); books:removeOne(id)
        end
        local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_SWAP, owner:objectName(), self:objectName(), "")
        local moves = sgs.CardsMoveList()
        local put = sgs.CardsMoveStruct(exchange:getSubcards(), owner, sgs.Player_PlaceSpecial, reason)
        put.to_pile_name = "hlxg_pizhuan_book"
        local get = sgs.CardsMoveStruct(take, owner, sgs.Player_PlaceHand, reason)
        moves:append(put); moves:append(get); room:moveCardsAtomic(moves, true)
    end
    if owner:isDead() or owner:getPile("hlxg_pizhuan_book"):length() < 4 then return end
    if room:getOtherPlayers(owner):isEmpty() or not gu_invoke(owner, "hlxg_tongbo_give") then return end
    local available = sgs.IntList(); for _, id in sgs.qlist(owner:getPile("hlxg_pizhuan_book")) do available:append(id) end
    local gifts = sgs.IntList()
    for i = 1, 4 do
        local id = hlc212_ag(room, owner, available, false, self:objectName(), "@hlxg_tongbo-gift")
        if id < 0 then return end
        gifts:append(id); available:removeOne(id)
    end
    -- Each of the four books may go to a different other character.
    for _, id in sgs.qlist(gifts) do
        if owner:isDead() or room:getOtherPlayers(owner):isEmpty() then return end
        local target = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@hlxg_tongbo-target", false, true)
        if not owner:getPile("hlxg_pizhuan_book"):contains(id) then return end
        if target then room:obtainCard(target, id, true) end
    end
    if owner:isAlive() then
        hlc212_recover(room, owner, owner)
        if owner:getMark("hlxg_tongbo_cap") < room:alivePlayerCount() then room:addPlayerMark(owner, "hlxg_tongbo_cap") end
    end
end)
hlxg_caiyong:addSkill(hlxg_pizhuan); hlxg_caiyong:addSkill(hlxg_pizhuan_max); hlxg_caiyong:addSkill(hlxg_tongbo)
