hlxg_zhiyan_yufan = gu_trigger("hlxg_zhiyan_yufan", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Finish then return end
    local target = room:askForPlayerChosen(owner, room:getAlivePlayers(), self:objectName(), "@hlxg_zhiyan_yufan", true, true)
    if not target then return end
    local ids = room:drawCardsList(target, 1, self:objectName())
    if ids:isEmpty() or target:isDead() then return end
    local id = ids:first(); room:showCard(target, id)
    local card = sgs.Sanguosha:getCard(id)
    if not card:isKindOf("EquipCard") then
        if owner:isAlive() then owner:drawCards(1, self:objectName()) end
    else
        if room:getCardOwner(id) == target and room:getCardPlace(id) == sgs.Player_PlaceHand then
            local use = sgs.CardUseStruct(); use.card = card; use.from = target; use.to:append(target)
            room:useCard(use, false)
        end
        if target:isAlive() then hlc212_recover(room, target, owner) end
    end
end)
hlxg_zongxuan = gu_trigger("hlxg_zongxuan", {sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    local move = data:toMoveOneTime()
    if not move.from or move.from:objectName() ~= owner:objectName() or move.to_place ~= sgs.Player_DiscardPile
        or bit32.band(move.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON) ~= sgs.CardMoveReason_S_REASON_DISCARD then return end
    local ids = hlc212_present(room, move.card_ids)
    if ids:isEmpty() or room:getOtherPlayers(owner):isEmpty() then return end
    if not gu_invoke(owner, self:objectName(), data) then return end
    local id = hlc212_ag(room, owner, ids, false, self:objectName(), "@hlxg_zongxuan-gift")
    if id < 0 then return end
    local target = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@hlxg_zongxuan-target", false, true)
    if not target then return end
    room:obtainCard(target, id, true); ids:removeOne(id)
    if owner:isDead() then return end
    owner:drawCards(1, self:objectName())
    local selected = sgs.IntList()
    room:setPlayerFlag(owner, "hlxg_zongxuan_top")
    while owner:isAlive() do
        ids = hlc212_present(room, ids)
        if ids:isEmpty() then break end
        local top = hlc212_ag(room, owner, ids, true, self:objectName(), "@hlxg_zongxuan-top")
        if top < 0 then break end
        selected:append(top); ids:removeOne(top)
    end
    room:setPlayerFlag(owner, "-hlxg_zongxuan_top")
    selected = hlc212_present(room, selected)
    if not selected:isEmpty() then
        local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_PUT, owner:objectName(), self:objectName(), "")
        local ordered = sgs.IntList()
        local list = sgs.QList2Table(selected)
        for i = #list, 1, -1 do ordered:append(list[i]) end
        local put = sgs.CardsMoveStruct(ordered, nil, sgs.Player_DrawPile, reason)
        room:moveCardsAtomic(put, true)
    end
end)
hlxg_yufan:addSkill(hlxg_zhiyan_yufan); hlxg_yufan:addSkill(hlxg_zongxuan)

