-- ==================== c213_01
do
-- c213_01: literal 欢乐 袁术 variants.
local function c213_kingdoms(room)
    local seen, n = {}, 0
    for _, p in sgs.qlist(room:getAlivePlayers()) do
        if not seen[p:getKingdom()] then seen[p:getKingdom()] = true; n = n + 1 end
    end
    return n
end
local function c213_discard_ids(p, room)
    local ids = sgs.IntList()
    for _, value in ipairs(gu_names(p, "c213_discard")) do
        local id = tonumber(value)
        if id and room:getCardPlace(id) == sgs.Player_DiscardPile then ids:append(id) end
    end
    return ids
end
hlxg_weidi_record = gu_record("#hlxg_weidi_record", {sgs.EventPhaseStart, sgs.CardsMoveOneTime, sgs.Damage, sgs.HpRecover, sgs.TargetSpecified},
    function(self, event, room, p, data)
        if event == sgs.EventPhaseStart then
            if p and p:getPhase() == sgs.Player_Discard then gu_setnames(p, "c213_discard", {}) end
        elseif event == sgs.CardsMoveOneTime then
            local m = data:toMoveOneTime()
            if not m.from or m.from:getPhase() ~= sgs.Player_Discard or m.to_place ~= sgs.Player_DiscardPile
                or bit32.band(m.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON) ~= sgs.CardMoveReason_S_REASON_DISCARD then return end
            local from = room:findPlayerByObjectName(m.from:objectName())
            if not from then return end
            local ids = gu_names(from, "c213_discard")
            for _, id in sgs.qlist(m.card_ids) do
                if not table.contains(ids, tostring(id)) then table.insert(ids, tostring(id)) end
            end
            gu_setnames(from, "c213_discard", ids)
        elseif event == sgs.Damage then
            local d = data:toDamage()
            if d.from then room:addPlayerMark(d.from, "c213_damage-Clear", d.damage) end
        elseif event == sgs.HpRecover then
            if p then room:addPlayerMark(p, "c213_recover-Clear") end
        elseif event == sgs.TargetSpecified then
            local use = data:toCardUse()
            if use.from and use.card then
                for _, to in sgs.qlist(use.to) do room:addPlayerMark(use.from, "c213_card_" .. to:objectName() .. "-Clear") end
            end
        end
    end)
extension_hl:addSkills(hlxg_weidi_record)
local function c213_weidi(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Discard then return end
    local ids = c213_discard_ids(owner, room)
    if ids:isEmpty() or room:getOtherPlayers(owner):isEmpty() or not gu_invoke(owner, self:objectName(), data) then return end
    local selected = sgs.IntList()
    local color
    if self:objectName() == "hlxg_weidi" then
        room:fillAG(ids, owner)
        local id = room:askForAG(owner, ids, false, self:objectName())
        room:clearAG(owner)
        if id < 0 then return end
        selected:append(id)
    else
        local red, black = false, false
        for _, id in sgs.qlist(ids) do
            local c = sgs.Sanguosha:getCard(id)
            red = red or c:isRed(); black = black or c:isBlack()
        end
        local choices = {}
        if red then table.insert(choices, "red") end
        if black then table.insert(choices, "black") end
        if #choices == 0 then return end
        color = room:askForChoice(owner, self:objectName(), table.concat(choices, "+"))
        for _, id in sgs.qlist(ids) do
            local c = sgs.Sanguosha:getCard(id)
            if (color == "red" and c:isRed()) or (color == "black" and c:isBlack()) then selected:append(id) end
        end
    end
    local to = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@" .. self:objectName() .. "-give", false, true)
    if not to then return end
    gu_obtain(room, to, selected, self:objectName())
    if color and owner:isAlive() and to:isAlive() and to:getKingdom() == "qun"
        and gu_invoke(owner, "hljx_weidi_return", sgs.QVariant(to)) then
        local opposite = color == "red" and "black" or "red"
        local n = 0
        for _, c in sgs.qlist(to:getCards("he")) do
            if (opposite == "red" and c:isRed()) or (opposite == "black" and c:isBlack()) then n = n + 1 end
        end
        n = math.min(n, selected:length())
        if n > 0 then
            local cards = room:askForExchange(to, self:objectName(), n, n, true, "@hljx_weidi-return:" .. owner:objectName(), false, ".|" .. opposite)
            if cards then room:obtainCard(owner, cards, self:objectName(), false); cards:deleteLater() end
        end
    end
end
hlxg_weidi = gu_trigger("hlxg_weidi", {sgs.EventPhaseEnd}, c213_weidi)
hljx_weidi = gu_trigger("hljx_weidi", {sgs.EventPhaseEnd}, c213_weidi)
local function c213_yongsi(self, event, room, p, data, owner)
    if p ~= owner then return end
    local x = c213_kingdoms(room)
    if event == sgs.DrawNCards then local draw = data:toDraw(); draw.num = draw.num + x; data:setValue(draw)
    elseif p:getPhase() == sgs.Player_Discard then
        room:askForDiscard(owner, self:objectName(), x, x, false, true)
    elseif self:objectName() == "hljx_yongsi" and p:getPhase() == sgs.Player_Finish and owner:getMark("c213_damage-Clear") <= 1 then
        owner:drawCards(x, self:objectName())
    end
end
hlxg_yongsi = gu_trigger("hlxg_yongsi", {sgs.DrawNCards, sgs.EventPhaseStart}, c213_yongsi, true)
hljx_yongsi = gu_trigger("hljx_yongsi", {sgs.DrawNCards, sgs.EventPhaseStart}, c213_yongsi, true)
hlxg_yuanshu = sgs.General(extension_hl, "hlxg_yuanshu", "qun", 4)
hljx_yuanshu = sgs.General(extension_hl, "hljx_yuanshu", "qun", 4)
hlxg_yuanshu:addSkill(hlxg_weidi); hlxg_yuanshu:addSkill(hlxg_yongsi)
hljx_yuanshu:addSkill(hljx_weidi); hljx_yuanshu:addSkill(hljx_yongsi)

local function c213_corners(p) return gu_names(p, "hlxg_canxi_corners") end
local function c213_setcorners(room, p, corners)
    gu_setnames(p, "hlxg_canxi_corners", corners)
    room:setPlayerMark(p, "&hlxg_canxi", #corners)
end
local function c213_active(p) return p:getTag("hlxg_canxi_active"):toString() end
local function c213_mode(p) return p:getTag("hlxg_canxi_mode"):toString() end
hlxg_zhonggu = sgs.CreateTriggerSkillV2 {
    name = "hlxg_zhonggu$", frequency = sgs.Skill_Compulsory, events = {sgs.DrawNCards},
    can_trigger = function(self, event, room, p, data)
        if p and p:hasLordSkill(self:objectName()) then
            local n = 0
            for _, q in sgs.qlist(room:getAlivePlayers()) do if q:getKingdom() == "qun" then n = n + 1 end end
            if room:getTag("TurnLengthCount"):toInt() >= n then return self:objectName(), p end
        end
        return false
    end,
    on_effect = function(self, event, room, p, ctx)
        local draw = ctx.original_data:toDraw(); draw.num = draw.num + 2; ctx.original_data:setValue(draw)
    end,
}
hlxg_pizhi = gu_trigger("hlxg_pizhi", {sgs.EventPhaseStart, sgs.Death}, function(self, event, room, p, data, owner)
    if event == sgs.EventPhaseStart then
        if p == owner and p:getPhase() == sgs.Player_Finish then
            local n = math.max(0, 4 - #c213_corners(owner))
            if n > 0 then owner:drawCards(n, self:objectName()) end
        end
        return
    end
    local dead = data:toDeath().who
    if not dead then return end
    local kingdom, last = dead:getKingdom(), true
    for _, q in sgs.qlist(room:getAlivePlayers()) do if q:getKingdom() == kingdom then last = false end end
    local corners = c213_corners(owner)
    if not table.contains(corners, kingdom) or (kingdom ~= c213_active(owner) and not last) then return end
    table.removeOne(corners, kingdom)
    c213_setcorners(room, owner, corners)
    if kingdom == c213_active(owner) then
        owner:setTag("hlxg_canxi_active", sgs.QVariant("")); owner:setTag("hlxg_canxi_mode", sgs.QVariant(""))
    end
    local n = math.max(0, 4 - #corners)
    if n > 0 then owner:drawCards(n, self:objectName()) end
    if owner:isAlive() then room:recover(owner, sgs.RecoverStruct(self:objectName(), owner, 1)) end
end, true)
hlxg_canxi = gu_trigger("hlxg_canxi", {sgs.GameStart, sgs.RoundStart, sgs.DamageCaused, sgs.HpRecover, sgs.TargetSpecified},
    function(self, event, room, p, data, owner)
        if event == sgs.GameStart then
            if p ~= owner then return end
            local corners = {}
            for _, q in sgs.qlist(room:getAlivePlayers()) do
                if not table.contains(corners, q:getKingdom()) then table.insert(corners, q:getKingdom()) end
            end
            c213_setcorners(room, owner, corners)
            local missing = math.max(0, 4 - #corners)
            if missing > 0 then room:setPlayerProperty(owner, "maxhp", sgs.QVariant(owner:getMaxHp() + missing)) end
        elseif event == sgs.RoundStart then
            if p ~= owner then return end
            owner:setTag("hlxg_canxi_active", sgs.QVariant("")); owner:setTag("hlxg_canxi_mode", sgs.QVariant(""))
            local corners = c213_corners(owner)
            if #corners == 0 then return end
            local kingdom = room:askForChoice(owner, self:objectName(), table.concat(corners, "+"))
            owner:setTag("hlxg_canxi_active", sgs.QVariant(kingdom))
            owner:setTag("hlxg_canxi_mode", sgs.QVariant(room:askForChoice(owner, self:objectName(), "wangsheng+xiangsi")))
        elseif event == sgs.DamageCaused then
            local d = data:toDamage()
            if d.from and d.from:getKingdom() == c213_active(owner) and c213_mode(owner) == "wangsheng"
                and d.from:getMark("c213_damage-Clear") == 0 then d.damage = d.damage + 1; data:setValue(d) end
        elseif event == sgs.HpRecover then
            if p and p ~= owner and p:getKingdom() == c213_active(owner) and c213_mode(owner) == "xiangsi"
                and p:getMark("c213_recover-Clear") == 1 then room:loseHp(p, 1, true, owner, self:objectName()) end
        elseif event == sgs.TargetSpecified then
            local use = data:toCardUse()
            if use.from and use.from ~= owner and use.from:getKingdom() == c213_active(owner) and c213_mode(owner) == "xiangsi"
                and use.to:contains(owner) and use.from:getMark("c213_card_" .. owner:objectName() .. "-Clear") == 1 then
                local nullified = use.nullified_list
                if not table.contains(nullified, owner:objectName()) then table.insert(nullified, owner:objectName()) end
                use.nullified_list = nullified; data:setValue(use)
            end
        end
    end, true)
hlxg_canxi_distance = sgs.CreateDistanceSkillV2 {
    name = "#hlxg_canxi_distance", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local from, to = ctx:getPrimary(), ctx:getSecondary()
        if not from or not to or from == to then return 0 end
        local n = 0
