            if owner:hasSkill("hlxg_canxi") and c213_mode(owner) == "wangsheng" and c213_active(owner) == from:getKingdom() then n = n - 1 end
        end
        if from:hasSkill("hlxg_canxi") and c213_mode(from) == "wangsheng" and c213_active(from) == from:getKingdom() then n = n - 1 end
        return n
    end,
}
