-- c213_02: each variant keeps its own state and lord skill.
local function c213_qun(room)
    local n = 0
    for _, p in sgs.qlist(room:getAlivePlayers()) do if p:getKingdom() == "qun" then n = n + 1 end end
    return n
end
local function c213_key(c, mode)
    if mode == 2 then return c:isRed() and "red" or (c:isBlack() and "black" or "none") end
    return c:getSuitString()
end
local function c213_luanji(name, mode)
    return sgs.CreateViewAsSkillV2 {
        name = name, n = 2, response_or_use = true,
        can_activate = function(self, request)
            if mode == 0 then return request:getPattern() == "@@" .. name end
            return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
        end,
        can_select_card = function(self, request, c)
            return not c:isEquipped() and request:getSelectedCardIds():length() < 2
                and (mode == 0 or request:getInitiator():getMark(name .. "_" .. c213_key(c, mode) .. "-Clear") == 0)
        end,
        card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 2 end,
        create_card = function(self, request)
            local c = sgs.Sanguosha:cloneCard("archery_attack", sgs.Card_NoSuit, 0)
            c:addSubcards(request:getSelectedCardIds()); c:setSkillName(name); return c
        end,
    }
end
local function c213_luanji_events(name, mode)
    return gu_trigger("#" .. name .. "_events", {sgs.EventPhaseStart, sgs.CardUsed, sgs.Damage, sgs.CardFinished, sgs.CardResponded},
        function(self, event, room, player, data, owner)
            if event == sgs.EventPhaseStart then
                if mode == 0 and player == owner and owner:getPhase() == sgs.Player_Play then
                    room:askForUseCard(owner, "@@" .. name, "@" .. name, -1, sgs.Card_MethodUse)
                end
                return
            end
            if event == sgs.CardResponded then
                if mode ~= 2 or player == owner or owner:getMark(name .. "_draw-Clear") >= 3 then return end
                local r = data:toCardResponse()
                if r.m_card and r.m_card:isKindOf("Jink") and r.m_toCard and r.m_toCard:isKindOf("ArcheryAttack") then
                    room:addPlayerMark(owner, name .. "_draw-Clear"); owner:drawCards(1, name)
                end
                return
            end
            if event == sgs.Damage then
                local d = data:toDamage()
                if not d.card or not d.card:isKindOf("ArcheryAttack") then return end
                if mode == 1 then room:setCardFlag(d.card, name .. "_damaged") end
                if mode == 2 and d.from == owner and d.to and d.to:isAlive() and owner:getMark(name .. "_discard-Clear") < 3
                    and owner:canDiscard(d.to, "he") and gu_invoke(owner, name, sgs.QVariant(d.to)) then
                    room:addPlayerMark(owner, name .. "_discard-Clear")
                    local id = room:askForCardChosen(owner, d.to, "he", name, false, sgs.Card_MethodDiscard)
                    room:throwCard(id, d.to, owner)
                end
                return
            end
            local use = data:toCardUse()
            if use.from ~= owner or not use.card or not use.card:isKindOf("ArcheryAttack") then return end
            if event == sgs.CardUsed then
                if use.card:getSkillName() == name and mode > 0 then
                    for _, id in sgs.qlist(use.card:getSubcards()) do
                        room:setPlayerMark(owner, name .. "_" .. c213_key(sgs.Sanguosha:getCard(id), mode) .. "-Clear", 1)
                    end
                end
                if mode == 1 then room:setCardFlag(use.card, "-" .. name .. "_damaged") end
            elseif event == sgs.CardFinished and mode == 1 then
                if not use.card:hasFlag(name .. "_damaged") then owner:drawCards(use.to:length(), name) end
                room:setCardFlag(use.card, "-" .. name .. "_damaged")
            end
        end)
end
local function c213_heal(room, owner, name)
    room:removePlayerMark(owner, "&" .. name)
    local r = sgs.RecoverStruct(); r.who = owner; r.recover = 1
    room:recover(owner, r); if owner:isAlive() then owner:drawCards(1, name) end
end
local function c213_xueyi(name)
    local card = sgs.CreateSkillCard {
        name = name .. "Card", target_fixed = true,
        on_use = function(self, room, source)
            if source:hasLordSkill(name) and source:getMark("&" .. name) > 0 then c213_heal(room, source, name) end
        end,
    }
    _G[name .. "Card"] = card
    return sgs.CreateViewAsSkillV2 {
        name = name .. "$", n = 0,
        can_activate = function(self, request)
            local p = request:getInitiator()
            return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY and p:hasLordSkill(name) and p:getMark("&" .. name) > 0
        end,
        can_select_card = function() return false end,
        create_card = function() return card:clone() end,
    }
end
local function c213_xueyi_events(name)
    return gu_trigger("#" .. name .. "_events", {sgs.GameStart, sgs.Dying}, function(self, event, room, player, data, owner)
        if not owner:hasLordSkill(name) then return end
        if event == sgs.GameStart then room:setPlayerMark(owner, "&" .. name, c213_qun(room))
        elseif data:toDying().who == owner and owner:getMark("&" .. name) > 0 and gu_invoke(owner, name, data) then
            c213_heal(room, owner, name)
        end
    end)
end
local function c213_max(name, dynamic)
    return sgs.CreateMaxCardsSkillV2 {
        name = string.format("#%s_max", name), holder_selector = sgs.CorrectSkill_Primary,
        correct_func = function(self, ctx)
            local p = ctx:getPrimary()
            if not p or not p:hasLordSkill(name) then return 0 end
            local room = sgs.Sanguosha:currentRoom()
            if not room then return 0 end
            return 2 * (dynamic and c213_qun(room) or p:getMark("&" .. name))
        end,
    }
end

