-- c213_03: literal current excerpt text, SkillV2.
hlxg_yuanshao3 = sgs.General(extension_hl, "hlxg_yuanshao3", "qun", 4)
hlxg_xuyou = sgs.General(extension_hl, "hlxg_xuyou", "qun", 3)
hljx_xuchu = sgs.General(extension_hl, "hljx_xuchu", "wei", 4)

local function c213_zongshi_card(p, id)
    local shown = sgs.Sanguosha:getCard(id)
    local card = sgs.Sanguosha:cloneCard(shown:objectName(), shown:getSuit(), shown:getNumber())
    card:setSkillName("hlxg_zongshi_yuanshao3")
    card:setCanRecast(false)
    for _, c in sgs.qlist(p:getHandcards()) do
        if c:getEffectiveId() ~= id and c:getSuit() == shown:getSuit() then card:addSubcard(c) end
    end
    return card
end
hlxg_zongshi_yuanshao3Card = sgs.CreateSkillCard {
    name = "hlxg_zongshi_yuanshao3Card", will_throw = false, handling_method = sgs.Card_MethodNone,
    filter = function(self, targets, to, from)
        local c = c213_zongshi_card(from, self:getSubcards():first())
        local ok = #targets < c:subcardsLength() and not from:isProhibited(to, c)
        if ok then
            if c:targetFixed() then
                ok = (not c:isKindOf("AOE") or to ~= from)
                if c:isKindOf("Peach") then ok = to:isWounded() end
                if c:isKindOf("Jink") or c:isKindOf("Nullification") then ok = false end
            else
                local list = sgs.PlayerList()
                -- Collateral's second target is its designated Slash victim.
                if c:isKindOf("Collateral") then for _, p in ipairs(targets) do list:append(p) end end
                ok = c:targetFilter(list, to, from)
            end
        end
        c:deleteLater()
        return ok
    end,
    feasible = function(self, targets, from)
        if #targets == 0 then return true end
        local c = c213_zongshi_card(from, self:getSubcards():first())
        local ok = #targets <= c:subcardsLength()
        if c:isKindOf("Collateral") then
            local list = sgs.PlayerList()
            for _, p in ipairs(targets) do list:append(p) end
            ok = ok and c:targetsFeasible(list, from)
        end
        c:deleteLater()
        return ok
    end,
    on_use = function(self, room, source, targets)
        local id = self:getSubcards():first()
        if room:getCardOwner(id) ~= source or room:getCardPlace(id) ~= sgs.Player_PlaceHand then return end
        local card = c213_zongshi_card(source, id)
        local x = card:subcardsLength()
        room:showCard(source, id)
        local use = sgs.CardUseStruct()
        use.card = card; use.from = source
        for _, p in ipairs(targets) do use.to:append(p) end
        if #targets == 0 then card:setFlags("hlxg_zongshi_zero") end
        room:useCard(use, true)
        card:deleteLater()
        if source:isAlive() and x > #targets then source:drawCards(x - #targets, "hlxg_zongshi_yuanshao3") end
    end,
}
hlxg_zongshi_yuanshao3 = sgs.CreateViewAsSkillV2 {
    name = "hlxg_zongshi_yuanshao3", n = 1,
    can_activate = function(self, request)
        return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
            or request:getPattern() == "@@hlxg_zongshi_yuanshao3"
    end,
    can_select_card = function(self, request, card)
        return request:getSelectedCardIds():isEmpty()
            and request:getInitiator():handCards():contains(card:getEffectiveId())
            and (card:isKindOf("BasicCard") or card:isNDTrick())
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        local card = hlxg_zongshi_yuanshao3Card:clone()
        card:addSubcards(request:getSelectedCardIds()); card:setSkillName(self:objectName()); return card
    end,
}
hlxg_zongshi_targets = gu_record("#hlxg_zongshi_yuanshao3_targets", {sgs.PreCardUsed}, function(self, event, room, p, data)
    local use = data:toCardUse()
    if use.card and use.card:hasFlag("hlxg_zongshi_zero") then
        -- Preserve the expressly chosen empty set after automatic target construction.
        use.to = sgs.SPlayerList(); data:setValue(use)
    end
end)
local function c213_xiaoyan(room, owner)
    local others = sgs.QList2Table(room:getOtherPlayers(owner))
    -- Damage everyone first; only then resolve their choices in seat order.
    for _, p in ipairs(others) do
        if p:isAlive() then room:damage(sgs.DamageStruct("hlxg_xiaoyan", owner, p, 1, sgs.DamageStruct_Fire)) end
    end
    for _, p in ipairs(others) do
        if p:isAlive() and owner:isAlive() then
            local choices = p:isNude() and "draw" or "give+draw"
            if room:askForChoice(p, "hlxg_xiaoyan", choices, sgs.QVariant(owner:objectName())) == "give" then
                local card = room:askForExchange(p, "hlxg_xiaoyan", 1, 1, true, "@hlxg_xiaoyan-give")
                if card then
                    room:obtainCard(owner, card, false)
                    local rec = sgs.RecoverStruct(); rec.who = owner; rec.recover = 1; room:recover(p, rec)
                end
            else owner:drawCards(1, "hlxg_xiaoyan") end
        end
    end
end
