do
-- c213_04; helpers belong to the enclosing GU block.
hlxg_yechou = sgs.CreateTriggerSkillV2 {
    name = "hlxg_yechou", events = {sgs.Death},
    can_trigger = function(self, event, room, p, data)
        local dead = data:toDeath().who
        if dead and dead:hasSkill(self:objectName()) then return self:objectName(), dead end
        return false
    end,
    on_cost = function(self, event, room, p, ctx)
        local dead = ctx.original_data:toDeath().who
        local to = room:askForPlayerChosen(dead, room:getOtherPlayers(dead), self:objectName(), "@hlxg_yechou", true, true)
        if not to then return false end
        dead:setTag("hlxg_yechou_target", sgs.QVariant(to:objectName()))
        return true
    end,
    on_effect = function(self, event, room, p, ctx)
        local dead = ctx.original_data:toDeath().who
        local to = room:findPlayerByObjectName(dead:getTag("hlxg_yechou_target"):toString())
        dead:removeTag("hlxg_yechou_target")
        if to then
            room:addPlayerMark(to, "hlxg_yechou_pending")
            room:addPlayerMark(to, "&hlxg_yechou")
        end
        return false
    end,
}
hlxg_yechou_delay = gu_record("#hlxg_yechou_delay", {sgs.EventPhaseStart, sgs.EventPhaseChanging, sgs.DamageInflicted}, function(self, event, room, p, data)
    if event == sgs.EventPhaseStart then
        if p and p:getPhase() == sgs.Player_RoundStart then room:setPlayerMark(p, "hlxg_yechou_pending", 0) end
    elseif event == sgs.EventPhaseChanging then
        if data:toPhaseChange().to ~= sgs.Player_NotActive then return end
        for _, to in sgs.qlist(room:getAlivePlayers()) do
            local n = to:getMark("hlxg_yechou_pending")
            for i = 1, n do if to:isAlive() then room:loseHp(to, 1, true, nil, "hlxg_yechou") end end
        end
    else
        local d = data:toDamage()
        if d.to and d.to:getMark("&hlxg_yechou") > 0 and d.damage >= d.to:getHp() then
            d.damage = d.damage * (2 ^ d.to:getMark("&hlxg_yechou")); data:setValue(d)
        end
    end
end)

hlxg_biaozhao = gu_trigger("hlxg_biaozhao", {sgs.RoundStart, sgs.DamageCaused}, function(self, event, room, p, data, owner)
    if event == sgs.RoundStart then
        if not gu_invoke(owner, self:objectName(), data) then return end
        local first = room:askForPlayerChosen(owner, room:getAlivePlayers(), self:objectName(), "@hlxg_biaozhao-first", false, true)
        local choices = room:getAlivePlayers(); choices:removeOne(first)
        if choices:isEmpty() then return end
        local second = room:askForPlayerChosen(owner, choices, self:objectName(), "@hlxg_biaozhao-second", false, true)
        owner:setTag("hlxg_biaozhao_first", sgs.QVariant(first:objectName()))
        owner:setTag("hlxg_biaozhao_second", sgs.QVariant(second:objectName()))
    else
        local d = data:toDamage()
        if d.card and d.from and d.to == owner and d.from:objectName() == owner:getTag("hlxg_biaozhao_second"):toString() then
            d.damage = d.damage + 1; data:setValue(d)
        end
    end
end)
hlxg_biaozhao_clear = gu_record("#hlxg_biaozhao_clear", {sgs.RoundStart, sgs.RoundEnd, sgs.Death}, function(self, event, room, p, data)
    local players = room:getAllPlayers(true)
    for _, owner in sgs.qlist(players) do
        if event ~= sgs.Death or data:toDeath().who == owner then
            owner:removeTag("hlxg_biaozhao_first"); owner:removeTag("hlxg_biaozhao_second")
        end
    end
end)
hlxg_biaozhao_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_biaozhao_mod", pattern = ".", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local from, to = ctx:getPrimary(), ctx:getSecondary()
        if not from or not to then return false end
        if ctx:getModType() ~= sgs.TargetModSkill_Residue and ctx:getModType() ~= sgs.TargetModSkill_DistanceLimit then return false end
        for _, owner in sgs.qlist(from:getAliveSiblings()) do
            if owner:getTag("hlxg_biaozhao_first"):toString() == from:objectName() and owner:getTag("hlxg_biaozhao_second"):toString() == to:objectName() then return 1000 end
        end
        if from:getTag("hlxg_biaozhao_first"):toString() == from:objectName() and from:getTag("hlxg_biaozhao_second"):toString() == to:objectName() then return 1000 end
        return false
    end,
}
local function c213_04_kongcheng(name)
    return sgs.CreateProhibitSkillV2 {
        name = name, frequency = sgs.Skill_Compulsory, holder_selector = sgs.CorrectSkill_System,
        is_prohibited = function(self, ctx)
            local to, c = ctx:getTo(), ctx:getCard()
            return to and c and to:hasSkill(self:objectName()) and to:isKongcheng()
                and (c:isKindOf("Slash") or c:isKindOf("Duel") or c:isKindOf("Snatch"))
        end,
    }
end
