    if p ~= owner then return end
    local start = p:getPhase() == sgs.Player_Start
    if not start and not (p:getPhase() == sgs.Player_Finish and p:getMark("hlxg_guanxing_zhugeliang_bottom-Clear") > 0) then return end
    if not gu_invoke(p, self:objectName()) then return end
    local ids = room:getNCards(room:alivePlayerCount() == 2 and 3 or 5, false)
    room:returnToTopDrawPile(ids)
    local top = room:askForGuanxing(p, ids)
    if start and top:isEmpty() then room:setPlayerMark(p, "hlxg_guanxing_zhugeliang_bottom-Clear", 1) end
end)
hljx_guanxing_take = gu_active("hljx_guanxing", nil, 0, 0,
    function() return false end, function(self, targets) return #targets == 0 end,
    function(self, room, source)
        local ids = source:getPile("hljx_guanxing_star")
        local n = ids:length()
        local x = room:alivePlayerCount() == 2 and 3 or 5
        gu_obtain(room, source, ids, "hljx_guanxing")
        if n >= x and source:getMark("hljx_guanxing_crossbow") == 0 then
            source:ViewAsEquip("crossbow", true); room:setPlayerMark(source, "hljx_guanxing_crossbow", 1)
        end
