hljx_guanxing = gu_trigger("hljx_guanxing", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or (p:getPhase() ~= sgs.Player_Start and p:getPhase() ~= sgs.Player_Finish) then return end
    if not gu_invoke(p, self:objectName()) then return end
    local x = room:alivePlayerCount() == 2 and 3 or 5
    local ids = room:getNCards(x, false); room:returnToTopDrawPile(ids)
    if p:getPile("hljx_guanxing_star"):length() < x then
        room:fillAG(ids, p)
        local id = room:askForAG(p, ids, true, self:objectName())
        room:clearAG(p)
        if id >= 0 then p:addToPile("hljx_guanxing_star", id, false); ids:removeOne(id) end
    end
    room:askForGuanxing(p, ids)
end)
hljx_guanxing:setViewAsSkill(hljx_guanxing_take)
