-- ==================== c213_05
do
-- c213_05: literal 欢乐杀修改 variants.
local function c21305_targets(card, r, selected, candidate)
    if not card then return false end
    local list = sgs.PlayerList()
    for _, p in ipairs(selected) do list:append(p) end
    card:deleteLater()
    if candidate then return card:targetFilter(list, candidate, r:getInitiator()) and not r:getInitiator():isProhibited(candidate, card, list) end
    return card:targetsFeasible(list, r:getInitiator())
end
local function c21305_convert(name, identity, red)
    return sgs.CreateViewAsSkillV2 {
        name = name, n = 1, response_or_use = true,
        can_select_target = function(self, r, selected, to) return c21305_targets(sgs.Sanguosha:cloneCard(identity), r, selected, to) end,
        targets_feasible = function(self, r, selected) return c21305_targets(sgs.Sanguosha:cloneCard(identity), r, selected) end,
        can_activate = function(self, r)
            local c = sgs.Sanguosha:cloneCard(identity); c:deleteLater()
            if r:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY then return c:isAvailable(r:getInitiator()) end
            return sgs.Sanguosha:matchExpPattern(r:getPattern(), r:getInitiator(), c)
        end,
        can_select_card = function(self, r, c)
            return r:getSelectedCardIds():isEmpty() and r:getInitiator():getHandcards():contains(c)
                and (red and c:isRed() or not red and c:isBlack())
        end,
        card_selection_feasible = function(self, r) return r:getSelectedCardIds():length() == 1 end,
        create_card = function(self, r)
            local old = sgs.Sanguosha:getCard(r:getSelectedCardIds():first())
            local c = sgs.Sanguosha:cloneCard(identity, old:getSuit(), old:getNumber())
            c:addSubcard(old); c:setSkillName(name); return c
        end,
    }
end
hlxg_huoji_zhugeliang2 = c21305_convert("hlxg_huoji_zhugeliang2", "fire_attack", true)
hlxg_kanpo = c21305_convert("hlxg_kanpo", "nullification", false)
hlxg_bazhen = gu_trigger("hlxg_bazhen", {sgs.FinishJudge}, function(self, event, room, p, data, owner)
    local j = data:toJudge()
    if j.who == owner and j.reason == "eight_diagram" and j.card and j.card:isBlack() then owner:drawCards(1, self:objectName()) end
end, true)
hlxg_kanpo_unanswerable = sgs.CreateRuleSkillV2 {
    name = "#hlxg_kanpo_unanswerable", global = true, events = {sgs.TrickCardCanceling},
    can_trigger = function(self, event, room, p, data)
        local e = data:toCardEffect()
        return e.from and e.from:hasSkill("hlxg_kanpo") and e.card and e.card:isKindOf("Nullification") and self:objectName() or false
    end,
    on_effect = function() return true end,
}
hlxg_huoji_zhugeliang2_effect = sgs.CreateRuleSkillV2 {
    name = "#hlxg_huoji_zhugeliang2_effect", global = true, events = {sgs.CardEffected}, priority = 0,
    can_trigger = function(self, event, room, p, data)
        local e = data:toCardEffect()
        return e.from and e.from:hasSkill("hlxg_huoji_zhugeliang2") and e.card:isKindOf("FireAttack") and self:objectName() or false
    end,
    on_effect = function(self, event, room, p, ctx)
        local e = ctx.original_data:toCardEffect()
        if e.nullified then return true end
        if not e.offset_card then e.offset_card = room:isCanceled(e); ctx.original_data:setValue(e) end
        if e.offset_card and not room:getThread():trigger(sgs.CardOffset, room, e.from, ctx.original_data) then return true end
        room:getThread():trigger(sgs.CardOnEffect, room, e.to, ctx.original_data)
        e = ctx.original_data:toCardEffect()
        for iteration = 0, e.extra_effect do
        if not e.to:isAlive() or e.to:isKongcheng() then break end
        local shown = room:askForCardShow(e.to, e.from, "fire_attack"); room:showCard(e.to, shown:getEffectiveId())
        local paid = false
        if e.from:isAlive() and gu_invoke(e.from, "hlxg_huoji_zhugeliang2", ctx.original_data) then
            local ids = room:getNCards(4, false)
            local disabled = sgs.IntList()
            for _, id in sgs.qlist(ids) do if sgs.Sanguosha:getCard(id):getSuit() ~= shown:getSuit() then disabled:append(id) end end
            e.from:setTag("hlxg_huoji_zhugeliang2_suit", sgs.QVariant(shown:getSuit()))
            room:fillAG(ids, e.from, disabled)
            local id = room:askForAG(e.from, ids, true, "hlxg_huoji_zhugeliang2")
            room:clearAG(e.from)
            e.from:removeTag("hlxg_huoji_zhugeliang2_suit")
            if id >= 0 and ids:contains(id) and not disabled:contains(id) then
                ids:removeOne(id); local cost = sgs.IntList(); cost:append(id); gu_throw(room, e.from, cost, "hlxg_huoji_zhugeliang2"); paid = true
            end
            room:returnToTopDrawPile(ids)
        end
        if not paid and e.from:isAlive() then
            paid = room:askForCard(e.from, ".|" .. shown:getSuitString() .. "|.|hand", "@hlxg_huoji_zhugeliang2-discard:" .. e.to:objectName(), ctx.original_data) ~= nil
        end
        if paid and e.from:isAlive() then
            local d = sgs.DamageStruct(); d.card = e.card; d.from = e.from; d.to = e.to; d.damage = 1; d.nature = sgs.DamageStruct_Fire; room:damage(d)
        end
        end
        return true
    end,
}
extension_hl:addSkills(hlxg_huoji_zhugeliang2_effect)
local function c21305_exchange(room, p)
    local pile = p:getPile("hlxg_qixing_stars")
    if pile:isEmpty() or p:isKongcheng() then return end
    local hand = room:askForExchange(p, "hlxg_qixing", math.min(p:getHandcardNum(), pile:length()), 1, false, "@hlxg_qixing-exchange", true)
    if not hand then return end
    local chosen = sgs.IntList()
    for i = 1, hand:subcardsLength() do
        room:fillAG(pile, p)
        local id = room:askForAG(p, pile, false, "hlxg_qixing")
        room:clearAG(p)
        if not pile:contains(id) then id = pile:first() end
        chosen:append(id); pile:removeOne(id)
    end
    p:addToPile("hlxg_qixing_stars", hand:getSubcards(), false)
    gu_obtain(room, p, chosen, "hlxg_qixing")
end
hlxg_qixing = gu_trigger("hlxg_qixing", {sgs.GameStart, sgs.EventPhaseEnd}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.GameStart then
        owner:addToPile("hlxg_qixing_stars", room:getNCards(7, false), false)
        c21305_exchange(room, owner)
    elseif p:getPhase() == sgs.Player_Draw then c21305_exchange(room, owner) end
end, true)
hlxg_dawu = gu_trigger("hlxg_dawu", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p == owner and p:getPhase() == sgs.Player_Finish and not owner:getPile("hlxg_qixing_stars"):isEmpty() and gu_invoke(owner, self:objectName(), data) then
        local ids = owner:getPile("hlxg_qixing_stars")
        room:fillAG(ids, owner); local id = room:askForAG(owner, ids, false, self:objectName()); room:clearAG(owner)
        if ids:contains(id) then local cost = sgs.IntList(); cost:append(id); gu_throw(room, owner, cost, self:objectName()); room:setPlayerMark(owner, "&hlxg_dawu", 1) end
    end
end)
hlxg_dawu_effect = sgs.CreateRuleSkillV2 {
    name = "#hlxg_dawu_effect", global = true, events = {sgs.EventPhaseStart, sgs.DamageInflicted},
    can_trigger = function(self, event, room, p, data)
        if not p or p:getMark("&hlxg_dawu") == 0 then return false end
        if event == sgs.EventPhaseStart then return p:getPhase() == sgs.Player_RoundStart and self:objectName() or false end
        return data:toDamage().nature == sgs.DamageStruct_Normal and self:objectName() or false
    end,
    on_effect = function(self, event, room, p, ctx)
        if event == sgs.EventPhaseStart then room:setPlayerMark(p, "&hlxg_dawu", 0); return false end
        local d = ctx.original_data:toDamage(); d.damage = d.damage - 1; ctx.original_data:setValue(d); return d.damage <= 0
    end,
}
