hlxg_kuangfengCard = sgs.CreateSkillCard {
    name = "hlxg_kuangfengCard", will_throw = false,
    filter = function(self, targets, to, from) return to ~= from and #targets < self:subcardsLength() end,
    feasible = function(self, targets) return #targets == self:subcardsLength() and #targets > 0 end,
