local function c21305_basic(r)
    for _, name in ipairs(r:getPattern():split("+")) do
        local c = sgs.Sanguosha:cloneCard(name)
        if c then
            c:deleteLater()
            if c:isKindOf("BasicCard") then return c end
        end
    end
    for _, name in ipairs({"slash", "jink", "peach", "analeptic", "fire_slash", "thunder_slash"}) do
        local c = sgs.Sanguosha:cloneCard(name); c:deleteLater()
        if sgs.Sanguosha:matchExpPattern(r:getPattern(), r:getInitiator(), c) then return c end
    end
end
hlxg_aocai = sgs.CreateViewAsSkillV2 {
    name = "hlxg_aocai", n = 0, response_or_use = true,
    can_select_target = function(self, r, selected, to) return c21305_targets(c21305_basic(r), r, selected, to) end,
    targets_feasible = function(self, r, selected) return c21305_targets(c21305_basic(r), r, selected) end,
    can_activate = function(self, r)
        return r:getInitiator():getPhase() == sgs.Player_NotActive and r:getReason() ~= sgs.CardUseStruct_CARD_USE_REASON_PLAY and c21305_basic(r) ~= nil
    end,
    card_selection_feasible = function(self, r) return r:getSelectedCardIds():isEmpty() end,
    create_card = function(self, r) local c = c21305_basic(r); if c then c:setSkillName(self:objectName()) end; return c end,
    cost = function(self, room, ctx, r)
        local p = r:getInitiator()
        local ids = room:getNCards(p:isKongcheng() and 4 or 3, false)
        local disabled, enabled = sgs.IntList(), sgs.IntList()
        local method = r:getReason() == sgs.CardUseStruct_CARD_USE_REASON_RESPONSE and sgs.Card_MethodResponse or sgs.Card_MethodUse
        for _, id in sgs.qlist(ids) do
            local c = sgs.Sanguosha:getCard(id)
            if c:isKindOf("BasicCard") and sgs.Sanguosha:matchExpPattern(r:getPattern(), p, c)
                and not p:isCardLimited(c, method) and not (c:isKindOf("Peach") and p:hasFlag("Global_PreventPeach")) then enabled:append(id) else disabled:append(id) end
        end
        room:fillAG(ids, p, disabled)
        local id = room:askForAG(p, enabled, true, self:objectName())
        room:clearAG(p); room:returnToTopDrawPile(ids)
        if not enabled:contains(id) then return false end
        local old = sgs.Sanguosha:getCard(id)
        local c = sgs.Sanguosha:cloneCard(old:objectName(), old:getSuit(), old:getNumber())
        c:addSubcard(id); c:setSkillName(self:objectName()); c:deleteLater(); ctx.updated_card = c
        return true
    end,
}
