hlxg_hongyuan = gu_trigger("hlxg_hongyuan", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Draw then return end
    local targets = room:askForPlayersChosen(owner, room:getAlivePlayers(), self:objectName(), 0, 2, "@hlxg_hongyuan", true)
    room:sortByActionOrder(targets)
    for _, to in sgs.qlist(targets) do
        if to:isAlive() then to:drawCards(1, self:objectName()) end
    end
end)
hlxg_mingzhe = gu_trigger("hlxg_mingzhe", {sgs.CardUsed, sgs.CardResponded, sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    if owner:getPhase() ~= sgs.Player_NotActive then return end
    local count = 0
    if event == sgs.CardsMoveOneTime then
        local move = data:toMoveOneTime()
        if move.from ~= owner or bit32.band(move.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON) ~= sgs.CardMoveReason_S_REASON_DISCARD then return end
        for i, id in sgs.qlist(move.card_ids) do
            local place = move.from_places:at(i)
            if (place == sgs.Player_PlaceHand or place == sgs.Player_PlaceEquip) and sgs.Sanguosha:getCard(id):isRed() then count = count + 1 end
        end
    elseif p == owner then
        local card
        if event == sgs.CardUsed then card = data:toCardUse().card else card = data:toCardResponse().m_card end
        if card and card:isRed() then count = 1 end
    end
    for i = 1, count do
        if owner:isAlive() and gu_invoke(owner, self:objectName(), data) then owner:drawCards(1, self:objectName()) end
    end
end, false, sgs.Skill_Frequent)
hlxg_huanshi = gu_trigger("hlxg_huanshi", {sgs.AskForRetrial}, function(self, event, room, p, data, owner)
    if owner:isNude() then return end
    local ids, disabled = sgs.IntList(), sgs.IntList()
    for _, card in sgs.qlist(owner:getCards("he")) do
        if owner:isCardLimited(card, sgs.Card_MethodResponse) then disabled:append(card:getEffectiveId())
        else ids:append(card:getEffectiveId()) end
    end
    if ids:isEmpty() or not gu_invoke(owner, self:objectName(), data) then return end
    local judge = data:toJudge()
    room:showAllCards(owner, judge.who)
    local all = sgs.IntList()
    for _, id in sgs.qlist(ids) do all:append(id) end
    for _, id in sgs.qlist(disabled) do all:append(id) end
    judge.who:setTag("HuanshiJudge", data)
    room:fillAG(all, judge.who, disabled)
    local id = room:askForAG(judge.who, ids, false, self:objectName())
    room:clearAG(judge.who)
    judge.who:removeTag("HuanshiJudge")
    if ids:contains(id) then room:retrial(sgs.Sanguosha:getCard(id), owner, judge, self:objectName()) end
end)
