hlxg_fuyin = gu_trigger("hlxg_fuyin", {sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or not use.to:contains(owner) or not use.from or not use.card
        or not (use.card:isKindOf("Slash") or use.card:isKindOf("Duel")) then return end
    if owner:getMark("hlxg_fuyin-Clear") > 0 then return end
    room:setPlayerMark(owner, "hlxg_fuyin-Clear", 1)
    if owner:getHandcardNum() <= use.from:getHandcardNum() then
        room:sendCompulsoryTriggerLog(owner, self:objectName())
        local nullified = use.nullified_list
        table.insert(nullified, owner:objectName()); use.nullified_list = nullified
        data:setValue(use)
    end
end, true)
hlxg_zuilun_record = gu_record("#hlxg_zuilun_record", {sgs.Damage, sgs.CardsMoveOneTime}, function(self, event, room, p, data)
    if event == sgs.Damage then
        local damage = data:toDamage()
        if damage.from and damage.damage > 0 then room:setPlayerMark(damage.from, "hlxg_zuilun_damage-Clear", 1) end
    else
        local move = data:toMoveOneTime()
        if move.from and bit32.band(move.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON) == sgs.CardMoveReason_S_REASON_DISCARD then
            local from = room:findPlayerByObjectName(move.from:objectName())
            if from then room:setPlayerMark(from, "hlxg_zuilun_discard-Clear", 1) end
        end
    end
end)
