hlxg_zuilun = gu_trigger("hlxg_zuilun", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Finish or not gu_invoke(owner, self:objectName()) then return end
    local n = owner:getMark("hlxg_zuilun_damage-Clear") > 0 and 1 or 0
    if owner:getMark("hlxg_zuilun_discard-Clear") == 0 then n = n + 1 end
    local fewest = true
    for _, other in sgs.qlist(room:getAlivePlayers()) do
        if other:getHandcardNum() < owner:getHandcardNum() then fewest = false; break end
    end
    if fewest then n = n + 1 end
    local ids, kept = room:getNCards(4), sgs.IntList()
    for i = 1, math.min(n, ids:length()) do
        room:fillAG(ids, owner)
        local id = room:askForAG(owner, ids, false, self:objectName())
        room:clearAG(owner)
        ids:removeOne(id); kept:append(id)
    end
    room:askForGuanxing(owner, ids, sgs.Room_GuanxingUpOnly)
    gu_obtain(room, owner, kept, self:objectName())
    if n == 0 then
        local others = room:getOtherPlayers(owner)
        local to
        if not others:isEmpty() then to = room:askForPlayerChosen(owner, others, self:objectName(), "@hlxg_zuilun-lose", false) end
        room:loseHp(owner, 1, true, owner, self:objectName())
        if to and to:isAlive() then room:loseHp(to, 1, true, owner, self:objectName()) end
    end
end)
