hlxg_nuanhui_use = sgs.CreateViewAsSkillV2 {
    name = "#hlxg_nuanhui_use",
    can_activate = function(self, request) return request:getPattern() == "@@#hlxg_nuanhui_use" end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function(self, request)
        local name = request:getInitiator():property("hlxg_nuanhui_card"):toString()
        local c = sgs.Sanguosha:cloneCard(name, sgs.Card_NoSuit, 0)
        if c then c:setSkillName("hlxg_nuanhui") end
        return c
    end,
}
hlxg_nuanhui = gu_trigger("hlxg_nuanhui", {sgs.EventPhaseStart}, function(self, event, room, actor, data, p)
    if actor ~= p or p:getPhase() ~= sgs.Player_Finish then return end
    local to = room:askForPlayerChosen(p, room:getAlivePlayers(), self:objectName(), "@hlxg_nuanhui-target", true, true)
    if not to then return end
    local n = math.max(1, to:getEquips():length())
    local seen, repeated = {}, false
    for i = 1, n do
        if to:isDead() then break end
        local choices = {}
        for _, name in ipairs(sgs.Sanguosha:getCardNames()) do
            local c = sgs.Sanguosha:cloneCard(name, sgs.Card_NoSuit, 0)
            if c then
                c:setSkillName(self:objectName())
                if c:isKindOf("BasicCard") and c:isAvailable(to) then table.insert(choices, name) end
                c:deleteLater()
            end
        end
        if #choices == 0 then break end
        local name = room:askForChoice(to, self:objectName(), table.concat(choices, "+") .. "+cancel")
        if name == "cancel" then break end
        room:setPlayerProperty(to, "hlxg_nuanhui_card", sgs.QVariant(name))
        local c = room:askForUseCardWithBorrowedSkill(to, "#hlxg_nuanhui_use", "hlxg_nuanhui", "@hlxg_nuanhui-use:" .. name, -1, sgs.Card_MethodUse, false)
        room:setPlayerProperty(to, "hlxg_nuanhui_card", sgs.QVariant(""))
        if not c then break end
        local used = c:objectName()
        if seen[used] then repeated = true end
        seen[used] = true
    end
    if repeated and to:isAlive() then to:throwAllEquips(self:objectName()) end
end)
hlxg_qiongyingCard = sgs.CreateSkillCard {
    name = "hlxg_qiongyingCard", target_fixed = true,
