    can_activate = function(self, request)
        local room = sgs.Sanguosha:currentRoom()
        if not room then return false end
        return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY and room:canMoveField("ej")
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function() local c = hlxg_qiongyingCard:clone(); c:setSkillName("hlxg_qiongying"); return c end,
}
hlxg_juyi = gu_trigger("hlxg_juyi", {sgs.EventPhaseStart}, function(self, event, room, actor, data, p)
    if actor ~= p or p:getPhase() ~= sgs.Player_Start or p:getMark("@hlxg_juyi") == 0
        or p:getMaxHp() <= room:getAlivePlayers():length() then return end
    if not gu_invoke(p, self:objectName()) then return end
    room:removePlayerMark(p, "@hlxg_juyi")
    local n = p:getMaxHp() - p:getHandcardNum()
    if n > 0 then room:drawCards(p, n, self:objectName()) end
    if p:isAlive() then room:handleAcquireDetachSkills(p, "hlxg_benghuai_zhugedan|hlxg_weizhong") end
end, false, sgs.Skill_Limited, "@hlxg_juyi")
hlxg_gongao = gu_trigger("hlxg_gongao", {sgs.EnterDying}, function(self, event, room, actor, data, p)
    local dying = data:toDying()
    if not dying.who or dying.who == p then return end
    room:gainMaxHp(p, 1, self:objectName())
    if p:isAlive() then room:recover(p, sgs.RecoverStruct(self:objectName(), p)) end
end, true)
hlxg_weizhong = gu_trigger("hlxg_weizhong", {sgs.MaxHpChanged}, function(self, event, room, actor, data, p)
    if actor == p then room:drawCards(p, 2, self:objectName()) end
end, true)
hlxg_benghuai_zhugedan = gu_trigger("hlxg_benghuai_zhugedan", {sgs.EventPhaseStart}, function(self, event, room, actor, data, p)
    if actor ~= p or p:getPhase() ~= sgs.Player_Finish then return end
    local smaller = false
    for _, to in sgs.qlist(room:getAlivePlayers()) do if to:getHp() < p:getHp() then smaller = true; break end end
    if not smaller then return end
    local choice = room:askForChoice(p, self:objectName(), "losehp+losemaxhp")
    if choice == "losehp" then room:loseHp(p, 1, true, p, self:objectName()) else room:loseMaxHp(p, 1, self:objectName()) end
    if p:isAlive() then room:drawCards(p, 1, self:objectName()) end
end, true)
