hlxg_huoxin = gu_active("hlxg_huoxin", 1, 1, 1,
    function(self, targets, to, from)
        if #targets >= 2 or to:isKongcheng() then return false end
        return #targets == 0 or targets[1]:canPindian(to)
    end,
    function(self, targets) return #targets == 2 end,
    function(self, room, source, targets)
        gu_throw(room, source, self:getSubcards(), "hlxg_huoxin")
        local first, second = targets[1], targets[2]
        if first:isDead() or second:isDead() or not first:canPindian(second) then return end
        local won = first:pindian(second, "hlxg_huoxin", nil)
        if won then first = second end
        if first:isDead() or source:isDead() then return end
        local suits = {}
        for _, suit in ipairs({"spade", "club", "heart", "diamond"}) do
            if first:getMark("&hlxg_huoxin_" .. suit .. "-Clear") == 0 then table.insert(suits, suit) end
        end
        if #suits == 0 or not gu_invoke(source, "hlxg_huoxin", sgs.QVariant(first)) then return end
        local suit = room:askForChoice(source, "hlxg_huoxin_suit", table.concat(suits, "+"))
        -- The suit is private: do not place it in a public mark or the recipient's prompt.
        local choice = room:askForChoice(first, "hlxg_huoxin", "give+charm", sgs.QVariant(source))
        if choice == "give" then
            local ids = c214_suit_cards(first, suit)
            if not ids:isEmpty() then
                local give = gu_dummy(ids); room:giveCard(first, source, give, "hlxg_huoxin", false); give:deleteLater()
            end
        else
            room:addPlayerMark(first, "&hlxg_huoxin_" .. suit .. "-Clear")
        end
    end,
    function(request, c) return not request:getInitiator():isJilei(c) end)
hlxg_huoxin_limit = sgs.CreateCardLimitSkill {
    name = "#hlxg_huoxin_limit",
    limit_list = function(self, p) return "use,response" end,
    limit_pattern = function(self, p)
        local suits = {}
        for _, suit in ipairs({"spade", "club", "heart", "diamond"}) do
            if p:getMark("&hlxg_huoxin_" .. suit .. "-Clear") > 0 then table.insert(suits, suit) end
        end
        return #suits > 0 and ".|" .. table.concat(suits, "+") or ""
    end,
}
hlxg_meihun_record = gu_record("#hlxg_meihun_record", {sgs.TargetConfirmed}, function(self, event, room, p, data)
    if not p then return end
    local use = data:toCardUse()
    if use.card and use.card:isKindOf("Slash") and use.to:contains(p) then
        room:addPlayerMark(p, "hlxg_meihun_slash-Clear")
    end
end)
hlxg_meihun = gu_trigger("hlxg_meihun", {sgs.EventPhaseStart, sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.EventPhaseStart then
        if p:getPhase() ~= sgs.Player_Finish then return end
    else
        local use = data:toCardUse()
        if not use.card or not use.card:isKindOf("Slash") or not use.to:contains(owner)
            or owner:getMark("hlxg_meihun_slash-Clear") ~= 1 then return end
    end
    if room:getOtherPlayers(owner):isEmpty() or not gu_invoke(owner, self:objectName()) then return end
    local suit = room:askForChoice(owner, "hlxg_meihun_suit", "spade+club+heart+diamond")
    local to = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@hlxg_meihun", false, true)
    if not to then return end
    local ids = c214_suit_cards(to, suit)
    if not ids:isEmpty() then
        local give = gu_dummy(ids); room:giveCard(to, owner, give, self:objectName(), false); give:deleteLater()
    elseif not to:isKongcheng() then
        room:showAllCards(to, owner)
        local id = room:askForCardChosen(owner, to, "h", self:objectName(), false, sgs.Card_MethodNone)
        room:obtainCard(owner, id, false)
    end
end)
