-- ==================== c214_02
do
-- c214_02: L2443 is skipped: no physical-card-free equipment use in this engine.
local function c214_02_candidates(room, p, zone)
    local list = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getOtherPlayers(p)) do
        if p:canDiscard(q, zone) then list:append(q) end
    end
    return list
end

hlxg_qixi_heqi = gu_trigger("hlxg_qixi_heqi", {sgs.EventPhaseStart}, function(self, event, room, player, data, p)
    if player ~= p or p:getPhase() ~= sgs.Player_Play then return end
    local list = c214_02_candidates(room, p, "hej")
    if list:isEmpty() then return end
    local q = room:askForPlayerChosen(p, list, self:objectName(), "@hlxg_qixi_heqi", true, true)
    if q then
        local id = room:askForCardChosen(p, q, "hej", self:objectName(), false, sgs.Card_MethodDiscard)
        room:throwCard(sgs.Sanguosha:getCard(id), self:objectName(), q, p)
    end
end)

hlxg_xuanfeng = gu_trigger("hlxg_xuanfeng", {sgs.CardsMoveOneTime, sgs.EventPhaseEnd}, function(self, event, room, player, data, p)
    local fire = false
    if event == sgs.CardsMoveOneTime then
        local move = data:toMoveOneTime()
        fire = move.from and move.from:objectName() == p:objectName() and move.from_places:contains(sgs.Player_PlaceEquip)
    else
        fire = player == p and p:getPhase() == sgs.Player_Discard and p:getMark("hlxg_xuanfeng_discard-PlayClear") >= 2
    end
    if not fire or room:getCurrentDyingPlayer() then return end
    local list = c214_02_candidates(room, p, "he")
    local count = 0
    for _, q in sgs.qlist(list) do
        for _, c in sgs.qlist(q:getCards("he")) do if p:canDiscard(q, c:getEffectiveId()) then count = count + 1 end end
    end
    if count < 2 then return end
    local q = room:askForPlayerChosen(p, list, self:objectName(), "@hlxg_xuanfeng", true, true)
    if not q then return end
    local victims = sgs.SPlayerList()
    for i = 1, 2 do
        if not p:isAlive() then break end
        if i == 2 then
            list = c214_02_candidates(room, p, "he")
            if list:isEmpty() then break end
            q = room:askForPlayerChosen(p, list, self:objectName(), "@hlxg_xuanfeng-second", false)
        end
        if not victims:contains(q) then victims:append(q) end
        local id = room:askForCardChosen(p, q, "he", self:objectName(), false, sgs.Card_MethodDiscard)
        room:throwCard(sgs.Sanguosha:getCard(id), self:objectName(), q, p)
    end
    local alive = sgs.SPlayerList()
    for _, v in sgs.qlist(victims) do if v:isAlive() then alive:append(v) end end
    if p:isAlive() and room:getCurrent() == p and p:getPhase() ~= sgs.Player_NotActive and not alive:isEmpty() then
        local v = room:askForPlayerChosen(p, alive, self:objectName(), "@hlxg_xuanfeng-damage", true)
        if v then local d = sgs.DamageStruct(); d.from = p; d.to = v; d.damage = 1; d.reason = self:objectName(); room:damage(d) end
    end
end)

-- Record every Slash target, even before 短兵 is acquired in the same turn.
hlxg_duanbing_heqi = gu_trigger("hlxg_duanbing_heqi", {sgs.TargetSpecified}, function(self, event, room, player, data, p)
    local use = data:toCardUse()
    if use.from ~= p or not use.card:isKindOf("Slash") then return end
    local key = "Jink_" .. use.card:toString()
    local old, new = p:getTag(key):toIntList(), sgs.IntList()
    for i = 0, use.to:length() - 1 do
        local q = use.to:at(i)
        local n = i < old:length() and old:at(i) or 1
        if p:distanceTo(q) == 1 and use.card:hasFlag("hlxg_duanbing_heqi_first_" .. q:objectName()) and n == 1 then n = 2 end
        new:append(n)
    end
    local v = sgs.QVariant(); v:setValue(new); p:setTag(key, v)
end)
hlxg_duanbing_heqi_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_duanbing_heqi_mod", pattern = "Slash", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local p, q = ctx:getPrimary(), ctx:getSecondary()
        if ctx:getModType() == sgs.TargetModSkill_ExtraTarget and p and q and p:hasSkill("hlxg_duanbing_heqi") and p:distanceTo(q) == 1 then return 1 end
        return false
    end,
}
hlxg_yingzi_heqi = gu_trigger("hlxg_yingzi_heqi", {sgs.DrawNCards}, function(self, event, room, player, data, p)
    local draw = data:toDraw()
    if player == p and draw.reason == "draw_phase" then draw.num = draw.num + 1; data:setValue(draw) end
end, true)
hlxg_yingzi_heqi_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_yingzi_heqi_max", holder_selector = sgs.CorrectSkill_System,
    fixed_func = function(self, ctx)
        local p = ctx:getPrimary()
        if p and p:hasSkill("hlxg_yingzi_heqi") then return p:getMaxHp() end
        return nil
    end,
}
local c214_02_grants = {"hlxg_yingzi_heqi", "hlxg_qixi_heqi", "hlxg_xuanfeng", "hlxg_duanbing_heqi"}
local function c214_02_qizhou(room, p)
    if not p or p:hasFlag("hlxg_qizhou_updating") then return end
    local suits, count = {}, 0
    if p:hasSkill("hlxg_qizhou") then
        for _, c in sgs.qlist(p:getEquips()) do
            local suit = c:getSuit()
            if suit >= sgs.Card_Spade and suit <= sgs.Card_Diamond and not suits[suit] then suits[suit] = true; count = count + 1 end
        end
    end
    room:setPlayerFlag(p, "hlxg_qizhou_updating")
    for i, name in ipairs(c214_02_grants) do
        local mark = "hlxg_qizhou_granted_" .. name
        if count >= i then
            if not p:hasSkill(name) then room:setPlayerMark(p, mark, 1); room:acquireSkill(p, name) end
        elseif p:getMark(mark) > 0 then
            room:setPlayerMark(p, mark, 0); room:detachSkillFromPlayer(p, name, false, true)
        end
    end
    room:setPlayerFlag(p, "-hlxg_qizhou_updating")
end
-- Resolve suit grants after equipment-loss triggers have used the previous grants.
hlxg_qizhou = sgs.CreateRuleSkillV2 {
    name = "hlxg_qizhou", global = true, frequency = sgs.Skill_Compulsory,
    priority = -5, events = {sgs.GameStart, sgs.CardsMoveOneTime},
    can_trigger = function(self, event, room, player, data)
        for _, p in sgs.qlist(room:getAlivePlayers()) do if p:hasSkill(self:objectName()) then return self:objectName(), p end end
        return false
    end,
    on_effect = function(self, event, room, player, ctx)
        for _, p in sgs.qlist(room:getAlivePlayers()) do if p:hasSkill(self:objectName()) then c214_02_qizhou(room, p) end end
        return false
    end,
}
hlxg_qizhou_record = gu_record("#hlxg_qizhou_record", {sgs.EventAcquireSkill, sgs.EventLoseSkill, sgs.CardsMoveOneTime, sgs.EventPhaseChanging, sgs.TargetSpecified, sgs.CardFinished}, function(self, event, room, player, data)
    if event == sgs.EventAcquireSkill or event == sgs.EventLoseSkill then
        if data:toString() == "hlxg_qizhou" then c214_02_qizhou(room, player) end
    elseif event == sgs.CardsMoveOneTime then
        local m = data:toMoveOneTime()
        if m.from and m.from:getPhase() == sgs.Player_Discard and bit32.band(m.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON) == sgs.CardMoveReason_S_REASON_DISCARD then
            local p = room:findPlayerByObjectName(m.from:objectName())
            if p then room:addPlayerMark(p, "hlxg_xuanfeng_discard-PlayClear", m.card_ids:length()) end
        end
    elseif event == sgs.TargetSpecified or event == sgs.CardFinished then
        local use = data:toCardUse()
        if use.from and use.card:isKindOf("Slash") then
            for _, q in sgs.qlist(use.to) do
                local mark = "hlxg_duanbing_heqi_seen_" .. q:objectName() .. "-Clear"
                local flag = "hlxg_duanbing_heqi_first_" .. q:objectName()
                if event == sgs.TargetSpecified then
                    room:setCardFlag(use.card, use.from:getMark(mark) == 0 and flag or "-" .. flag)
                    room:setPlayerMark(use.from, mark, 1)
                else room:setCardFlag(use.card, "-" .. flag) end
            end
        end
    elseif player then
        local change = data:toPhaseChange()
        if change.to == sgs.Player_Discard or change.from == sgs.Player_Discard then room:setPlayerMark(player, "hlxg_xuanfeng_discard-PlayClear", 0) end
    end
end)

hlxg_shanxi = gu_active("hlxg_shanxi", 1, 0, 0,
    function(self, targets, to, from) return #targets == 0 and to ~= from and not to:inMyAttackRange(from) end,
    gu_one_feasible,
    function(self, room, p, targets)
        local q = targets[1]
        local maximum = 1
        for i = 0, 4 do if p:hasEquipArea(i) and not p:getEquip(i) then maximum = maximum + 1 end end
        local shown, owners = sgs.IntList(), {}
        for i = 1, maximum do
            local choices = {"finish"}
            local mine, theirs = false, false
            for _, id in sgs.qlist(p:handCards()) do if not shown:contains(id) then mine = true end end
            for _, id in sgs.qlist(q:handCards()) do if not shown:contains(id) then theirs = true end end
            if mine then table.insert(choices, "self") end
            if theirs then table.insert(choices, "other") end
            if #choices == 1 then break end
            local choice = room:askForChoice(p, "hlxg_shanxi", table.concat(choices, "+"), sgs.QVariant(q:objectName()))
            if choice == "finish" then break end
            local who = choice == "self" and p or q
            local id = room:askForCardChosen(p, who, "h", "hlxg_shanxi", false, sgs.Card_MethodNone, shown)
            shown:append(id); owners[id] = who
        end
        for _, id in sgs.qlist(shown) do room:showCard(owners[id], id) end
        local discarded = false
        for _, id in sgs.qlist(shown) do
            local who = owners[id]
            if sgs.Sanguosha:getCard(id):isKindOf("Jink") and room:getCardOwner(id) == who and room:getCardPlace(id) == sgs.Player_PlaceHand then
                room:throwCard(sgs.Sanguosha:getCard(id), "hlxg_shanxi", who, p); discarded = true
            end
        end
        if discarded and p:isAlive() and q:isAlive() then
            local available = false
            for _, c in sgs.qlist(q:getCards("hej")) do if not shown:contains(c:getEffectiveId()) then available = true end end
            if available then
                local id = room:askForCardChosen(p, q, "hej", "hlxg_shanxi", false, sgs.Card_MethodNone, shown)
                room:obtainCard(p, id, false)
            end
        end
    end)
