hlxg_luanwuCard = sgs.CreateSkillCard {
    name = "hlxg_luanwuCard", target_fixed = true,
    on_use = function(self, room, p, targets)
        room:removePlayerMark(p, "@hlxg_luanwu")
        for _, q in sgs.qlist(room:getOtherPlayers(p)) do
            if q:isAlive() then
                local nearest, list = 10000, sgs.SPlayerList()
                for _, v in sgs.qlist(room:getOtherPlayers(q)) do nearest = math.min(nearest, q:distanceTo(v)) end
                for _, v in sgs.qlist(room:getOtherPlayers(q)) do
                    if q:distanceTo(v) == nearest and q:canSlash(v, nil, false) then list:append(v) end
                end
                if list:isEmpty() or not room:askForUseSlashTo(q, list, "@hlxg_luanwu-slash", true, true, false) then room:loseHp(q, 1, true, p, "hlxg_luanwu") end
            end
        end
    end,
}
