-- c214_03: literal Huanle variants; helpers from offline.lua are in scope.
local function c214_active(name, limited, n, filter, feasible, effect, activate)
    _G[name .. "Card"] = sgs.CreateSkillCard {
        name = name .. "Card", will_throw = false,
        filter = filter, feasible = feasible, on_use = effect,
    }
    return sgs.CreateViewAsSkillV2 {
        name = name, n = n,
        frequency = limited and sgs.Skill_Limited or sgs.Skill_NotFrequent,
        limit_mark = limited and ("@" .. name) or nil,
        can_activate = function(self, request)
            local p = request:getInitiator()
            return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
                and (not limited or p:getMark("@" .. name) > 0)
                and (not activate or activate(p))
        end,
        can_select_card = function(self, request, c)
            return request:getSelectedCardIds():length() < n and not c:isEquipped()
        end,
        card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == n end,
        create_card = function(self, request)
            local card = _G[name .. "Card"]:clone()
            card:addSubcards(request:getSelectedCardIds()); card:setSkillName(name)
            return card
        end,
    }
end

hljx_jiaxu = sgs.General(extension_hl, "hljx_jiaxu", "qun", 3)
hljx_luanwu = c214_active("hljx_luanwu", true, 0,
    function() return false end, function(self, targets) return #targets == 0 end,
    function(self, room, source, targets)
        room:removePlayerMark(source, "@hljx_luanwu")
        local others = room:getOtherPlayers(source)
        room:sortByActionOrder(others)
        for _, p in sgs.qlist(others) do
            if p:isAlive() then
                local nearest, candidates = math.huge, sgs.SPlayerList()
                for _, q in sgs.qlist(room:getOtherPlayers(p)) do nearest = math.min(nearest, p:distanceTo(q)) end
                for _, q in sgs.qlist(room:getOtherPlayers(p)) do
                    if p:distanceTo(q) == nearest and p:canSlash(q, nil, true) then candidates:append(q) end
                end
                if candidates:isEmpty() or not room:askForUseSlashTo(p, candidates, "@hljx_luanwu-slash", true, true, false) then
                    room:loseHp(p, 1, true, source, "hljx_luanwu")
                end
            end
        end
        if source:isAlive() then room:askForUseCard(source, "@@hljx_luanwu_slash", "@hljx_luanwu-extra") end
    end)
hljx_luanwu_slash = sgs.CreateViewAsSkillV2 {
    name = "#hljx_luanwu_slash",
    can_activate = function(self, request) return request:getPattern() == "@@hljx_luanwu_slash" end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function(self, request)
        local c = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0)
        c:setSkillName("hljx_luanwu"); c:setFlags("hljx_luanwu_extra"); return c
    end,
}
hljx_luanwu_mod = sgs.CreateTargetModSkillV2 {
    name = "#hljx_luanwu_mod", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local c = ctx:getCard()
        if c and c:hasFlag("hljx_luanwu_extra") and ctx:getModType() == sgs.TargetModSkill_DistanceLimit then return 1000 end
        return false
    end,
}
hljx_wansha = gu_trigger("hljx_wansha", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Play then return end
    local candidates = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getAlivePlayers()) do if q:getHp() > 1 then candidates:append(q) end end
    if candidates:isEmpty() then return end
    local q = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hljx_wansha", true, true)
    if q then
        local pending = gu_names(owner, "hljx_wansha_pending")
        table.insert(pending, q:objectName()); gu_setnames(owner, "hljx_wansha_pending", pending)
        room:loseHp(q, 1, true, owner, self:objectName())
    end
end, true)
hljx_wansha_recover = gu_record("#hljx_wansha_recover", {sgs.EventPhaseEnd, sgs.EventPhaseChanging},
    function(self, event, room, p, data)
        if not p then return end
        if event == sgs.EventPhaseEnd then
            if p:getPhase() ~= sgs.Player_Play then return end
        elseif data:toPhaseChange().from ~= sgs.Player_Play then return end
        local pending = gu_names(p, "hljx_wansha_pending")
        p:removeTag("hljx_wansha_pending")
        for _, name in ipairs(pending) do
            local q = room:findPlayerByObjectName(name)
            if q and q:isAlive() then local r = sgs.RecoverStruct(); r.who = p; room:recover(q, r) end
        end
    end)
hljx_wansha_limit = sgs.CreateCardLimitSkill {
    name = "#hljx_wansha_limit",
    limit_list = function() return "use" end,
    limit_pattern = function(self, p)
        local current
        local dying = p:hasFlag("Global_Dying")
        for _, q in sgs.qlist(p:getAliveSiblings(true)) do
            if q:hasFlag("CurrentPlayer") then current = q end
            if q:hasFlag("Global_Dying") then dying = true end
        end
        if dying and current and current ~= p and current:hasSkill("hljx_wansha") then return "Peach" end
        return ""
    end,
}
hljx_weimu = gu_trigger("hljx_weimu", {sgs.DamageInflicted}, function(self, event, room, p, data, owner)
    if p == owner and owner:getPhase() ~= sgs.Player_NotActive then
        owner:drawCards(2 * data:toDamage().damage, self:objectName()); return true
    end
end, true)
hljx_weimu_prohibit = sgs.CreateProhibitSkillV2 {
    name = "#hljx_weimu_prohibit", holder_selector = sgs.CorrectSkill_System,
    is_prohibited = function(self, ctx)
        local q, c = ctx:getTo(), ctx:getCard()
        return q and q:hasSkill("hljx_weimu") and c and c:isBlack() and c:isKindOf("TrickCard")
    end,
}
