hlxg_yongdi = c214_active("hlxg_yongdi", true, 0,
    function(self, targets, to, from) return #targets == 0 end, gu_one_feasible,
    function(self, room, source, targets)
        room:removePlayerMark(source, "@hlxg_yongdi")
        local q = targets[1]
        local maxhp, hp, hand = math.huge, math.huge, math.huge
        for _, p in sgs.qlist(room:getAlivePlayers()) do
            maxhp = math.min(maxhp, p:getMaxHp()); hp = math.min(hp, p:getHp()); hand = math.min(hand, p:getHandcardNum())
        end
        -- Evaluate all three conditions at selection, including ties.
        local a, b, c = q:getMaxHp() == maxhp, q:getHp() == hp, q:getHandcardNum() == hand
        if a then room:setPlayerProperty(q, "maxhp", sgs.QVariant(q:getMaxHp() + 1)) end
        if b and q:isAlive() then local r = sgs.RecoverStruct(); r.who = source; room:recover(q, r) end
        if c and q:isAlive() then q:drawCards(math.min(q:getMaxHp(), 5), "hlxg_yongdi") end
    end)
