hlxg_jianshu = c214_active("hlxg_jianshu", false, 1,
    function(self, targets, to, from) return #targets < 2 and to ~= from end,
    function(self, targets) return #targets == 2 end,
    function(self, room, source, targets)
        room:setPlayerMark(source, "hlxg_jianshu-PlayClear", 1)
        local first, second = targets[1], targets[2]
        gu_obtain(room, first, self:getSubcards(), "hlxg_jianshu")
        if not first:isAlive() or not second:isAlive() or not first:canPindian(second) then return end
        local result = first:pindianInt(second, "hlxg_jianshu")
        if result ~= 1 and result ~= -1 and result ~= 0 then return end
        local winner = result == 1 and first or (result == -1 and second or nil)
        if winner and winner:isAlive() and source:isAlive() and not winner:isNude() then
            local cards = winner:getCards("he")
            local c = cards:at(math.random(0, cards:length() - 1))
            room:obtainCard(source, c, false)
        end
        local death = false
        for _, q in ipairs({first, second}) do
            if q ~= winner and q:isAlive() then
                room:loseHp(q, 1, true, source, "hlxg_jianshu")
                if q:isDead() then death = true end
            end
        end
        if death then room:setPlayerMark(source, "hlxg_jianshu-PlayClear", 0) end
    end, function(p) return p:getMark("hlxg_jianshu-PlayClear") == 0 end)
hlxg_jiaxu2:addSkill(hlxg_yongdi); hlxg_jiaxu2:addSkill(hlxg_zhenlve); hlxg_jiaxu2:addSkill(hlxg_zhenlve_prohibit)
