hlxg_longdan_zhaoyun = sgs.CreateViewAsSkillV2 {
    name = "hlxg_longdan_zhaoyun", n = 1, response_or_use = true,
    can_activate = function(self, request)
        if request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY then return sgs.Slash_IsAvailable(request:getInitiator()) end
        return request:getPattern() == "slash" or request:getPattern() == "jink"
    end,
    can_select_card = function(self, request, c)
        if not request:getSelectedCardIds():isEmpty() then return false end
        local slash = request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY or request:getPattern() == "slash"
        return slash and c:isKindOf("Jink") or (not slash and c:isKindOf("Slash"))
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        local original = sgs.Sanguosha:getCard(request:getSelectedCardIds():first())
        local c = sgs.Sanguosha:cloneCard(original:isKindOf("Jink") and "slash" or "jink", original:getSuit(), original:getNumber())
        c:addSubcard(original); c:setSkillName(self:objectName()); return c
    end,
}
