-- ==================== c214_04
do
-- c214_04: the 谋弈 variant is deliberately omitted.
local function c214_name(card, soul)
    if soul then
        return ({[sgs.Card_Heart] = "peach", [sgs.Card_Diamond] = "fire_slash",
            [sgs.Card_Club] = "jink", [sgs.Card_Spade] = "nullification"})[card:getSuit()]
    end
    if card:isKindOf("Slash") then return "jink" end
    if card:isKindOf("Jink") then return "slash" end
    if card:isKindOf("Peach") then return "analeptic" end
    if card:isKindOf("Analeptic") then return "peach" end
end
local function c214_convert(name, soul)
    local function eligible(r, original)
        local p = r:getInitiator()
        if not p:getCards("he"):contains(original) then return false end
        local output = c214_name(original, soul)
        if not output or (output == "peach" and p:getMark("Global_PreventPeach") > 0) then return false end
        local c = sgs.Sanguosha:cloneCard(output, original:getSuit(), original:getNumber())
        c:addSubcard(original); c:setSkillName(name)
        local ok
        if r:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY then ok = c:isAvailable(p)
        else ok = sgs.Sanguosha:matchExpPattern(r:getPattern(), p, c) end
        c:deleteLater(); return ok
    end
    return sgs.CreateViewAsSkillV2 {
        name = name, n = soul and 2 or 1, response_or_use = true,
        can_activate = function(self, r)
            for _, c in sgs.qlist(r:getInitiator():getCards("he")) do if eligible(r, c) then return true end end
            return false
        end,
        can_select_card = function(self, r, c)
            local ids = r:getSelectedCardIds()
            return ids:length() < (soul and 2 or 1) and eligible(r, c)
                and (ids:isEmpty() or c:getSuit() == sgs.Sanguosha:getCard(ids:first()):getSuit())
        end,
        card_selection_feasible = function(self, r)
            local n = r:getSelectedCardIds():length(); return n >= 1 and n <= (soul and 2 or 1)
        end,
        create_card = function(self, r)
            local ids = r:getSelectedCardIds()
            if ids:isEmpty() then return nil end
            local original = sgs.Sanguosha:getCard(ids:first())
            local c = sgs.Sanguosha:cloneCard(c214_name(original, soul), original:getSuit(), original:getNumber())
            c:addSubcards(ids); c:setSkillName(name); return c
        end,
    }
end
hljx_zhaoyun = sgs.General(extension_hl, "hljx_zhaoyun", "shu", 4)
hljx_longdan = c214_convert("hljx_longdan", false)
hljx_yajiao = gu_trigger("hljx_yajiao", {sgs.CardUsed, sgs.CardResponded, sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if event == sgs.EventPhaseStart then
        if p:getPhase() == sgs.Player_Finish and owner:getMark("hljx_longdan-Clear") > 0 then owner:drawCards(1, self:objectName()) end
        return
    end
    if p ~= owner then return end
    local c, hand
    if event == sgs.CardUsed then local use = data:toCardUse(); c = use.card; hand = use.m_isHandcard
    else local response = data:toCardResponse(); c = response.m_card; hand = response.m_isHandcard end
    if not c then return end
    if c:getSkillName() == "hljx_longdan" then room:setPlayerMark(owner, "hljx_longdan-Clear", 1) end
    if owner:getPhase() ~= sgs.Player_NotActive or not hand or not gu_invoke(owner, self:objectName(), data) then return end
    local ids = room:getNCards(1)
    if ids:isEmpty() then return end
    local top = sgs.Sanguosha:getCard(ids:first())
    room:moveCardTo(top, nil, sgs.Player_PlaceTable, true)
    room:fillAG(ids)
    local target = room:askForPlayerChosen(owner, room:getAlivePlayers(), self:objectName(), "@hljx_yajiao", false, true)
    room:clearAG()
    if target then room:obtainCard(target, top, self:objectName(), true) end
end)
