hlxg_longhun_bonus = gu_trigger("#hlxg_longhun_bonus", {sgs.CardUsed, sgs.CardResponded, sgs.ConfirmDamage, sgs.PreHpRecover}, function(self, event, room, p, data, owner)
    local c
    if event == sgs.ConfirmDamage then c = data:toDamage().card
    elseif event == sgs.PreHpRecover then c = data:toRecover().card
    elseif event == sgs.CardUsed then c = data:toCardUse().card
    else c = data:toCardResponse().m_card end
    if not c or c:getSkillName() ~= "hlxg_longhun" or c:subcardsLength() ~= 2 then return end
    if event == sgs.ConfirmDamage then
        local d = data:toDamage()
        if d.from == owner and c:isRed() then d.damage = d.damage + 1; data:setValue(d) end
    elseif event == sgs.PreHpRecover then
        local r = data:toRecover()
        if r.who == owner and c:isRed() then r.recover = r.recover + 1; data:setValue(r) end
    elseif p == owner then
        -- Each virtual conversion has one immediate bonus, even if both events fire.
        if c:hasFlag("hlxg_longhun_bonus_done") then return end
        room:setCardFlag(c, "hlxg_longhun_bonus_done")
        if c:isRed() then owner:drawCards(1, "hlxg_longhun")
        else
            local current = room:getCurrent()
            if current and owner:canGet(current, "hej") then
                local id = room:askForCardChosen(owner, current, "hej", "hlxg_longhun", false, sgs.Card_MethodGet)
                if id >= 0 then room:obtainCard(owner, id, "hlxg_longhun", false) end
            end
        end
    end
end, true)
