-- ==================== c214_05
do
-- c214_05: counters record game history even before a skill is acquired.
local function c214_05_card(card)
    return card and (card:isKindOf("Slash") or (card:isBlack() and card:isNDTrick()))
end
hlxg_sushou = gu_trigger("hlxg_sushou", {sgs.EventPhaseStart}, function(self, event, room, player, data, owner)
    if not player or player:getPhase() ~= sgs.Player_Play then return end
    for _, p in sgs.qlist(room:getAlivePlayers()) do
        if p:getHandcardNum() > player:getHandcardNum() then return end
    end
    if not gu_invoke(owner, self:objectName(), sgs.QVariant(player)) then return end
    room:loseHp(sgs.HpLostStruct(owner, 1, self:objectName(), owner))
    if not owner:isAlive() then return end
    local x = owner:getLostHp()
    owner:drawCards(x, self:objectName())
    if not owner:isAlive() or not player:isAlive() or owner:objectName() == player:objectName() then return end
    local viewed = sgs.IntList()
    local n = math.ceil(player:getHandcardNum() / 2)
    for i = 1, n do
        local id = room:askForCardChosen(owner, player, "h", self:objectName(), false, sgs.Card_MethodNone, viewed)
        if id < 0 then break end
        viewed:append(id)
    end
    if viewed:isEmpty() then return end
    room:fillAG(viewed, owner)
    local maximum = math.min(x, viewed:length(), owner:getHandcardNum())
    local offered
    if maximum > 0 then
        offered = room:askForExchange(owner, self:objectName(), maximum, 0,
            false, "@hlxg_sushou-exchange", true)
    end
    local picked = sgs.IntList()
    if offered then
        for i = 1, offered:subcardsLength() do
            local id = room:askForAG(owner, viewed, false, self:objectName())
            if id < 0 then break end
            picked:append(id)
            viewed:removeOne(id)
            room:fillAG(viewed, owner)
        end
    end
    room:clearAG(owner)
    if offered and not picked:isEmpty() and picked:length() == offered:subcardsLength() then
        local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_SWAP, owner:objectName(), player:objectName(), self:objectName(), "")
        local moves = sgs.CardsMoveList()
        moves:append(sgs.CardsMoveStruct(offered:getSubcards(), owner, player, sgs.Player_PlaceHand, sgs.Player_PlaceHand, reason))
        moves:append(sgs.CardsMoveStruct(picked, player, owner, sgs.Player_PlaceHand, sgs.Player_PlaceHand, reason))
        room:moveCardsAtomic(moves, false)
    end
    if offered then offered:deleteLater() end
end)
hlxg_zhongjie = gu_trigger("hlxg_zhongjie", {sgs.Dying}, function(self, event, room, player, data, owner)
    local dying = data:toDying()
    if not dying.who or not dying.who:isAlive() or not dying.hplost or owner:getMark("hlxg_zhongjie_lun") > 0 then return end
    if not gu_invoke(owner, self:objectName(), sgs.QVariant(dying.who)) then return end
    room:setPlayerMark(owner, "hlxg_zhongjie_lun", 1)
    local recover = sgs.RecoverStruct(); recover.who = owner; recover.recover = 1
    room:recover(dying.who, recover)
    if dying.who:isAlive() then dying.who:drawCards(1, self:objectName()) end
end)
local function c214_05_targets(self, event, room, player, data, owner)
    local use = data:toCardUse()
    if not use.from or use.from:objectName() ~= owner:objectName() or not c214_05_card(use.card) then return end
    local name = self:objectName()
    local x = owner:getMark("&" .. name)
    if event == sgs.CardUsed then
        -- Target-fixed tricks cannot select extra targets through TargetMod.
        if not use.card:targetFixed() or x == 0 then return end
        for i = 1, x do
            local candidates = sgs.SPlayerList()
            for _, p in sgs.qlist(room:getAlivePlayers()) do
                if not use.to:contains(p) and not owner:isProhibited(p, use.card) then candidates:append(p) end
            end
            if candidates:isEmpty() then break end
            owner:setTag(name .. "_card", sgs.QVariant(use.card))
            local to = room:askForPlayerChosen(owner, candidates, name, "@" .. name .. "-target", true, true)
            owner:removeTag(name .. "_card")
            if not to then break end
            use.to:append(to)
        end
        room:sortByActionOrder(use.to)
        data:setValue(use)
    elseif use.to:length() < x then
        if name == "hljx_luanzhan" and owner:getMark(name .. "-Clear") > 0 then return end
        x = math.floor(x / 2)
        room:setPlayerMark(owner, "&" .. name, x)
        if name == "hljx_luanzhan" then
            room:setPlayerMark(owner, name .. "-Clear", 1)
            owner:drawCards(x, name)
        end
    end
end
hlxg_luanzhan = gu_trigger("hlxg_luanzhan", {sgs.CardUsed, sgs.TargetSpecified}, c214_05_targets)
hljx_luanzhan = gu_trigger("hljx_luanzhan", {sgs.CardUsed, sgs.TargetSpecified}, c214_05_targets)
local function c214_05_mod(self, ctx)
    local from, card = ctx:getPrimary(), ctx:getCard()
    local name = string.sub(self:objectName(), 2):gsub("_targets$", "")
    if ctx:getModType() == sgs.TargetModSkill_ExtraTarget and from and from:hasSkill(name) and c214_05_card(card) then
        return from:getMark("&" .. name)
    end
    return false
end
hlxg_luanzhan_targets = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_luanzhan_targets", pattern = ".", holder_selector = sgs.CorrectSkill_Primary, correct_func = c214_05_mod,
}
hljx_luanzhan_targets = sgs.CreateTargetModSkillV2 {
    name = "#hljx_luanzhan_targets", pattern = ".", holder_selector = sgs.CorrectSkill_Primary, correct_func = c214_05_mod,
}
hljx_luanzhan_history = gu_record("#hljx_luanzhan_history", {sgs.GameStart, sgs.HpChanged, sgs.Damage}, function(self, event, room, player, data)
    if event == sgs.GameStart then
        for _, p in sgs.qlist(room:getAllPlayers(true)) do
            p:setTag("hljx_luanzhan_hp", sgs.QVariant(p:getHp()))
        end
    elseif event == sgs.HpChanged and player then
        local previous = player:getTag("hljx_luanzhan_hp")
        local decreased = not previous:isNull() and player:getHp() < previous:toInt()
        player:setTag("hljx_luanzhan_hp", sgs.QVariant(player:getHp()))
        if decreased then
            for _, p in sgs.qlist(room:getAllPlayers(true)) do room:addPlayerMark(p, "&hljx_luanzhan") end
        end
    elseif event == sgs.Damage then
        local damage = data:toDamage()
        if damage.from and damage.damage > 0 then room:addPlayerMark(damage.from, "&hlxg_luanzhan") end
    end
end)
