    name = "#hlxg_koujing_filter",
    view_filter = function(self, c)
        local r = sgs.Sanguosha:currentRoom()
        local p = r and r:getCardOwner(c:getId())
        return p and r:getCardPlace(c:getId()) == sgs.Player_PlaceHand and p:getMark("hlxg_koujing_" .. c:getId() .. "-Clear") > 0
    end,
    view_as = function(self, c)
        local slash = sgs.Sanguosha:cloneCard("slash", c:getSuit(), c:getNumber())
        slash:setSkillName("hlxg_koujing")
        local w = sgs.Sanguosha:getWrappedCard(c:getId())
        w:takeOver(slash); slash:deleteLater(); return w
    end,
}
hlxg_koujing = gu_trigger("hlxg_koujing", {sgs.EventPhaseStart, sgs.Damaged}, function(self, event, room, player, data, p)
    if event == sgs.EventPhaseStart then
        if player ~= p or p:getPhase() ~= sgs.Player_Play or p:isKongcheng() then return end
        local c = room:askForExchange(p, self:objectName(), p:getHandcardNum(), 1, false, "@hlxg_koujing", true)
        if not c then return end
        for _, id in sgs.qlist(c:getSubcards()) do room:setPlayerMark(p, "hlxg_koujing_" .. id .. "-Clear", 1) end
        room:filterCards(p, p:getHandcards(), true)
    else
        local d = data:toDamage()
        if d.from ~= p or d.to == p or not d.card or d.card:getSkillName() ~= self:objectName() then return end
        local ids = sgs.IntList()
        for _, id in sgs.qlist(p:handCards()) do
            if p:getMark("hlxg_koujing_" .. id .. "-Clear") > 0 then ids:append(id) end
        end
        if ids:isEmpty() then return end
        room:showCard(p, ids)
        if not d.to:isAlive() or d.to:isKongcheng() or not gu_invoke(d.to, "hlxg_koujing_exchange", data) then return end
        local moves = sgs.CardsMoveList()
        local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_SWAP, p:objectName(), d.to:objectName(), self:objectName(), "")
        moves:append(sgs.CardsMoveStruct(d.to:handCards(), p, sgs.Player_PlaceHand, reason))
        moves:append(sgs.CardsMoveStruct(ids, d.to, sgs.Player_PlaceHand, reason))
        room:moveCardsAtomic(moves, false)
    end
end)
hlxg_koujing_record = gu_record("#hlxg_koujing_record", {sgs.CardUsed, sgs.CardsMoveOneTime, sgs.EventPhaseChanging}, function(self, event, room, p, data)
    if event == sgs.CardUsed then
        local u = data:toCardUse()
        if u.card and u.card:getSkillName() == "hlxg_koujing" and u.m_addHistory then
            room:addPlayerHistory(u.from, u.card:getClassName(), -1)
            u.m_addHistory = false; data:setValue(u)
        end
    elseif event == sgs.CardsMoveOneTime then
        local m = data:toMoveOneTime()
        if not m.from then return end
        local owner = room:findPlayerByObjectName(m.from:objectName())
        if not owner then return end
        for i, id in sgs.qlist(m.card_ids) do
            if m.from_places:at(i) == sgs.Player_PlaceHand then room:setPlayerMark(owner, "hlxg_koujing_" .. id .. "-Clear", 0) end
        end
    elseif data:toPhaseChange().to == sgs.Player_NotActive then
        for _, q in sgs.qlist(room:getAlivePlayers()) do
            for _, id in sgs.qlist(q:handCards()) do room:setPlayerMark(q, "hlxg_koujing_" .. id .. "-Clear", 0) end
            room:filterCards(q, q:getCards("he"), true)
        end
    end
end)
