            room:setCardFlag(e.card, "hlxg_chijie_null_" .. p:objectName())
        end
    else
        local u = data:toCardUse()
        if not u.from or u.from == p or not u.to:contains(p) or u.card:hasFlag("hlxg_chijie_damage") or p:getMark("hlxg_chijie_get-Clear") >= 2 then return end
        if room:getCardPlace(u.card:getEffectiveId()) ~= sgs.Player_PlaceTable then
            if not u.card:isVirtualCard() or u.card:getSubcards():isEmpty() then return end
            for _, id in sgs.qlist(u.card:getSubcards()) do if room:getCardPlace(id) ~= sgs.Player_PlaceTable then return end end
        end
        if gu_invoke(p, "hlxg_chijie_obtain", data) then
            room:addPlayerMark(p, "hlxg_chijie_get-Clear"); room:obtainCard(p, u.card, true)
        end
    end
end)
hlxg_chijie_record = sgs.CreateRuleSkillV2 {
    name = "#hlxg_chijie_record", global = true, priority = 10,
    events = {sgs.CardUsed, sgs.DamageDone, sgs.CardEffected, sgs.CardFinished},
    can_trigger = function(self, event, room, p, data)
        if event ~= sgs.CardEffected then return false end
        local e = data:toCardEffect()
        for _, q in sgs.qlist(room:getAllPlayers()) do
            if e.card:hasFlag("hlxg_chijie_null_" .. q:objectName()) and e.to ~= q then return self:objectName() end
        end
        return false
    end,
    on_effect = function() return true end,
    on_record = function(self, event, room, p, ctx)
        local data = ctx.original_data
        if event == sgs.DamageDone then
            local d = data:toDamage(); if d.card then room:setCardFlag(d.card, "hlxg_chijie_damage") end
        elseif event == sgs.CardUsed or event == sgs.CardFinished then
            local c = data:toCardUse().card
            if event == sgs.CardUsed then room:setCardFlag(c, "-hlxg_chijie_damage") end
            for _, q in sgs.qlist(room:getAllPlayers()) do room:setCardFlag(c, "-hlxg_chijie_null_" .. q:objectName()) end
        end
    end,
}

local function hl06_judge(room, p)
    local j = sgs.JudgeStruct(); j.who = p; j.reason = "hlxg_tuntian"; j.pattern = ".|heart"; j.good = false
    room:judge(j)
end
hlxg_tuntian = gu_trigger("hlxg_tuntian", {sgs.CardsMoveOneTime, sgs.EventPhaseStart, sgs.FinishJudge}, function(self, event, room, player, data, p)
    if event == sgs.CardsMoveOneTime then
        local m = data:toMoveOneTime()
        if p:getPhase() ~= sgs.Player_NotActive or not m.from or m.from:objectName() ~= p:objectName() then return end
        if not (m.from_places:contains(sgs.Player_PlaceHand) or m.from_places:contains(sgs.Player_PlaceEquip)) then return end
        if gu_invoke(p, self:objectName(), data) then hl06_judge(room, p) end
    elseif event == sgs.EventPhaseStart then
        if player == p and p:getPhase() == sgs.Player_Finish and room:askForDiscard(p, self:objectName(), 1, 1, true, false, "@hlxg_tuntian") then hl06_judge(room, p) end
    else
        local j = data:toJudge()
        if j.who == p and j.reason == self:objectName() and j.card:getSuit() ~= sgs.Card_Heart then p:addToPile("hlxg_field", j.card) end
    end
end)
