-- ==================== c214_07
do
-- c214_07: literal variants, reusing identical engine skills where available.
hlxg_dengai2 = sgs.General(extension_hl, "hlxg_dengai2", "god", 4)
hlxg_dengzhi = sgs.General(extension_hl, "hlxg_dengzhi", "shu", 3)
hlxg_zoushi = sgs.General(extension_hl, "hlxg_zoushi", "qun", 3, false)
-- Reuse the identical engine Tuoyu and Jianliang; use Tuoyu's native area marks.
local c21407_areas = {"sdatyfengtian", "sdatyqingqu", "sdatyjunshan"}
local function c21407_open(p)
    for _, mark in sgs.qlist(p:getMarkNames()) do
        if mark:sub(1, 1) == "&" and mark:sub(-7) == "+#tuoyu" and p:getMark(mark) > 0 then
            local result = {}
            for _, area in ipairs(c21407_areas) do
                if mark:find(area, 1, true) then table.insert(result, area) end
            end
            return result
        end
    end
    return {}
end
hlxg_cuixin_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_cuixin_mod", pattern = ".", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local card, mod = ctx:getCard(), ctx:getModType()
        if card and card:getSkillName() == "hlxg_cuixin"
            and (mod == sgs.TargetModSkill_Residue or mod == sgs.TargetModSkill_DistanceLimit) then return 1000 end
        return false
    end,
}
hlxg_xianjin = gu_trigger("hlxg_xianjin", {sgs.Damage, sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    local mark = event == sgs.Damage and "hlxg_xianjin_dealt" or "hlxg_xianjin_received"
    room:addPlayerMark(owner, mark)
    if owner:getMark(mark) % 2 ~= 0 then return end
    local open, choices = c21407_open(owner), {}
    local n = #open
    for _, area in ipairs(c21407_areas) do
        if not table.contains(open, area) then table.insert(choices, area) end
    end
    if #choices > 0 then
        local area = room:askForChoice(owner, "hlxg_xianjin", table.concat(choices, "+"))
        for _, markname in sgs.qlist(owner:getMarkNames()) do
            if markname:sub(-7) == "+#tuoyu" then room:setPlayerMark(owner, markname, 0) end
        end
        table.insert(open, area)
        room:setPlayerMark(owner, "&" .. table.concat(open, "+") .. "+#tuoyu", 1)
        n = n + 1
    end
    owner:drawCards(n, "hlxg_xianjin")
end, true)
hlxg_cuixin = gu_trigger("hlxg_cuixin", {sgs.CardFinished}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    local use = data:toCardUse()
    if not use.card or use.card:getSkillName() == "hlxg_cuixin" then return end
    local last, next = owner:getLastAlive(), owner:getNextAlive()
    local repeats = {}
    for _, to in sgs.qlist(use.to) do
        if to == last then table.insert(repeats, next)
        elseif to == next then table.insert(repeats, last) end
    end
    for _, to in ipairs(repeats) do
        if owner:isDead() then break end
        local card = sgs.Sanguosha:cloneCard(use.card:objectName(), sgs.Card_NoSuit, 0)
        if card then
            card:setSkillName("hlxg_cuixin")
            if to:isAlive() and not owner:isProhibited(to, card)
                and (card:targetFixed() or card:targetFilter(sgs.PlayerList(), to, owner))
                then
                owner:setTag("hlxg_cuixin_card", sgs.QVariant(use.card:objectName()))
                if gu_invoke(owner, "hlxg_cuixin", sgs.QVariant(to:objectName())) then
                local again = sgs.CardUseStruct()
                again.card, again.from = card, owner
                again.to:append(to)
                room:useCard(again, false)
                end
                owner:removeTag("hlxg_cuixin_card")
            end
            card:deleteLater()
        end
    end
end)
hlxg_qijing = gu_trigger("hlxg_qijing", {sgs.EventPhaseChanging}, function(self, event, room, p, data, owner)
    if data:toPhaseChange().to ~= sgs.Player_NotActive or owner:getMark("hlxg_qijing") > 0 then return end
    if #c21407_open(owner) < 3 then return end
    room:setPlayerMark(owner, "hlxg_qijing", 1)
    room:loseMaxHp(owner, 1, "hlxg_qijing")
    if owner:isDead() then return end
    room:acquireSkill(owner, "hlxg_cuixin")
    if room:getOtherPlayers(owner):length() >= 2 then
        local to = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), "hlxg_qijing", "@hlxg_qijing-seat")
        -- Insert immediately before the chosen player, preserving everyone else's order.
        local order = sgs.QList2Table(room:getAlivePlayers())
        table.sort(order, function(a, b) return a:getSeat() < b:getSeat() end)
        local index
        for i, q in ipairs(order) do if q == owner then index = i; break end end
        while index do
            local j = index % #order + 1
            if order[j] == to then break end
            room:swapSeat(owner, order[j])
            order[index], order[j] = order[j], owner
            index = j
        end
    end
    owner:gainAnExtraTurn()
end, true, sgs.Skill_Wake)
