hlxg_weimeng = gu_active("hlxg_weimeng", 1, 0, 0, gu_one, gu_one_feasible,
    function(self, room, source, targets)
        local to = targets[1]
        local x = math.max(0, source:getHp() + source:getMark("hlxg_weimeng_bonus"))
        room:setPlayerMark(source, "hlxg_weimeng_bonus", 0)
        local ids = room:askForCardsChosen(source, to, "h", "hlxg_weimeng", 0, math.min(x, to:getHandcardNum()), false)
        local sum = 0
        for _, id in sgs.qlist(ids) do sum = sum + sgs.Sanguosha:getCard(id):getNumber() end
        local n = ids:length()
        gu_obtain(room, source, ids, "hlxg_weimeng")
        if source:isDead() or to:isDead() then return end
        local given, total = nil, 0
        if n > 0 then
            given = room:askForExchange(source, "hlxg_weimeng", n, n, true, "@hlxg_weimeng-give:" .. to:objectName())
            if not given then return end
            for _, id in sgs.qlist(given:getSubcards()) do total = total + sgs.Sanguosha:getCard(id):getNumber() end
            room:obtainCard(to, given, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_GIVE,
                source:objectName(), to:objectName(), "hlxg_weimeng", ""), false)
            given:deleteLater()
        end
        if total > sum then source:drawCards(1, "hlxg_weimeng")
        elseif total < sum and source:canDiscard(to, "hej") then
            local id = room:askForCardChosen(source, to, "hej", "hlxg_weimeng", false, sgs.Card_MethodDiscard)
            room:throwCard(sgs.Sanguosha:getCard(id), to, source)
        elseif total == sum then room:setPlayerMark(source, "hlxg_weimeng_bonus", 1) end
    end)
