hlxg_qingcheng = gu_active("hlxg_qingcheng", 1, 0, 0,
    function(self, targets, to, from)
        return #targets == 0 and to:getHandcardNum() <= from:getHandcardNum() + from:getLostHp()
    end, gu_one_feasible,
    function(self, room, source, targets)
        local to = targets[1]
        if to == source then return end
        local moves = sgs.CardsMoveList()
        local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_SWAP, source:objectName(), "hlxg_qingcheng", "")
        moves:append(sgs.CardsMoveStruct(source:handCards(), source, to, sgs.Player_PlaceHand, sgs.Player_PlaceHand, reason))
        moves:append(sgs.CardsMoveStruct(to:handCards(), to, source, sgs.Player_PlaceHand, sgs.Player_PlaceHand, reason))
        room:moveCardsAtomic(moves, false)
    end)
hlxg_huoshui = gu_active("hlxg_huoshui", nil, 0, 0,
    function(self, targets, to, from)
        return gu_one(self, targets, to, from) and to:getMark("hlxg_huoshui_target_" .. from:objectName() .. "-Clear") == 0
    end, gu_one_feasible,
    function(self, room, source, targets)
        local to, choices = targets[1], {}
        for _, choice in ipairs({"invalidate", "hand", "equip"}) do
            if source:getMark("hlxg_huoshui_" .. choice .. "-PlayClear") == 0 then table.insert(choices, choice) end
        end
        if #choices == 0 then return end
        local choice = room:askForChoice(source, "hlxg_huoshui", table.concat(choices, "+"), sgs.QVariant(to:objectName()))
        room:setPlayerMark(source, "hlxg_huoshui_" .. choice .. "-PlayClear", 1)
        room:setPlayerMark(to, "hlxg_huoshui_target_" .. source:objectName() .. "-Clear", 1)
        if choice == "invalidate" then
            room:setPlayerMark(to, "hlxg_huoshui_invalid-Clear", 1)
            room:filterCards(to, to:getCards("he"), true)
        elseif choice == "hand" then
            room:showAllCards(to, source)
            if not to:isKongcheng() then
                local id = room:askForCardChosen(source, to, "h", "hlxg_huoshui", true)
                room:obtainCard(source, id, false)
