        end
    end, nil,
    function(p)
        return p:getMark("hlxg_huoshui_invalidate-PlayClear") == 0
            or p:getMark("hlxg_huoshui_hand-PlayClear") == 0 or p:getMark("hlxg_huoshui_equip-PlayClear") == 0
    end)
