-- ==================== c215_01
do
-- c215_01: literal 欢乐 variants; assembled with the GU helpers in scope.
local function c215_active(name, card, quota, maximum, enabled)
    local spec = {
        name = name, n = maximum or 0,
        can_activate = function(self, request)
            local p = request:getInitiator()
            return p and request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
                and (not enabled or enabled(p))
        end,
        can_select_card = function(self, request, c)
            local p = request:getInitiator()
            return request:getSelectedCardIds():length() < (maximum or 0)
                and p:canDiscard(p, c:getEffectiveId())
        end,
        card_selection_feasible = function(self, request)
            return request:getSelectedCardIds():length() <= (maximum or 0)
        end,
        create_card = function(self, request)
            local c = card:clone()
            c:addSubcards(request:getSelectedCardIds()); c:setSkillName(name)
            return c
        end,
    }
    if quota then
        spec.limit_scope = sgs.Skill_Limit_Phase; spec.phase_name = "Play"; spec.max_usage_limit = quota
    end
    return sgs.CreateViewAsSkillV2(spec)
end
local function c215_discardable(p, target)
    local n = 0
    for _, c in sgs.qlist(target:getCards("he")) do
        if p:canDiscard(target, c:getEffectiveId()) then n = n + 1 end
    end
    return n
end

hlxg_zhenghun = sgs.General(extension_hl, "hlxg_zhenghun", "wei", 3)
hlxg_qiangzhiCard = sgs.CreateSkillCard {
    name = "hlxg_qiangzhiCard", will_throw = false, handling_method = sgs.Card_MethodNone,
    filter = function(self, targets, to, from)
        return gu_one(self, targets, to, from)
            and c215_discardable(from, to) >= 3 - self:subcardsLength()
    end,
    feasible = gu_one_feasible,
    on_use = function(self, room, source, targets)
        local target = targets[1]
        local own, other = 0, 0
        -- Separate moves are essential: every discard can trigger 辟田.
        for _, id in sgs.qlist(self:getSubcards()) do
            if source:isAlive() and room:getCardOwner(id) == source and source:canDiscard(source, id) then
                room:throwCard(id, "hlxg_qiangzhi", source); own = own + 1
            end
        end
        for i = 1, 3 - self:subcardsLength() do
            if source:isDead() or target:isDead() or not source:canDiscard(target, "he") then break end
            local id = room:askForCardChosen(source, target, "he", "hlxg_qiangzhi", false, sgs.Card_MethodDiscard)
            if id < 0 then break end
            room:throwCard(id, "hlxg_qiangzhi", target, source); other = other + 1
        end
        if own == 3 and target:isAlive() then
            room:damage(sgs.DamageStruct("hlxg_qiangzhi", source:isAlive() and source or nil, target, 1))
        elseif other == 3 and source:isAlive() then
            room:damage(sgs.DamageStruct("hlxg_qiangzhi", target:isAlive() and target or nil, source, 1))
        end
    end,
}
hlxg_qiangzhi = c215_active("hlxg_qiangzhi", hlxg_qiangzhiCard, 1, 3)
hlxg_pitian = gu_trigger("hlxg_pitian", {sgs.CardsMoveOneTime, sgs.Damaged, sgs.EventPhaseStart},
    function(self, event, room, p, data, owner)
        if event == sgs.CardsMoveOneTime then
            local move = data:toMoveOneTime()
            if move.from == owner and not move.card_ids:isEmpty() and move.to_place == sgs.Player_DiscardPile
                and bit32.band(move.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON) == sgs.CardMoveReason_S_REASON_DISCARD then
                room:addPlayerMark(owner, "&hlxg_pitian", 1)
            end
        elseif event == sgs.Damaged then
            if p == owner then room:addPlayerMark(owner, "&hlxg_pitian", 1) end
        elseif p == owner and owner:getPhase() == sgs.Player_Finish
            and owner:getHandcardNum() < owner:getMaxCards() and gu_invoke(owner, self:objectName()) then
            owner:drawCards(math.min(5, owner:getMaxCards() - owner:getHandcardNum()), self:objectName())
            room:setPlayerMark(owner, "&hlxg_pitian", 0)
        end
    end, true)
hlxg_pitian_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_pitian_max", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        return p and p:hasSkill("hlxg_pitian") and p:getMark("&hlxg_pitian") or 0
    end,
}
hlxg_zhenghun:addSkill(hlxg_qiangzhi); hlxg_zhenghun:addSkill(hlxg_pitian)
hlxg_zhenghun:addSkill(hlxg_pitian_max)
extension_hl:insertRelatedSkills("hlxg_pitian", "#hlxg_pitian_max")

local function c215_yiji(room, p)
    p:drawCards(2, "hljx_yiji")
    local remaining = 2
    while p:isAlive() and remaining > 0 and not p:isKongcheng() do
        local ids = sgs.IntList()
        for _, c in sgs.qlist(p:getHandcards()) do
            if not c:hasFlag("using") then ids:append(c:getEffectiveId()) end
        end
        if ids:isEmpty() then break end
        local before = ids:length()
        if not room:askForYiji(p, ids, "hljx_yiji", false, false, true, remaining, room:getOtherPlayers(p)) then break end
        local given = before - ids:length()
        if given <= 0 then break end
        remaining = remaining - given
    end
end
hljx_guojia = sgs.General(extension_hl, "hljx_guojia", "wei", 3)
hljx_tiandu = sgs.CreateTriggerSkillV2 {
    name = "hljx_tiandu", events = {sgs.FinishJudge}, frequency = sgs.Skill_Frequent,
    can_trigger = function(self, event, room, p, data)
        if not p or p:isDead() or not p:hasSkill(self:objectName()) then return false end
        local judge = data:toJudge()
        if judge.card and room:getCardPlace(judge.card:getEffectiveId()) == sgs.Player_PlaceJudge then return self:objectName() end
        return false
    end,
    on_cost = function(self, event, room, p, ctx)
        return gu_invoke(p, self:objectName(), ctx.original_data)
    end,
    on_effect = function(self, event, room, p, ctx)
        local judge = ctx.original_data:toJudge()
        if judge.card and room:getCardPlace(judge.card:getEffectiveId()) == sgs.Player_PlaceJudge then
            room:obtainCard(p, judge.card, self:objectName(), true)
        end
        return false
    end,
}
hljx_yiji = gu_trigger("hljx_yiji", {sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    for i = 1, data:toDamage().damage do
        if owner:isDead() then break end
        if gu_invoke(owner, self:objectName(), data) then c215_yiji(room, owner) end
    end
end, false, sgs.Skill_Frequent)
local function c215_stats(p)
    return {p:getHandcardNum(), p:getHp(), p:getWeaponsCount(), p:getArmorsCount(),
        p:getOffensiveHorsesCount() + p:getDefensiveHorsesCount()}
end
hljx_shenglunCard = sgs.CreateSkillCard {
    name = "hljx_shenglunCard", will_throw = false, handling_method = sgs.Card_MethodNone,
    filter = function(self, targets, to, from) return #targets < 2 and to ~= from end,
    feasible = function(self, targets) return #targets <= 2 end,
    on_use = function(self, room, source, targets)
        local ours = c215_stats(source)
        for _, target in ipairs(targets) do
            local theirs = c215_stats(target)
            for i = 1, 5 do
                local mark = ours[i] > theirs[i] and "&hljx_shenglun_win" or "&hljx_shenglun_lose"
                if source:getMark(mark) < 10 then room:addPlayerMark(source, mark, 1) end
            end
        end
        if source:getMark("&hljx_shenglun_win") == 10
            and room:askForChoice(source, "hljx_shenglun", "win+cancel") == "win" then
            room:setPlayerMark(source, "&hljx_shenglun_win", 0)
            room:recover(source, sgs.RecoverStruct("hljx_shenglun", source, 1))
            if source:isAlive() then c215_yiji(room, source) end
        end
        if source:isAlive() and source:getMark("&hljx_shenglun_lose") == 10
            and room:askForChoice(source, "hljx_shenglun", "lose+cancel") == "lose" then
            room:setPlayerMark(source, "&hljx_shenglun_lose", 0)
            local target = room:askForPlayerChosen(source, room:getAlivePlayers(), "hljx_shenglun", "@hljx_shenglun-damage")
            if target then room:damage(sgs.DamageStruct("hljx_shenglun", source, target, 1)) end
            if source:isAlive() then c215_yiji(room, source) end
        end
    end,
}
hljx_shenglun = c215_active("hljx_shenglun", hljx_shenglunCard, 1)
hljx_guojia:addSkill(hljx_tiandu); hljx_guojia:addSkill(hljx_shenglun); hljx_guojia:addSkill(hljx_yiji)

-- 佐幸 is acquired by 天翊, rather than innate; bind its grant to the actual giver.
local c215_zuoxing_name = "hlxg_zuoxing"
local c215_zuoxing_vs = sgs.CreateViewAsSkillV2 {
    name = c215_zuoxing_name, n = 0, guhuo_type = "r",
    limit_scope = sgs.Skill_Limit_Phase, phase_name = "Play", max_usage_limit = 1,
    can_activate = function(self, request)
        local p = request:getInitiator()
        return p and request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
            and p:getMark("hlxg_zuoxing_enabled-PlayClear") > 0
    end,
    allow_declaration = function(self, p, name)
        local card = sgs.Sanguosha:cloneCard(name)
        if not card then return false end
        local valid = card:isNDTrick()
        card:deleteLater(); return valid
    end,
    build_card = function(self, request, name)
        local card = sgs.Sanguosha:cloneCard(name)
        if not card then return nil end
        if not card:isNDTrick() then card:deleteLater(); return nil end
        card:setSkillName("hlxg_zuoxing"); card:setCanRecast(false)
        return card
    end,
}
hlxg_zuoxing = sgs.CreateTriggerSkillV2 {
    name = "hlxg_zuoxing", events = {sgs.EventPhaseStart}, view_as_skill = c215_zuoxing_vs, guhuo_type = "r",
    can_trigger = function(self, event, room, p, data)
        if not p or p:isDead() or not p:hasSkill(self:objectName()) or p:getPhase() ~= sgs.Player_Play then return false end
        local giver = p:getTag("hlxg_zuoxing_grantor"):toPlayer()
        if giver and giver:isAlive() and giver:getMaxHp() > 1 then return self:objectName() end
        return false
    end,
    on_cost = function(self, event, room, p, ctx) return gu_invoke(p, self:objectName()) end,
    on_effect = function(self, event, room, p, ctx)
        local giver = p:getTag("hlxg_zuoxing_grantor"):toPlayer()
        if giver and giver:isAlive() and giver:getMaxHp() > 1 then
            room:loseMaxHp(giver, 1, self:objectName())
            if p:isAlive() then room:setPlayerMark(p, "hlxg_zuoxing_enabled-PlayClear", 1) end
        end
        return false
    end,
}
extension_hl:addSkills(hlxg_zuoxing)
hlxg_tianyi_guojia_record = gu_record("#hlxg_tianyi_guojia_record", {sgs.DamageDone},
    function(self, event, room, p, data)
        local damage = data:toDamage()
        if damage.to and damage.damage > 0 then room:setPlayerMark(damage.to, "hlxg_tianyi_guojia_damaged", 1) end
    end)
hlxg_tianyi_guojia = sgs.CreateTriggerSkillV2 {
    name = "hlxg_tianyi_guojia", frequency = sgs.Skill_Wake, events = {sgs.EventPhaseStart},
    waked_skills = "hlxg_zuoxing",
    can_trigger = function(self, event, room, p, data)
        if not p or p:isDead() or not p:hasSkill(self:objectName()) or p:getMark(self:objectName()) > 0
            or p:getPhase() ~= sgs.Player_Start then return false end
        if not p:getTag(self:objectName() .. "_SKILLCANWAKE"):toStringList():isEmpty() then return self:objectName() end
        for _, other in sgs.qlist(room:getAlivePlayers()) do
            if other:getMark("hlxg_tianyi_guojia_damaged") == 0 then return false end
        end
        return self:objectName()
    end,
    on_effect = function(self, event, room, p, ctx)
        p:canWake(self:objectName()) -- Consume a grant only when the awakening resolves.
        room:setPlayerMark(p, self:objectName(), 1)
        room:gainMaxHp(p, 2, self:objectName())
        room:recover(p, sgs.RecoverStruct(self:objectName(), p, 1))
        if p:isAlive() then
            local to = room:askForPlayerChosen(p, room:getAlivePlayers(), self:objectName(), "@hlxg_tianyi_guojia-grant")
            if to then
                to:setTag("hlxg_zuoxing_grantor", sgs.QVariant(p))
                room:acquireSkill(to, "hlxg_zuoxing")
            end
        end
        return false
    end,
}
hlxg_huishi_guojiaCard = sgs.CreateSkillCard {
    name = "hlxg_huishi_guojiaCard", target_fixed = true, will_throw = false,
    handling_method = sgs.Card_MethodNone,
    on_use = function(self, room, source)
        local ids = sgs.IntList()
        while source:isAlive() do
            local judge = sgs.JudgeStruct()
            judge.who = source; judge.reason = "hlxg_huishi_guojia"; judge.pattern = "."
            judge.good = true; judge.throw_card = false
            room:judge(judge)
            if not judge.card then break end
            local id = judge.card:getEffectiveId()
            if room:getCardPlace(id) == sgs.Player_PlaceJudge then ids:append(id) end
            local mark = "hlxg_huishi_guojia_suit" .. judge.card:getSuit() .. "-PlayClear"
            local fresh = source:getMark(mark) == 0
            room:setPlayerMark(source, mark, 1)
            if not fresh or source:isDead() or source:getMaxHp() >= 10 then break end
            room:gainMaxHp(source, 1, "hlxg_huishi_guojia")
            if source:isDead() or not gu_invoke(source, "hlxg_huishi_guojia", sgs.QVariant("continue")) then break end
        end
        local retained = sgs.IntList()
        for _, id in sgs.qlist(ids) do
            if room:getCardPlace(id) == sgs.Player_PlaceJudge then retained:append(id) end
        end
        if retained:isEmpty() then return end
        local to
        if source:isAlive() then
            room:fillAG(retained, source)
            to = room:askForPlayerChosen(source, room:getAlivePlayers(), "hlxg_huishi_guojia", "@hlxg_huishi_guojia-give", true)
            room:clearAG(source)
        end
        local cards = gu_dummy(retained)
        if to then
            local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_GIVE, source:objectName(), to:objectName(), "hlxg_huishi_guojia", "")
            room:obtainCard(to, cards, reason, true)
            local highest = to:isAlive()
            for _, p in sgs.qlist(room:getAlivePlayers()) do
                if p:getHandcardNum() > to:getHandcardNum() then highest = false end
            end
            if highest and source:isAlive() then room:loseMaxHp(source, 1, "hlxg_huishi_guojia") end
        else
            room:moveCardTo(cards, nil, sgs.Player_DiscardPile,
                sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_NATURAL_ENTER, source:objectName(), "hlxg_huishi_guojia", ""), true)
        end
        cards:deleteLater()
    end,
}
hlxg_huishi_guojia = c215_active("hlxg_huishi_guojia", hlxg_huishi_guojiaCard, 1, 0,
    function(p) return p:getMaxHp() < 10 end)
local function c215_unawakened(p)
    local names = {}
    for _, sk in sgs.qlist(p:getVisibleSkillList()) do
        if sk:getFrequency(p) == sgs.Skill_Wake and p:getMark(sk:objectName()) == 0 then
            table.insert(names, sk:objectName())
        end
    end
    return names
end
hlxg_huishi_guojia2Card = sgs.CreateSkillCard {
    name = "hlxg_huishi_guojia2Card", will_throw = false, handling_method = sgs.Card_MethodNone,
    filter = function(self, targets, to, from)
        if #targets > 0 then return false end
        local names = c215_unawakened(to)
        return (#names > 0 and from:getMaxHp() >= from:aliveCount())
            or (#names == 0 and from:getMaxHp() > 2)
    end,
    feasible = gu_one_feasible,
    on_use = function(self, room, source, targets)
        local to = targets[1]
        local names = c215_unawakened(to)
        if (#names > 0 and source:getMaxHp() < room:alivePlayerCount())
            or (#names == 0 and source:getMaxHp() <= 2) then return end
        room:removePlayerMark(source, "@hlxg_huishi_guojia2")
        if #names > 0 then
            local name = room:askForChoice(source, "hlxg_huishi_guojia2", table.concat(names, "+"), sgs.QVariant(to))
            to:setCanWake("hlxg_huishi_guojia2", name)
        else to:drawCards(4, "hlxg_huishi_guojia2") end
        if source:isAlive() then room:loseMaxHp(source, 2, "hlxg_huishi_guojia2") end
    end,
}
-- Limited metadata belongs on the V2 view-as skill so the engine initializes its token.
local c215_huishi2_spec = {
    name = "hlxg_huishi_guojia2", n = 0, frequency = sgs.Skill_Limited, limit_mark = "@hlxg_huishi_guojia2",
    can_activate = function(self, request)
        local p = request:getInitiator()
        return p and request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
            and p:getMark("@hlxg_huishi_guojia2") > 0
    end,
    create_card = function(self, request)
        local card = hlxg_huishi_guojia2Card:clone(); card:setSkillName("hlxg_huishi_guojia2"); return card
    end,
}
hlxg_huishi_guojia2 = sgs.CreateViewAsSkillV2(c215_huishi2_spec)
hlxg_guojia = sgs.General(extension_hl, "hlxg_guojia", "god", 3)
hlxg_guojia:addSkill(hlxg_tianyi_guojia); hlxg_guojia:addSkill(hlxg_tianyi_guojia_record)
hlxg_guojia:addSkill(hlxg_huishi_guojia); hlxg_guojia:addSkill(hlxg_huishi_guojia2)
extension_hl:insertRelatedSkills("hlxg_tianyi_guojia", "#hlxg_tianyi_guojia_record")

