do
hlxg_guotufengji = sgs.General(extension_hl, "hlxg_guotufengji", "qun", 3)
hlxg_guosi = sgs.General(extension_hl, "hlxg_guosi", "qun", 4)
hljx_guohuai = sgs.General(extension_hl, "hljx_guohuai", "wei", 4)

hlxg_jigong = gu_trigger("hlxg_jigong", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if p:getPhase() == sgs.Player_Play and gu_invoke(owner, self:objectName()) then
        local n = tonumber(room:askForChoice(owner, self:objectName(), "0+1+2+3")) or 0
        room:setPlayerMark(owner, "hlxg_jigong_active-Clear", 1)
        room:setPlayerMark(owner, "hlxg_jigong_draw-Clear", n)
        room:setPlayerMark(owner, "hlxg_jigong_damage-Clear", 0)
        if n > 0 then owner:drawCards(n, self:objectName()) end
    elseif p:getPhase() == sgs.Player_Discard and owner:getMark("hlxg_jigong_active-Clear") > 0
        and owner:getMark("hlxg_jigong_damage-Clear") >= owner:getMark("hlxg_jigong_draw-Clear") then
        local recover = sgs.RecoverStruct(); recover.who = owner; recover.recover = 1
        room:recover(owner, recover)
    end
end)
hlxg_jigong_record = gu_record("#hlxg_jigong_record", {sgs.Damage}, function(self, event, room, p, data)
    local d = data:toDamage()
    if d.from and d.from:getPhase() == sgs.Player_Play and d.from:getMark("hlxg_jigong_active-Clear") > 0 then
        room:addPlayerMark(d.from, "hlxg_jigong_damage-Clear", d.damage)
    end
end)
hlxg_jigong_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_jigong_max", holder_selector = sgs.CorrectSkill_System,
    fixed_func = function(self, ctx)
        local p = ctx:getPrimary()
        if p and p:getMark("hlxg_jigong_active-Clear") > 0 then return p:getMark("hlxg_jigong_damage-Clear") + 1 end
        return -1
    end,
}
hlxg_shifei = gu_trigger("hlxg_shifei", {sgs.CardAsked}, function(self, event, room, p, data, owner)
    if p ~= owner or data:toStringList():at(0) ~= "jink" then return end
    local current = room:getCurrent()
    if not current or current:isDead() or not gu_invoke(owner, self:objectName(), data) then return end
    current:drawCards(1, self:objectName())
    if owner:isDead() then return end
    local unique = true
    for _, q in sgs.qlist(room:getAlivePlayers()) do
        if q ~= current and q:getHandcardNum() >= current:getHandcardNum() then unique = false end
    end
    if unique then return end
    local candidates = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getAlivePlayers()) do
        if owner:canDiscard(q, "hej") then candidates:append(q) end
    end
    if candidates:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_shifei")
    local id = room:askForCardChosen(owner, to, "hej", self:objectName(), false, sgs.Card_MethodDiscard)
    if id < 0 then return end
    room:throwCard(id, self:objectName(), to, owner)
    local card = sgs.Sanguosha:cloneCard("jink", sgs.Card_NoSuit, 0)
    card:setSkillName(self:objectName()); card:deleteLater(); room:provide(card)
    return true
end)

-- Record every actual card use before optional extraction, including nonmatching uses.
hlxg_cidao_record = gu_record("#hlxg_cidao_record", {sgs.CardUsed, sgs.CardResponded, sgs.EventPhaseStart}, function(self, event, room, p, data)
    if not p then return end
    if event == sgs.EventPhaseStart then
        if p:getPhase() == sgs.Player_Play then p:removeTag("hlxg_cidao_previous"); p:removeTag("hlxg_cidao_candidates") end
        return
    end
    if p:getPhase() ~= sgs.Player_Play then return end
    local use = data:toCardUse()
    if event == sgs.CardResponded then
        local response = data:toCardResponse()
        if not response.m_isUse then return end
        p:removeTag("hlxg_cidao_previous"); p:removeTag("hlxg_cidao_candidates"); return
    end
    if not use.card or use.card:isKindOf("SkillCard") then return end
    local previous, now, both = gu_names(p, "hlxg_cidao_previous"), {}, {}
    for _, q in sgs.qlist(use.to) do
        if q ~= p then
            table.insert(now, q:objectName())
            if table.contains(previous, q:objectName()) then table.insert(both, q:objectName()) end
        end
    end
    gu_setnames(p, "hlxg_cidao_previous", now)
    gu_setnames(p, "hlxg_cidao_candidates", both)
end)
hlxg_cidao = gu_trigger("hlxg_cidao", {sgs.CardUsed}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Play or p:getMark("hlxg_cidao_used-PlayClear") > 0 then return end
    local use = data:toCardUse()
    if not use.card or use.card:isKindOf("SkillCard") then return end
    local names = gu_names(p, "hlxg_cidao_candidates")
    local candidates = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getOtherPlayers(owner)) do
        if table.contains(names, q:objectName()) and not q:isAllNude() then candidates:append(q) end
    end
    if candidates:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_cidao", true, true)
    if not to then return end
    room:setPlayerMark(owner, "hlxg_cidao_used-PlayClear", 1)
    local id = room:askForCardChosen(owner, to, "hej", self:objectName())
    room:obtainCard(owner, id, false)
end)
hlxg_tanbei = gu_active("hlxg_tanbei", 1, 0, 0, gu_one, gu_one_feasible, function(self, room, source, targets)
    local to = targets[1]
    local choices = to:isAllNude() and "nolimit" or "get+nolimit"
    if room:askForChoice(to, "hlxg_tanbei", choices, sgs.QVariant(source:objectName())) == "get" then
        local id = room:askForCardChosen(source, to, "hej", "hlxg_tanbei")
        room:obtainCard(source, id, false)
        room:setPlayerMark(source, "hlxg_tanbei_block_" .. to:objectName() .. "-Clear", 1)
    else
        room:setPlayerMark(source, "hlxg_tanbei_free_" .. to:objectName() .. "-Clear", 1)
    end
end)
hlxg_tanbei_prohibit = sgs.CreateProhibitSkillV2 {
    name = "#hlxg_tanbei_prohibit", holder_selector = sgs.CorrectSkill_System,
    is_prohibited = function(self, ctx)
        local from, to = ctx:getFrom(), ctx:getTo()
        return from and to and from:getMark("hlxg_tanbei_block_" .. to:objectName() .. "-Clear") > 0
    end,
}
hlxg_tanbei_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_tanbei_mod", pattern = ".", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local from, to = ctx:getPrimary(), ctx:getSecondary()
        if from and to and from:getMark("hlxg_tanbei_free_" .. to:objectName() .. "-Clear") > 0
            and (ctx:getModType() == sgs.TargetModSkill_Residue or ctx:getModType() == sgs.TargetModSkill_DistanceLimit) then
            if ctx:getModType() == sgs.TargetModSkill_Residue then return sgs.CorrectSkillResult.unlimitedResidue() end
            return 1000
        end
        return false
    end,
}
hljx_jingce_record = gu_record("#hljx_jingce_record", {sgs.CardUsed, sgs.CardResponded}, function(self, event, room, p, data)
    local c
    if event == sgs.CardResponded then
        local response = data:toCardResponse()
        if not response.m_isUse then return end
        c = response.m_card
    else c = data:toCardUse().card end
    if p and c and not c:isKindOf("SkillCard") and c:getSuit() >= sgs.Card_Spade and c:getSuit() <= sgs.Card_Diamond then
        room:setPlayerMark(p, "hljx_jingce_suit" .. c:getSuit() .. "-Clear", 1)
    end
end)
hljx_jingce = gu_trigger("hljx_jingce", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Finish or not gu_invoke(owner, self:objectName()) then return end
    local n = 1
    for suit = sgs.Card_Spade, sgs.Card_Diamond do n = n + p:getMark("hljx_jingce_suit" .. suit .. "-Clear") end
    owner:drawCards(math.min(3, n), self:objectName())
end)
hlxg_guotufengji:addSkill(hlxg_jigong); hlxg_guotufengji:addSkill(hlxg_jigong_record); hlxg_guotufengji:addSkill(hlxg_jigong_max); hlxg_guotufengji:addSkill(hlxg_shifei)
hlxg_guosi:addSkill(hlxg_cidao); hlxg_guosi:addSkill(hlxg_cidao_record); hlxg_guosi:addSkill(hlxg_tanbei); hlxg_guosi:addSkill(hlxg_tanbei_prohibit); hlxg_guosi:addSkill(hlxg_tanbei_mod)
hljx_guohuai:addSkill(hljx_jingce); hljx_guohuai:addSkill(hljx_jingce_record)
extension_hl:insertRelatedSkills("hlxg_jigong", "#hlxg_jigong_record")
extension_hl:insertRelatedSkills("hlxg_jigong", "#hlxg_jigong_max")
extension_hl:insertRelatedSkills("hlxg_cidao", "#hlxg_cidao_record")
extension_hl:insertRelatedSkills("hlxg_tanbei", "#hlxg_tanbei_prohibit")
