-- ==================== c215_03
do
-- c215_03: literal Huanle changes; assembled in the GU helper scope.
hlxg_zhonghui = sgs.General(extension_hl, "hlxg_zhonghui", "wei", 4)
hlxg_zhongyao = sgs.General(extension_hl, "hlxg_zhongyao", "wei", 3)
hlxg_yanrou = sgs.General(extension_hl, "hlxg_yanrou", "wei", 4)

hlxg_paiyi = gu_active("hlxg_paiyi", 1, 0, 0,
    function(self, targets, to, from) return #targets == 0 end, gu_one_feasible,
    function(self, room, source, targets)
        local ids = source:getPile("hlxg_quanji")
        if ids:isEmpty() then return end
        room:fillAG(ids, source)
        local id = room:askForAG(source, ids, false, "hlxg_paiyi")
        room:clearAG(source)
        room:throwCard(id, "hlxg_paiyi", nil)
        local to = targets[1]
        if not to:isAlive() then return end
        to:drawCards(2, "hlxg_paiyi")
        if source:isAlive() and to:isAlive() and to:getHandcardNum() > source:getHandcardNum() then
            local d = sgs.DamageStruct(); d.from = source; d.to = to; d.damage = 1; d.reason = "hlxg_paiyi"
            room:damage(d)
        end
    end, nil, function(p) return not p:getPile("hlxg_quanji"):isEmpty() end)
hlxg_quanjiCard = sgs.CreateSkillCard {
    name = "hlxg_quanjiCard", target_fixed = true, will_throw = false,
    handling_method = sgs.Card_MethodNone,
    on_use = function(self, room, source) source:addToPile("hlxg_quanji", self:getSubcards()) end,
}
hlxg_quanji_store = sgs.CreateViewAsSkillV2 {
    name = "#hlxg_quanji_store", n = 5,
    can_activate = function(self, r)
        local p = r:getInitiator()
        return r:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY and p:hasSkill("hlxg_quanji")
            and p:getPile("hlxg_quanji"):length() < 5
    end,
    can_select_card = function(self, r, c)
        local p = r:getInitiator()
        return p:handCards():contains(c:getEffectiveId())
            and r:getSelectedCardIds():length() < 5 - p:getPile("hlxg_quanji"):length()
    end,
    card_selection_feasible = function(self, r)
        local n = r:getSelectedCardIds():length()
        return n > 0 and n <= 5 - r:getInitiator():getPile("hlxg_quanji"):length()
    end,
    create_card = function(self, r)
        local c = hlxg_quanjiCard:clone(); c:addSubcards(r:getSelectedCardIds()); c:setSkillName("hlxg_quanji")
        return c
    end,
}
hlxg_quanji = gu_trigger("hlxg_quanji", {sgs.Damaged}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    for i = 1, data:toDamage().damage do
        if owner:isAlive() and gu_invoke(owner, self:objectName(), data) then owner:drawCards(2, self:objectName()) end
    end
end)
hlxg_quanji_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_quanji_max",
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        return p and p:hasSkill("hlxg_quanji") and p:getPile("hlxg_quanji"):length() or 0
    end,
}

-- Record actual damage for every player, including before acquiring the skills.
hlxg_zuoding_record = gu_record("#hlxg_zuoding_record", {sgs.EventPhaseStart, sgs.DamageDone}, function(self, event, room, p, data)
    if event == sgs.EventPhaseStart then
        if p and p:getPhase() == sgs.Player_Play then room:setTag("hlxg_zuoding_damaged", sgs.QVariant(false)) end
    else
        local d = data:toDamage()
        if d.damage <= 0 then return end
        room:setTag("hlxg_zuoding_damaged", sgs.QVariant(true))
        if d.from then
            room:addPlayerMark(d.from, "hlxg_xiangshu_total", d.damage)
            room:addPlayerMark(d.from, "hlxg_xiangshu-Clear", d.damage)
        end
    end
end)
hlxg_zuoding = gu_trigger("hlxg_zuoding", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local u = data:toCardUse()
    if not p or p:getPhase() ~= sgs.Player_Play or u.from ~= p or not u.card
        or u.card:getSuit() ~= sgs.Card_Spade or u.card:isKindOf("SkillCard")
        or room:getTag("hlxg_zuoding_damaged"):toBool() or u.to:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, u.to, self:objectName(), "@hlxg_zuoding", true, true)
    if to then to:drawCards(1, self:objectName()) end
end)
hlxg_huomo = sgs.CreateViewAsSkillV2 {
    name = "hlxg_huomo", n = 1, response_or_use = true, guhuo_type = "b",
    can_activate = function(self, r)
        local p = r:getInitiator()
        return p and p:getMark("hlxg_huomo-Clear") < 2
            and (r:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
                or r:getReason() == sgs.CardUseStruct_CARD_USE_REASON_RESPONSE_USE)
    end,
    allow_declaration = function(self, p, name)
        local c = sgs.Sanguosha:cloneCard(name)
        if not c then return false end
        local ok = c:isKindOf("BasicCard"); c:deleteLater(); return ok
    end,
    can_select_card = function(self, r, c)
        return c and r:getSelectedCardIds():isEmpty() and c:isBlack() and not c:isKindOf("BasicCard")
            and r:getInitiator():getCards("he"):contains(c) and not c:hasFlag("using")
    end,
    card_selection_feasible = function(self, r) return r:getSelectedCardIds():length() == 1 end,
    build_card = function(self, r, name)
        local c = sgs.Sanguosha:cloneCard(name, sgs.Card_NoSuit, 0)
        if c then c:addSubcards(r:getSelectedCardIds()); c:setSkillName(self:objectName()) end
        return c
    end,
    pay = function(self, room, ctx, r)
        local p, ids = r:getInitiator(), r:getSelectedCardIds()
        if ids:length() ~= 1 or p:getMark("hlxg_huomo-Clear") >= 2 then return false end
        local c = sgs.Sanguosha:getCard(ids:first())
        if not c:isBlack() or c:isKindOf("BasicCard") or not p:getCards("he"):contains(c) then return false end
        room:addPlayerMark(p, "hlxg_huomo-Clear")
        local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_PUT, p:objectName(), self:objectName(), "")
        room:moveCardTo(c, p, nil, sgs.Player_DrawPile, reason, true)
        return true
    end,
    on_effect = function(self, ctx)
        if not ctx.use_card then return sgs.ViewAsSkillV2_FinishSkill end
        local c = sgs.Sanguosha:cloneCard(ctx.use_card:objectName(), sgs.Card_NoSuit, 0)
        c:setSkillName(self:objectName()); c:deleteLater(); ctx.updated_card = c
        return sgs.ViewAsSkillV2_ContinueEffects
    end,
}

hlxg_choutao = gu_trigger("hlxg_choutao", {sgs.TargetSpecified, sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    local u = data:toCardUse()
    if p ~= owner or not u.from or not u.card or not u.card:isKindOf("Slash") then return end
    if event == sgs.TargetSpecified and u.from ~= owner then return end
    if event == sgs.TargetConfirmed and not u.to:contains(owner) then return end
    if not owner:canDiscard(u.from, "he") or not gu_invoke(owner, self:objectName(), data) then return end
    local id = room:askForCardChosen(owner, u.from, "he", self:objectName(), false, sgs.Card_MethodDiscard)
    if id < 0 then return end
    room:throwCard(id, self:objectName(), u.from, owner)
    u = data:toCardUse()
    local key = "Jink_" .. u.card:toString()
    local jinks = u.from:getTag(key):toIntList()
    local result = sgs.IntList()
    for i = 0, u.to:length() - 1 do
        local blocked = event == sgs.TargetSpecified or u.to:at(i) == owner
        result:append(blocked and 0 or (i < jinks:length() and jinks:at(i) or 1))
    end
    u.from:setTag(key, sgs.QVariant(result))
    if u.from == owner then u.m_addHistory = false end
    data:setValue(u)
end)
hlxg_xiangshu = gu_trigger("hlxg_xiangshu", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Finish or owner:getMark("@hlxg_xiangshu") == 0
        or owner:getMark("hlxg_xiangshu-Clear") == 0 then return end
    local candidates = sgs.SPlayerList()
    for _, to in sgs.qlist(room:getAlivePlayers()) do if to:isWounded() then candidates:append(to) end end
    if candidates:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_xiangshu-target", true, true)
    if not to then return end
    room:removePlayerMark(owner, "@hlxg_xiangshu")
    local x = math.min(5, owner:getMark("hlxg_xiangshu_total"))
    local rec = sgs.RecoverStruct(); rec.who = owner; rec.recover = x
    room:recover(to, rec)
    if to:isAlive() then to:drawCards(x, self:objectName()) end
end, false, sgs.Skill_Limited, "@hlxg_xiangshu")

