do
-- c215_04: literal 欢乐杀修改 variants.
hlxg_hanze = sgs.General(extension_hl, "hlxg_hanze", "wu", 3)
hlxg_ruanyu = sgs.General(extension_hl, "hlxg_ruanyu", "wei", 3)
hlxg_lukang = sgs.General(extension_hl, "hlxg_lukang", "wu", 4)

hlxg_xiashu = gu_trigger("hlxg_xiashu", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_RoundStart then return end
    local to = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@hlxg_xiashu", true, true)
    if not to then return end
    gu_obtain(room, to, owner:handCards(), self:objectName())
    local shown = sgs.IntList()
    if not to:isKongcheng() then
        local c = room:askForExchange(to, self:objectName(), to:getHandcardNum(), 0, false, "@hlxg_xiashu-show", true)
        if c then shown = c:getSubcards(); room:showCard(to, shown); c:deleteLater() end
    end
    local choice = room:askForChoice(owner, self:objectName(), "shown+hidden")
    local ids = sgs.IntList()
    for _, id in sgs.qlist(to:handCards()) do
        if shown:contains(id) == (choice == "shown") then ids:append(id) end
    end
    gu_obtain(room, owner, ids, self:objectName())
end)
hlxg_kuanshi = gu_trigger("hlxg_kuanshi", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    local key = "hlxg_kuanshi_" .. owner:objectName()
    if p ~= owner then return end
    if p:getPhase() == sgs.Player_RoundStart then
        for _, to in sgs.qlist(room:getAllPlayers()) do room:setPlayerMark(to, key, 0); room:setPlayerMark(to, key .. "_damage", 0) end
    elseif p:getPhase() == sgs.Player_Finish then
        local to = room:askForPlayerChosen(owner, room:getAlivePlayers(), self:objectName(), "@hlxg_kuanshi", true, true)
        if to then room:setPlayerMark(to, key, 1); room:setPlayerMark(to, key .. "_damage", 0) end
    end
end)
hlxg_kuanshi_record = gu_record("#hlxg_kuanshi_record", {sgs.Damaged}, function(self, event, room, p, data)
    for _, owner in sgs.qlist(room:getAllPlayers()) do
        local key = "hlxg_kuanshi_" .. owner:objectName()
        if p:getMark(key) > 0 then
            local n = p:getMark(key .. "_damage") + data:toDamage().damage
            room:setPlayerMark(p, key .. "_damage", n % 2)
            for i = 1, math.floor(n / 2) do
                if p:isAlive() then local r = sgs.RecoverStruct(); r.who = owner; r.recover = 1; room:recover(p, r) end
            end
        end
    end
end)
hlxg_hanze:addSkill(hlxg_xiashu); hlxg_hanze:addSkill(hlxg_kuanshi); hlxg_hanze:addSkill(hlxg_kuanshi_record)
extension_hl:insertRelatedSkills("hlxg_kuanshi", "#hlxg_kuanshi_record")

hlxg_xingzuo = gu_trigger("hlxg_xingzuo", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if p:getPhase() == sgs.Player_Play and gu_invoke(owner, self:objectName()) then
        room:setPlayerMark(p, "hlxg_xingzuo-Clear", 1)
        local bottom = room:getNCards(3, false, false)
        local viewed = sgs.IntList()
        for _, id in sgs.qlist(bottom) do viewed:append(id) end
        room:notifyMoveToPile(p, bottom, "hlxg_xingzuo", sgs.Player_DrawPile, true, false)
        local c
        if not p:isKongcheng() then c = room:askForExchange(p, self:objectName(), math.min(3, p:getHandcardNum()), 0, false, "@hlxg_xingzuo", true) end
        local incoming = sgs.IntList()
        if c then
            for i = 1, c:subcardsLength() do
                room:fillAG(bottom, p)
                local id = room:askForAG(p, bottom, false, self:objectName()); room:clearAG(p); bottom:removeOne(id); incoming:append(id)
            end
        end
        room:notifyMoveToPile(p, viewed, "hlxg_xingzuo", sgs.Player_DrawPile, false, false)
        if c then
            local out = c:getSubcards()
            room:returnToEndDrawPile(bottom)
            bottom = sgs.IntList()
            room:moveCardsToEndOfDrawpile(p, out, self:objectName(), false)
            c:deleteLater()
        end
        room:returnToEndDrawPile(bottom)
        gu_obtain(room, p, incoming, self:objectName())
    elseif p:getPhase() == sgs.Player_Finish and p:getMark("hlxg_xingzuo-Clear") > 0 then
        local tos = sgs.SPlayerList()
        for _, to in sgs.qlist(room:getAlivePlayers()) do if not to:isKongcheng() then tos:append(to) end end
        if tos:isEmpty() then return end
        local to = room:askForPlayerChosen(p, tos, self:objectName(), "@hlxg_xingzuo-target", true, true)
        if to then
            local bottom = room:getNCards(3, false, false)
            room:moveCardsToEndOfDrawpile(to, to:handCards(), self:objectName(), false)
            gu_obtain(room, to, bottom, self:objectName())
        end
    end
end)

local function hl_black(p, c)
    if not c:isBlack() or not p:handCards():contains(c:getEffectiveId()) then return false end
    local n = 0
    for _, h in sgs.qlist(p:getHandcards()) do if h:isBlack() then n = n + 1 end end
    return n == 1
end
hlxg_miaoxian = sgs.CreateViewAsSkillV2 {
    name = "hlxg_miaoxian", guhuo_type = "r", response_or_use = true,
    can_activate = function(self, request)
        local reason = request:getReason()
        return (reason == sgs.CardUseStruct_CARD_USE_REASON_PLAY or reason == sgs.CardUseStruct_CARD_USE_REASON_RESPONSE_USE or request:getPattern() == "nullification")
            and request:getInitiator():getMark("hlxg_miaoxian-Clear") == 0
    end,
    can_select_card = function(self, request, c) return request:getSelectedCardIds():isEmpty() and hl_black(request:getInitiator(), c) end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    allow_declaration = function(self, p, name)
        local c = sgs.Sanguosha:cloneCard(name)
        if not c then return false end
        local ok = c:isNDTrick(); c:deleteLater(); return ok
    end,
}
hlxg_miaoxian.response_pattern = "nullification"
hlxg_miaoxian_record = gu_record("#hlxg_miaoxian_record", {sgs.CardUsed}, function(self, event, room, p, data)
    local c = data:toCardUse().card
    if not p or not c then return end
    if c:getSkillName() == "hlxg_miaoxian" then room:addPlayerMark(p, "hlxg_miaoxian-Clear") end
    if not p:hasSkill("hlxg_miaoxian") then return end
    if c:isRed() and (not c:isVirtualCard() or c:subcardsLength() == 1) then
        for _, h in sgs.qlist(p:getHandcards()) do if h:isRed() then return end end
        p:drawCards(1, "hlxg_miaoxian")
    end
end)
hlxg_ruanyu:addSkill(hlxg_miaoxian_record)
extension_hl:insertRelatedSkills("hlxg_miaoxian", "#hlxg_miaoxian_record")
hlxg_ruanyu:addSkill(hlxg_xingzuo); hlxg_ruanyu:addSkill(hlxg_miaoxian)

hlxg_jueyan = gu_active("hlxg_jueyan", 1, 0, 0, function() return false end, function(self, targets) return #targets == 0 end,
    function(self, room, p)
        local choices = {}
        if p:hasEquipArea(0) then table.insert(choices, "weapon") end
        if p:hasEquipArea(1) then table.insert(choices, "armor") end
        if p:hasEquipArea(2) or p:hasEquipArea(3) then table.insert(choices, "horses") end
        if #choices == 0 then return end
        local choice = room:askForChoice(p, "hlxg_jueyan", table.concat(choices, "+"))
        if choice == "weapon" then p:throwEquipArea(0); room:addPlayerMark(p, "hlxg_jueyan_slash-Clear", 3)
        elseif choice == "armor" then p:throwEquipArea(1); p:drawCards(3, "hlxg_jueyan"); room:addPlayerMark(p, "hlxg_jueyan_max-Clear", 3)
        else
            if p:hasEquipArea(2) then p:throwEquipArea(2) end
            if p:hasEquipArea(3) then p:throwEquipArea(3) end
            local r = sgs.RecoverStruct(); r.who = p; room:recover(p, r)
            room:setPlayerMark(p, "hlxg_jueyan_jizhi-PlayClear", 1)
            if not p:hasSkill("hlxg_jizhi_lukang") then room:acquireSkill(p, "hlxg_jizhi_lukang"); room:setPlayerMark(p, "hlxg_jueyan_granted-PlayClear", 1) end
        end
    end, nil, function(p) return p:hasEquipArea(0) or p:hasEquipArea(1) or p:hasEquipArea(2) or p:hasEquipArea(3) end)
hlxg_jueyan_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_jueyan_mod", pattern = ".", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local p, c = ctx:getPrimary(), ctx:getCard()
        if ctx:getModType() == sgs.TargetModSkill_DistanceLimit and p:getMark("hlxg_jueyan_jizhi-PlayClear") > 0 then return 999 end
        if ctx:getModType() == sgs.TargetModSkill_Residue and c and c:isKindOf("Slash") then return p:getMark("hlxg_jueyan_slash-Clear") end
        return 0
    end,
}
hlxg_jueyan_max = sgs.CreateMaxCardsSkillV2 {
