}
hlxg_jizhi_lukang = sgs.CreateTriggerSkillV2 {
    name = "hlxg_jizhi_lukang", events = {sgs.CardUsed},
    can_trigger = function(self, event, room, p, data)
        local c = data:toCardUse().card
