}
hlxg_jueyan_cleanup = gu_record("#hlxg_jueyan_cleanup", {sgs.EventPhaseEnd, sgs.EventPhaseChanging}, function(self, event, room, p, data)
    if ((event == sgs.EventPhaseEnd and p:getPhase() == sgs.Player_Play) or (event == sgs.EventPhaseChanging and data:toPhaseChange().from == sgs.Player_Play)) and p:getMark("hlxg_jueyan_granted-PlayClear") > 0 then
        room:setPlayerMark(p, "hlxg_jueyan_granted-PlayClear", 0)
        room:detachSkillFromPlayer(p, "hlxg_jizhi_lukang", false, true)
    end
end)
hlxg_lukang:addSkill(hlxg_jueyan_cleanup)
extension_hl:insertRelatedSkills("hlxg_jueyan", "#hlxg_jueyan_cleanup")
extension_hl:addSkills(hlxg_jizhi_lukang)
hlxg_huairou = sgs.CreateViewAsSkillV2 {
    name = "hlxg_huairou", guhuo_type = "lr", will_throw_selected_cards = false,
    can_activate = function(self, request) return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY end,
