-- ==================== c215_05
do
-- c215_05: literal 欢乐修改 / 欢乐界限突破 variants.
local function c215_05_give(room, owner, skill)
    if not owner:isAlive() or owner:isKongcheng() then return end
    local to = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), skill,
        "@" .. skill .. "-give", true, true)
    if not to then return end
    local card = room:askForExchange(owner, skill, 1, 1, false, "@" .. skill .. "-card", false)
    if card then room:obtainCard(to, card, false); card:deleteLater() end
end

hlxg_huaiju = sgs.CreateRuleSkillV2 {
    name = "hlxg_huaiju", global = true, frequency = sgs.Skill_Compulsory,
    priority = 3,
    events = {sgs.GameStart, sgs.DamageInflicted, sgs.DrawNCards},
    can_trigger = function(self, event, room, player, data)
        if not player or not player:isAlive() then return false end
        if (event == sgs.GameStart and player:hasSkill(self:objectName()))
            or (event ~= sgs.GameStart and player:getMark("@hlxg_huaiju") > 0) then
            return self:objectName(), player
        end
        return false
    end,
    on_effect = function(self, event, room, player, ctx)
        if event == sgs.GameStart then room:addPlayerMark(player, "@hlxg_huaiju", 3)
        elseif event == sgs.DamageInflicted then
            room:removePlayerMark(player, "@hlxg_huaiju", 1)
            return true
        else local draw = ctx.original_data:toDraw(); draw.num = draw.num + 1; ctx.original_data:setValue(draw) end
        return false
    end,
}
hlxg_zhenglun = gu_trigger("hlxg_zhenglun", {sgs.DrawNCards}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:getMark("@hlxg_huaiju") > 0 then return end
    if gu_invoke(owner, self:objectName(), data) then
        local draw = data:toDraw(); draw.num = math.max(0, draw.num - 1); data:setValue(draw)
        room:addPlayerMark(owner, "@hlxg_huaiju", 1)
    end
end)
hlxg_yili = gu_trigger("hlxg_yili", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:getPhase() ~= sgs.Player_Play then return end
    local others = room:getOtherPlayers(owner)
    if others:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, others, self:objectName(), "@hlxg_yili", true, true)
    if not to then return end
    local choices = "losehp"
    if owner:getMark("@hlxg_huaiju") > 0 then choices = choices .. "+orange" end
    if room:askForChoice(owner, self:objectName(), choices) == "orange" then
        room:removePlayerMark(owner, "@hlxg_huaiju", 1)
    else room:loseHp(owner, 1) end
    if to:isAlive() then room:addPlayerMark(to, "@hlxg_huaiju", 1) end
end)

hlxg_qianxun = gu_trigger("hlxg_qianxun", {sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or not use.card or not use.card:isKindOf("TrickCard")
