hlxg_cuike = gu_trigger("hlxg_cuike", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or p:getPhase() ~= sgs.Player_Play then return end
    local odd = owner:getMark("&hlxg_junlve") % 2 == 1
    local q = room:askForPlayerChosen(owner, room:getAlivePlayers(), self:objectName(), odd and "@hlxg_cuike-damage" or "@hlxg_cuike-chain", true, true)
    if q then
        if odd then room:damage(sgs.DamageStruct(self:objectName(), owner, q, 1))
        else
            room:setPlayerProperty(q, "chained", sgs.QVariant(true))
            if owner:canDiscard(q, "hej") then
                local id = room:askForCardChosen(owner, q, "hej", self:objectName(), false, sgs.Card_MethodDiscard)
                room:throwCard(id, self:objectName(), q, owner)
            end
        end
    end
    if owner:isAlive() and owner:getMark("&hlxg_junlve") > room:alivePlayerCount() and gu_invoke(owner, "hlxg_cuike", data) then
        room:setPlayerMark(owner, "&hlxg_junlve", 0)
        local tos = room:askForPlayersChosen(owner, room:getOtherPlayers(owner), self:objectName(), 0, room:alivePlayerCount() - 1, "@hlxg_cuike-all", true)
        for _, t in sgs.qlist(tos) do
            if t:isAlive() then room:damage(sgs.DamageStruct(self:objectName(), owner, t, 1)) end
        end
    end
end)
hlxg_zhanhuoCard = sgs.CreateSkillCard {
