    local target = hlxg_zhiwei_target(room, owner)
    if event == sgs.GameStart or (event == sgs.EventPhaseStart and p == owner and p:getPhase() == sgs.Player_Start and not target) then
        if event == sgs.GameStart and p ~= owner then return end
        local q = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@hlxg_zhiwei-select", event ~= sgs.GameStart, true)
        if q then owner:setTag("hlxg_zhiwei_target", sgs.QVariant(q:objectName())) end
    elseif event == sgs.Damage and p == target then owner:drawCards(1, self:objectName())
    elseif event == sgs.Damaged and p == target and not owner:isKongcheng() then
        local c = room:askForExchange(owner, self:objectName(), 1, 1, false, "@hlxg_zhiwei-give", true)
        if c then room:obtainCard(target, c, false); c:deleteLater() end
    elseif event == sgs.EventPhaseStart and p == owner and p:getPhase() == sgs.Player_Discard then
        owner:removeTag("hlxg_zhiwei_discard")
    elseif event == sgs.CardsMoveOneTime and owner:getPhase() == sgs.Player_Discard then
        local move = data:toMoveOneTime()
        if move.from and move.from:objectName() == owner:objectName() and bit32.band(move.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON) == sgs.CardMoveReason_S_REASON_DISCARD then
            local ids = gu_names(owner, "hlxg_zhiwei_discard")
