            gu_setnames(owner, "hlxg_zhiwei_discard", ids)
        end
    elseif event == sgs.EventPhaseEnd and p == owner and p:getPhase() == sgs.Player_Discard then
        local ids = sgs.IntList()
        for _, id in ipairs(gu_names(owner, "hlxg_zhiwei_discard")) do
            id = tonumber(id)
            if room:getCardPlace(id) == sgs.Player_DiscardPile then ids:append(id) end
        end
        owner:removeTag("hlxg_zhiwei_discard")
        if target and not ids:isEmpty() and gu_invoke(owner, self:objectName(), sgs.QVariant(target)) then gu_obtain(room, target, ids, self:objectName()) end
    end
end)
