-- ==================== c215_07
do
-- c215_07: forced Slashes ignore usage history, but retain range/prohibition legality.
local function c215_07_targets(from, slash)
    local result = sgs.SPlayerList()
    for _, to in sgs.qlist(from:getRoom():getAlivePlayers()) do
        if to ~= from and from:inMyAttackRange(to) and not from:isProhibited(to, slash)
            and not from:isCardLimited(slash, sgs.Card_MethodUse) then result:append(to) end
    end
    return result
end
local function c215_07_mingce(name, revised)
    return gu_trigger(name, {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
        if p ~= owner or p:getPhase() ~= sgs.Player_Play then return end
        local slash = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0)
        slash:setSkillName(name)
        local sources = sgs.SPlayerList()
        for _, q in sgs.qlist(room:getAlivePlayers()) do
            if (revised or q ~= owner) and not c215_07_targets(q, slash):isEmpty() then sources:append(q) end
        end
        if not revised and sources:isEmpty() then slash:deleteLater(); return end
        if not gu_invoke(owner, name, data) then slash:deleteLater(); return end
        local choice = "slash"
        if revised then
            choice = room:askForChoice(owner, name, sources:isEmpty() and "draw" or "slash+draw")
        end
        if choice == "draw" then
            local to = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), name, "@hljx_mingce-draw")
            if to then
                room:addPlayerMark(to, "&hljx_mingce_pending")
                owner:drawCards(1, name)
                if to:isAlive() then to:drawCards(1, name) end
            end
        else
            local from = room:askForPlayerChosen(owner, sources, name, "@" .. name .. "-source")
            if from then
                local tos = c215_07_targets(from, slash)
                if not tos:isEmpty() then
                    local to = room:askForPlayerChosen(owner, tos, name, "@" .. name .. "-target")
                    if to then
                        if revised then slash:setTag("hljx_mingce_owner", sgs.QVariant(owner:objectName())) end
                        local use = sgs.CardUseStruct()
                        use.card = slash; use.from = from; use.to:append(to)
                        room:useCard(use, false)
                    end
                end
            end
        end
        slash:deleteLater()
    end)
end
hlxg_mingce = c215_07_mingce("hlxg_mingce", false)
hljx_mingce = c215_07_mingce("hljx_mingce", true)
local function c215_07_zhichi(name, revised)
    return gu_trigger(name, {sgs.Damaged, sgs.CardEffected, sgs.DamageInflicted}, function(self, event, room, p, data, owner)
        if p ~= owner then return end
        if event == sgs.Damaged then
            if owner:getPhase() == sgs.Player_NotActive then
                room:setPlayerMark(owner, "&" .. name .. "-Clear", 1)
                room:sendCompulsoryTriggerLog(owner, name, true)
            end
        elseif owner:getMark("&" .. name .. "-Clear") > 0 then
            if event == sgs.DamageInflicted then return revised end
            local card = data:toCardEffect().card
            return card and (card:isNDTrick() or (not revised and card:isKindOf("Slash")))
        end
    end, true)
end
