hlxg_fenming = gu_trigger("hlxg_fenming", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:getPhase() ~= sgs.Player_Finish or not gu_invoke(owner, self:objectName(), data) then return end
    local targets = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getAlivePlayers()) do if q:isChained() then targets:append(q) end end
    local n = 0
    for _, q in sgs.qlist(targets) do
        if owner:isAlive() and q:isAlive() and owner:canDiscard(q, "he") then
            local id = room:askForCardChosen(owner, q, "he", self:objectName(), false, sgs.Card_MethodDiscard)
            room:throwCard(id, self:objectName(), q, owner)
            n = n + 1 -- A discarded card still counts if a move trigger relocates it.
        end
    end
    if owner:isAlive() and n > 0 then owner:drawCards(n, self:objectName()) end
end)
