hlxg_jiuxianCard = sgs.CreateSkillCard {
    name = "hlxg_jiuxianCard",
    will_throw = false,
    handling_method = sgs.Card_MethodRecast,
    filter = function(self, targets, to, from)
        local duel = sgs.Sanguosha:cloneCard("duel")
        duel:setSkillName("hlxg_jiuxian")
        local list = sgs.PlayerList()
        for _, p in ipairs(targets) do list:append(p) end
        local valid = not from:isProhibited(to, duel, list) and duel:targetFilter(list, to, from)
        duel:deleteLater()
        return valid
    end,
    feasible = function(self, targets, from)
        local duel = sgs.Sanguosha:cloneCard("duel")
        duel:setSkillName("hlxg_jiuxian")
        local list = sgs.PlayerList()
        for _, p in ipairs(targets) do list:append(p) end
        local valid = duel:targetsFeasible(list, from)
        duel:deleteLater()
        return valid
    end,
    on_validate = function(self, use)
        local source = use.from
        local room = source:getRoom()
        local count = self:subcardsLength()
        if count > 0 then
            local log = sgs.LogMessage()
            log.type = "$RecastCard"
            log.from = source
            log.card_str = self:subcardString()
            room:sendLog(log)
            local reason = sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_RECAST,
                source:objectName(), "hlxg_jiuxian", "")
            room:moveCardTo(self, source, nil, sgs.Player_DiscardPile, reason, true)
            source:drawCards(count, "hlxg_jiuxian")
        end
        local duel = sgs.Sanguosha:cloneCard("duel")
        duel:setSkillName("_hlxg_jiuxian")
        duel:setTag("hlxg_jiuxian_owner", sgs.QVariant(source:objectName()))
        for _, p in sgs.qlist(use.to) do
            room:setCardFlag(duel, "hlxg_jiuxian_target_" .. p:objectName())
        end
        return duel
    end,
}
hlxg_jiuxian = sgs.CreateViewAsSkillV2 {
    name = "hlxg_jiuxian",
    n = 999,
    limit_scope = sgs.Skill_Limit_Phase,
    phase_name = "Play",
    max_usage_limit = 1,
    can_activate = function(self, request)
        local p = request:getInitiator()
        if not p or request:getReason() ~= sgs.CardUseStruct_CARD_USE_REASON_PLAY then return false end
        local duel = sgs.Sanguosha:cloneCard("duel")
        duel:setSkillName("hlxg_jiuxian")
        local available = duel:isAvailable(p)
        duel:deleteLater()
        return available
    end,
    can_select_card = function(self, request, card)
        local p = request:getInitiator()
        return p and p:getHandcards():contains(card)
            and not p:isCardLimited(card, sgs.Card_MethodRecast, true)
            and request:getSelectedCardIds():length() < math.ceil(p:getHandcardNum() / 2)
    end,
    card_selection_feasible = function(self, request)
        local p = request:getInitiator()
        return p and request:getSelectedCardIds():length() <= math.ceil(p:getHandcardNum() / 2)
    end,
    create_card = function(self, request)
        local card = hlxg_jiuxianCard:clone()
        card:addSubcards(request:getSelectedCardIds())
        card:setSkillName("hlxg_jiuxian")
        return card
    end,
}
hlxg_jiuxian_heal = gu_trigger("#hlxg_jiuxian_heal", {sgs.Damage},
    function(self, event, room, player, data, owner)
        local damage = data:toDamage()
        if not damage.card or not damage.to
            or damage.card:getTag("hlxg_jiuxian_owner"):toString() ~= owner:objectName()
            or not damage.card:hasFlag("hlxg_jiuxian_target_" .. damage.to:objectName()) then return end
        local candidates = sgs.SPlayerList()
        for _, p in sgs.qlist(room:getOtherPlayers(damage.to)) do
            if p:isWounded() and damage.to:inMyAttackRange(p) then candidates:append(p) end
        end
        if candidates:isEmpty() then return end
        local target = room:askForPlayerChosen(owner, candidates, "hlxg_jiuxian", "@hlxg_jiuxian", true, true)
        if target then room:recover(target, sgs.RecoverStruct(owner, nil, 1)) end
    end)

hlxg_chenyong_record = gu_record("#hlxg_chenyong_record", {sgs.CardUsed, sgs.CardResponded},
    function(self, event, room, player, data)
        if not player or player:getPhase() == sgs.Player_NotActive then return end
        local card
        if event == sgs.CardUsed then card = data:toCardUse().card
        else
            local response = data:toCardResponse()
            if response.m_isUse then card = response.m_card end
        end
        if not card or card:isKindOf("SkillCard") then return end
        local mark = "hlxg_chenyong_type" .. card:getTypeId() .. "-Clear"
        if player:getMark(mark) == 0 then
            room:setPlayerMark(player, mark, 1)
            room:addPlayerMark(player, "&hlxg_chenyong-Clear", 1)
        end
    end)
extension_hl:addSkills(hlxg_chenyong_record)
