hlxg_bifa = gu_trigger("hlxg_bifa", {sgs.EventPhaseStart}, function(self, event, room, player, data, owner)
    if player ~= owner or player:getPhase() ~= sgs.Player_Finish or owner:isKongcheng() then return end
    local targets = sgs.SPlayerList()
    for _, p in sgs.qlist(room:getOtherPlayers(owner)) do
        if p:getPile("hlxg_bifa"):isEmpty() then targets:append(p) end
    end
    if targets:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, targets, "hlxg_bifa", "@hlxg_bifa-target", true, true)
    if not to then return end
    local card = room:askForExchange(owner, "hlxg_bifa", 1, 1, false, "@hlxg_bifa-put", true)
    if not card then return end
    to:setTag("hlxg_bifa_source", sgs.QVariant(owner:objectName()))
    to:addToPile("hlxg_bifa", card, false)
end)
-- Settlement survives loss of the source skill and the source's death.
hlxg_bifa_settle = sgs.CreateRuleSkillV2 {
    name = "#hlxg_bifa_settle", global = true, frequency = sgs.Skill_Compulsory,
    events = {sgs.EventPhaseStart},
    can_trigger = function(self, event, room, player, data)
        if player and player:isAlive() and player:getPhase() == sgs.Player_RoundStart
            and not player:getPile("hlxg_bifa"):isEmpty() then return self:objectName(), player end
        return false
    end,
    on_effect = function(self, event, room, player, ctx)
        local id = player:getPile("hlxg_bifa"):first()
        local card = sgs.Sanguosha:getCard(id)
        local source = room:findPlayerByObjectName(player:getTag("hlxg_bifa_source"):toString(), true)
        player:removeTag("hlxg_bifa_source")
        room:fillAG(player:getPile("hlxg_bifa"), player)
        local pattern = card:isKindOf("BasicCard") and "BasicCard" or card:isKindOf("TrickCard") and "TrickCard" or "EquipCard"
        local give
        if source and source:isAlive() then
            give = room:askForCard(player, pattern .. "|.|.|hand", "@hlxg_bifa-give", sgs.QVariant(source), sgs.Card_MethodNone, source, false, "hlxg_bifa")
        end
        room:clearAG(player)
        if give then
            room:obtainCard(source, give, false)
            if player:getPile("hlxg_bifa"):contains(id) then room:obtainCard(player, id, false) end
        else
            room:throwCard(id, "hlxg_bifa", nil)
            room:loseHp(player, 1, true, source, "hlxg_bifa")
        end
        return false
    end,
}
hlxg_chenlin:addSkill(hlxg_bifa)
