hlxg_wangzu = gu_trigger("hlxg_wangzu", {sgs.DamageInflicted}, function(self, event, room, player, data, owner)
    local damage = data:toDamage()
    if player ~= owner or damage.damage <= 0 or not damage.from or damage.from == owner or owner:getMark("hlxg_wangzu-Clear") > 0 then return end
    local legal = {}
    for _, c in sgs.qlist(owner:getHandcards()) do if owner:canDiscard(owner, c:getEffectiveId()) then table.insert(legal, c:getEffectiveId()) end end
    if #legal == 0 then return end
    local function campSize(p)
        local n = 1
        for _, q in sgs.qlist(room:getOtherPlayers(p)) do if q:isYourFriend(p) then n = n + 1 end end
        return n
    end
    local most, size = true, campSize(owner)
    for _, q in sgs.qlist(room:getAlivePlayers()) do if campSize(q) > size then most = false end end
    local id
    if most then
        local card = room:askForCard(owner, ".|.|.|hand", "@hlxg_wangzu-discard", data, sgs.Card_MethodNone, nil, false, "hlxg_wangzu")
        if not card or not owner:canDiscard(owner, card:getEffectiveId()) then return end
        id = card:getEffectiveId()
    else
        if not gu_invoke(owner, "hlxg_wangzu", data) then return end
        id = legal[math.random(#legal)]
    end
    room:addPlayerMark(owner, "hlxg_wangzu-Clear")
    room:throwCard(id, "hlxg_wangzu", owner)
    damage.damage = damage.damage - 1
    data:setValue(damage)
    return damage.damage <= 0
end)
hlxg_chendeng:addSkill(hlxg_wangzu)

hlxg_yingshuo = gu_active("hlxg_yingshuo", nil, 1, 1,
    function(self, targets, to, from)
