        room:obtainCard(to, self, false)
        if not to:isAlive() or not source:isAlive() then return end
        local n = 0
        for _, c in sgs.qlist(to:getCards("he")) do if c:isKindOf("EquipCard") then n = n + 1 end end
        local choice = n >= 2 and room:askForChoice(to, "hlxg_yingshuo", "damage+give", sgs.QVariant(source)) or "damage"
        if choice == "give" then
            local cards = room:askForExchange(to, "hlxg_yingshuo", n, 2, true, "@hlxg_yingshuo-give", false, "EquipCard")
            if cards then room:obtainCard(source, cards, false) end
        else
            room:damage(sgs.DamageStruct("hlxg_yingshuo", source, to, 1))
            room:setPlayerMark(source, "hlxg_yingshuo-PlayClear", 0)
        end
    end,
    function(request, c) return request:getInitiator():getCards("he"):contains(c) end,
    function(p) return p:getMark("hlxg_yingshuo-PlayClear") == 0 and not p:isNude() end)
hlxg_chendeng:addSkill(hlxg_yingshuo)

hlxg_pindi = gu_active("hlxg_pindi", nil, 1, 1,
    function(self, targets, to, from)
        return gu_one(self, targets, to, from) and to:getMark("hlxg_pindi_" .. from:objectName() .. "-Clear") == 0
    end, gu_one_feasible,
    function(self, room, source, targets)
        local to = targets[1]
        local c = sgs.Sanguosha:getCard(self:getSubcards():first())
        room:setPlayerMark(source, "hlxg_pindi_type" .. c:getTypeId() .. "-Clear", 1)
        room:setPlayerMark(to, "hlxg_pindi_" .. source:objectName() .. "-Clear", 1)
        room:addPlayerMark(source, "hlxg_pindi_count-Clear")
        local n = source:getMark("hlxg_pindi_count-Clear")
        gu_throw(room, source, self:getSubcards(), "hlxg_pindi")
        if not source:isAlive() or not to:isAlive() then return end
        if room:askForChoice(source, "hlxg_pindi", "draw+discard", sgs.QVariant(to)) == "draw" then to:drawCards(n, "hlxg_pindi")
        else room:askForDiscard(to, "hlxg_pindi", n, n, false, true) end
        if source:isAlive() and to:isWounded() and not source:isChained() then room:setPlayerChained(source, true) end
    end,
    function(request, c)
        local p = request:getInitiator()
        return p:getCards("he"):contains(c) and p:canDiscard(p, c:getEffectiveId())
            and p:getMark("hlxg_pindi_type" .. c:getTypeId() .. "-Clear") == 0
    end)
hlxg_chenqun:addSkill(hlxg_pindi)

hlxg_faen = gu_trigger("hlxg_faen", {sgs.TurnedOver, sgs.ChainStateChanged, sgs.DamageInflicted}, function(self, event, room, player, data, owner)
    if not player or not player:isAlive() then return end
    if event == sgs.DamageInflicted then
        local damage = data:toDamage()
        if damage.damage <= 0 or not player:isChained() or not owner:canDiscard(owner, "he") then return end
        if room:askForCard(owner, ".", "@hlxg_faen-prevent:" .. player:objectName(), data, sgs.Card_MethodDiscard, nil, false, "hlxg_faen") then
            damage.damage = 0
            data:setValue(damage)
            return true
        end
    elseif (event == sgs.TurnedOver or player:isChained()) and gu_invoke(owner, "hlxg_faen", sgs.QVariant(player)) then
        player:drawCards(1, "hlxg_faen")
    end
end)
hlxg_chenqun:addSkill(hlxg_faen)

