do
-- c216_02: literal 欢乐杀修改 variants.
hlxg_taoqian = sgs.General(extension_hl, "hlxg_taoqian", "qun", 3)
hlxg_leitong = sgs.General(extension_hl, "hlxg_leitong", "shu", 4)
hlxg_hanhaoshihuan = sgs.General(extension_hl, "hlxg_hanhaoshihuan", "wei", 4)

hlxg_yixiang_record = gu_record("#hlxg_yixiang_record", {sgs.PreCardUsed, sgs.CardFinished}, function(self, event, room, player, data)
    local use = data:toCardUse()
    if not use.card then return end
    if event == sgs.CardFinished then
        room:setCardFlag(use.card, "-hlxg_yixiang_first")
        room:setCardFlag(use.card, "-hlxg_yixiang_second")
    elseif use.from and use.from:getPhase() == sgs.Player_Play then
        room:addPlayerMark(use.from, "hlxg_yixiang_count-PlayClear")
        local n = use.from:getMark("hlxg_yixiang_count-PlayClear")
        if n == 1 then room:setCardFlag(use.card, "hlxg_yixiang_first") end
        if n == 2 then room:setCardFlag(use.card, "hlxg_yixiang_second") end
    end
end)
hlxg_yixiang = gu_trigger("hlxg_yixiang", {sgs.DamageInflicted, sgs.TargetConfirmed}, function(self, event, room, player, data, owner)
    if event == sgs.DamageInflicted then
        local d = data:toDamage()
        if d.to ~= owner or not d.from or d.from == owner or d.from:getPhase() ~= sgs.Player_Play
            or not d.card or not d.card:hasFlag("hlxg_yixiang_first") then return end
        room:sendCompulsoryTriggerLog(owner, self:objectName(), true)
        d.damage = d.damage - 1
        data:setValue(d)
        return d.damage <= 0
    end
    local use = data:toCardUse()
    if player ~= owner or not use.from or use.from == owner or use.from:getPhase() ~= sgs.Player_Play
        or not use.card or not use.card:isBlack() or not use.card:hasFlag("hlxg_yixiang_second")
        or not use.to:contains(owner) then return end
    room:sendCompulsoryTriggerLog(owner, self:objectName(), true)
    local nullified = use.nullified_list
    if not table.contains(nullified, owner:objectName()) then table.insert(nullified, owner:objectName()) end
    use.nullified_list = nullified
    data:setValue(use)
end, true)
hlxg_zhaohuo = gu_trigger("hlxg_zhaohuo", {sgs.EnterDying}, function(self, event, room, player, data, owner)
    local dying = data:toDying()
    if not dying.who or dying.who == owner or owner:getMaxHp() <= 1 then return end
    room:sendCompulsoryTriggerLog(owner, self:objectName(), true)
    local n = owner:getMaxHp() - 1
    room:loseMaxHp(owner, n)
    if owner:isAlive() then owner:drawCards(2 * n, self:objectName()) end
end, true)
hlxg_yirang = gu_trigger("hlxg_yirang", {sgs.EventPhaseStart}, function(self, event, room, player, data, owner)
    if player ~= owner or owner:getPhase() ~= sgs.Player_Play then return end
    local ids = sgs.IntList()
    for _, c in sgs.qlist(owner:getCards("he")) do
        if not c:isKindOf("BasicCard") then ids:append(c:getEffectiveId()) end
    end
    if ids:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@hlxg_yirang", true, true)
    if not to then return end
    local n = ids:length()
    local gift = gu_dummy(ids)
    room:giveCard(owner, to, gift, self:objectName())
    gift:deleteLater()
    if owner:isAlive() and to:getMaxHp() > owner:getMaxHp() then
        room:gainMaxHp(owner, to:getMaxHp() - owner:getMaxHp())
        room:recover(owner, sgs.RecoverStruct(self:objectName(), owner, n))
    end
end)
hlxg_taoqian:addSkill(hlxg_yixiang)
hlxg_taoqian:addSkill(hlxg_yixiang_record)
hlxg_taoqian:addSkill(hlxg_zhaohuo)
hlxg_taoqian:addSkill(hlxg_yirang)
extension_hl:insertRelatedSkills("hlxg_yixiang", "#hlxg_yixiang_record")

hlxg_kuijiCard = sgs.CreateSkillCard {
    name = "hlxg_kuijiCard", target_fixed = true, will_throw = false,
    on_use = function(self, room, source, targets)
        local original = sgs.Sanguosha:getCard(self:getSubcards():first())
        local supply = sgs.Sanguosha:cloneCard("supply_shortage", original:getSuit(), original:getNumber())
        supply:setSkillName("hlxg_kuiji")
        local wrapped = sgs.Sanguosha:getWrappedCard(original:getEffectiveId())
        wrapped:takeOver(supply)
        room:broadcastUpdateCard(room:getAllPlayers(true), wrapped:getEffectiveId(), wrapped)
        room:moveCardTo(wrapped, source, source, sgs.Player_PlaceDelayedTrick,
            sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_PUT, source:objectName(), "", "hlxg_kuiji", ""), true)
        supply:deleteLater()
        if source:isDead() then return end
        source:drawCards(2, "hlxg_kuiji")
        if source:isDead() then return end
        local candidates, maximum = sgs.SPlayerList(), -10000
        for _, p in sgs.qlist(room:getOtherPlayers(source)) do maximum = math.max(maximum, p:getHp()) end
        for _, p in sgs.qlist(room:getOtherPlayers(source)) do if p:getHp() == maximum then candidates:append(p) end end
        if candidates:isEmpty() then return end
        local to = room:askForPlayerChosen(source, candidates, "hlxg_kuiji", "@hlxg_kuiji", true, true)
        if to then room:damage(sgs.DamageStruct("hlxg_kuiji", source, to, 2)) end
    end,
}
hlxg_kuiji = sgs.CreateViewAsSkillV2 {
    name = "hlxg_kuiji", limit_scope = sgs.Skill_Limit_Phase, phase_name = "Play", max_usage_limit = 1,
    can_activate = function(self, request) return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY end,
    can_select_card = function(self, request, c)
        return request:getSelectedCardIds():isEmpty() and c:isBlack() and c:isKindOf("BasicCard")
            and request:getInitiator():getHandcards():contains(c)
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        local card = hlxg_kuijiCard:clone()
        card:addSubcards(request:getSelectedCardIds()); card:setSkillName("hlxg_kuiji")
        return card
    end,
}
hlxg_kuiji_dying = gu_trigger("#hlxg_kuiji_dying", {sgs.EnterDying}, function(self, event, room, player, data, owner)
    local dying = data:toDying()
    if not dying.damage or dying.damage.reason ~= "hlxg_kuiji" or dying.damage.from ~= owner then return end
    local to = room:askForPlayerChosen(owner, room:getAlivePlayers(), "hlxg_kuiji", "@hlxg_kuiji-recover", true, true)
    if to then room:recover(to, sgs.RecoverStruct("hlxg_kuiji", owner, 1)) end
end)
