hlxg_yonglve = gu_trigger("hlxg_yonglve", {sgs.EventPhaseStart}, function(self, event, room, player, data, owner)
    if not player or player == owner or player:getPhase() ~= sgs.Player_Judge or player:getJudgingArea():isEmpty() then return end
    local choices = {}
    if owner:canDiscard(player, "j") then table.insert(choices, "judge") end
    if owner:canDiscard(owner, "he") then table.insert(choices, "self") end
    if #choices == 0 or not gu_invoke(owner, self:objectName(), data) then return end
    local choice = room:askForChoice(owner, self:objectName(), table.concat(choices, "+"), ToData(player))
    if choice == "judge" then
        local id = room:askForCardChosen(owner, player, "j", self:objectName(), false, sgs.Card_MethodDiscard)
        room:throwCard(sgs.Sanguosha:getCard(id), player, owner)
    else
        if not room:askForDiscard(owner, self:objectName(), 1, 1, false, true) then return end
    end
    if owner:isDead() or player:isDead() then return end
    if owner:inMyAttackRange(player) then owner:drawCards(1, self:objectName())
    else
        local slash = sgs.Sanguosha:cloneCard("slash", sgs.Card_NoSuit, 0)
        slash:setSkillName(self:objectName())
        if owner:canSlash(player, slash, false) then
            local use = sgs.CardUseStruct(); use.card = slash; use.from = owner; use.to:append(player)
            room:useCard(use, false)
        end
        slash:deleteLater()
    end
end)
hlxg_shenduan_vs = sgs.CreateViewAsSkillV2 {
    name = "hlxg_shenduan", expand_pile = "#hlxg_shenduan",
    can_activate = function(self, request) return request:getPattern() == "@@hlxg_shenduan" end,
    can_select_card = function(self, request, card)
        return request:getSelectedCardIds():isEmpty() and request:getInitiator():getPile("#hlxg_shenduan"):contains(card:getEffectiveId())
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        if request:getSelectedCardIds():length() ~= 1 then return nil end
        local original = sgs.Sanguosha:getCard(request:getSelectedCardIds():first())
        local c = sgs.Sanguosha:cloneCard("supply_shortage", original:getSuit(), original:getNumber())
        c:addSubcard(original); c:setSkillName("hlxg_shenduan")
        return c
    end,
}
hlxg_shenduan = gu_trigger("hlxg_shenduan", {sgs.CardsMoveOneTime}, function(self, event, room, player, data, owner)
    local move = data:toMoveOneTime()
    if not move.from or move.from:objectName() ~= owner:objectName() or move.to_place ~= sgs.Player_DiscardPile
        or bit32.band(move.reason.m_reason, sgs.CardMoveReason_S_MASK_BASIC_REASON) ~= sgs.CardMoveReason_S_REASON_DISCARD then return end
    -- Each discarded card is independently optional; refresh the remaining discard-pile cards after each use.
    local pending = sgs.IntList()
    for i, id in sgs.qlist(move.card_ids) do
        local c = sgs.Sanguosha:getCard(id)
        local place = move.from_places:at(i)
        if (place == sgs.Player_PlaceHand or place == sgs.Player_PlaceEquip) and c:isBlack() and not c:isKindOf("TrickCard")
            and room:getCardPlace(id) == sgs.Player_DiscardPile then pending:append(id) end
    end
    while owner:isAlive() and not pending:isEmpty() do
        local available = sgs.IntList()
        for _, id in sgs.qlist(pending) do if room:getCardPlace(id) == sgs.Player_DiscardPile then available:append(id) end end
        if available:isEmpty() then break end
        room:notifyMoveToPile(owner, available, "hlxg_shenduan", sgs.Player_PlaceUnknown, true)
        local used = room:askForUseCard(owner, "@@hlxg_shenduan", "@hlxg_shenduan")
        room:notifyMoveToPile(owner, available, "hlxg_shenduan", sgs.Player_PlaceUnknown, false)
        if not used then break end
        pending = sgs.IntList()
        for _, id in sgs.qlist(available) do
            if not used:getSubcards():contains(id) and used:getEffectiveId() ~= id then pending:append(id) end
        end
    end
end)
-- The trigger and its view-as component share the public skill name.
hlxg_shenduan:setViewAsSkill(hlxg_shenduan_vs)
hlxg_shenduan_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_shenduan_mod", pattern = "SupplyShortage", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local card = ctx:getCard()
        if card and card:getSkillName() == "hlxg_shenduan" and ctx:getModType() == sgs.TargetModSkill_DistanceLimit then return 1000 end
        return 0
    end,
}
