-- ==================== c216_03
do
-- c216_03: independent conversions retain the ordinary card's targeting rules.
local function c216_convert(name, cardname, select, enabled)
    return sgs.CreateViewAsSkillV2 {
        name = name, n = 1, response_or_use = true, history_key = cardname == "slash" and "Slash" or cardname == "duel" and "Duel" or "Snatch",
        can_activate = function(self, request) return enabled(request) end,
        can_select_card = function(self, request, card)
            return request:getSelectedCardIds():isEmpty() and not card:hasFlag("using") and select(request:getInitiator(), card)
        end,
        card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
        create_card = function(self, request)
            local material = sgs.Sanguosha:getCard(request:getSelectedCardIds():first())
            local card = sgs.Sanguosha:cloneCard(cardname, material:getSuit(), material:getNumber())
            card:addSubcard(material); card:setSkillName(name)
            return card
        end,
    }
end
local function c216_play(request) return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY end
hlxg_hansui = sgs.General(extension_hl, "hlxg_hansui", "qun", 4)
hlxg_weiwu = c216_convert("hlxg_weiwu", "snatch", function(p, c) return c:isRed() and p:getCards("he"):contains(c) end,
    function(r) return c216_play(r) and r:getInitiator():getMark("hlxg_weiwu-PlayClear") == 0 end)
hlxg_weiwu_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_weiwu_mod", pattern = "Snatch", holder_selector = sgs.CorrectSkill_Primary,
    correct_func = function(self, ctx)
        local c = ctx:getCard()
        if c and c:getSkillName() == "hlxg_weiwu" and ctx:getModType() == sgs.TargetModSkill_DistanceLimit then return 1000 end
        return false
    end,
}
