hlxg_niluan_record = gu_record("#hlxg_niluan_record", {sgs.PreCardUsed, sgs.Damage, sgs.CardFinished}, function(self, event, room, p, data)
    if event == sgs.Damage then
        local d = data:toDamage()
        if d.card and d.card:isKindOf("Slash") and d.from and d.card:getTag("c216_niluan_owner"):toString() == d.from:objectName() then
            d.card:setTag("c216_niluan_damage", sgs.QVariant(true))
