        if use.card:getSkillName() == "hlxg_weiwu" then room:addPlayerMark(use.from, "hlxg_weiwu-PlayClear") end
        if use.card:isKindOf("Slash") then
            use.card:setTag("c216_niluan_damage", sgs.QVariant(false))
            use.card:setTag("c216_niluan_owner", sgs.QVariant(use.from:hasSkill("hlxg_niluan") and use.from:objectName() or ""))
        end
    elseif use.card:isKindOf("Slash") and use.card:getTag("c216_niluan_owner"):toString() == use.from:objectName() then
        if not use.card:getTag("c216_niluan_damage"):toBool() then use.m_addHistory = false; data:setValue(use) end
        use.card:removeTag("c216_niluan_owner"); use.card:removeTag("c216_niluan_damage")
    end
end)
