hlxg_bingyi = gu_trigger("hlxg_bingyi", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:getPhase() ~= sgs.Player_Finish or owner:isKongcheng() or not gu_invoke(owner, self:objectName()) then return end
    local cards = owner:getHandcards()
    local first = cards:first()
    local samecolor, samenumber = true, true
    for _, c in sgs.qlist(cards) do
        if c:getColor() ~= first:getColor() then samecolor = false end
        if c:getNumber() ~= first:getNumber() then samenumber = false end
    end
    room:showAllCards(owner)
    if samecolor then
        local tos = room:askForPlayersChosen(owner, room:getAlivePlayers(), self:objectName(), 0, cards:length(), "@hlxg_bingyi", true)
        for _, q in sgs.qlist(tos) do if q:isAlive() then q:drawCards(1, self:objectName()) end end
        if samenumber and owner:isAlive() then owner:drawCards(1, self:objectName()) end
    end
end)
