hljx_shuangxiong_vs = c216_convert("hljx_shuangxiong", "duel", function(p, c)
    return p:handCards():contains(c:getEffectiveId()) and ((p:getMark("hljx_shuangxiong_color-Clear") == 1 and c:isBlack()) or (p:getMark("hljx_shuangxiong_color-Clear") == 2 and c:isRed()))
end, function(r)
    return c216_play(r) and r:getInitiator():getMark("hljx_shuangxiong_color-Clear") > 0 and r:getInitiator():getMark("hljx_shuangxiong_used-Clear") < 3
end)
hljx_shuangxiong = sgs.CreateTriggerSkillV2 {
    name = "hljx_shuangxiong", events = {sgs.EventPhaseStart, sgs.Damaged}, view_as_skill = hljx_shuangxiong_vs,
    can_trigger = function(self, event, room, p, data)
        if not p or not p:isAlive() or not p:hasSkill(self:objectName()) then return false end
        if event == sgs.EventPhaseStart then return p:getPhase() == sgs.Player_Draw and self:objectName() or false end
        local d = data:toDamage()
        return d.card and d.card:isKindOf("Duel") and d.card:getSkillName() == self:objectName()
            and d.card:getTag("c216_shuangxiong_owner"):toString() == p:objectName() and self:objectName() or false
    end,
    on_cost = function(self, event, room, p, ctx) return gu_invoke(p, self:objectName(), ctx.original_data) end,
    on_effect = function(self, event, room, p, ctx)
        if event == sgs.Damaged then
            local duel = ctx.original_data:toDamage().card
            local ids = sgs.IntList()
            for _, str in ipairs(duel:getTag("c216_shuangxiong_slashes"):toString():split("+")) do
                local id = tonumber(str)
                if id and room:getCardPlace(id) == sgs.Player_DiscardPile and not ids:contains(id) then ids:append(id) end
            end
            gu_obtain(room, p, ids, self:objectName())
            return false
        end
        local ids = room:getNCards(3)
        local all = gu_dummy(ids)
        room:moveCardTo(all, nil, sgs.Player_PlaceTable, true); all:deleteLater()
        local color = room:askForChoice(p, self:objectName(), "red+black")
        room:setPlayerMark(p, "hljx_shuangxiong_color-Clear", color == "red" and 1 or 2)
        local gain, rest = sgs.IntList(), sgs.IntList()
        for _, id in sgs.qlist(ids) do
            local c = sgs.Sanguosha:getCard(id)
            if room:getCardPlace(id) == sgs.Player_PlaceTable then
                if (color == "red" and c:isRed()) or (color == "black" and c:isBlack()) then gain:append(id) else rest:append(id) end
            end
        end
        gu_obtain(room, p, gain, self:objectName())
        gu_throw(room, nil, rest, self:objectName())
        return true
    end,
}
hljx_shuangxiong_record = gu_record("#hljx_shuangxiong_record", {sgs.PreCardUsed, sgs.CardResponded}, function(self, event, room, p, data)
    if event == sgs.PreCardUsed then
        local use = data:toCardUse()
        if use.card and use.from and use.card:getSkillName() == "hljx_shuangxiong" and use.card:isKindOf("Duel") then
            room:addPlayerMark(use.from, "hljx_shuangxiong_used-Clear")
            use.card:setTag("c216_shuangxiong_owner", sgs.QVariant(use.from:objectName()))
            use.card:setTag("c216_shuangxiong_slashes", sgs.QVariant(""))
        end
    else
        local response = data:toCardResponse()
        local duel, slash = response.m_toCard, response.m_card
        if not duel or not slash or not slash:isKindOf("Slash") or duel:getSkillName() ~= "hljx_shuangxiong" or not p then return end
        if duel:getTag("c216_shuangxiong_owner"):toString() == p:objectName() then return end
        local ids = gu_names(duel, "c216_shuangxiong_slashes")
        if slash:isVirtualCard() then
            for _, id in sgs.qlist(slash:getSubcards()) do table.insert(ids, tostring(id)) end
        else table.insert(ids, tostring(slash:getEffectiveId())) end
        duel:setTag("c216_shuangxiong_slashes", sgs.QVariant(table.concat(ids, "+")))
    end
end)
