hlxg_fengpo_record = gu_record("#hlxg_fengpo_record", {sgs.PreCardUsed, sgs.ConfirmDamage, sgs.CardFinished}, function(self, event, room, p, data)
    if event == sgs.ConfirmDamage then
        local d = data:toDamage()
        if d.card then
            local x = d.card:getTag("hlxg_fengpo_bonus"):toInt()
            if x > 0 then d.damage = d.damage + x; data:setValue(d) end
        end
        return
    end
    local use = data:toCardUse()
    if not use.card then return end
    if event == sgs.CardFinished then
        use.card:removeTag("hlxg_fengpo_bonus")
        room:setCardFlag(use.card, "-hlxg_fengpo_first")
    elseif use.from and use.from:getPhase() ~= sgs.Player_NotActive
        and (use.card:isKindOf("Slash") or use.card:isKindOf("Duel")) then
        room:addPlayerMark(use.from, "hlxg_fengpo_count-Clear")
        if use.from:getMark("hlxg_fengpo_count-Clear") == 1 then room:setCardFlag(use.card, "hlxg_fengpo_first") end
    end
end)
hlxg_fengpo = gu_trigger("hlxg_fengpo", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if use.from ~= owner or owner:getPhase() == sgs.Player_NotActive or not use.card
        or not use.card:hasFlag("hlxg_fengpo_first") or use.to:length() ~= 1
        or not gu_invoke(owner, self:objectName(), data) then return end
    local choice = room:askForChoice(owner, self:objectName(), "draw+damage", data)
    local to = use.to:first()
    room:showAllCards(to, owner)
    local x = 0
    for _, c in sgs.qlist(to:getHandcards()) do if c:isRed() then x = x + 1 end end
    x = math.min(x, 4)
    if choice == "draw" then owner:drawCards(x, self:objectName())
    else use.card:setTag("hlxg_fengpo_bonus", sgs.QVariant(x)) end
end)
