hlxg_qianxi = gu_trigger("hlxg_qianxi", {sgs.EventPhaseStart}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:getPhase() ~= sgs.Player_Start or not gu_invoke(owner, self:objectName()) then return end
    local ids = room:getNCards(2)
    if ids:isEmpty() then return end
    room:fillAG(ids, owner)
    local id = room:askForAG(owner, ids, false, self:objectName())
    room:clearAG(owner)
    if not ids:contains(id) then id = ids:first() end
    local c = sgs.Sanguosha:getCard(id)
    local color = c:isRed() and "red" or (c:isBlack() and "black" or "")
    room:throwCard(c, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_NATURAL_ENTER, owner:objectName(), self:objectName(), ""), nil)
    ids:removeOne(id)
    gu_obtain(room, owner, ids, self:objectName())
    if owner:isDead() then return end
    local tos = sgs.SPlayerList()
    for _, to in sgs.qlist(room:getAlivePlayers()) do if owner:distanceTo(to) == 1 then tos:append(to) end end
    if tos:isEmpty() then return end
    local to = room:askForPlayerChosen(owner, tos, self:objectName(), "@hlxg_qianxi", false, true)
    if to and color ~= "" then room:setPlayerCardLimitation(to, "use,response", ".|" .. color .. "|.|hand", true, self:objectName()) end
end)
hlxg_madai:addSkill(hlxg_qianxi)
