hlxg_fuman_use = sgs.CreateViewAsSkillV2 {
    name = "#hlxg_fuman_use",
    can_activate = function(self, request) return request:getPattern() == "@@#hlxg_fuman_use" end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function(self, request)
        local p = request:getInitiator()
        local id = p:getMark("hlxg_fuman_id") - 1
        if id < 0 or not p:handCards():contains(id) then return nil end
        return sgs.Sanguosha:getCard(id)
    end,
}
extension_hl:addSkills(hlxg_fuman_use)
hlxg_fuman = gu_active("hlxg_fuman", nil, 1, 1,
    function(self, targets, to, from)
        return gu_one(self, targets, to, from) and from:getMark("hlxg_fuman_" .. to:objectName() .. "-PlayClear") == 0
    end, gu_one_feasible,
    function(self, room, source, targets)
        local to = targets[1]
        room:addPlayerMark(source, "hlxg_fuman_" .. to:objectName() .. "-PlayClear")
        gu_throw(room, source, self:getSubcards(), "hlxg_fuman")
        if to:isDead() then return end
        local ids = sgs.IntList()
        for _, id in sgs.qlist(room:getDiscardPile()) do
            if sgs.Sanguosha:getCard(id):isKindOf("Slash") then ids:append(id) end
        end
        if ids:isEmpty() then return end
        room:fillAG(ids, to)
        local id = room:askForAG(to, ids, false, "hlxg_fuman")
        room:clearAG(to)
        if not ids:contains(id) then id = ids:first() end
        local key = "hlxg_fuman_" .. id
        local names = gu_names(to, key)
        table.insert(names, source:objectName()); gu_setnames(to, key, names)
        room:obtainCard(to, id, false)
        if to:isDead() or not to:handCards():contains(id) then return end
        local old = to:getMark("hlxg_fuman_id")
        room:setPlayerMark(to, "hlxg_fuman_id", id + 1)
        local used = room:askForUseCardWithBorrowedSkill(to, "#hlxg_fuman_use", "hlxg_fuman", "@hlxg_fuman-use", -1, sgs.Card_MethodUse, false)
        room:setPlayerMark(to, "hlxg_fuman_id", old)
        if used then
            if source:isAlive() then source:drawCards(1, "hlxg_fuman") end
            if to:isAlive() then to:drawCards(1, "hlxg_fuman") end
        end
    end,
    function(request, c)
        local p = request:getInitiator()
        return p:getCards("he"):contains(c) and not p:isJilei(c)
    end)
hlxg_fuman_record = gu_record("#hlxg_fuman_record", {sgs.PreCardUsed, sgs.DamageDone, sgs.CardFinished}, function(self, event, room, p, data)
    if event == sgs.DamageDone then
        local d = data:toDamage()
        if d.card and d.damage > 0 and d.card:getTag("hlxg_fuman_owners"):toString() ~= "" then
            room:setCardFlag(d.card, "hlxg_fuman_damaged")
        end
        return
    end
    local use = data:toCardUse()
    if not use.card or not use.from then return end
    if event == sgs.PreCardUsed then
        if not use.card:isKindOf("Slash") then return end
        local ids = use.card:isVirtualCard() and use.card:getSubcards() or gu_ids({use.card})
        local names = {}
        for _, id in sgs.qlist(ids) do
            local key = "hlxg_fuman_" .. id
            for _, name in ipairs(gu_names(use.from, key)) do table.insert(names, name) end
            use.from:removeTag(key)
        end
        if #names > 0 then use.card:setTag("hlxg_fuman_owners", sgs.QVariant(table.concat(names, "+"))) end
    else
        if use.card:hasFlag("hlxg_fuman_damaged") then
            for _, name in ipairs(gu_names(use.card, "hlxg_fuman_owners")) do
                local owner = room:findPlayerByObjectName(name)
                if owner and owner:isAlive() then owner:drawCards(1, "hlxg_fuman") end
            end
        end
        use.card:removeTag("hlxg_fuman_owners")
        room:setCardFlag(use.card, "-hlxg_fuman_damaged")
    end
end)
