hlxg_sanyao = gu_trigger("hlxg_sanyao", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if use.from ~= owner or not use.card or owner:getMark("hlxg_sanyao-Clear") > 0 then return end
    local highest, unique = nil, true
    for _, other in sgs.qlist(room:getAlivePlayers()) do
        if not highest or other:getHp() > highest:getHp() then highest = other; unique = true
        elseif other:getHp() == highest:getHp() then unique = false end
    end
    if not unique or not highest or highest == owner or not use.to:contains(highest) then return end
    room:setPlayerMark(owner, "hlxg_sanyao-Clear", 1)
    room:sendCompulsoryTriggerLog(owner, self:objectName())
    local damage = sgs.DamageStruct()
    damage.from = owner; damage.to = highest; damage.damage = 1; damage.reason = self:objectName()
    room:damage(damage)
end, true)
hlxg_masu:addSkill(hlxg_sanyao)

hljx_sanyaoCard = sgs.CreateSkillCard {
    name = "hljx_sanyaoCard", will_throw = false,
    filter = function(self, targets, to, from)
        return to ~= from and #targets < self:subcardsLength()
    end,
    feasible = function(self, targets) return #targets == self:subcardsLength() end,
    on_use = function(self, room, source, targets)
        gu_throw(room, source, self:getSubcards(), "hljx_sanyao")
        for _, to in ipairs(targets) do
            if to:isAlive() then
                local damage = sgs.DamageStruct()
                damage.from = source; damage.to = to; damage.damage = 1; damage.reason = "hljx_sanyao"
                room:damage(damage)
            end
        end
    end,
}
hljx_sanyao = sgs.CreateViewAsSkillV2 {
    name = "hljx_sanyao", limit_scope = sgs.Skill_Limit_Phase, phase_name = "Play", max_usage_limit = 1,
    can_activate = function(self, request) return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY end,
    can_select_card = function(self, request, card)
        local p = request:getInitiator()
        return request:getSelectedCardIds():length() < 4 and p:canDiscard(p, card:getEffectiveId())
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() <= 4 end,
    create_card = function(self, request)
        local card = hljx_sanyaoCard:clone()
        card:addSubcards(request:getSelectedCardIds()); card:setSkillName("hljx_sanyao")
        return card
    end,
}
hljx_masu:addSkill(hljx_sanyao)

hlxg_tieqi_machao = gu_trigger("hlxg_tieqi_machao", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if use.from ~= owner or not use.card or not use.card:isKindOf("Slash") then return end
    for index, to in ipairs(sgs.QList2Table(use.to)) do
        if owner:isAlive() and to:isAlive() and gu_invoke(owner, self:objectName(), ToData(to)) then
            local judge = sgs.JudgeStruct()
            judge.who = owner; judge.reason = self:objectName(); judge.pattern = ".|red"; judge.good = true
            room:judge(judge)
            if judge.card and judge.card:isRed() then
                local tag = "Jink_" .. use.card:toString()
                local jinks = owner:getTag(tag):toIntList()
                if index <= jinks:length() then jinks:replace(index - 1, 0) end
                local value = sgs.QVariant(); value:setValue(jinks); owner:setTag(tag, value)
            elseif judge.card and judge.card:isBlack() then owner:drawCards(1, self:objectName()) end
        end
    end
end)
