hljx_tieqi = gu_trigger("hljx_tieqi", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or use.from ~= owner or not use.card or not use.card:isKindOf("Slash") then return end
    local key = "Jink_" .. use.card:toString()
    for i = 0, use.to:length() - 1 do
        local target = use.to:at(i)
        if owner:isAlive() and target:isAlive() and room:askForSkillInvoke(owner, self:objectName(), sgs.QVariant(target)) then
            room:addPlayerMark(target, "@skill_invalidity")
            room:addPlayerMark(target, "hljx_tieqi_invalid")
            for _, q in sgs.qlist(room:getAlivePlayers()) do room:filterCards(q, q:getCards("he"), true) end
            local judge = sgs.JudgeStruct()
            judge.who = owner; judge.reason = self:objectName(); judge.pattern = "."; judge.good = true
            room:judge(judge)
            if judge.card:isRed() then
                local old, values = owner:getTag(key):toIntList(), sgs.IntList()
                for j = 0, use.to:length() - 1 do values:append(j == i and 0 or (j < old:length() and old:at(j) or 1)) end
                local v = sgs.QVariant(); v:setValue(values); owner:setTag(key, v)
            elseif judge.card:isBlack() then owner:drawCards(2, self:objectName()) end
        end
    end
end)
hljx_tieqi_clear = gu_record("#hljx_tieqi_clear", {sgs.EventPhaseChanging, sgs.Death}, function(self, event, room, p, data)
    if event == sgs.EventPhaseChanging then
        if data:toPhaseChange().to ~= sgs.Player_NotActive then return end
    elseif not p or data:toDeath().who ~= p or room:getCurrent() ~= p then return end
    for _, q in sgs.qlist(room:getAllPlayers(true)) do
        local n = q:getMark("hljx_tieqi_invalid")
        if n > 0 then
            room:setPlayerMark(q, "hljx_tieqi_invalid", 0)
            room:removePlayerMark(q, "@skill_invalidity", n)
        end
    end
    for _, q in sgs.qlist(room:getAlivePlayers()) do room:filterCards(q, q:getCards("he"), true) end
end)
hljx_yuma = gu_trigger("hljx_yuma", {sgs.CardsMoveOneTime}, function(self, event, room, p, data, owner)
    local move = data:toMoveOneTime()
    if not move.from or move.from:objectName() ~= owner:objectName() then return end
    local n = 0
    for i = 0, move.card_ids:length() - 1 do
        local c = sgs.Sanguosha:getEngineCard(move.card_ids:at(i))
        if move.from_places:at(i) == sgs.Player_PlaceEquip and (c:isKindOf("OffensiveHorse") or c:isKindOf("DefensiveHorse")) then n = n + 1 end
    end
    for i = 1, n do if owner:isAlive() then owner:drawCards(2, self:objectName()) end end
end, true)
hljx_yuma_distance = sgs.CreateDistanceSkillV2 {
    name = "#hljx_yuma_distance", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
