}

hlxg_shichou = gu_trigger("hlxg_shichou", {sgs.Damage, sgs.CardFinished}, function(self, event, room, p, data, owner)
    if event == sgs.Damage then
        local d = data:toDamage()
        if p ~= owner or d.from ~= owner or not d.card or not d.card:isKindOf("Slash") then return end
        if owner:getMark("hlxg_shichou_draw-Clear") < 3 then
            room:addPlayerMark(owner, "hlxg_shichou_draw-Clear")
            owner:drawCards(1, self:objectName())
        end
    else
        local use = data:toCardUse()
        if use.from ~= owner or not use.card or not use.card:isKindOf("Slash") or use.card:hasFlag("hlxg_shichou_damage") then return end
        local ids = sgs.IntList()
        for _, pile in ipairs({room:getDrawPile(), room:getDiscardPile()}) do
            for _, id in sgs.qlist(pile) do
                if sgs.Sanguosha:getCard(id):isKindOf("Slash") then ids:append(id) end
            end
        end
        if not ids:isEmpty() then room:obtainCard(owner, ids:at(math.random(ids:length())), false) end
    end
end)
-- Record every damage source, even if Shichou is temporarily invalidated.
