    if event == sgs.DamageDone then
        local d = data:toDamage()
        if d.card and d.card:isKindOf("Slash") then room:setCardFlag(d.card, "hlxg_shichou_damage") end
    elseif event == sgs.PreCardUsed then
        local c = data:toCardUse().card
        if c then room:setCardFlag(c, "-hlxg_shichou_damage") end
    end
end)
