        local p = ctx:getPrimary()
        if p and p:hasSkill("hlxg_shichou") and ctx:getModType() == sgs.TargetModSkill_ExtraTarget then return p:getLostHp() + 1 end
        return 0
    end,
}
hlxg_zhuiji = gu_trigger("hlxg_zhuiji", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or use.from ~= owner or not use.card or not use.card:isKindOf("Slash") then return end
    local names = use.no_respond_list
    for _, target in sgs.qlist(use.to) do
        if target:getHp() >= owner:getHp() and not table.contains(names, target:objectName()) then table.insert(names, target:objectName()) end
    end
    use.no_respond_list = names; data:setValue(use)
end, true)
