    fixed_func = function(self, ctx)
        local p, q = ctx:getPrimary(), ctx:getSecondary()
        if p and q and p ~= q and p:hasSkill("hlxg_zhuiji") and q:getHp() <= p:getHp() then return 1 end
        return nil
    end,
}
