hlxg_xizhen = gu_trigger("hlxg_xizhen", {sgs.EventPhaseStart, sgs.CardUsed, sgs.CardResponded, sgs.CardFinished}, function(self, event, room, p, data, owner)
    if event == sgs.EventPhaseStart then
        if p ~= owner or p:getPhase() ~= sgs.Player_Play then return end
        local choices, candidates = {}, {}
        for _, name in ipairs({"slash", "duel"}) do
            local c = sgs.Sanguosha:cloneCard(name, sgs.Card_NoSuit, 0)
            c:setSkillName("hlxg_xizhen")
            local list = sgs.SPlayerList()
            if c:isAvailable(owner) then
                for _, to in sgs.qlist(room:getOtherPlayers(owner)) do
                    if not owner:isProhibited(to, c) and c:targetFilter(sgs.PlayerList(), to, owner) then list:append(to) end
                end
            end
            c:deleteLater()
            if not list:isEmpty() then table.insert(choices, name); candidates[name] = list end
        end
        if #choices == 0 or not gu_invoke(owner, "hlxg_xizhen", data) then return end
        local name = room:askForChoice(owner, "hlxg_xizhen", table.concat(choices, "+"), data)
        local to = room:askForPlayerChosen(owner, candidates[name], "hlxg_xizhen", "@hlxg_xizhen", false, true)
        if not to then return end
        local c = sgs.Sanguosha:cloneCard(name, sgs.Card_NoSuit, 0); c:setSkillName("hlxg_xizhen")
        room:useCard(sgs.CardUseStruct(c, owner, to)); c:deleteLater()
        if owner:isAlive() and owner:getPhase() == sgs.Player_Play then room:setPlayerMark(owner, "hlxg_xizhen-PlayClear", 1) end
    elseif event == sgs.CardFinished then
        local use = data:toCardUse()
        if use.card and use.card:getTag("hlxg_xizhen_owner"):toString() == owner:objectName() then use.card:removeTag("hlxg_xizhen_owner") end
    elseif event == sgs.CardUsed then
        local use = data:toCardUse()
        if use.from == owner and owner:getPhase() == sgs.Player_Play and owner:getMark("hlxg_xizhen-PlayClear") > 0 then
            use.card:setTag("hlxg_xizhen_owner", sgs.QVariant(owner:objectName()))
        end
    else
        local response = data:toCardResponse()
        if not p or not response.m_card or not response.m_toCard or response.nullified
            or owner:getPhase() ~= sgs.Player_Play or owner:getMark("hlxg_xizhen-PlayClear") == 0
            or response.m_toCard:getTag("hlxg_xizhen_owner"):toString() ~= owner:objectName() then return end
        room:recover(p, sgs.RecoverStruct("hlxg_xizhen", owner)); owner:drawCards(2, "hlxg_xizhen")
    end
end)
hlxg_gaolan:addSkill(hlxg_xizhen)

local function c216_07_jinjiu(general, name, king)
    local filter = sgs.CreateFilterSkill {
        name = name,
        view_filter = function(self, c) return c:isKindOf("Analeptic") end,
        view_as = function(self, c)
            local slash = sgs.Sanguosha:cloneCard("slash", c:getSuit(), king and 13 or c:getNumber())
            slash:setSkillName(name)
            local wrapped = sgs.Sanguosha:getWrappedCard(c:getId()); wrapped:takeOver(slash); slash:deleteLater(); return wrapped
        end,
    }
    local modname, prohibitname = "#" .. name .. "_mod", "#" .. name .. "_prohibit"
    local mod = sgs.CreateTargetModSkillV2 {
        name = modname, pattern = "Slash", holder_selector = sgs.CorrectSkill_System,
        correct_func = function(self, ctx)
            local from, card = ctx:getPrimary(), ctx:getCard()
            if from and from:hasSkill(name) and card and card:getSkillName() == name and ctx:getModType() == sgs.TargetModSkill_Residue then
                return sgs.CorrectSkillResult.unlimitedResidue()
            end
            return 0
        end,
    }
    local prohibit = sgs.CreateProhibitSkillV2 {
        name = prohibitname, holder_selector = sgs.CorrectSkill_AllHolders,
        is_prohibited = function(self, ctx)
            local holder, from, card = ctx:getHolder(), ctx:getFrom(), ctx:getCard()
            return holder and from and card and holder:hasSkill(name) and holder ~= from
                and holder:getPhase() ~= sgs.Player_NotActive and card:isKindOf("Analeptic")
        end,
    }
    local gain = gu_trigger("#" .. name .. "_gain", {sgs.CardFinished}, function(self, event, room, p, data, owner)
        local use = data:toCardUse()
        if use.from and use.from ~= owner and use.card and use.card:isKindOf("Analeptic") then
            local ids = sgs.IntList()
            if use.card:isVirtualCard() then
                for _, id in sgs.qlist(use.card:getSubcards()) do
                    if room:getCardPlace(id) == sgs.Player_DiscardPile or room:getCardPlace(id) == sgs.Player_PlaceTable then ids:append(id) end
                end
            elseif use.card:getEffectiveId() >= 0 then
                local id = use.card:getEffectiveId()
                if room:getCardPlace(id) == sgs.Player_DiscardPile or room:getCardPlace(id) == sgs.Player_PlaceTable then ids:append(id) end
            end
            gu_obtain(room, owner, ids, name)
        end
    end, true)
    _G[name] = filter; _G[modname] = mod; _G[prohibitname] = prohibit; _G["#" .. name .. "_gain"] = gain
    general:addSkill(filter); general:addSkill(mod); general:addSkill(prohibit); general:addSkill(gain)
    for _, suffix in ipairs({"mod", "prohibit", "gain"}) do extension_hl:insertRelatedSkills(name, "#" .. name .. "_" .. suffix) end
end
