local function c216_07_bonus(name, limited)
    return gu_trigger(name, {sgs.DamageCaused, sgs.CardOffset}, function(self, event, room, p, data, owner)
        if event == sgs.DamageCaused then
            local d = data:toDamage()
            if d.from ~= owner or owner:getPhase() == sgs.Player_NotActive or owner:getMark(name .. "_damage-Clear") > 0
                or (limited and (not d.card or not d.card:isKindOf("Slash"))) then return end
            room:setPlayerMark(owner, name .. "_damage-Clear", 1); d.damage = d.damage + 1; data:setValue(d)
        else
            local e = data:toCardEffect()
            if p ~= owner or e.from ~= owner or not e.card or not e.card:isKindOf("Slash")
                or not e.offset_card or not e.offset_card:isKindOf("Jink")
                or (limited and owner:getMark(name .. "_draw-Clear") > 0) then return end
            if limited then room:setPlayerMark(owner, name .. "_draw-Clear", 1) end
            owner:drawCards(1, limited and name or "hljx_xianzhen")
        end
    end, true)
end
