-- c216_08: literal batch text, no distance condition on either 狂骨.
local function c216_08_kuanggu(name)
    return gu_trigger(name, {sgs.Damage}, function(self, event, room, p, data, owner)
        local damage = data:toDamage()
        if damage.from ~= owner then return end
        for i = 1, damage.damage do
            if owner:isDead() then break end
            if gu_invoke(owner, name, data) then
                local choice = room:askForChoice(owner, name, "recover+draw")
                if choice == "recover" then
                    local recover = sgs.RecoverStruct()
                    recover.who = owner; recover.recover = 1
                    room:recover(owner, recover)
                else owner:drawCards(1, name) end
            end
        end
    end)
end
