hljx_qimouCard = sgs.CreateSkillCard {
    name = "hljx_qimouCard", target_fixed = true, will_throw = false,
    on_use = function(self, room, source, targets)
        room:removePlayerMark(source, "@hljx_qimou")
        -- Repeated increments select an arbitrary nonnegative amount without an artificial cap.
        local n = 0
        source:setTag("hljx_qimou_amount", sgs.QVariant(n))
        while room:askForChoice(source, "hljx_qimou", "increase+confirm", sgs.QVariant(n)) == "increase" do
            n = n + 1; source:setTag("hljx_qimou_amount", sgs.QVariant(n))
        end
        source:removeTag("hljx_qimou_amount")
        source:removeTag("hljx_qimou_lost")
        if n > 0 then room:loseHp(source, n, true, source, "hljx_qimou") end
        -- Use the committed HpLost amount, rather than HP differences affected by rescue.
        local lost = source:getTag("hljx_qimou_lost"):toInt()
        source:removeTag("hljx_qimou_lost")
        if n == 0 then lost = 0 end
        if source:isAlive() then
            source:drawCards(1, "hljx_qimou")
            room:addPlayerMark(source, "hljx_qimou_bonus-Clear", lost)
        end
    end,
}
hljx_qimou = sgs.CreateViewAsSkillV2 {
    name = "hljx_qimou", frequency = sgs.Skill_Limited, limit_mark = "@hljx_qimou",
    can_activate = function(self, request)
        return request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY
            and request:getInitiator():getMark("@hljx_qimou") > 0
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():isEmpty() end,
    create_card = function(self, request)
        local c = hljx_qimouCard:clone(); c:setSkillName("hljx_qimou"); return c
    end,
}
