hlxg_haoshi = gu_trigger("hlxg_haoshi", {sgs.EventPhaseEnd}, function(self, event, room, p, data, owner)
    if p ~= owner or owner:getPhase() ~= sgs.Player_Draw or not gu_invoke(owner, self:objectName(), data) then return end
    owner:drawCards(2, self:objectName())
    if owner:isDead() or owner:getHandcardNum() <= 5 then return end
    local n = math.floor(owner:getHandcardNum() / 2)
    local minimum = nil; local candidates = sgs.SPlayerList()
    for _, q in sgs.qlist(room:getOtherPlayers(owner)) do
        if not minimum or q:getHandcardNum() < minimum then minimum = q:getHandcardNum() end
    end
    for _, q in sgs.qlist(room:getOtherPlayers(owner)) do
        if q:getHandcardNum() == minimum then candidates:append(q) end
    end
    local choice = candidates:isEmpty() and "discard" or room:askForChoice(owner, self:objectName(), "give+discard")
    if choice == "discard" then
        room:askForDiscard(owner, self:objectName(), n, n, false, false, "@hlxg_haoshi-discard")
    else
        local to = room:askForPlayerChosen(owner, candidates, self:objectName(), "@hlxg_haoshi-give", false, true)
        local cards = room:askForExchange(owner, self:objectName(), n, n, false, "@hlxg_haoshi-cards")
        if cards and to then room:giveCard(owner, to, cards, self:objectName()); cards:deleteLater() end
    end
end)
local function c216_08_discardable(p)
    local n = 0
    for _, c in sgs.qlist(p:getCards("he")) do if p:canDiscard(p, c:getEffectiveId()) then n = n + 1 end end
    return n
end
