        local n = math.abs(targets[1]:getHandcardNum() - targets[2]:getHandcardNum())
        if n > 0 and not room:askForDiscard(source, "hlxg_dimeng", n, n, false, true, "@hlxg_dimeng-discard") then return end
        if targets[1]:isAlive() and targets[2]:isAlive() then room:swapCards(targets[1], targets[2], "h", "hlxg_dimeng") end
    end)
