hljx_haoshi = gu_trigger("hljx_haoshi", {sgs.EventPhaseEnd, sgs.TargetConfirmed}, function(self, event, room, p, data, owner)
    if event == sgs.EventPhaseEnd then
        if p ~= owner or p:getPhase() ~= sgs.Player_Draw then return end
        owner:drawCards(2, self:objectName())
        if owner:isDead() or owner:getHandcardNum() <= 5 then return end
        local to = room:askForPlayerChosen(owner, room:getOtherPlayers(owner), self:objectName(), "@hljx_haoshi-give", true, true)
        if not to then return end
        local n = math.floor(owner:getHandcardNum() / 2)
        local cards = room:askForExchange(owner, self:objectName(), n, n, false, "@hljx_haoshi-cards", false)
        if cards then
            local names = gu_names(owner, "hljx_haoshi_recipients")
            if not table.contains(names, to:objectName()) then table.insert(names, to:objectName()) end
            gu_setnames(owner, "hljx_haoshi_recipients", names)
            room:giveCard(owner, to, cards, self:objectName())
            cards:deleteLater()
        end
    else
        local use = data:toCardUse()
        if p ~= owner or not use.card or not use.to:contains(owner) then return end
        if not use.card:isKindOf("Slash") and not use.card:isNDTrick() then return end
        for _, name in ipairs(gu_names(owner, "hljx_haoshi_recipients")) do
            for _, to in sgs.qlist(room:getOtherPlayers(owner)) do
                if owner:isAlive() and to:objectName() == name and not to:isKongcheng() then
                    local c = room:askForCard(to, ".|.|.|hand", "@hljx_haoshi-aid:" .. owner:objectName(), data, sgs.Card_MethodNone, owner, false, self:objectName())
                    if c then room:giveCard(to, owner, c, self:objectName()) end
                end
            end
        end
    end
end)
