        local moves = sgs.CardsMoveList()
        if not a:isKongcheng() then
            moves:append(sgs.CardsMoveStruct(a:handCards(), a, b, sgs.Player_PlaceHand, sgs.Player_PlaceHand,
                sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_SWAP, source:objectName(), "hljx_dimeng", "")))
