                sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_SWAP, source:objectName(), "hljx_dimeng", "")))
        end
        if not moves:isEmpty() then room:moveCardsAtomic(moves, false) end
        room:addPlayerMark(source, "&hljx_dimeng", n)
    end, nil, function(p) return p:getMark("&hljx_dimeng") == 0 end)
