    if p ~= owner then return end
    if event == sgs.CardUsed then
        local use = data:toCardUse()
        if use.from ~= owner or not use.card or (not use.card:isKindOf("Slash") and not use.card:isNDTrick()) then return end
        local names = use.no_respond_list
        for _, to in sgs.qlist(room:getOtherPlayers(owner)) do
            if owner:distanceTo(to) <= 2 and not table.contains(names, to:objectName()) then table.insert(names, to:objectName()) end
        end
        use.no_respond_list = names; data:setValue(use)
    else
        local damage = data:toDamage()
        if damage.from == owner and damage.to and damage.to ~= owner and damage.to:isAlive() then
            room:setPlayerMark(damage.to, "&hlxg_fuqi-Clear", 1)
            room:filterCards(damage.to, damage.to:getCards("he"), true)
        end
    end
end, true)
