-- c217_01: literal excerpt implementations; the second Huang Zhong is skipped.
hlxg_huangzhong = sgs.General(extension_hl, "hlxg_huangzhong", "shu", 4)
hlxg_liegong_huangzhong = gu_trigger("hlxg_liegong_huangzhong", {sgs.TargetSpecified}, function(self, event, room, player, data, owner)
    local use = data:toCardUse()
    if use.from ~= owner or not use.card or not use.card:isKindOf("Slash") then return end
    local key = "Jink_" .. use.card:toString()
    local counts = sgs.QList2Table(owner:getTag(key):toIntList())
    local result = sgs.IntList()
    for i, target in ipairs(sgs.QList2Table(use.to)) do
        local n = counts[i] or 1
        if target:getHp() >= owner:getHp() or target:getHandcardNum() >= owner:getHandcardNum() then n = 0 end
        result:append(n)
    end
    local value = sgs.QVariant(); value:setValue(result); owner:setTag(key, value)
end, true)
hlxg_huangzhong:addSkill(hlxg_liegong_huangzhong)

