hljx_qicai = sgs.CreateTargetModSkillV2 {
    name = "hljx_qicai", pattern = "TrickCard", frequency = sgs.Skill_Compulsory,
    holder_selector = sgs.CorrectSkill_Primary,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        if p and p:hasSkill(self:objectName()) and ctx:getModType() == sgs.TargetModSkill_DistanceLimit then return 1000 end
        return false
    end,
}
hljx_qicai_limit = sgs.CreateCardLimitSkill {
    name = "#hljx_qicai_limit",
    limit_list = function() return "discard" end,
    limit_pattern = function(self, player, card)
        if not card or not (card:isKindOf("Weapon") or card:isKindOf("Armor")) then return "" end
        for _, other in sgs.qlist(player:getAliveSiblings()) do
            if other:hasSkill("hljx_qicai") and other:getEquipsId():contains(card:getEffectiveId()) then return card:toString() end
        end
        return ""
    end,
}
hljx_jizhi = gu_trigger("hljx_jizhi", {sgs.CardUsed}, function(self, event, room, player, data, owner)
    local card = data:toCardUse().card
    if player ~= owner or not card or not card:isKindOf("TrickCard") or card:isVirtualCard() or card:getSkillName() ~= "" then return end
    if not gu_invoke(owner, self:objectName(), data) then return end
    local ids = owner:drawCardsList(1, self:objectName())
    if ids:isEmpty() then return end
    local drawn = sgs.Sanguosha:getCard(ids:first())
    if drawn:isKindOf("BasicCard") then
        room:addPlayerMark(owner, "&hljx_jizhi_hand-Clear")
    elseif drawn:isKindOf("TrickCard") then
        room:addPlayerMark(owner, "&hljx_jizhi_slash-Clear")
    elseif drawn:isKindOf("EquipCard") and owner:isAlive() and room:getCardOwner(ids:first()) == owner and room:getCardPlace(ids:first()) == sgs.Player_PlaceHand then
        local slot = drawn:getRealCard():toEquipCard():location()
        local targets = sgs.SPlayerList()
        for _, p in sgs.qlist(room:getOtherPlayers(owner)) do if p:hasEquipArea(slot) then targets:append(p) end end
        if targets:isEmpty() then return end
        local target = room:askForPlayerChosen(owner, targets, self:objectName(), "@hljx_jizhi-equip", true, true)
        if not target then return end
        local old = target:getEquip(slot)
        if old then room:throwCard(old, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_CHANGE_EQUIP, target:objectName(), self:objectName(), ""), target) end
        if target:isAlive() and target:hasEquipArea(slot) and room:getCardOwner(ids:first()) == owner and room:getCardPlace(ids:first()) == sgs.Player_PlaceHand then
            room:moveCardTo(drawn, owner, target, sgs.Player_PlaceEquip,
                sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_PUT, owner:objectName(), self:objectName(), ""), true)
        end
    end
end)
hljx_jizhi_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hljx_jizhi_max", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary(); return p and p:getMark("&hljx_jizhi_hand-Clear") or 0
    end,
}
hljx_jizhi_slash = sgs.CreateTargetModSkillV2 {
    name = "#hljx_jizhi_slash", pattern = "Slash", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        if p and ctx:getModType() == sgs.TargetModSkill_Residue then return p:getMark("&hljx_jizhi_slash-Clear") end
        return false
    end,
}
for _, skill in ipairs({hljx_qicai, hljx_qicai_limit, hljx_jizhi, hljx_jizhi_max, hljx_jizhi_slash}) do hljx_huangyueying:addSkill(skill) end
