hlxg_qicai_huangyueying = sgs.CreateTargetModSkillV2 {
    name = "hlxg_qicai_huangyueying", frequency = sgs.Skill_Compulsory,
    holder_selector = sgs.CorrectSkill_Primary,
    correct_func = function(self, ctx)
        local p, c = ctx:getPrimary(), ctx:getCard()
        if p and p:hasSkill(self:objectName()) and c and c:isKindOf("TrickCard")
            and ctx:getModType() == sgs.TargetModSkill_DistanceLimit then return 1000 end
        return false
    end,
