hlxg_jizhi_huangyueying = gu_trigger("hlxg_jizhi_huangyueying", {sgs.CardUsed},
    function(self, event, room, p, data, owner)
        local use = data:toCardUse()
        if p == owner and use.card and not use.card:isVirtualCard()
            and use.card:getSkillName() == "" and use.card:isNDTrick() and gu_invoke(owner, self:objectName(), data) then
            owner:drawCards(1, self:objectName())
        end
    end)

hlxg_jiqiao = gu_trigger("hlxg_jiqiao", {sgs.EventPhaseStart},
    function(self, event, room, p, data, owner)
        if p ~= owner or p:getPhase() ~= sgs.Player_Play or not gu_invoke(owner, self:objectName()) then return end
        -- Zero is allowed by 任意张: it also reaches the no-trick fallback.
        local discarded = room:askForDiscard(owner, self:objectName(), owner:getCardCount(true), 0,
            false, true, "@hlxg_jiqiao", "^TrickCard")
        local n = discarded and discarded:subcardsLength() or 0
        local ids = sgs.IntList()
        if n > 0 then
            ids = room:getNCards(2 * n, false)
            if not ids:isEmpty() then
                room:moveCardsAtomic(sgs.CardsMoveStruct(ids, nil, sgs.Player_PlaceTable,
                    sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_TURNOVER, owner:objectName(), self:objectName(), "")), true)
            end
        end
        local got, rest = sgs.IntList(), sgs.IntList()
        local revealed_trick = false
        for _, id in sgs.qlist(ids) do
            local trick = sgs.Sanguosha:getCard(id):isKindOf("TrickCard")
            revealed_trick = revealed_trick or trick
            if room:getCardPlace(id) == sgs.Player_PlaceTable then
                if trick and owner:isAlive() then got:append(id) else rest:append(id) end
            end
        end
        if owner:isAlive() then gu_obtain(room, owner, got, self:objectName()) end
        if not rest:isEmpty() then
            local dummy = gu_dummy(rest)
            room:throwCard(dummy, sgs.CardMoveReason(sgs.CardMoveReason_S_REASON_NATURAL_ENTER,
                owner:objectName(), self:objectName(), ""), nil)
            dummy:deleteLater()
        end
        if not revealed_trick and owner:isAlive() then
            for _, id in sgs.qlist(room:getDrawPile()) do
                if sgs.Sanguosha:getCard(id):isKindOf("TrickCard") then
                    room:obtainCard(owner, id, true)
                    break
                end
            end
        end
    end)

-- Keep the virtual armor and the two conditional skill grants in sync with equipment.
hlxg_linglong = gu_trigger("hlxg_linglong", {sgs.GameStart}, function() end, true)
hlxg_linglong_record = gu_record("#hlxg_linglong_record",
    {sgs.GameStart, sgs.CardsMoveOneTime, sgs.EventAcquireSkill, sgs.EventLoseSkill, sgs.EventPhaseStart},
    function(self, event, room, p, data)
        for _, owner in sgs.qlist(room:getAlivePlayers()) do
            local active = owner:hasSkill("hlxg_linglong")
            local armor = active and not owner:getArmor()
            if armor and owner:getMark("hlxg_linglong_armor") == 0 then
                room:setPlayerMark(owner, "hlxg_linglong_armor", 1)
                owner:ViewAsEquip("eight_diagram", true)
            elseif not armor and owner:getMark("hlxg_linglong_armor") > 0 then
                room:setPlayerMark(owner, "hlxg_linglong_armor", 0)
                owner:removeViewAsEquip("eight_diagram", false)
            end
            local grant = active and owner:getEquips():isEmpty()
            for _, skill in ipairs({"hlxg_qicai_huangyueying", "hlxg_jizhi_huangyueying"}) do
                local mark = "hlxg_linglong_grant_" .. skill
                if grant and not owner:hasSkill(skill, true) then
                    room:setPlayerMark(owner, mark, 1)
                    room:acquireSkill(owner, skill)
                elseif not grant and owner:getMark(mark) > 0 then
                    room:setPlayerMark(owner, mark, 0)
                    room:detachSkillFromPlayer(owner, skill, false, true)
                end
            end
        end
    end)
hlxg_linglong_max = sgs.CreateMaxCardsSkillV2 {
    name = "#hlxg_linglong_max", holder_selector = sgs.CorrectSkill_Primary,
    correct_func = function(self, ctx)
        local p = ctx:getPrimary()
        if p and p:hasSkill("hlxg_linglong") and not p:getOffensiveHorse() and not p:getDefensiveHorse() then return 1 end
        return false
    end,
}
