hlxg_huangyueying:addSkill(hlxg_linglong)
hlxg_huangyueying:addSkill(hlxg_linglong_record)
hlxg_huangyueying:addSkill(hlxg_linglong_max)
hlxg_huangyueying:addRelateSkill("hlxg_qicai_huangyueying")
hlxg_huangyueying:addRelateSkill("hlxg_jizhi_huangyueying")
extension_hl:insertRelatedSkills("hlxg_linglong", "#hlxg_linglong_record")
extension_hl:insertRelatedSkills("hlxg_linglong", "#hlxg_linglong_max")

