hlxg_zhaxiang_huanggai2 = gu_trigger("hlxg_zhaxiang_huanggai2", {sgs.HpLost, sgs.EventPhaseStart, sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    if p ~= owner then return end
    if event == sgs.HpLost then
        for i = 1, data:toHpLost().lose do
            if owner:isDead() then break end
            owner:drawCards(3, self:objectName())
        end
    elseif event == sgs.EventPhaseStart then
        if owner:getPhase() == sgs.Player_Finish then owner:drawCards(math.ceil(owner:getLostHp() / 2), self:objectName()) end
    else
        local use = data:toCardUse()
        if not use.card or use.card:isKindOf("SkillCard") then return end
        if owner:getMark("hlxg_zhaxiang_huanggai2_count-Clear") <= math.ceil(owner:getLostHp() / 2) then
            local names = use.no_respond_list
            table.insert(names, "_ALL_TARGETS")
            use.no_respond_list = names; data:setValue(use)
        end
    end
end, true)
