        if not p or not c or c:isKindOf("SkillCard") or not p:hasSkill("hlxg_zhaxiang_huanggai2") then return 0 end
        if p:getMark("hlxg_zhaxiang_huanggai2_count-Clear") >= math.ceil(p:getLostHp() / 2) then return 0 end
        if ctx:getModType() == sgs.TargetModSkill_Residue then return sgs.CorrectSkillResult.unlimitedResidue() end
        if ctx:getModType() == sgs.TargetModSkill_DistanceLimit then return 1000 end
        return 0
    end,
}

hlxg_jinggong = sgs.CreateViewAsSkillV2 {
    name = "hlxg_jinggong",
    can_activate = function(self, request)
        local p = request:getInitiator()
        if not p then return false end
        if request:getReason() == sgs.CardUseStruct_CARD_USE_REASON_PLAY then return sgs.Slash_IsAvailable(p) end
        return request:getPattern() == "slash"
    end,
    can_select_card = function(self, request, card)
        return request:getSelectedCardIds():isEmpty() and card:isKindOf("EquipCard")
    end,
    card_selection_feasible = function(self, request) return request:getSelectedCardIds():length() == 1 end,
    create_card = function(self, request)
        local ids = request:getSelectedCardIds()
        if ids:length() ~= 1 then return nil end
        local equip = sgs.Sanguosha:getCard(ids:first())
        local slash = sgs.Sanguosha:cloneCard("slash", equip:getSuit(), equip:getNumber())
        slash:addSubcard(equip); slash:setSkillName(self:objectName())
        return slash
    end,
}
hlxg_jinggong_mod = sgs.CreateTargetModSkillV2 {
    name = "#hlxg_jinggong_mod", holder_selector = sgs.CorrectSkill_System,
    correct_func = function(self, ctx)
        local c = ctx:getCard()
        if c and c:getSkillName() == "hlxg_jinggong" and ctx:getModType() == sgs.TargetModSkill_DistanceLimit then return 1000 end
        return 0
    end,
}
hlxg_jinggong_damage = gu_trigger("#hlxg_jinggong_damage", {sgs.ConfirmDamage}, function(self, event, room, p, data, owner)
    local damage = data:toDamage()
    if damage.from ~= owner or not damage.to or not damage.card or damage.card:getSkillName() ~= "hlxg_jinggong" then return end
    if damage.chain or damage.transfer then return end
    damage.damage = math.min(5, owner:distanceTo(damage.to)); data:setValue(damage)
end, true)
hlxg_xiaojuan = gu_trigger("hlxg_xiaojuan", {sgs.TargetSpecified}, function(self, event, room, p, data, owner)
    local use = data:toCardUse()
    if p ~= owner or not use.card or use.card:isKindOf("EquipCard") or use.card:isKindOf("SkillCard") or use.to:length() ~= 1 then return end
    local to = use.to:first()
    local n = math.ceil(to:getHandcardNum() / 2)
    if n == 0 or not owner:canDiscard(to, "h") or not gu_invoke(owner, self:objectName(), data) then return end
    local ids = room:askForCardsChosen(owner, to, "h", self:objectName(), n, n, false, sgs.Card_MethodDiscard, sgs.IntList(), false)
    local same = false
    for _, id in sgs.qlist(ids) do
        if sgs.Sanguosha:getCard(id):getSuit() == use.card:getSuit() then same = true end
    end
    gu_throw(room, to, ids, self:objectName())
    if same and owner:isAlive() then room:askForDiscard(owner, self:objectName(), 1, 1, false, false) end
end)

hljx_huanggai:addSkill(hljx_kurou); hljx_huanggai:addSkill(hljx_zhaxiang); hljx_huanggai:addSkill(hljx_zhaxiang_mod)
hlxg_huanggai2:addSkill(hlxg_kurou_huanggai2); hlxg_huanggai2:addSkill(hlxg_zhaxiang_huanggai2)
hlxg_huanggai2:addSkill(hlxg_kurou_huanggai2_record); hlxg_huanggai2:addSkill(hlxg_kurou_huanggai2_max)
hlxg_huanggai2:addSkill(hlxg_zhaxiang_huanggai2_record); hlxg_huanggai2:addSkill(hlxg_zhaxiang_huanggai2_mod)
hlxg_huangzu:addSkill(hlxg_jinggong); hlxg_huangzu:addSkill(hlxg_jinggong_mod); hlxg_huangzu:addSkill(hlxg_jinggong_damage); hlxg_huangzu:addSkill(hlxg_xiaojuan)
